/* Library of Limu · HSK 1 Grammar Pack (70 lessons) */
(window.OFFY_GBOOK_PACKS=window.OFFY_GBOOK_PACKS||{})[1]={"g3-1-001":{"t":["คำเติมหน้า 小— และ 第—","Prefixes 小— and 第—","前缀：小—、第—","Tiền tố 小— và 第—","接頭辞「小—・第—」"],"f":["小 + 姓（亲切称呼：小王 / 小李）","第 + 数词 +（量词）+ 名词（序数：第一个 / 第二天）"],"why":["小— วางหน้าแซ่ของคนที่อายุน้อยกว่าหรือรุ่นราวคราวเดียวกันเพื่อเรียกอย่างเป็นกันเอง (小王, 小李) · 第— วางหน้าตัวเลขเพื่อเปลี่ยนเป็นลำดับที่ (第一, 第二, 第三天) · ระวัง: 第 ตามด้วยเลขสองต้องใช้ 二 เสมอ (第二 ไม่ใช่ 第两) และห้ามวาง 小 หน้าแซ่ผู้ใหญ่/ครู","小— attaches before a surname to address a peer or younger person warmly (小王, 小李). · 第— turns a cardinal number into an ordinal (第一, 第二天). · Watch out: 'second' is always 第二 (never 第两), and do not use 小— for elders or teachers.","“小—”加在同辈或晚辈姓氏前表示亲切称呼（小王、小李）。 · “第—”加在数词前构成序数（第一、第二天）。 · 注意：“第二”只能用“二”，不能说“第两”；对长辈、老师不宜称“小＋姓”。","小— đứng trước họ người bằng hoặc nhỏ tuổi hơn để gọi thân mật (小王, 小李). · 第— đứng trước số từ tạo số thứ tự (第一, 第二天). · Lưu ý: 'thứ hai' luôn là 第二 (không dùng 第两) và không gọi 小 trước họ thầy cô/người lớn tuổi.","「小—」は同年代や年下の姓の前に付けて親しみを表す（小王・小李）。 · 「第—」は数詞の前で序数を作る（第一・第二天）。 · 注意：「第2」は必ず「第二」（第两は不可）。目上の人や先生には「小—」を使わない。"],"use":[{"ok":true,"zh":"小王是我的朋友。","fix":"","py":"Xiǎo Wáng shì wǒ de péngyou.","tr":["เสี่ยวหวังเป็นเพื่อนของฉัน","Xiao Wang is my friend.","Tiểu Vương là bạn của tôi.","王さんは私の友達です。"],"h":["เรียกเพื่อน/รุ่นน้องด้วย 小 + แซ่","Use 小 + surname for friends or juniors","称呼平辈或晚辈用“小＋姓”","Gọi bạn bè/người nhỏ hơn bằng 小 + họ","友人・年下には「小＋姓」"],"w":["ทำได้เพราะ 小— เป็นหน่วยเติมหน้าเรียกอย่างสนิทสนมสำหรับคนรุ่นเดียวกันหรืออายุน้อยกว่า (เช่น 小王, 小李, 小张)","Works because 小— warmly addresses peers or younger people by surname (小王, 小李, 小张).","“小＋姓”适合称呼同辈或年轻的朋友、同事，语气亲切自然。","Đúng vì 小 + họ là cách gọi thân mật bạn bè hoặc người nhỏ tuổi hơn.","同年代や年下の友人・同僚を親しみを込めて呼ぶときに使う。"],"ref":"HSK 3.0 g3-1-001 · 教育部國語辭典"},{"ok":true,"zh":"这是我的第一本书。","fix":"","py":"Zhè shì wǒ de dì-yī běn shū.","tr":["นี่คือหนังสือเล่มแรกของฉัน","This is my first book.","Đây là cuốn sách đầu tiên của tôi.","これは私の最初の本です。"],"h":["สร้างลำดับที่ด้วย 第 + ตัวเลข (+ ลักษณนาม + คำนาม)","Form ordinals with 第 + number (+ measure word + noun)","“第＋数词＋量词＋名词”表序数","Tạo số thứ tự bằng 第 + số + lượng từ + danh từ","序数は「第＋数詞＋量詞＋名詞」"],"w":["ทำได้เพราะ 第— เปลี่ยนเลข 一 เป็นลำดับ 'ที่หนึ่ง' และเชื่อมกับคำนาม 书 ด้วยลักษณนาม 本 ครบถ้วน","Works because 第— turns 一 into 'first' and links cleanly to 书 via the measure word 本.","“第”把基数变为序数，接名词时加上相应量词（第一本书、第二天）。","Đúng vì 第 biến số đếm thành số thứ tự và dùng lượng từ 本 trước 书.","「第」で序数になり、名詞の前に対応する量詞「本」を添える。"],"ref":"HSK 3.0 g3-1-001 · g3-1-068"},{"ok":false,"zh":"这是我的第两本书。","fix":"这是我的第二本书。","py":"Zhè shì wǒ de dì-èr běn shū.","tr":["นี่คือหนังสือเล่มที่สองของฉัน","This is my second book.","Đây là cuốn sách thứ hai của tôi.","これは私の2冊目の本です。"],"h":["ห้ามใช้ 第两 แทน 第二","Never say 第两 instead of 第二","序数不能说“第两”","Không nói 第两 thay cho 第二","「第两」は使えず必ず「第二」"],"w":["ไม่ได้ เพราะแม้จะมีลักษณนาม 本 ตามหลัง แต่พอมี 第 นำหน้าเพื่อบอกลำดับที่ ภาษาจีนบังคับใช้ 二 เสมอ (第二本书) ต่างจากบอกจำนวน 2 เล่ม (两本书)","Wrong because ordinals with 第 ALWAYS use 二 even before a measure word (第二本书), unlike counting quantity (两本书).","不行，虽然有量词“本”，但加了“第”表序数时必须用“二”（第二本书），区别于数量“两本书”。","Không được vì dù có lượng từ 本 nhưng khi có 第 chỉ thứ tự bắt buộc dùng 二 (第二本书).","量詞「本」があっても「第」が付く序数では必ず「二」（第二本书）を使う。"],"ref":"กลุ่มเทียบคำ g9 · HSK 3.0 g3-1-068"},{"ok":false,"zh":"小老师你好！","fix":"王老师你好！","py":"Wáng lǎoshī nǐ hǎo!","tr":["สวัสดีครับ/ค่ะ คุณครูหวัง","Hello, Teacher Wang!","Chào thầy/cô Vương!","王先生、こんにちは！"],"h":["ไม่ใช้ 小— เรียกครูหรือผู้ใหญ่ (ใช้ แซ่ + ตำแหน่ง)","Don't use 小— for teachers or elders","不能用“小—”称呼老师或长辈","Không dùng 小— gọi thầy cô / người lớn tuổi","先生や目上の人に「小—」は使わない"],"w":["ไม่ได้ เพราะ 小— ใช้กับคนอายุน้อยกว่าหรือเพื่อนรุ่นเดียวกันเท่านั้น เรียกครูหรือผู้ใหญ่ให้ใช้ แซ่ + 老师 / 先生 (王老师, 李先生)","Wrong because 小— is for peers/juniors; address teachers or elders with Surname + 老师/先生 (王老师, 李先生).","不行，“小—”不用于长辈或老师，应称“姓＋老师／先生”（王老师、李先生）。","Không được vì 小— chỉ gọi người ngang hoặc nhỏ tuổi hơn; gọi thầy cô dùng Họ + 老师 (王老师).","「小—」は目上や先生には失礼になるため「姓＋老师／先生」（王老师）と呼ぶ。"],"ref":"HSK 3.0 g3-1-001"}],"ex":[["小王是我的同学。","Xiǎo Wáng shì wǒ de tóngxué.","เสี่ยวหวังเป็นเพื่อนร่วมชั้นของฉัน","Xiao Wang is my classmate.","Tiểu Vương là bạn cùng lớp của tôi.","王さんは私のクラスメートです。","小王"],["小李今天不上班。","Xiǎo Lǐ jīntiān bù shàngbān.","วันนี้เสี่ยวหลี่ไม่ไปทำงาน","Xiao Li doesn't work today.","Hôm nay Tiểu Lý không đi làm.","李さんは今日仕事が休みです。","小李"],["这是我的第一本书。","Zhè shì wǒ de dì-yī běn shū.","นี่คือหนังสือเล่มแรกของฉัน","This is my first book.","Đây là cuốn sách đầu tiên của tôi.","これは私の最初の本です。","第一"],["他买了第二个手机。","Tā mǎile dì-èr ge shǒujī.","เขาซื้อโทรศัพท์เครื่องที่สองแล้ว","He bought his second phone.","Anh ấy đã mua chiếc điện thoại thứ hai.","彼は2台目のスマホを買いました。","第二"],["我们明天去第一医院。","Wǒmen míngtiān qù dì-yī yīyuàn.","พรุ่งนี้พวกเราไปโรงพยาบาลที่หนึ่ง","Tomorrow we go to the No. 1 Hospital.","Ngày mai chúng tôi đến bệnh viện số 1.","明日、第一病院へ行きます。","第一"]],"err":[["这是我的第两本书。","这是我的第二本书。","ลำดับที่สองใช้ 第二 เสมอ แม้มีลักษณนามตามหลัง","Always use 第二 for 'second', even before a measure word.","序数“第二”永远不用“两”。","Số thứ tự thứ hai luôn là 第二, không dùng 两.","序数の2番目は常に「第二」で「两」は不可。"],["小老师你好！","王老师你好！","เรียกครูหรือผู้ใหญ่ใช้ แซ่ + 老师 ไม่ใช้ 小—","Address teachers with Surname + 老师, not 小—.","称呼老师用“姓＋老师”，不用“小—”。","Gọi thầy cô dùng Họ + 老师, không dùng 小—.","先生には「小—」ではなく「姓＋老师」。"]],"rel":["g3-1-068","g3-1-011"]},"g3-1-002":{"t":["คำเติมท้าย —们 และ —边","Suffixes —们 and —边","后缀：—们、—边","Hậu tố —们 và —边","接尾辞「—们・—边」"],"f":["人称代词 / 指人名词 + 们（我们 / 朋友们）","方位词 + 边（外边 / 里面）"],"why":["—们 เติมท้ายสรรพนามบุคคล (我们, 你们, 他们) หรือคำนามเรียกคน (朋友们, 同学们, 老师们) เพื่อบอกพหูพจน์ · กฎเหล็กของ —们: (1) ห้ามใช้กับสิ่งของ (2) ห้ามใช้คู่กับตัวเลขระบุจำนวนชัดเจน เช่น 三个朋友们 (ผิด!) · —边 เติมท้ายคำบอกทิศ/ตำแหน่งเพื่อบอกฝั่งหรือบริเวณ (外边 = ข้างนอก)","—们 makes pronouns (我们, 你们, 他们) and human nouns (朋友们, 同学们) plural. · Two strict rules for —们: (1) do not attach it to inanimate objects, (2) NEVER combine it with a specific number (三个朋友们 is wrong!). · —边 attaches to position words to indicate a side or area (外边 'outside').","“—们”加在人称代词（我们、他们）或指人名词（朋友们、同学们）后表复数。 · 两条铁律：（1）不用于无生命物品；（2）前面有具体数量词时绝不能加“们”（不说“三个朋友们”）。 · “—边”加在方位词后表方位区域（外边）。","—们 thêm sau đại từ nhân xưng (我们, 他们) hoặc danh từ chỉ người (朋友们, 同学们) để chỉ số nhiều. · Hai quy tắc cứng: (1) không dùng cho đồ vật, (2) KHÔNG dùng chung với số lượng cụ thể (không nói 三个朋友们). · —边 thêm sau từ phương vị chỉ phía/khu vực (外边).","「—们」は人称代名詞（我们・他们）や人を表す名詞（朋友们・同学们）の複数を作る。 · 鉄則2つ：（1）物には付けない、（2）具体的な数量詞と一緒に使えない（三个朋友们は不可）。 · 「—边」は方位詞に付いて側・場所を表す（外边）。"],"use":[{"ok":true,"zh":"同学们都在学校。","fix":"","py":"Tóngxuémen dōu zài xuéxiào.","tr":["เพื่อนร่วมชั้นทุกคนอยู่ที่โรงเรียน","All the classmates are at school.","Các bạn cùng lớp đều ở trường.","クラスメートたちはみんな学校にいます。"],"h":["เติม —们 ท้ายคำนามเรียกคนเมื่อไม่ระบุจำนวนเป๊ะ","Add —们 to human nouns when no exact number is given","无具体数量时可说“同学们／朋友们”","Thêm —们 sau danh từ chỉ người khi không có số cụ thể","具体的な数がなければ人の名詞に「—们」を付けられる"],"w":["ทำได้เพราะ 同学 เป็นคำเรียกคนและไม่มีตัวเลขบอกจำนวนข้างหน้า —们 จึงช่วยบอกความเป็นกลุ่ม/พหูพจน์ได้ชัดเจน","Works because 同学 refers to people and has no exact numeral before it, so —们 naturally marks the group.","“同学”指人且前面没有具体数量词，加“们”表示群体复数完全自然。","Đúng vì 同学 chỉ người và không có số đếm cụ thể phía trước.","「同学」は人を表し前に具体数がないため、「们」で複数の集団を表せる。"],"ref":"HSK 3.0 g3-1-002 · 教育部國語辭典"},{"ok":true,"zh":"外边很冷。","fix":"","py":"Wàibian hěn lěng.","tr":["ข้างนอกหนาวมาก","It is very cold outside.","Bên ngoài rất lạnh.","外はとても寒いです。"],"h":["เติม —边 ท้ายคำบอกทิศเพื่อใช้เป็นคำนามสถานที่เดี่ยว ๆ ได้","Add —边 to a direction word so it stands alone as a place noun","“外边”等方位词可独立作主语或处所","Thêm —边 sau từ phương vị để đứng độc lập làm nơi chốn","「外边」などは単独で場所の名詞・主語になれる"],"w":["ทำได้เพราะการเติม —边 ทำให้คำบอกทิศกลายเป็นคำนามสถานที่ 2 พยางค์ที่ยืนเป็นประธานประโยคได้เอง (เช่น 外边很冷) แทนที่จะใช้ 外 ตัวเดียวโดด ๆ","Works because —边 turns a 1-character direction into a full 2-syllable place noun that can stand alone as subject (外边很冷).","加“边”构成双音节方位词（外边），可以独立作主语或宾语。","Đúng vì thêm —边 tạo thành danh từ phương vị 2 âm tiết đứng làm chủ ngữ được.","「—边」を付けることで2音節の方位詞になり、単独で主語や場所として使える。"],"ref":"HSK 3.0 g3-1-002 · g3-1-003"},{"ok":false,"zh":"我有三个朋友们。","fix":"我有三个朋友。","py":"Wǒ yǒu sān ge péngyou.","tr":["ฉันมีเพื่อนสามคน","I have three friends.","Tôi có ba người bạn.","私には友達が三人います。"],"h":["ห้ามใช้ —们 คู่กับตัวเลขระบุจำนวน","Never combine —们 with a specific number","有具体数量词时不能加“们”","Không dùng —们 khi đã có số lượng cụ thể","具体的な数量詞と「—们」は併用不可"],"w":["ไม่ได้ เพราะ 三个 บอกจำนวนชัดเจนแล้วว่า 3 คน การเติม —们 เข้าไปอีกจะซ้ำซ้อนและผิดไวยากรณ์จีน ต้องตัด —们 ออกเป็น 三个朋友 (หรือใช้ 很多朋友 ก็ไม่ใส่ 们)","Wrong because 三个 already specifies the exact number; adding —们 is ungrammatical in Chinese. Drop —们 → 三个朋友.","不行，前面已有具体数量“三个”，就不能再加“们”，必须说“三个朋友”（“很多朋友”一般也不加“们”）。","Không được vì 三个 đã nêu rõ số lượng rồi, thêm —们 là sai ngữ pháp. Phải bỏ —们 → 三个朋友.","「三个」で数が明示されているため「们」を重ねるのは誤用。「三个朋友」にする。"],"ref":"HSK 3.0 g3-1-002 · 教育部國語辭典"},{"ok":false,"zh":"这些书们很好看。","fix":"这些书很好看。","py":"Zhèxiē shū hěn hǎokàn.","tr":["หนังสือพวกนี้น่าอ่านมาก","These books are very interesting.","Những cuốn sách này rất hay.","これらの本はとても面白いです。"],"h":["ห้ามเติม —们 ท้ายสิ่งของ (ใช้ 这些 / 那些 / 很多 แทน)","Never attach —们 to inanimate objects","物品名词不能加“们”","Không thêm —们 sau đồ vật (dùng 这些 / 很多)","物の名詞に「—们」は付けられない"],"w":["ไม่ได้ เพราะ —们 ใช้กับมนุษย์เท่านั้น (ยกเว้นนิทานที่ทำให้สัตว์/ของพูดได้) ถ้าจะบอกพหูพจน์ของสิ่งของให้ใช้ 这些 (เหล่านี้), 那些 (เหล่านั้น) หรือ 很多 แทน","Wrong because —们 is for people only (except personification). Use 这些, 那些, or 很多 for plural objects.","不行，“们”只用于指人名词（拟人修辞除外）；物品复数用“这些、那些、很多”表示。","Không được vì —们 chỉ dùng cho người; số nhiều của đồ vật dùng 这些, 那些, 很多.","「们」は人専用（擬人法を除く）。物の複数は「这些・那些・很多」で表す。"],"ref":"HSK 3.0 g3-1-002"}],"ex":[["我们都是学生。","Wǒmen dōu shì xuésheng.","พวกเราทุกคนเป็นนักเรียน","We are all students.","Chúng tôi đều là học sinh.","私たちはみんな学生です。","我们"],["同学们都在学校。","Tóngxuémen dōu zài xuéxiào.","เพื่อนร่วมชั้นทุกคนอยู่ที่โรงเรียน","The classmates are all at school.","Các bạn cùng lớp đều ở trường.","クラスメートたちはみんな学校にいます。","同学们"],["朋友们来了。","Péngyoumen lái le.","เพื่อน ๆ มากันแล้ว","Our friends have arrived.","Bạn bè đến rồi.","友達が来ました。","朋友们"],["外边很冷。","Wàibian hěn lěng.","ข้างนอกหนาวมาก","It is very cold outside.","Bên ngoài rất lạnh.","外はとても寒いです。","外边"],["外边下雨了。","Wàibian xià yǔ le.","ข้างนอกฝนตกแล้ว","It's raining outside.","Bên ngoài mưa rồi.","外は雨が降ってきました。","外边"]],"err":[["我有三个朋友们。","我有三个朋友。","มีตัวเลขระบุจำนวนแล้ว ห้ามเติม —们","Never add —们 when a specific number is present.","有具体数量词时不能加“们”。","Đã có số đếm cụ thể thì không thêm —们.","具体的な数があるときは「们」を付けない。"],["这些书们很好看。","这些书很好看。","—们 ใช้กับคนเท่านั้น ไม่ใช้กับสิ่งของ","—们 is only for people, never inanimate objects.","“们”只用于人，不用于物品。","—们 chỉ dùng cho người, không dùng cho đồ vật.","「们」は人専用で物には使わない。"]],"rel":["g3-1-009","g3-1-003"]},"g3-1-003":{"t":["คำบอกตำแหน่ง: 上 / 下 / 里 / 外 / 前 / 后","Position nouns: 上 / 下 / 里 / 外 / 前 / 后","方位名词：上、下、里、外、前、后","Danh từ phương vị: 上 / 下 / 里 / 外 / 前 / 后","方位詞：上・下・里・外・前・后"],"f":["名词 + 上 / 下 / 里 / 外 / 前 / 后（桌子上 / 房间里）","时间 + 前 / 后（三天后 / 八点前）"],"why":["คำบอกตำแหน่ง 6 ตัว (上 บน, 下 ล่าง, 里 ใน, 外 นอก, 前 หน้า/ก่อน, 后 หลัง) ในภาษาจีนวางไว้ 'ข้างหลัง' คำนามหรือช่วงเวลา เสมอ ตรงข้ามกับภาษาไทย · เช่น 桌子上 = โต๊ะ + บน (บนโต๊ะ), 房间里 = ห้อง + ใน (ในห้อง), 三天后 = สามวัน + หลัง (อีกสามวัน / หลังจากสามวัน) · ข้อควรระวัง: ห้ามวาง 里 / 上 / 后 ไว้หน้าคำนามแบบภาษาไทย และชื่อสถานที่ใหญ่ (北京, 中国, 学校) มักไม่ต้องเติม 里","Position nouns (上 on, 下 under, 里 inside, 外 outside, 前 front/before, 后 behind/after) ALWAYS come AFTER the reference noun or time span — the opposite of English/Thai. · Examples: 桌子上 (on the table), 房间里 (in the room), 三天后 (three days later). · Never put them before the noun like Thai 'บนโต๊ะ / อีกสามวัน'.","方位名词“上、下、里、外、前、后”总是放在参照名词或时间词的后面，与泰语、英语相反：桌子上、房间里、三天后。 · 注意：绝不能按泰语语序放在名词前；大地点名称（北京、中国）前接“在”时通常不加“里”。","Danh từ phương vị (上 trên, 下 dưới, 里 trong, 外 ngoài, 前 trước, 后 sau) LUÔN đứng SAU danh từ hoặc mốc thời gian — ngược tiếng Việt/Thái: 桌子上 (trên bàn), 房间里 (trong phòng), 三天后 (ba ngày sau).","方位詞（上・下・里・外・前・后）は常に基準となる名詞や時間の後ろに置く：桌子上（机の上）、房间里（部屋の中）、三天后（三日後）。 · 名詞の前には置けない。"],"use":[{"ok":true,"zh":"书在桌子上。","fix":"","py":"Shū zài zhuōzi shàng.","tr":["หนังสืออยู่บนโต๊ะ","The book is on the table.","Sách ở trên bàn.","本は机の上にあります。"],"h":["วางคำบอกตำแหน่งไว้หลังคำนาม (โต๊ะ + บน)","Put the position noun AFTER the object (table + on)","方位词放在名词后面（桌子上）","Đặt phương vị từ SAU danh từ (桌子上)","方位詞は名詞の後ろ（桌子上）"],"w":["ทำได้เพราะภาษาจีนวางคำนามอ้างอิง (桌子) ไว้ก่อน แล้วค่อยระบุจุดที่ตั้ง (上) ต่อท้าย ทำให้ได้กลุ่มคำสถานที่ที่ตามหลัง 在 ได้เลย","Works because Chinese places the reference object (桌子) first and attaches the position (上) behind it to form a place phrase after 在.","“名词＋方位词”构成处所短语（桌子上、椅子下），可直接放在“在”后面。","Đúng vì tiếng Trung đặt vật làm mốc (桌子) trước rồi mới gắn phương vị (上) phía sau.","「名詞＋方位詞」（桌子上）で場所の句を作り、「在」の後ろに置ける。"],"ref":"HSK 3.0 g3-1-003 · g3-1-034"},{"ok":true,"zh":"三天后我回家。","fix":"","py":"Sān tiān hòu wǒ huí jiā.","tr":["อีกสามวันฉันจะกลับบ้าน","In three days I'm going home.","Ba ngày sau tôi về nhà.","3日後に帰省します。"],"h":["บอกเวลา 'ก่อน/หลัง…' วาง 前 / 后 ไว้หลังช่วงเวลา","Put 前 / 后 AFTER the duration ('3 days later')","“时间段＋前／后”表示之前／之后","Đặt 前 / 后 SAU khoảng thời gian (三天后)","「〜前／〜後」は期間＋前／后"],"w":["ทำได้เพราะ 三天 (สามวัน) เป็นช่วงเวลา และ 后 (หลังจาก) ต่อท้ายเพื่อแปลว่า 'อีกสามวัน / สามวันต่อมา' ตามลำดับจีน 100%","Works because duration (三天) comes first and 后 follows it to mean 'three days later'.","“时间＋后”表示“……之后”，语序必须是“三天后”。","Đúng vì khoảng thời gian 三天 đứng trước, 后 đứng sau để chỉ 'sau ba ngày'.","期間の「三天」の後ろに「后」を置いて「3日後」を表す。"],"ref":"เสริม w3-00080"},{"ok":false,"zh":"书在上桌子。","fix":"书在桌子上。","py":"Shū zài zhuōzi shàng.","tr":["หนังสืออยู่บนโต๊ะ","The book is on the table.","Sách ở trên bàn.","本は机の上にあります。"],"h":["ห้ามวาง 上 / 下 / 里 ไว้หน้าคำนามแบบไทย","Never put 上 / 下 / 里 before the noun","不能把“上、下、里”放在名词前","Không đặt 上 / 下 / 里 trước danh từ","「上・下・里」を名詞の前に置けない"],"w":["ไม่ได้ เพราะในภาษาไทยพูดว่า 'บน + โต๊ะ' แต่ภาษาจีนสลับด้านเสมอ ต้องเป็น 桌子上 (ส่วน 上桌子 จะฟังเหมือนกริยา 'ขึ้นไปบนโต๊ะ')","Wrong because Chinese reverses Thai/English 'on table' → 桌子上 (上桌子 sounds like a verb 'climb onto the table').","不行，汉语方位词必须在名词后，“桌子上”才表位置；“上桌子”会变成动宾结构“爬上桌子”。","Không được vì tiếng Trung đặt phương vị sau danh từ (桌子上); 上桌子 nghe như động từ 'trèo lên bàn'.","方位詞は名詞の後ろに置く。「上桌子」は「机に上がる」という動詞句になってしまう。"],"ref":"HSK 3.0 g3-1-003"},{"ok":false,"zh":"后三天我回家。","fix":"三天后我回家。","py":"Sān tiān hòu wǒ huí jiā.","tr":["อีกสามวันฉันกลับบ้าน","I'll go home in three days.","Ba ngày sau tôi về nhà.","3日後に帰省します。"],"h":["ห้ามวาง 后 / 前 ไว้หน้าช่วงเวลา","Never put 后 / 前 before the duration","不能说“后三天”，要说“三天后”","Không nói 后三天 mà phải nói 三天后","「后三天」ではなく「三天后」"],"w":["ไม่ได้ เพราะการบอก 'อีกสามวัน' หรือ 'สามวันก่อน' ภาษาจีนต้องเอาช่วงเวลาขึ้นก่อนแล้วตามด้วย 后/前 เสมอ: 三天后 / 三天前","Wrong because 'three days later/ago' always puts the duration first: 三天后 / 三天前.","不行，表时间先后须把时间段放前面：三天后／三天前。","Không được vì phải đặt khoảng thời gian trước: 三天后 / 三天前.","「3日後／3日前」は常に期間を前に置いて「三天后／三天前」とする。"],"ref":"เสริม w3-00080"}],"ex":[["书在桌子上。","Shū zài zhuōzi shàng.","หนังสืออยู่บนโต๊ะ","The book is on the table.","Sách ở trên bàn.","本は机の上にあります。","上"],["猫在椅子下。","Māo zài yǐzi xià.","แมวอยู่ใต้เก้าอี้","The cat is under the chair.","Con mèo ở dưới ghế.","猫は椅子の下にいます。","下"],["他在房间里看书。","Tā zài fángjiān lǐ kàn shū.","เขาอ่านหนังสืออยู่ในห้อง","He is reading in the room.","Anh ấy đọc sách trong phòng.","彼は部屋の中で本を読んでいます。","里"],["三天后我回家。","Sān tiān hòu wǒ huí jiā.","อีกสามวันฉันกลับบ้าน","I'm going home in three days.","Ba ngày sau tôi về nhà.","3日後に帰ります。","后"],["八点前我到学校。","Bā diǎn qián wǒ dào xuéxiào.","ก่อนแปดโมงฉันถึงโรงเรียน","I arrive at school before eight.","Trước 8 giờ tôi đến trường.","8時前に学校に着きます。","前"]],"err":[["书在上桌子。","书在桌子上。","คำบอกตำแหน่ง (上, 下, 里) อยู่หลังคำนามเสมอ","Position words (上, 下, 里) always go AFTER the noun.","方位词放在名词后面（桌子上）。","Phương vị từ luôn đứng sau danh từ (桌子上).","方位詞は常に名詞の後ろ（桌子上）。"],["后三天我回家。","三天后我回家。","'อีก 3 วัน' วาง 后 ไว้หลังช่วงเวลา: 三天后","Put 后 after the duration: 三天后.","表示“……之后”要把“后”放后面：三天后。","Đặt 后 sau khoảng thời gian: 三天后.","「3日後」は「后」を後ろに置く：三天后。"]],"rel":["g3-1-034","g3-1-021","g3-1-002"]},"g3-1-004":{"t":["会 / 能 / 可以: ทำได้สามแบบ","会 / 能 / 可以: three kinds of 'can'","会、能、可以：三种“能做”","会 / 能 / 可以: ba kiểu 'có thể'","会・能・可以：三つの「できる」"],"f":["主语 + 会 + 动词（学来的技能）","主语 + 能 + 动词（能力、客观条件）","主语 + 可以 + 动词（允许、请求）"],"why":["ภาษาไทยแปลว่า 'ได้ / เป็น' เหมือนกัน แต่ภาษาจีนแยกชัดตามเหตุผลที่ทำได้ · 会 ใช้กับทักษะที่ต้องเรียนรู้หรือฝึกฝน (พูดภาษา ขับรถ) และยังใช้คาดการณ์ว่าจะเกิด (明天会下雨) · 能 เน้นความสามารถทางร่างกายหรือเงื่อนไขสถานการณ์ว่าทำได้ไหม (วันนี้ป่วยเลยไปไม่ได้) · 可以 เน้นการขออนุญาตหรืออนุญาตให้ทำ (ขอนั่งตรงนี้ได้ไหม)","All three translate as 'can', but Chinese separates why you can do it. · 会 is for learned skills (speaking a language, driving) and predicting future events. · 能 focuses on physical ability or whether circumstances allow it (e.g. being sick so you cannot go). · 可以 focuses on permission or polite requests (may I sit here?).","“会、能、可以”都表示可能或能力，但侧重点不同。 · “会”指通过学习掌握的技能（会说汉语、会开车），也可表推测。 · “能”强调客观条件或身体能力是否允许（生病了不能去）。 · “可以”侧重许可和请求（可以坐这儿吗？）。","Cả ba đều dịch là 'có thể / biết', nhưng khác lý do. · 会 dùng cho kỹ năng học được (nói tiếng Trung, lái xe). · 能 nhấn mạnh năng lực hoặc điều kiện khách quan có cho phép không. · 可以 nhấn mạnh sự cho phép hoặc xin phép lịch sự.","どれも「できる」と訳すが理由が異なる。 · 「会」は学んで身につけた技能（中国語が話せる・運転できる）。 · 「能」は身体能力や客観的な条件が許すかどうか。 · 「可以」は許可や丁寧なお願い（ここに座ってもいいですか）。"],"use":[{"ok":true,"zh":"我会开车。","fix":"","py":"Wǒ huì kāichē.","tr":["ฉันขับรถเป็น","I know how to drive.","Tôi biết lái xe.","私は車を運転できます。"],"h":["ทักษะที่ต้องเรียนมาใช้ 会","Use 会 for learned skills","学来的技能用“会”","Kỹ năng học được dùng 会","学んで得た技能は「会」"],"w":["ขับรถ พูดภาษาจีน ทำอาหาร เป็นทักษะที่ต้องฝึกเรียน จึงใช้ 会 บอกว่า 'ทำเป็น' ได้ตรงความหมายที่สุด","Driving or speaking a language is an acquired skill, so 会 ('know how to') is the exact choice.","开车、说汉语都是通过学习掌握的技能，用“会”最准确。","Lái xe, nói tiếng Trung là kỹ năng học được nên dùng 会 là chính xác nhất.","運転や語学は学んで身につける技能なので「会」が最も的確。"],"ref":"กลุ่มเทียบคำ g3 · เสริม w3-00082"},{"ok":true,"zh":"我今天不能开车，我生病了。","fix":"","py":"Wǒ jīntiān bù néng kāichē, wǒ shēngbìng le.","tr":["วันนี้ฉันขับรถไม่ได้ ฉันไม่สบาย","I can't drive today, I'm sick.","Hôm nay tôi không thể lái xe, tôi bị ốm rồi.","今日は病気なので運転できません。"],"h":["เงื่อนไข/ร่างกายไม่เอื้อใช้ 不能","Use 不能 when conditions block you","条件不允许用“不能”","Điều kiện không cho phép dùng 不能","条件や体調で無理なときは「不能」"],"w":["ถึงจะขับรถเป็น (会) แต่วันนี้ป่วยจึงทำไม่ได้ ใช้ 不能 เพื่อชี้ว่าสภาพร่างกายหรือสถานการณ์ไม่เอื้ออำนวย","Even if you know how to drive (会), being sick stops you today — 不能 expresses that objective conditions prevent it.","即使会开车，但因为生病等客观条件做不到，必须用“不能”。","Dù biết lái xe (会), nhưng hôm nay bị ốm nên không làm được — dùng 不能 để chỉ điều kiện không cho phép.","運転自体はできても（会）、病気など客観的な条件でできないときは「不能」を使う。"],"ref":"กลุ่มเทียบคำ g3 · ประโยคตัวอย่าง_300"},{"ok":true,"zh":"我可以坐这儿吗？","fix":"","py":"Wǒ kěyǐ zuò zhèr ma?","tr":["ฉันขอนั่งตรงนี้ได้ไหม","May I sit here?","Tôi có thể ngồi đây không?","ここに座ってもいいですか。"],"h":["ขออนุญาตใช้ 可以…吗？","Use 可以…吗？ to ask permission","请求许可常用“可以……吗？”","Xin phép dùng 可以…吗？","許可を求めるときは「可以…吗？」"],"w":["การนั่งเก้าอี้ไม่ใช่ทักษะที่ต้องเรียน แต่เป็นการขอความยินยอมจากอีกฝ่าย จึงใช้ 可以 (ตอบอนุญาตว่า 可以 แต่ถ้าปฏิเสธห้าม มักตอบว่า 不能 หรือ 不可以)","Sitting down is not a learned skill — you are asking permission, so 可以 fits naturally (to refuse permission, say 不能 or 不可以).","坐下不是技能，而是征求对方同意，用“可以”最自然；表示禁止时常用“不能／不可以”。","Ngồi xuống không phải kỹ năng mà là xin phép, nên dùng 可以 (từ chối thường dùng 不能 hoặc 不可以).","座ることは技能ではなく許可を求める行為なので「可以」が自然（断るときは「不能／不可以」）。"],"ref":"กลุ่มเทียบคำ g3 · ประโยคตัวอย่าง_300"},{"ok":false,"zh":"我会坐这儿吗？","fix":"我可以坐这儿吗？","py":"Wǒ kěyǐ zuò zhèr ma?","tr":["ฉันขอนั่งตรงนี้ได้ไหม","May I sit here?","Tôi có thể ngồi đây không?","ここに座ってもいいですか。"],"h":["ห้ามใช้ 会 ขออนุญาต","Don't use 会 to ask permission","不能用“会”请求许可","Không dùng 会 để xin phép","許可を求めるのに「会」は使えない"],"w":["ไม่ได้ เพราะ 会 แปลว่า 'ทำเป็น/มีความรู้ทักษะ' ถ้าพูด 我会坐这儿吗 จะฟังแปลกว่า 'ฉันนั่งตรงนี้เป็นไหม' ต้องเปลี่ยนเป็น 可以 หรือ 能","Wrong because 会 asks whether you possess a learned skill ('do I know how to sit here?'); use 可以 or 能 for permission.","不行，因为“会”问的是有没有技能，说“我会坐这儿吗”不合常理，请求许可应说“可以”或“能”。","Không được vì 会 hỏi về kỹ năng ('tôi có biết ngồi đây không?'), xin phép phải dùng 可以 hoặc 能.","「会」は技能の有無を聞くため「ここに座る技術があるか」のように不自然になる。許可には「可以／能」を使う。"],"ref":"กลุ่มเทียบคำ g3 · 教育部國語辭典"},{"ok":false,"zh":"我今天不会开车，我生病了。","fix":"我今天不能开车，我生病了。","py":"Wǒ jīntiān bù néng kāichē, wǒ shēngbìng le.","tr":["วันนี้ฉันขับรถไม่ได้ ฉันไม่สบาย","I can't drive today, I'm sick.","Hôm nay tôi không thể lái xe, tôi bị ốm rồi.","今日は病気なので運転できません。"],"h":["ป่วย/ติดธุระ ห้ามใช้ 不会 แทน 不能","Don't use 不会 for temporary inability","因故做不到不能用“不会”","Vì bận/ốm không dùng 不会 thay 不能","体調不良などでできないときは「不会」不可"],"w":["ไม่ได้ เพราะ 不会 แปลว่า 'ขับรถไม่เป็น (ไม่เคยเรียน)' การป่วยไม่ได้ทำให้ทักษะหายไป ต้องใช้ 不能 เพื่อบอกว่าวันนี้เงื่อนไขไม่เอื้อ","Wrong because 不会 means you don't know how to drive at all; being sick removes the condition, not the skill, so use 不能.","不行，“不会开车”指没学过、不懂怎么开；生病只是今天条件不允许，技能还在，要用“不能”。","Không được vì 不会 nghĩa là không biết lái; bị ốm không làm mất kỹ năng mà chỉ là hôm nay không đủ điều kiện, phải dùng 不能.","「不会开车」は運転の仕方を知らない意味になる。病気で一時的に無理な場合は「不能」を使う。"],"ref":"กลุ่มเทียบคำ g3"}],"ex":[["我会说汉语。","Wǒ huì shuō Hànyǔ.","ฉันพูดภาษาจีนเป็น","I can speak Chinese.","Tôi biết nói tiếng Trung.","私は中国語が話せます。","会"],["他会开车。","Tā huì kāichē.","เขาขับรถเป็น","He knows how to drive.","Anh ấy biết lái xe.","彼は車を運転できます。","会"],["我今天不能去。","Wǒ jīntiān bù néng qù.","วันนี้ฉันไปไม่ได้","I can't go today.","Hôm nay tôi không thể đi.","今日は行けません。","能"],["我可以坐这儿吗？","Wǒ kěyǐ zuò zhèr ma?","ฉันขอนั่งตรงนี้ได้ไหม","May I sit here?","Tôi có thể ngồi đây không?","ここに座ってもいいですか。","可以"],["你可以看我的书。","Nǐ kěyǐ kàn wǒ de shū.","คุณอ่านหนังสือของฉันได้นะ","You may read my book.","Bạn có thể đọc sách của tôi.","私の本を読んでもいいですよ。","可以"],["你明天能来学校吗？","Nǐ míngtiān néng lái xuéxiào ma?","พรุ่งนี้คุณมาโรงเรียนได้ไหม","Can you come to school tomorrow?","Ngày mai bạn có thể đến trường không?","明日学校に来られますか。","能"]],"err":[["我会坐这儿吗？","我可以坐这儿吗？","ขออนุญาตใช้ 可以 (หรือ 能) ไม่ใช่ 会 เพราะ 会 ใช้กับทักษะที่เรียนมา","Use 可以 (or 能) for permission; 会 is for learned skills.","请求许可用“可以”（或“能”），不用表示技能的“会”。","Xin phép dùng 可以 (hoặc 能), không dùng 会.","許可を求めるのは「可以（能）」で、技能の「会」ではない。"],["我今天不会去，我生病了。","我今天不能去，我生病了。","ป่วยหรือติดธุระทำให้ไปไม่ได้ ใช้ 不能 ไม่ใช่ 不会","Temporary inability due to sickness takes 不能, not 不会.","因生病等原因去不了用“不能”，不用“不会”。","Bị ốm nên không đi được dùng 不能, không dùng 不会.","病気で行けないなど条件による不可は「不能」を使う。"]],"rel":["g3-1-006","g3-1-005","g3-1-020"]},"g3-1-005":{"t":["想 / 要: อยาก กับ จะ/ต้องการ","想 / 要: 'want to' vs 'will / need'","想、要：愿望与意愿、需求","想 / 要: 'muốn' và 'sẽ / cần'","想・要：「〜したい」と「〜するつもり／欲しい」"],"f":["主语 + 想 + 动词（愿望、想法）","主语 + 要 + 动词 / 名词（决定、需要）","主语 + 不想 + 动词（否定“想”和“要”）"],"why":["想 บอกความปรารถนาหรือความคิดในใจว่า 'อยาก…' ซึ่งอาจยังไม่ได้ลงมือทำ และใช้กับคนแปลว่า 'คิดถึง' (我很想你) · 要 น้ำหนักแรงกว่า แปลว่า 'จะ / ตั้งใจแน่วแน่ว่าจะ…' หรือวางหน้าคำนามแปลว่า 'ต้องการ/เอา' (我要一杯茶) · จุดสำคัญที่คนพลาดบ่อย: ปฏิเสธทั้ง 想 และ 要 (ไม่อยาก/ไม่ตั้งใจจะ) ใช้ 不想 เพราะ 不要 แปลว่า 'อย่า' หรือ 'ไม่เอา'","想 expresses a wish or desire ('would like to'), and with a person means 'miss' (我很想你). · 要 is stronger: 'am going to / am determined to', or before a noun 'want / order' (我要一杯茶). · Crucial caution: to negate wanting/intending to do something, use 不想 — because 不要 + verb means 'don't!' (prohibition).","“想”表示愿望、打算，语气较柔和，接人时还表示“想念”（我很想你）。 · “要”语气更强，表示决定要做，或直接接名词表示“需要、点单”（我要一杯茶）。 · 关键注意：否定“想／要＋动词”用“不想”，因为“不要＋动词”通常表示劝阻“别做”。","想 diễn tả mong muốn nhẹ nhàng, đi với người còn nghĩa là 'nhớ' (我很想你). · 要 mạnh hơn: quyết định sẽ làm, hoặc đứng trước danh từ nghĩa là 'cần / gọi món' (我要一杯茶). · Lưu ý quan trọng: phủ định ý muốn dùng 不想, vì 不要 + động từ nghĩa là 'đừng!'.","「想」は「〜したい」という願望（人に対しては「会いたい・恋しい」）。 · 「要」はより強い意志「〜するつもり」や名詞の前で「欲しい・注文する」（我要一杯茶）。 · 最重要の注意点：したくないの否定は「不想」。「不要＋動詞」は禁止の「〜しないで」になる。"],"use":[{"ok":true,"zh":"我想去中国。","fix":"","py":"Wǒ xiǎng qù Zhōngguó.","tr":["ฉันอยากไปประเทศจีน","I'd like to go to China.","Tôi muốn đi Trung Quốc.","中国へ行きたいです。"],"h":["บอกความปรารถนาในใจใช้ 想 + กริยา","Use 想 + verb for wishes","表达愿望用“想＋动词”","Diễn tả mong muốn dùng 想 + động từ","願望は「想＋動詞」"],"w":["ใช้ได้เพราะ 想 ถ่ายทอดความอยากหรือความตั้งใจอ่อน ๆ ในใจ โดยไม่จำเป็นต้องตัดสินใจหรือจองตั๋วแล้ว","Works because 想 expresses a desire or thought in mind without implying a firm plan yet.","“想”重在表达心里的愿望，不必已经决定或付诸行动。","Đúng vì 想 chỉ mong muốn trong lòng, chưa nhất thiết đã quyết định chắc chắn.","「想」は心の中の願望を表し、まだ確定していなくても自然に使える。"],"ref":"กลุ่มเทียบคำ g4 · ประโยคตัวอย่าง_300"},{"ok":true,"zh":"我要一杯茶。","fix":"","py":"Wǒ yào yī bēi chá.","tr":["ฉันขอชาหนึ่งแก้ว","I'd like a cup of tea.","Cho tôi một cốc trà.","お茶を一杯ください。"],"h":["สั่งของ/เอาสิ่งของใช้ 要 + คำนาม","Use 要 + noun to request/order items","要东西、点单用“要＋名词”","Gọi món / cần đồ dùng 要 + danh từ","注文や欲しいものは「要＋名詞」"],"w":["ทำได้เพราะ 要 เป็นคำกริยาแท้ที่ตามด้วยคำนามได้ตรง ๆ แปลว่า 'เอา/ต้องการ/ขอสั่ง' ต่างจาก 想 ที่ตามด้วยคำนามของกินโดยตรงไม่ได้","Works because 要 acts as a transitive verb taking a noun directly ('want/order'), whereas 想 cannot directly take an item noun to mean 'want'.","“要”可直接带名词宾语表示索取或点单，而“想”不能直接加食物名词表示想要。","Đúng vì 要 là động từ nhận trực tiếp danh từ ('lấy/gọi món'), còn 想 không cộng thẳng đồ vật để nói 'muốn lấy'.","「要」は直接名詞を目的語にとって「欲しい・注文する」と言えるが、「想」は物の名詞を直接置けない。"],"ref":"กลุ่มเทียบคำ g4 · 教育部國語辭典"},{"ok":true,"zh":"我不想去学校。","fix":"","py":"Wǒ bù xiǎng qù xuéxiào.","tr":["ฉันไม่อยากไปโรงเรียน","I don't want to go to school.","Tôi không muốn đi học.","学校へ行きたくないです。"],"h":["ปฏิเสธความอยาก/ความตั้งใจใช้ 不想","Negate wanting/intending with 不想","否定意愿用“不想”","Phủ định ý muốn dùng 不想","したくないの否定は「不想」"],"w":["ใช้ 不想 ทั้งเวลาปฏิเสธ 想 และเวลาปฏิเสธความตั้งใจแบบ 要 (如 明天你要去吗？— 我不想去) เพราะน้ำเสียงสุภาพและตรงความหมายว่า 'ไม่อยากทำ'","Use 不想 to negate both 想 and intentional 要 — it naturally means 'don't want to' without sounding like a command.","否定“想”或表意愿的“要”都用“不想”，不会产生“禁止／命令”的歧义。","Phủ định cả 想 lẫn 要 (ý định) đều dùng 不想 để diễn đạt 'không muốn', không bị hiểu nhầm thành cấm đoán.","「想」も意志の「要」も否定は「不想」を使うと「したくない」が自然に伝わる。"],"ref":"กลุ่มเทียบคำ g4"},{"ok":false,"zh":"我想一杯茶。","fix":"我要一杯茶。","py":"Wǒ yào yī bēi chá.","tr":["ฉันขอชาหนึ่งแก้ว","I'd like a cup of tea.","Cho tôi một cốc trà.","お茶を一杯ください。"],"h":["ห้ามวางคำนามสิ่งของหลัง 想 เพื่อแปลว่า 'เอา'","Don't put an item noun directly after 想","“想”后不能直接加物品名词表“想要”","Không đặt thẳng danh từ đồ vật sau 想","「想＋物の名詞」で「欲しい」とは言えない"],"w":["ไม่ได้ เพราะ 想 + คำนาม จะกลายเป็น 'คิดถึง…' (เช่น 我想妈妈 = ฉันคิดถึงแม่) ถ้าอยากได้ชาต้องใส่กริยาคั่นเป็น 我想喝一杯茶 หรือใช้ 要 เป็น 我要一杯茶","Wrong because 想 + noun means 'to miss someone/something'; for tea, add a verb (我想喝一杯茶) or use 要 (我要一杯茶).","不行，“想＋名词”常表“想念”（我想妈妈）。想要茶必须加动词“我想喝一杯茶”，或直接用“我要一杯茶”。","Không được vì 想 + danh từ mang nghĩa 'nhớ nhung'. Muốn uống trà phải thêm động từ (我想喝一杯茶) hoặc dùng 要 (我要一杯茶).","「想＋名詞」は「〜が恋しい」の意味になる。欲しいときは動詞を足す（我想喝一杯茶）か「我要一杯茶」と言う。"],"ref":"กลุ่มเทียบคำ g4 · 教育部國語辭典"},{"ok":false,"zh":"我不要去学校。","fix":"我不想去学校。","py":"Wǒ bù xiǎng qù xuéxiào.","tr":["ฉันไม่อยากไปโรงเรียน","I don't want to go to school.","Tôi không muốn đi học.","学校へ行きたくないです。"],"h":["ระวัง 不要 + กริยา มักฟังเหมือนคำห้าม/ปฏิเสธแข็ง","Careful: 不要 + verb usually means 'don't!'","慎用“不要＋动词”表“不想”","Tránh dùng 不要 + động từ để nói 'không muốn'","「不要＋動詞」を「したくない」に使うのは注意"],"w":["คำว่า 不要 + กริยา ใช้หลัก ๆ เพื่อห้ามปราม ('อย่าทำ…' เช่น 不要说话) ถ้าใช้กับประธาน 我 ว่า 'ไม่อยากไป' ควรใช้ 不想 จะเป็นธรรมชาติและถูกต้องกว่า (不要 + คำนาม อย่าง 我不要这个 = ฉันไม่เอาอันนี้ ใช้ได้)","不要 + verb primarily expresses prohibition ('don't!'). To say 'I don't want to go', use 不想 (note: 不要 + noun like 我不要这个 'I don't want this' is fine).","“不要＋动词”主要用于劝阻（不要说话），表达自己“不想做”应说“不想”；接名词说“我不要这个”则可以。","不要 + động từ chủ yếu dùng để cấm đoán ('đừng'). Nói 'không muốn làm' hãy dùng 不想 (còn 我不要这个 = không lấy cái này thì dùng được).","「不要＋動詞」は主に禁止（〜しないで）。自分がしたくないときは「不想」を使う（「我不要这个」のように名詞なら可）。"],"ref":"กลุ่มเทียบคำ g4 · g7"}],"ex":[["我想买一本书。","Wǒ xiǎng mǎi yī běn shū.","ฉันอยากซื้อหนังสือหนึ่งเล่ม","I want to buy a book.","Tôi muốn mua một cuốn sách.","本を一冊買いたいです。","想"],["我要喝水。","Wǒ yào hē shuǐ.","ฉันต้องการดื่มน้ำ","I want to drink water.","Tôi muốn uống nước.","水が飲みたいです。","要"],["我要一杯茶。","Wǒ yào yī bēi chá.","ฉันขอชาหนึ่งแก้ว","I'd like a cup of tea.","Cho tôi một cốc trà.","お茶を一杯ください。","要"],["我很想你。","Wǒ hěn xiǎng nǐ.","ฉันคิดถึงคุณมาก","I miss you very much.","Tôi rất nhớ bạn.","あなたにとても会いたいです。","想"],["我不想去饭店。","Wǒ bù xiǎng qù fàndiàn.","ฉันไม่อยากไปร้านอาหาร","I don't want to go to the restaurant.","Tôi không muốn đi nhà hàng.","レストランへ行きたくないです。","不想"],["我不要这个。","Wǒ bùyào zhège.","ฉันไม่เอาอันนี้","I don't want this one.","Tôi không lấy cái này.","これは要りません。","不要"]],"err":[["我想一杯茶。","我要一杯茶。","想 + คำนามแปลว่า 'คิดถึง' · สั่งของใช้ 要 + คำนาม หรือใส่กริยาเป็น 我想喝一杯茶","想 + noun means 'miss'; use 要 + noun to order, or add a verb (我想喝一杯茶).","“想＋名词”表“想念”，点单用“要＋名词”或加动词“我想喝一杯茶”。","想 + danh từ nghĩa là 'nhớ'; gọi món dùng 要 + danh từ hoặc thêm động từ.","「想＋名詞」は「恋しい」。注文は「要＋名詞」か動詞を補う。"],["我很要你。","我很想你。","ความหมาย 'คิดถึง' ใช้ 想 เท่านั้น 要 ไม่มีความหมายนี้","Only 想 means 'to miss someone'; 要 does not.","表示“想念”只能用“想”，“要”没有这个意思。","Nghĩa 'nhớ nhung' chỉ dùng 想, 要 không có nghĩa này.","「会いたい・恋しい」は「想」のみ。「要」にはない意味。"]],"rel":["g3-1-004","g3-1-020"]},"g3-1-006":{"t":["可以: ขออนุญาต / อนุญาต / พอใช้ได้","可以: permission, possibility & 'not bad'","能愿动词：可以","可以: xin phép, cho phép và 'khá ổn'","助動詞「可以」：許可・可能・まあまあ"],"f":["主语 + 可以 + 动词 + 吗？（请求许可）","可以 / 不可以 / 不能（回答许可或禁止）"],"why":["可以 เน้นการ 'ขออนุญาต / อนุญาต' (我可以坐这儿吗？) และบอกทางเลือกที่ทำได้ · ข้อควรระวังสำคัญมากเวลาตอบปฏิเสธ: ถ้าอีกฝ่ายถาม 可以…吗？ เวลาไม่อนุญาต คนจีนนิยมตอบว่า 不能 หรือ 不可以 (ห้ามทำ!) ส่วน 不可以 ใช้ได้ แต่ถ้าอยากพูดว่า 'ฉันทำไม่เป็น' ห้ามใช้ 不可以 ต้องใช้ 不会 · นอกจากนี้ 可以 เดี่ยว ๆ ยังแปลว่า 'ก็โอเค / ไม่เลว' ได้ด้วย (这个菜还可以)","可以 focuses on permission and polite requests (我可以坐这儿吗？) or viable options. · Key caution when refusing permission: answer 不能 or 不可以 ('not allowed'). · Do not use 不可以 to say you lack a learned skill (use 不会). · Alone, 可以 also means 'pretty good / okay' (这个菜还可以).","“可以”侧重许可、请求（我可以坐这儿吗？）以及情理上行得通。 · 重要注意：回答“可以……吗？”表示不允许时常用“不能”或“不可以”；表示没学过技能时不能用“不可以”，要用“不会”。 · “可以”单用还可表“还不错”（这个菜还可以）。","可以 nhấn mạnh sự cho phép / xin phép (我可以坐这儿吗？). · Lưu ý quan trọng: khi từ chối không cho phép thường dùng 不能 hoặc 不可以; khi nói 'không biết làm' phải dùng 不会. · Đứng riêng, 可以 còn nghĩa là 'cũng ổn / khá ngon'.","「可以」は許可・お願い（我可以坐这儿吗？）が中心。 · 注意：不許可の返答は「不能」や「不可以」。技能がないときは「不可以」ではなく「不会」。 · 単独で「まあまあ良い」（这个菜还可以）の意味もある。"],"use":[{"ok":true,"zh":"我可以看你的书吗？","fix":"","py":"Wǒ kěyǐ kàn nǐ de shū ma?","tr":["ฉันขออ่านหนังสือของคุณได้ไหม","May I read your book?","Tôi có thể đọc sách của bạn không?","あなたの本を読んでもいいですか。"],"h":["ขออนุญาตอย่างสุภาพใช้ 我可以…吗？","Ask permission politely with 我可以…吗？","礼貌请求许可用“我可以……吗？”","Xin phép lịch sự dùng 我可以…吗？","丁寧な許可依頼は「我可以…吗？」"],"w":["ทำได้เพราะเป็นคำขอความยินยอมจากเจ้าของหนังสือ สามารถตอบอนุญาตสั้น ๆ ว่า 可以 ได้เลย","Works as the standard polite way to ask permission; the owner can simply answer 可以 ('sure').","向他人征求同意最自然的表达，对方同意时可直接回答“可以”。","Đúng và lịch sự nhất khi xin phép; người kia đồng ý có thể đáp gọn 可以.","相手に許可を求める最も自然な言い方。OKなら「可以」だけで答えられる。"],"ref":"กลุ่มเทียบคำ g3 · ประโยคตัวอย่าง_300"},{"ok":true,"zh":"这儿不能说话。","fix":"","py":"Zhèr bù néng shuōhuà.","tr":["ตรงนี้ห้ามพูดคุย","You can't talk here.","Ở đây không được nói chuyện.","ここでは話してはいけません。"],"h":["ห้าม/ไม่อนุญาต ใช้ 不能 หรือ 不可以","Use 不能 or 不可以 to forbid an action","表示禁止常用“不能”或“不可以”","Cấm đoán / không cho phép dùng 不能 hoặc 不可以","禁止には「不能」または「不可以」"],"w":["ทำได้เพราะเมื่อต้องการห้ามหรือแจ้งกฎระเบียบ (เช่น ในห้องเรียน/โรงพยาบาล) 不能 กับ 不可以 สื่อว่า 'ไม่อนุญาตให้ทำ'","Works because both 不能 and 不可以 express 'not allowed / forbidden' for rules or refusals.","表示规定或劝阻“不允许做某事”时，“不能”比“不可以”更常用、更地道。","Đúng vì 不能 (và 不可以) diễn tả quy định cấm đoán 'không được phép'.","禁止や不許可を表すとき「不能」（または「不可以」）が自然に使われる。"],"ref":"กลุ่มเทียบคำ g3 · 教育部國語辭典"},{"ok":true,"zh":"这个菜还可以。","fix":"","py":"Zhège cài hái kěyǐ.","tr":["อาหารจานนี้ก็โอเคนะ (ไม่เลว)","This dish is pretty good.","Món này cũng khá ổn.","この料理はなかなかいいですね。"],"h":["还可以 = ก็โอเค / พอใช้ได้ (ทำหน้าที่คล้ายคุณศัพท์)","还可以 = 'not bad / decent' as a predicate","“还可以”作谓语表示“不坏、尚好”","还可以 = 'cũng ổn / không tệ'","「还可以」＝「まあまあ良い」"],"w":["ทำได้ตามนิยามในพจนานุกรมกระทรวงศึกษาฯ ไต้หวัน (不壞、尚好) โดยมักใส่ 还 นำหน้าเป็น 还可以 เพื่อบอกว่าคุณภาพพอใช้ได้ถึงดีทีเดียว","Works per the MOE dictionary sense ('not bad / fairly good'), usually paired with 还 as 还可以.","符合词典中“不坏、尚好”的义项，常与“还”连用构成“还可以”。","Đúng theo nghĩa 'khá ổn / không tệ', thường đi kèm 还 thành 还可以.","辞書の「悪くない・まずまず」の用法で、よく「还」を付けて「还可以」と言う。"],"ref":"教育部國語辭典 可以"},{"ok":false,"zh":"我不可以说汉语。","fix":"我不会说汉语。","py":"Wǒ bù huì shuō Hànyǔ.","tr":["ฉันพูดภาษาจีนไม่เป็น","I can't speak Chinese.","Tôi không biết nói tiếng Trung.","私は中国語が話せません。"],"h":["ห้ามใช้ 不可以 เพื่อบอกว่า 'ทำทักษะไม่เป็น'","Don't use 不可以 for lacking a skill","不会某种技能不能用“不可以”","Không dùng 不可以 để nói 'không biết làm'","技能がないことを「不可以」とは言わない"],"w":["ไม่ได้ เพราะ 我不可以说汉语 แปลว่า 'ฉันไม่ได้รับอนุญาตให้พูดภาษาจีน' (เหมือนโดนห้ามพูด) ถ้าจะบอกว่าพูดไม่เป็นเพราะยังไม่ได้เรียน ต้องใช้ 不会","Wrong because 我不可以说汉语 means 'I am not allowed to speak Chinese'; lacking the skill must use 不会.","不行，“我不可以说汉语”听起来像被禁止说汉语；没学过技能必须用“不会”。","Không được vì 我不可以说汉语 nghe như bị cấm nói tiếng Trung; không biết nói phải dùng 不会.","「我不可以说汉语」は「中国語を話すのを禁じられている」意味になる。話せないなら「不会」。"],"ref":"กลุ่มเทียบคำ g3"}],"ex":[["我可以坐这儿吗？","Wǒ kěyǐ zuò zhèr ma?","ฉันขอนั่งตรงนี้ได้ไหม","May I sit here?","Tôi có thể ngồi đây không?","ここに座ってもいいですか。","可以"],["你可以看我的书。","Nǐ kěyǐ kàn wǒ de shū.","คุณอ่านหนังสือของฉันได้นะ","You may read my book.","Bạn có thể đọc sách của tôi.","私の本を読んでもいいですよ。","可以"],["我可以喝一杯水吗？","Wǒ kěyǐ hē yī bēi shuǐ ma?","ฉันขอดื่มน้ำสักแก้วได้ไหม","May I have a glass of water?","Tôi có thể uống một cốc nước không?","お水を一杯いただいてもいいですか。","可以"],["这里不可以说话。","Zhèlǐ bù kěyǐ shuōhuà.","ตรงนี้ห้ามพูดคุย","Talking is not allowed here.","Ở đây không được nói chuyện.","ここは私語禁止です。","不可以"],["这个菜还可以。","Zhège cài hái kěyǐ.","อาหารจานนี้ก็โอเคนะ","This dish is pretty good.","Món này cũng khá ổn.","この料理はまあまあおいしいです。","可以"]],"err":[["我不可以说汉语。","我不会说汉语。","พูดภาษาไม่เป็น (ทักษะ) ใช้ 不会 ไม่ใช่ 不可以","Lacking a skill takes 不会, not 不可以.","没学过某项技能用“不会”，不用“不可以”。","Không biết kỹ năng dùng 不会, không dùng 不可以.","技能がないときは「不可以」ではなく「不会」。"]],"rel":["g3-1-004","g3-1-020"]},"g3-1-007":{"t":["离合词: กริยาแยกได้ (睡觉 · 说话 · 上课)","Separable verbs (离合词): 睡觉 · 说话 · 上课","离合词：睡觉、说话、上课等","Động từ ly hợp (离合词): 睡觉 · 说话 · 上课","離合詞（离合词）：睡觉・说话・上课"],"f":["主语 + 离合词（睡觉 / 说话 / 上课）","主语 + 动 + 了/数量 + 宾（睡了八个小时 / 说汉语）"],"why":["คำอย่าง 睡觉 (นอน), 说话 (พูดคุย), 上课 (เข้าเรียน), 吃饭 (กินข้าว) ดูเหมือนคำกริยา 1 คำ แต่จริง ๆ ประกอบจาก 'กริยา + กรรม' ในตัวแล้ว (睡+觉, 说+话, 上+课) · เพราะมีกรรมติดมาแล้ว จึงเอาไปวางท้ายประโยคเฉย ๆ ได้ (他在睡觉) แต่ต่อกรรมเพิ่มข้างหลังไม่ได้ และเวลามีระยะเวลาหรือคำขยายต้องแทรกไว้ตรงกลางหรือใช้แค่ตัวกริยาหน้า","Words like 睡觉 (sleep), 说话 (speak), 上课 (have class), and 吃饭 (eat) look like single verbs, but are actually 'verb + built-in object' (睡+觉, 说+话, 上+课). · Because they already hold an object, they cannot take another object right after them, and duration/modifiers must go inside or attach to the verb part alone.","“睡觉、说话、上课、吃饭”等词内部是“动词＋宾语”结构（睡＋觉、说＋话）。 · 因为本身已经带有宾语，所以后面不能再直接带宾语；如果要带时量、数量或“了”，必须拆开插在中间，或只用前面的动词。","Các từ như 睡觉, 说话, 上课, 吃饭 thực chất gồm 'động từ + tân ngữ' (睡+觉, 说+话). · Vì đã có sẵn tân ngữ nên không thể thêm tân ngữ nữa ở phía sau; khi có thời lượng hoặc 了 phải tách ra chen vào giữa hoặc chỉ dùng động từ đứng đầu.","「睡觉・说话・上课・吃饭」などは1語に見えるが実は「動詞＋目的語」（睡＋觉、说＋话）の構造。 · すでに目的語を含むため後ろに別の目的語を続けられず、時間量や「了」は間に挟むか動詞部分だけを使う。"],"use":[{"ok":true,"zh":"他们在说话。","fix":"","py":"Tāmen zài shuōhuà.","tr":["พวกเขากำลังพูดคุยกัน","They are talking.","Họ đang nói chuyện.","彼らは話しています。"],"h":["ใช้เต็มคำเมื่อไม่ระบุกรรมเพิ่ม","Use the full word when no extra object follows","不带其他宾语时合起来用","Dùng nguyên từ khi không có tân ngữ thêm","別の目的語がないときはそのまま使う"],"w":["ทำได้เพราะ 说话 มีกรรมคือ 话 (คำพูด) ครบในตัวอยู่แล้ว เหมาะสำหรับพูดจบประโยคโดยไม่ต้องระบุว่าพูดเรื่องอะไร","Works because 说话 already contains its own object 话 ('words'), forming a complete action on its own.","“说话”自带宾语“话”，不说明说的内容时合用最自然。","Đúng vì 说话 đã có sẵn tân ngữ 话 (lời nói), đứng cuối câu hoàn chỉnh tự nhiên.","「说话」はすでに目的語「话」を含むので、内容を言わないときはそのまま文末に置ける。"],"ref":"กลุ่มเทียบคำ g25 · ประโยคตัวอย่าง_300"},{"ok":true,"zh":"请说汉语。","fix":"","py":"Qǐng shuō Hànyǔ.","tr":["กรุณาพูดภาษาจีน","Please speak Chinese.","Xin hãy nói tiếng Trung.","中国語を話してください。"],"h":["เมื่อมีกรรมเฉพาะ ให้ตัดตัวหลังออก (用 说 ไม่ใช่ 说话)","Drop the built-in object when specifying a real object","带具体宾语时只用前一个动词","Khi có tân ngữ cụ thể chỉ dùng động từ đầu","具体的な目的語を置くときは前の動詞だけ使う"],"w":["ทำได้เพราะพอเราอยากระบุกรรมใหม่ (汉语 ภาษาจีน) เราจึงใช้แค่กริยา 说 แล้วตามด้วย 汉语 โดยตัด 话 ออกเพื่อไม่ให้กรรมชนกัน","Works because when you specify a new object (汉语), using only the verb 说 avoids having two objects collide.","要说出具体语言“汉语”时，只用动词“说”带“汉语”，避免双宾语冲突。","Đúng vì khi nêu rõ tân ngữ mới (汉语), chỉ dùng động từ 说 để tránh trùng hai tân ngữ.","「汉语」という具体的な目的語を置くため、動詞「说」だけにして目的語の重複を避ける。"],"ref":"กลุ่มเทียบคำ g25"},{"ok":true,"zh":"我睡了八个小时。","fix":"","py":"Wǒ shuìle bā ge xiǎoshí.","tr":["ฉันนอนไปแปดชั่วโมง","I slept for eight hours.","Tôi đã ngủ tám tiếng.","8時間寝ました。"],"h":["บอกระยะเวลา ใช้ 睡 + 了 + เวลา","Attach duration directly after the verb 睡","加时量补语时拆开或只用“睡”","Thêm thời lượng: dùng 睡 + 了 + thời gian","時間量を付けるときは「睡＋了＋時間」"],"w":["ทำได้เพราะ 睡 เป็นกริยาเดี่ยว จึงตามด้วย 了 และระยะเวลา 八个小时 ได้ทันที (หรือจะใส่ 觉 ปิดท้ายเป็น 睡了八个小时觉 ก็ได้)","Works because 睡 alone is a bare verb that freely takes 了 and a duration 八个小时 (optionally closing with 觉).","“睡”是单动词，可以直接接“了＋时量”（也可说“睡了八个小时觉”）。","Đúng vì 睡 là động từ đơn, nối thẳng 了 + thời lượng được ngay.","「睡」だけなら純粋な動詞なので直後に「了＋時間量」を続けられる。"],"ref":"กลุ่มเทียบคำ g24"},{"ok":false,"zh":"请说话汉语。","fix":"请说汉语。","py":"Qǐng shuō Hànyǔ.","tr":["กรุณาพูดภาษาจีน","Please speak Chinese.","Xin hãy nói tiếng Trung.","中国語を話してください。"],"h":["ห้ามเอา 说话 ไปต่อกรรมตรง ๆ","Never put an object right after 说话","“说话”后面不能再加宾语","Không thêm tân ngữ trực tiếp sau 说话","「说话」の直後に目的語を置けない"],"w":["ไม่ได้ เพราะ 说话 = 说 + 话 มีกรรม (话) อยู่แล้ว ถ้าต่อ 汉语 เข้าไปอีกจะกลายเป็นมีกรรมซ้อนกันสองตัว ต้องตัด 话 ออกเป็น 请说汉语","Wrong because 说话 already contains the object 话; adding 汉语 creates a double-object clash. Drop 话 → 请说汉语.","不行，“说话”本身已有宾语“话”，再加“汉语”会宾语重叠，应去掉“话”说“请说汉语”。","Không được vì 说话 đã có tân ngữ 话 rồi, thêm 汉语 sẽ bị thừa tân ngữ. Phải bỏ 话 → 请说汉语.","「说话」はすでに目的語「话」を持つため「汉语」を続けると目的語が重複する。「请说汉语」にする。"],"ref":"กลุ่มเทียบคำ g25"},{"ok":false,"zh":"我睡觉了八个小时。","fix":"我睡了八个小时。","py":"Wǒ shuìle bā ge xiǎoshí.","tr":["ฉันนอนไปแปดชั่วโมง","I slept for eight hours.","Tôi đã ngủ tám tiếng.","8時間寝ました。"],"h":["ห้ามวางระยะเวลาไว้หลัง 睡觉","Don't place a duration after 睡觉","不能把时量放在“睡觉”后面","Không đặt thời lượng sau 睡觉","「睡觉」の後ろに時間量を置けない"],"w":["ไม่ได้ เพราะ 觉 เป็นคำนาม (กรรม) จึงวาง 了 + ระยะเวลา ไว้ข้างหลังไม่ได้ ต้องแยกออกจากกันเป็น 睡了八个小时 (หรือ 睡了八个小时觉)","Wrong because 觉 is a noun (the object), so 了 + duration cannot follow it; split it as 睡了八个小时.","不行，“觉”是名词宾语，不能直接在其后加“了＋时量”，必须说“睡了八个小时”。","Không được vì 觉 là danh từ tân ngữ, không đặt 了 + thời lượng phía sau được. Phải tách ra: 睡了八个小时.","「觉」は名詞（目的語）なので直後に「了＋時間量」を置けない。「睡了八个小时」と切り離す。"],"ref":"กลุ่มเทียบคำ g24"}],"ex":[["孩子在睡觉。","Háizi zài shuìjiào.","ลูกกำลังนอนหลับ","The child is sleeping.","Đứa bé đang ngủ.","子どもは寝ています。","睡觉"],["他们在说话。","Tāmen zài shuōhuà.","พวกเขากำลังพูดคุยกัน","They are talking.","Họ đang nói chuyện.","彼らは話しています。","说话"],["请说汉语。","Qǐng shuō Hànyǔ.","กรุณาพูดภาษาจีน","Please speak Chinese.","Xin hãy nói tiếng Trung.","中国語を話してください。","说"],["我睡了八个小时。","Wǒ shuìle bā ge xiǎoshí.","ฉันนอนไปแปดชั่วโมง","I slept for eight hours.","Tôi đã ngủ tám tiếng.","8時間寝ました。","睡"],["我们八点上课。","Wǒmen bā diǎn shàngkè.","พวกเราเข้าเรียนแปดโมง","We start class at eight.","Chúng tôi vào lớp lúc 8 giờ.","私たちは8時に授業が始まります。","上课"],["妈妈去医院看病。","Māma qù yīyuàn kànbìng.","แม่ไปหาหมอที่โรงพยาบาล","Mom goes to the hospital to see a doctor.","Mẹ đi bệnh viện khám bệnh.","母は病院へ診察に行きます。","看病"]],"err":[["请说话汉语。","请说汉语。","说话 มีกรรม (话) ในตัวแล้ว ต่อกรรมเพิ่มไม่ได้ ใช้ 说 + ภาษา","说话 already includes an object (话) and cannot take another; use 说.","“说话”已带宾语“话”，不能再接宾语，应说“说汉语”。","说话 đã có sẵn tân ngữ nên không nối thêm 汉语 được, dùng 说.","「说话」は目的語を含むため後ろに言語名を続けられない。「说」を使う。"],["我睡觉了八个小时。","我睡了八个小时。","睡觉 เป็นคำแยกได้ วางระยะเวลาไว้หลัง 睡觉 ไม่ได้ ต้องใช้ 睡了 + เวลา","睡觉 is separable; duration cannot follow 觉 — use 睡了 + duration.","“睡觉”是离合词，时量不能放后面，应说“睡了八个小时”。","睡觉 là từ ly hợp, không đặt thời lượng phía sau; dùng 睡了 + thời lượng.","「睡觉」は離合詞なので後ろに時間量を置けない。「睡了＋時間」にする。"]],"rel":["g3-1-025","g3-1-041"]},"g3-1-008":{"t":["几 / 多少: ถามจำนวน “กี่” กับ “เท่าไร”","几 / 多少: asking 'how many / how much'","几、多少：询问数量","几 / 多少: hỏi số lượng 'mấy / bao nhiêu'","几・多少：数を尋ねる「いくつ・いくら」"],"f":["几 + 量词 + 名词（10 以内，必须有量词）","多少 +（量词）+ 名词（数量不限，可省量词）","……多少钱？（问价格）"],"why":["几 ใช้ถามจำนวนที่คาดว่าไม่มาก (มักไม่เกิน 10) และต้องมีลักษณนามตามหลังเสมอ (几个, 几口人, 几本书) · 多少 ใช้ถามจำนวนเท่าไรก็ได้ (มากหรือน้อย ไม่รู้มาก่อน) และละลักษณนามได้ · ถามราคาใช้ 多少钱 เสมอ และถามอายุเด็กใช้ 你几岁？ โดยไม่ต้องมี 有","几 asks about a small expected number (usually under 10) and MUST be followed by a measure word (几个, 几口人). · 多少 works for any quantity and lets you omit the measure word. · Always ask prices with 多少钱, and ask a child's age with 你几岁？ (no 有).","“几”用于询问预计较小的数量（一般10以内），后面必须带量词（几个、几口人）。 · “多少”不限数量大小，后面的量词可以省略。 · 问价格固定用“多少钱”；问小孩年龄用“你几岁？”，不用“有”。","几 hỏi số lượng nhỏ (thường dưới 10) và bắt buộc có lượng từ đi kèm (几个, 几口人). · 多少 hỏi mọi số lượng và có thể bỏ lượng từ. · Hỏi giá luôn dùng 多少钱; hỏi tuổi trẻ em dùng 你几岁？ (không dùng 有).","「几」は少ない数（普通10以下）を尋ね、必ず量詞を伴う（几个・几口人）。 · 「多少」は数の大小を問わず量詞を省略できる。 · 値段は「多少钱」、子どもの年齢は「你几岁？」（「有」は不要）。"],"use":[{"ok":true,"zh":"你家有几口人？","fix":"","py":"Nǐ jiā yǒu jǐ kǒu rén?","tr":["ครอบครัวคุณมีกี่คน","How many people are in your family?","Nhà bạn có mấy người?","ご家族は何人ですか。"],"h":["จำนวนน้อยใช้ 几 + ลักษณนาม","Use 几 + measure word for small numbers","小数目用“几＋量词”","Số nhỏ dùng 几 + lượng từ","少ない数は「几＋量詞」"],"w":["ทำได้เพราะจำนวนสมาชิกในบ้านมักไม่เกิน 10 คน และมีลักษณนาม 口 (นับคนในครอบครัว) คั่นระหว่าง 几 กับ 人 ถูกต้อง","Works because family size is normally under 10 and the required measure word 口 sits between 几 and 人.","家庭人口通常在10以内，且“几”和“人”之间正确加了量词“口”。","Đúng vì số người trong nhà thường dưới 10 và có đủ lượng từ 口 giữa 几 và 人.","家族の人数は普通10人以下で、「几」と「人」の間に量詞「口」が正しく入っている。"],"ref":"กลุ่มเทียบคำ g8 · g10 · ประโยคตัวอย่าง_300"},{"ok":true,"zh":"你们学校有多少学生？","fix":"","py":"Nǐmen xuéxiào yǒu duōshao xuésheng?","tr":["โรงเรียนคุณมีนักเรียนกี่คน","How many students are in your school?","Trường bạn có bao nhiêu học sinh?","学校には生徒が何人いますか。"],"h":["จำนวนมาก/ไม่จำกัดใช้ 多少 (ละลักษณนามได้)","Use 多少 for large/unknown numbers (measure word optional)","大数目用“多少”（可省量词）","Số lớn dùng 多少 (bỏ được lượng từ)","多い・不明な数は「多少」（量詞省略可）"],"w":["ทำได้เพราะจำนวนนักเรียนในโรงเรียนมักมากกว่า 10 คน จึงใช้ 多少 และสามารถวางหน้าคำนาม 学生 ได้เลยโดยไม่ต้องใส่ 个","Works because a school has more than 10 students, and 多少 can sit directly before a noun without needing 个.","学校学生通常超过十人，用“多少”合适，且“多少”后可省去量词“个”。","Đúng vì số học sinh thường lớn hơn 10 và 多少 đứng thẳng trước danh từ được mà không cần 个.","学校の生徒数は10人以上なので「多少」が適切で、量詞「个」を省略できる。"],"ref":"กลุ่มเทียบคำ g8"},{"ok":true,"zh":"你几岁？","fix":"","py":"Nǐ jǐ suì?","tr":["หนูอายุเท่าไร","How old are you? (to a child)","Cháu mấy tuổi rồi?","何歳ですか（子ども向け）。"],"h":["ถามอายุเด็กใช้ 几岁 โดยไม่ต้องมี 有","Ask a child's age with 几岁 (no 有)","问小孩年龄用“几岁”，不用“有”","Hỏi tuổi trẻ em dùng 几岁 (không có 有)","子どもの年齢は「有」なしで「几岁」"],"w":["ทำได้เพราะในภาษาจีน 'จำนวน + 岁' ทำหน้าที่เป็นภาคแสดง (谓语) ได้เองเลย ไม่ต้องใส่คำว่า 'มี' (有) เหมือนภาษาไทย (และ 岁 เป็นลักษณนามเวลาในตัวแล้ว)","Works because 'number + 岁' acts directly as the predicate in Chinese (no 有 needed), and 岁 itself functions as a measure word.","汉语中“数词＋岁”可直接作谓语，不必加“有”，且“岁”本身就是量词。","Đúng vì trong tiếng Trung 'số + 岁' tự làm vị ngữ được, không cần thêm 有.","中国語では「数＋岁」だけで述語になり「有」は不要。また「岁」自体が量詞の働きをする。"],"ref":"เสริม w3-00085 · HSK 3.0 g3-1-036"},{"ok":false,"zh":"你有几孩子？","fix":"你有几个孩子？","py":"Nǐ yǒu jǐ ge háizi?","tr":["คุณมีลูกกี่คน","How many children do you have?","Bạn có mấy người con?","お子さんは何人いますか。"],"h":["ห้ามละลักษณนามหลัง 几","Never omit the measure word after 几","“几”后不能省略量词","Không được bỏ lượng từ sau 几","「几」の後ろの量詞は省略不可"],"w":["ไม่ได้ เพราะ 几 ทำหน้าที่เหมือนตัวเลข (一, 两, 三) จึงต้องมีลักษณนามคั่นหน้าคำนามเสมอ (ยกเว้นคำที่เป็นลักษณนามในตัวเช่น 几天, 几年, 几岁) ต้องแก้เป็น 几个孩子","Wrong because 几 behaves like a numeral and requires a measure word before a noun (except self-measuring nouns like 天, 年, 岁). Say 几个孩子.","不行，“几”相当于数词，名词前必须加量词（天、年、岁等本身作量词的除外），应说“几个孩子”。","Không được vì 几 hoạt động như số từ, bắt buộc có lượng từ trước danh từ. Phải sửa thành 几个孩子.","「几」は数詞と同じく名詞の前に量詞が必須（天・年・岁など自体が量詞の語を除く）。「几个孩子」にする。"],"ref":"กลุ่มเทียบคำ g8"},{"ok":false,"zh":"你有几岁？","fix":"你几岁？","py":"Nǐ jǐ suì?","tr":["หนูอายุเท่าไร","How old are you?","Cháu mấy tuổi rồi?","何歳ですか。"],"h":["ถามอายุห้ามใส่ 有 แบบภาษาไทย","Don't add 有 when asking age","问年龄不能加“有”","Hỏi tuổi không thêm 有","年齢を聞くとき「有」を入れない"],"w":["ไม่ได้ เพราะภาษาจีนไม่ได้ใช้โครงสร้าง 'มีอายุ' เหมือนภาษาไทย (และถ้าถามผู้ใหญ่ให้ใช้ 你多大？ เพราะ 几岁 ใช้ถามเด็กอายุราวไม่เกิน 10 ขวบ)","Wrong because Chinese does not use 'have' (有) for age; simply say 你几岁？ for children, or 你多大？ for adults.","不行，汉语问年龄不加“有”；“你几岁？”用于问小孩，问成年人应说“你多大？”。","Không được vì tiếng Trung không dùng 有 để hỏi tuổi; hỏi trẻ em dùng 你几岁？, hỏi người lớn dùng 你多大？.","中国語では年齢に「有」を使わない。子どもには「你几岁？」、大人には「你多大？」。"],"ref":"เสริม w3-00085"}],"ex":[["你有几个孩子？","Nǐ yǒu jǐ ge háizi?","คุณมีลูกกี่คน","How many children do you have?","Bạn có mấy người con?","お子さんは何人いますか。","几"],["你家有几口人？","Nǐ jiā yǒu jǐ kǒu rén?","ครอบครัวคุณมีกี่คน","How many people are in your family?","Nhà bạn có mấy người?","ご家族は何人ですか。","几"],["你们学校有多少学生？","Nǐmen xuéxiào yǒu duōshao xuésheng?","โรงเรียนคุณมีนักเรียนกี่คน","How many students does your school have?","Trường bạn có bao nhiêu học sinh?","学校には生徒が何人いますか。","多少"],["这个多少钱？","Zhège duōshao qián?","อันนี้ราคาเท่าไร","How much is this?","Cái này bao nhiêu tiền?","これはいくらですか。","多少"],["现在几点？","Xiànzài jǐ diǎn?","ตอนนี้กี่โมงแล้ว","What time is it now?","Bây giờ là mấy giờ?","今何時ですか。","几"],["你买了几本书？","Nǐ mǎile jǐ běn shū?","คุณซื้อหนังสือมากี่เล่ม","How many books did you buy?","Bạn đã mua mấy cuốn sách?","本を何冊買いましたか。","几"]],"err":[["你有几孩子？","你有几个孩子？","หลัง 几 ต้องมีลักษณนามเสมอ (几个孩子)","几 always requires a measure word (几个孩子).","“几”后必须带量词（几个孩子）。","Sau 几 bắt buộc có lượng từ (几个孩子).","「几」の後ろには必ず量詞が要る（几个孩子）。"],["你有几岁？","你几岁？","ถามอายุในภาษาจีนไม่ต้องมี 有","Chinese needs no 有 when asking age.","问年龄不用“有”。","Hỏi tuổi không dùng 有.","年齢を尋ねるとき「有」は要らない。"],["这个几钱？","这个多少钱？","ถามราคาใช้ 多少钱 เสมอ ไม่ใช้ 几钱","Always ask prices with 多少钱, never 几钱.","问价格固定用“多少钱”，不说“几钱”。","Hỏi giá luôn dùng 多少钱, không nói 几钱.","値段は常に「多少钱」を使い、「几钱」とは言わない。"]],"rel":["g3-1-012","g3-1-048","g3-1-067"]},"g3-1-009":{"t":["คำสรรพนามบุคคล: 我 / 你 / 您 / 他 / 她 / 它 / 大家","Personal pronouns: 我 / 你 / 您 / 他 / 她 / 它 / 大家","人称代词：我、你、您、他、她、它、大家","Đại từ nhân xưng: 我 / 你 / 您 / 他 / 她 / 它 / 大家","人称代名詞：我・你・您・他・她・它・大家"],"f":["单数：我 / 你 / 您（敬称）/ 他 / 她 / 它","复数：我们 / 你们 / 他们 / 她们 / 它们 / 大家"],"why":["ภาษาจีนไม่ผันรูปสรรพนามตามตำแหน่งประธานหรือกรรม (我 เป็นได้ทั้ง 'ฉัน' และ 'ของฉัน/ให้ฉัน') · 他 (ผู้ชาย), 她 (ผู้หญิง), 它 (สัตว์/สิ่งของ) อ่าน tā เหมือนกันหมด ต่างกันเฉพาะรูปเขียน · 您 ใช้เรียกผู้ใหญ่หรือคนที่ไม่สนิทอย่างสุภาพ (และไม่มีรูป 您们!) · 大家 แปลว่า 'ทุกคน' เป็นพหูพจน์อยู่แล้ว จึงห้ามเติม 们 และนิยมใช้คู่กับ 都","Chinese pronouns never change form between subject and object (我 = I / me). · 他 (he), 她 (she), and 它 (it) are all pronounced tā — only the character differs. · 您 is the polite 'you' for elders/strangers (and has NO plural 您们!). · 大家 ('everyone') is already plural — never add 们.","汉语人称代词作主语、宾语形式不变。 · “他、她、它”读音都是 tā，只靠字形区分性别或事物。 · “您”表敬称，规范汉语不说“您们”。 · “大家”本身已指全体复数，不能再加“们”，常与“都”呼应。","Đại từ tiếng Trung không đổi dạng giữa chủ ngữ và tân ngữ. · 他, 她, 它 đều đọc là tā, chỉ khác chữ viết. · 您 dùng kính trọng người lớn tuổi (và KHÔNG có dạng 您们). · 大家 ('mọi người') vốn là số nhiều nên không thêm 们.","中国語の人称代名詞は主格・目的格で形が変わらない。 · 「他・她・它」はすべて tā と読み、文字だけで区別する。 · 「您」は敬称だが「您们」とは言わない。 · 「大家」はすでに複数なので「们」を付けない。"],"use":[{"ok":true,"zh":"您好，请问您是王老师吗？","fix":"","py":"Nín hǎo, qǐngwèn nín shì Wáng lǎoshī ma?","tr":["สวัสดีครับ/ค่ะ ขอถามหน่อย ท่านคืออาจารย์หวังใช่ไหมครับ/คะ","Hello, excuse me, are you Teacher Wang?","Xin chào, xin hỏi ngài có phải thầy Vương không?","こんにちは、失礼ですが王先生でしょうか。"],"h":["เรียกครู/ผู้ใหญ่/ลูกค้าอย่างสุภาพใช้ 您","Use 您 politely for teachers, elders & guests","对老师、长辈或宾客用敬称“您”","Dùng 您 lịch sự với thầy cô / người lớn tuổi","先生・目上の人には敬称「您」"],"w":["ทำได้และสุภาพมาก เพราะ 您 มีราก 心 (ใจ) อยู่ข้างล่าง สื่อถึงการให้เกียรติจากใจ เหมาะกับผู้สูงวัย ครู หรือคนที่เพิ่งพบ","Works politely because 您 (你 over 心 'heart') shows genuine respect to elders, teachers, or new acquaintances.","“您”用于敬称长辈、老师或初识对象，礼貌得体。","Đúng và lịch sự vì 您 thể hiện sự tôn trọng với thầy cô, người lớn tuổi.","「您」は先生や目上の人への丁寧な敬称として最適。"],"ref":"HSK 3.0 g3-1-009 · ชนิดของคำ_12ชนิด"},{"ok":true,"zh":"大家都喜欢吃苹果。","fix":"","py":"Dàjiā dōu xǐhuan chī píngguǒ.","tr":["ทุกคนต่างก็ชอบกินแอปเปิล","Everyone likes eating apples.","Mọi người đều thích ăn táo.","みんなりんごを食べるのが好きです。"],"h":["大家 (ทุกคน) ใช้คู่กับ 都 โดยไม่ต้องเติม 们","Use 大家 ('everyone') with 都 and no 们","“大家”本身表复数，常配“都”","大家 ('mọi người') đi với 都, không thêm 们","「大家」はそのまま複数で「都」と相性が良い"],"w":["ทำได้เพราะ 大家 หมายถึงกลุ่มคนทั้งหมดในวงสนทนาอยู่แล้ว จึงจับคู่กับ 都 (ทุกคนล้วน…) ได้อย่างเป็นธรรมชาติ","Works because 大家 already denotes everyone present, pairing naturally with 都.","“大家”已总指在场所有人，配副词“都”自然流畅。","Đúng vì 大家 đã chỉ toàn thể mọi người, đi cùng 都 rất tự nhiên.","「大家」は全員を指すため「都」と自然に呼応する。"],"ref":"HSK 3.0 g3-1-009 · ชนิดของคำ_12ชนิด"},{"ok":false,"zh":"您们好！","fix":"你们好！","py":"Nǐmen hǎo!","tr":["สวัสดีทุกคน / สวัสดีทุกท่าน","Hello everyone!","Xin chào các bạn / quý vị!","皆さん、こんにちは！"],"h":["ภาษาจีนมาตรฐานไม่ใช้ 您们","Standard Chinese does not use 您们","规范汉语不说“您们”","Tiếng Trung chuẩn không dùng 您们","標準語では「您们」を使わない"],"w":["ไม่ได้ เพราะ 您 ใช้เฉพาะเอกพจน์ (1 คน) เท่านั้น ถ้าจะทักหลายคนอย่างสุภาพ ให้พูดว่า 你们好 หรือ 大家好 แทน","Wrong because 您 is strictly singular; to greet multiple people politely, say 你们好 or 大家好.","不行，“您”只用于单数，对多人打招呼应说“你们好”或“大家好”。","Không được vì 您 chỉ dùng cho số ít; chào nhiều người hãy dùng 你们好 hoặc 大家好.","「您」は単数専用。複数の人への丁寧な挨拶は「你们好」や「大家好」を使う。"],"ref":"HSK 3.0 g3-1-009"},{"ok":false,"zh":"大家们都去学校。","fix":"大家都去学校。","py":"Dàjiā dōu qù xuéxiào.","tr":["ทุกคนไปโรงเรียนกันหมด","Everyone is going to school.","Mọi người đều đi học.","みんな学校へ行きます。"],"h":["ห้ามเติม 们 ท้าย 大家","Never add 们 after 大家","“大家”后面不能加“们”","Không thêm 们 sau 大家","「大家」に「们」は付けられない"],"w":["ไม่ได้ เพราะ 大家 มีความหมายพหูพจน์ ('ทุกคน') ในตัวอยู่แล้ว การเติม 们 ซ้ำจึงผิดไวยากรณ์ ต้องตัด 们 ออกเป็น 大家都去学校","Wrong because 大家 already means 'everyone' (plural); adding 们 is redundant and ungrammatical.","不行，“大家”本身就是复数，不能再加“们”。","Không được vì 大家 đã mang nghĩa số nhiều rồi, thêm 们 là thừa và sai.","「大家」自体が複数なので「们」を足すのは誤用。"],"ref":"HSK 3.0 g3-1-009 · g3-1-002"}],"ex":[["您是王老师吗？","Nín shì Wáng lǎoshī ma?","ท่านคืออาจารย์หวังใช่ไหมครับ/คะ","Are you Teacher Wang?","Ngài có phải thầy Vương không?","王先生でしょうか。","您"],["她是我的姐姐。","Tā shì wǒ de jiějie.","เธอคือพี่สาวของฉัน","She is my older sister.","Cô ấy là chị gái tôi.","彼女は私の姉です。","她"],["我有一只猫，它很漂亮。","Wǒ yǒu yī zhī māo, tā hěn piàoliang.","ฉันมีแมวหนึ่งตัว มันสวยมาก","I have a cat; it is very pretty.","Tôi có một con mèo, nó rất đẹp.","猫を一匹飼っていて、とてもきれいです。","它"],["大家都喜欢他。","Dàjiā dōu xǐhuan tā.","ทุกคนต่างก็ชอบเขา","Everyone likes him.","Mọi người đều thích anh ấy.","みんな彼が好きです。","大家"],["你们明天上班吗？","Nǐmen míngtiān shàngbān ma?","พรุ่งนี้พวกคุณไปทำงานไหม","Do you guys work tomorrow?","Ngày mai các bạn có đi làm không?","明日あなたたちは仕事ですか。","你们"]],"err":[["您们好！","你们好！","ภาษาจีนมาตรฐานไม่ใช้ 您们 ให้ใช้ 你们好 หรือ 大家好","Standard Chinese does not use 您们; say 你们好 or 大家好.","规范汉语不说“您们”，应说“你们好／大家好”。","Không nói 您们, hãy dùng 你们好 hoặc 大家好.","「您们」は使わず「你们好／大家好」と言う。"],["大家们都去学校。","大家都去学校。","大家 เป็นพหูพจน์อยู่แล้ว ห้ามเติม 们","大家 is already plural — never add 们.","“大家”已是复数，不能加“们”。","大家 đã là số nhiều, không thêm 们.","「大家」は複数なので「们」は付けない。"]],"rel":["g3-1-002","g3-1-016","g3-1-035"]},"g3-1-010":{"t":["คำชี้เฉพาะ: 这 / 那 / 这儿 / 那儿 / 这些 / 那些","Demonstratives: 这 / 那 / 这儿 / 那儿 / 这些 / 那些","指示代词：这、那、这儿、那儿、这些、那些","Đại từ chỉ định: 这 / 那 / 这儿 / 那儿 / 这些 / 那些","指示代名詞：这・那・这儿・那儿・这些・那些"],"f":["这 / 那 + 量词 + 名词（这本书 / 那个人）","这些 / 那些 + 名词（这些苹果，不加量词）","这儿 / 这里（近）· 那儿 / 那里（远）"],"why":["这 = นี้ (ใกล้ตัวผู้พูด) · 那 = นั้น (ไกลออกไป) · เมื่อวางหน้าคำนามเอกพจน์ ต้องมีลักษณนามคั่นเสมอ (这本书, 那杯茶) ต่างจากภาษาไทยที่วาง 'นี้/นั้น' ไว้ท้ายคำนาม · ถ้าเป็นพหูพจน์ใช้ 这些 / 那些 + คำนามได้เลยโดยไม่ต้องมีลักษณนาม · 这儿/这里 = ที่นี่, 那儿/那里 = ที่นั่น (这儿 เป็นภาษาพูดภาคเหนือ, 这里 ใช้ทั่วไปและภาษาเขียน) · ระวัง: อย่าสับสน 那 nà (นั้น) กับ 哪 nǎ (ไหน)","这 = this (near), 那 = that (far). · Before a singular noun, ALWAYS insert a measure word (这本书, 那杯茶) — unlike Thai, where 'นี้/นั้น' follows the noun. · For plurals, use 这些 / 那些 directly before the noun (no measure word). · 这儿/这里 = here, 那儿/那里 = there. · Don't mix up 那 nà ('that') with 哪 nǎ ('which?').","“这”指近处，“那”指远处。 · 指单数名词时中间必须加量词（这本书、那杯茶）；指复数用“这些／那些＋名词”，不再加量词。 · “这儿／这里”表近处地点，“那儿／那里”表远处地点。 · 注意区分“那 nà”和疑问词“哪 nǎ”。","这 = này (gần), 那 = kia/đó (xa). · Trước danh từ số ít bắt buộc có lượng từ (这本书, 那杯茶) — ngược trật tự tiếng Việt/Thái. · Số nhiều dùng 这些 / 那些 + danh từ (không thêm lượng từ). · 这儿/这里 = ở đây, 那儿/那里 = ở kia. · Phân biệt 那 nà (đó) và 哪 nǎ (nào).","「这」は近く、「那」は遠くを指す。 · 単数名詞の前には必ず量詞を挟む（这本书・那杯茶）。 · 複数は「这些／那些＋名詞」で量詞不要。 · 「这儿／这里」＝ここ、「那儿／那里」＝あそこ。 · 「那 nà」と疑問詞「哪 nǎ」を混同しない。"],"use":[{"ok":true,"zh":"这本书很好看。","fix":"","py":"Zhè běn shū hěn hǎokàn.","tr":["หนังสือเล่มนี้น่าอ่านมาก","This book is very interesting.","Cuốn sách này rất hay.","この本はとても面白いです。"],"h":["ชี้เฉพาะเอกพจน์: 这/那 + ลักษณนาม + คำนาม","Singular: 这/那 + measure word + noun","单数指代：这／那＋量词＋名词","Số ít: 这/那 + lượng từ + danh từ","単数は「这／那＋量詞＋名詞」"],"w":["ทำได้เพราะวาง 这 ไว้หน้าคำนามและใส่ลักษณนาม 本 คั่น (ถ้ามีตัวเลข 一 จะละ 一 ออกได้ เช่น 这一本书 → 这本书)","Works because 这 precedes the noun with the measure word 本 between them (the numeral 一 is usually omitted: 这本书).","“这／那”放名词前并加量词“本”（数词“一”通常省略）。","Đúng vì 这 đứng trước danh từ và có lượng từ 本 ở giữa.","「这」を名詞の前に置き、間に量詞「本」を挟む（「一」は普通省略）。"],"ref":"ชนิดของคำ_12ชนิด · ประโยคตัวอย่าง_300"},{"ok":true,"zh":"这些苹果很便宜。","fix":"","py":"Zhèxiē píngguǒ hěn piányi.","tr":["แอปเปิลพวกนี้ถูกมาก","These apples are very cheap.","Những quả táo này rất rẻ.","これらのりんごはとても安いです。"],"h":["ชี้เฉพาะพหูพจน์: 这些 / 那些 + คำนาม (ไม่ต้องใส่ 个)","Plural: 这些 / 那些 + noun (no extra measure word)","复数用“这些／那些＋名词”，不加量词","Số nhiều dùng 这些 / 那些 + danh từ (không thêm 个)","複数は「这些／那些＋名詞」（量詞不要）"],"w":["ทำได้เพราะ 些 ในตัวทำหน้าที่บอกปริมาณไม่เจาะจง ('จำนวนหนึ่ง/พวก…') คล้ายลักษณนามอยู่แล้ว จึงต่อคำนาม 苹果 ได้ทันที","Works because 些 itself functions like a plural measure word ('some/these'), so the noun follows immediately.","“些”本身充当不定数量词，后面直接接名词，不能再加“个”。","Đúng vì 些 đã đóng vai trò lượng từ bất định nên nối thẳng danh từ.","「些」自体が不定の量詞の働きをするため、そのまま名詞を続けられる。"],"ref":"ชนิดของคำ_12ชนิด · HSK 3.0 g3-1-010"},{"ok":false,"zh":"这书很好看。","fix":"这本书很好看。","py":"Zhè běn shū hěn hǎokàn.","tr":["หนังสือเล่มนี้น่าอ่านมาก","This book is very interesting.","Cuốn sách này rất hay.","この本はとても面白いです。"],"h":["ห้ามละลักษณนามระหว่าง 这/那 กับคำนาม","Don't omit the measure word between 这/那 and a noun","“这／那”与名词间一般不能省量词","Không bỏ lượng từ giữa 这/那 và danh từ","「这／那」と名詞の間の量詞を省かない"],"w":["ไม่ได้ในประโยคปกติ เพราะภาษาจีนบังคับโครงสร้าง 这/那 + ลักษณนาม + คำนาม (这本书, 那个手机) ยกเว้นเวลาทำหน้าที่เป็นประธานแล้วตามด้วย 是 อย่าง 这是书 = นี่คือหนังสือ","Wrong in standard phrasing: 这/那 before a noun needs a measure word (这本书), unlike standalone subject 这是书 ('this is a book').","不行，修饰名词时必须加量词“这本书”；只有“这”独立作主语接“是”（这是书）时才不加量词。","Không được khi bổ nghĩa trực tiếp cho danh từ; phải có lượng từ 本 (这本书).","名詞を修飾するときは量詞が要る（这本书）。「这是书」のように主語として独立するときのみ不要。"],"ref":"HSK 3.0 g3-1-010"},{"ok":false,"zh":"这些个苹果很便宜。","fix":"这些苹果很便宜。","py":"Zhèxiē píngguǒ hěn piányi.","tr":["แอปเปิลพวกนี้ถูกมาก","These apples are very cheap.","Những quả táo này rất rẻ.","これらのりんごはとても安いです。"],"h":["หลัง 这些 / 那些 ห้ามเติมลักษณนามซ้ำ","Never add a measure word after 这些 / 那些","“这些／那些”后不能再加量词","Không thêm lượng từ sau 这些 / 那些","「这些／那些」の後に量詞を重ねない"],"w":["ไม่ได้ เพราะ 些 ทำหน้าที่แทนลักษณนามไปแล้ว ถ้าใส่ 个 ซ้ำเข้าไปจะผิดหลักไวยากรณ์ ต้องตัดออกเป็น 这些苹果","Wrong because 些 already fills the measure-word slot; adding 个 is redundant. Say 这些苹果.","不行，“些”已经占据量词位置，再加“个”重复且不规范。","Không được vì 些 đã thay vị trí lượng từ rồi, thêm 个 bị thừa.","「些」がすでに量詞の枠を占めているため、「个」を重ねてはいけない。"],"ref":"HSK 3.0 g3-1-010"}],"ex":[["这本书很好看。","Zhè běn shū hěn hǎokàn.","หนังสือเล่มนี้น่าอ่านมาก","This book is very interesting.","Cuốn sách này rất hay.","この本はとても面白いです。","这"],["那个手机很贵。","Nàge shǒujī hěn guì.","โทรศัพท์เครื่องนั้นแพงมาก","That phone is very expensive.","Chiếc điện thoại đó rất đắt.","あのスマホはとても高いです。","那个"],["这些苹果很便宜。","Zhèxiē píngguǒ hěn piányi.","แอปเปิลพวกนี้ถูกมาก","These apples are very cheap.","Những quả táo này rất rẻ.","これらのりんごはとても安いです。","这些"],["这里很漂亮。","Zhèlǐ hěn piàoliang.","ที่นี่สวยมาก","It is very pretty here.","Ở đây rất đẹp.","ここはとてもきれいです。","这里"],["我认识那个人。","Wǒ rènshi nàge rén.","ฉันรู้จักคนคนนั้น","I know that person.","Tôi quen người kia.","あの人を知っています。","那个"]],"err":[["书这很好看。","这本书很好看。","ภาษาจีนวาง 这/那 + ลักษณนาม ไว้หน้าคำนามเสมอ (这本书)","Put 这/那 + measure word before the noun (这本书).","指示代词和量词放在名词前面（这本书）。","Đặt 这/那 + lượng từ trước danh từ (这本书).","「这／那＋量詞」は必ず名詞の前に置く（这本书）。"],["这些个苹果很便宜。","这些苹果很便宜。","หลัง 这些 / 那些 ไม่ต้องเติมลักษณนามซ้ำ","Do not add another measure word after 这些 / 那些.","“这些／那些”后面不加量词。","Sau 这些 / 那些 không thêm lượng từ.","「这些／那些」の後ろに量詞は重ねない。"]],"rel":["g3-1-008","g3-1-012","g3-1-032"]},"g3-1-011":{"t":["二 / 两: เลข “สอง” ใช้ต่างกันอย่างไร","二 / 两: two ways to say 'two'","二、两：数字“2”的两种用法","二 / 两: hai cách nói số 'hai'","二・两：「2」の使い分け"],"f":["两 + 量词 + 名词（两个人 / 两本书 / 两点）","二（数数、序号、日期、多位数：一二三 / 第二 / 二号 / 十二）"],"why":["ภาษาจีนมีคำว่า 'สอง' สองตัวคือ 二 และ 两 ที่ใช้แทนกันไม่ได้ · หน้าลักษณนามเพื่อบอกจำนวนสิ่งของและเวลาโมง ใช้ 两 เสมอ (两个苹果, 两本书, 两点) · ส่วนการนับเลข (一、二、三), ลำดับที่ (第二), วันที่/เดือน (二月二号) และตัวเลขหลายหลัก (十二, 二十二) ใช้ 二","Chinese has two words for 'two' that cannot be swapped. · Before a measure word to count things or tell o'clock, always use 两 (两个苹果, 两本书, 两点). · For counting (一、二、三), ordinals (第二), dates/months (二月二号), and multi-digit numbers (十二, 二十二), use 二.","汉语的“2”分“二”和“两”，不能随意互换。 · 量词前表数量及钟点用“两”（两个苹果、两本书、两点）。 · 数数（一二三）、序数（第二）、日期月份（二月二号）和多位数（十二、二十二）用“二”。","Tiếng Trung phân biệt 二 và 两, không thay cho nhau tùy tiện. · Trước lượng từ đếm số lượng và giờ dùng 两 (两个苹果, 两点). · Đếm số, số thứ tự (第二), ngày tháng (二月二号) và số nhiều chữ số (十二, 二十二) dùng 二.","中国語の「2」は「二」と「两」を使い分ける。 · 量詞の前で数量や時刻を言うときは「两」（两个苹果・两本书・两点）。 · 数えるとき・序数（第二）・日付月（二月二号）・二桁以上の数字（十二・二十二）は「二」。"],"use":[{"ok":true,"zh":"我有两个苹果。","fix":"","py":"Wǒ yǒu liǎng ge píngguǒ.","tr":["ฉันมีแอปเปิลสองลูก","I have two apples.","Tôi có hai quả táo.","りんごが二つあります。"],"h":["หน้าลักษณนามใช้ 两 เสมอ","Always use 两 before a measure word","量词前用“两”","Trước lượng từ luôn dùng 两","量詞の前は必ず「两」"],"w":["ทำได้เพราะเรากำลังนับจำนวนสิ่งของ (2 ลูก) หน้าลักษณนาม 个 จึงต้องใช้ 两 (รวมถึง 两本书, 两个人, 两杯茶)","Works because we are counting items before the measure word 个 — always use 两 (also 两本书, 两个人, 两杯茶).","在量词“个、本、杯”等前表示数量“2”时，必须用“两”。","Đúng vì đang đếm số lượng trước lượng từ 个 nên phải dùng 两 (cũng như 两本书, 两个人).","量詞「个」の前で数量を数えるので必ず「两」を使う（两本书・两个人も同じ）。"],"ref":"กลุ่มเทียบคำ g9 · ประโยคตัวอย่าง_300"},{"ok":true,"zh":"今天二月二号。","fix":"","py":"Jīntiān èr yuè èr hào.","tr":["วันนี้วันที่สองกุมภาพันธ์","Today is February 2nd.","Hôm nay là ngày 2 tháng 2.","今日は2月2日です。"],"h":["เดือน วันที่ ลำดับที่ และเลขหลายหลักใช้ 二","Use 二 for months, dates, ordinals & multi-digit numbers","月份、日期、序数、多位数用“二”","Tháng, ngày, thứ tự và số nhiều chữ số dùng 二","月・日付・序数・二桁以上は「二」"],"w":["ทำได้เพราะ 二月 (เดือน 2) และ 二号 (วันที่ 2) เป็นลำดับในปฏิทิน ไม่ใช่การนับปริมาณสิ่งของ (ต่างจาก 'สองเดือน' ที่นับปริมาณเป็น 两个月)","Works because 二月 (February) and 二号 (the 2nd) name positions on a calendar rather than counting a quantity (contrast 两个月 'two months').","“二月、二号”表示日历上的顺序编号，不是数量，所以用“二”（对比：两个月）。","Đúng vì 二月 (tháng 2) và 二号 (ngày 2) là thứ tự lịch, không phải đếm số lượng (khác với 两个月 = 2 tháng).","「二月・二号」はカレンダーの順番なので「二」を使う（期間の「2か月＝两个月」とは区別する）。"],"ref":"กลุ่มเทียบคำ g9 · ประโยคตัวอย่าง_300"},{"ok":true,"zh":"现在两点。","fix":"","py":"Xiànzài liǎng diǎn.","tr":["ตอนนี้บ่ายสอง / ตีสอง (สองโมง)","It is two o'clock now.","Bây giờ là hai giờ.","今2時です。"],"h":["บอกเวลา 'สองโมง' ใช้ 两点","Tell 'two o'clock' with 两点","说“两点钟”用“两”","Nói 'hai giờ' dùng 两点","時刻の「2時」は「两点」"],"w":["ทำได้เพราะ 点 ใน HSK 3.0 จัดเป็นลักษณนามบอกเวลา (时量词) เวลา 2 นาฬิกาจึงพูดว่า 两点 เสมอ ไม่ใช่ 二点","Works because 点 acts as a time measure word in Chinese, so 2 o'clock is always 两点, never 二点.","“点”在语法中属时量词，表示两小时的钟点固定说“两点”，不说“二点”。","Đúng vì 点 là lượng từ thời gian nên 2 giờ luôn nói 两点, không nói 二点.","「点」は時間量詞なので2時は常に「两点」と言い、「二点」とは言わない。"],"ref":"HSK 3.0 g3-1-014 · g3-1-070"},{"ok":false,"zh":"我有二个苹果。","fix":"我有两个苹果。","py":"Wǒ yǒu liǎng ge píngguǒ.","tr":["ฉันมีแอปเปิลสองลูก","I have two apples.","Tôi có hai quả táo.","りんごが二つあります。"],"h":["ห้ามใช้ 二 หน้าลักษณนาม","Never use 二 directly before a measure word","量词前不能用“二”","Không dùng 二 trước lượng từ","量詞の前に「二」は使えない"],"w":["ไม่ได้ เพราะเลข 2 ตัวเดียวหน้าลักษณนามต้องใช้ 两 เสมอ (แต่ถ้าเป็นเลขหลักสิบลงท้ายด้วย 2 เช่น 十二个 หรือ 二十二个 ให้ใช้ 二 ได้)","Wrong because standalone '2' before a measure word must be 两 (only multi-digit numbers ending in 2 like 十二个 use 二).","不行，单独的“2”在量词前必须用“两”（但“十二个、二十二个”等尾数为2的多位数仍用“二”）。","Không được vì số 2 đứng một mình trước lượng từ phải dùng 两 (chỉ số nhiều chữ số như 十二个 mới dùng 二).","単独の「2」が量詞の前に来るときは必ず「两」（「十二个」のような二桁以上の末尾の2のみ「二」）。"],"ref":"กลุ่มเทียบคำ g9"},{"ok":false,"zh":"今天二十两号。","fix":"今天二十二号。","py":"Jīntiān èrshí èr hào.","tr":["วันนี้วันที่ 22","Today is the 22nd.","Hôm nay là ngày 22.","今日は22日です。"],"h":["ห้ามใช้ 两 ในหลักสิบและหลักหน่วย","Never use 两 in the tens or ones digit","十位和个位不能用“两”","Không dùng 两 ở hàng chục và hàng đơn vị","十の位・一の位に「两」は使えない"],"w":["ไม่ได้ เพราะหลักหน่วยและหลักสิบของตัวเลขหลายหลัก (12, 20, 22) ต้องใช้ 二 เท่านั้น (两 ใช้ได้แค่ตัวเดียวหน้าลักษณนาม หรือหลักร้อยขึ้นไปอย่าง 两百)","Wrong because the tens and ones digits of multi-digit numbers (12, 20, 22) always take 二, never 两.","不行，多位数的十位和个位（如12、20、22）只能用“二”，不能用“两”。","Không được vì hàng chục và hàng đơn vị trong số nhiều chữ số (12, 20, 22) chỉ dùng 二.","二桁以上の数字の十の位と一の位（12・20・22）は必ず「二」を使い、「两」は使えない。"],"ref":"กลุ่มเทียบคำ g9"}],"ex":[["我有两个苹果。","Wǒ yǒu liǎng ge píngguǒ.","ฉันมีแอปเปิลสองลูก","I have two apples.","Tôi có hai quả táo.","りんごが二つあります。","两"],["他买了两本书。","Tā mǎile liǎng běn shū.","เขาซื้อหนังสือสองเล่ม","He bought two books.","Anh ấy đã mua hai cuốn sách.","彼は本を二冊買いました。","两"],["现在两点。","Xiànzài liǎng diǎn.","ตอนนี้สองโมงแล้ว","It is two o'clock now.","Bây giờ là hai giờ.","今2時です。","两"],["今天二号。","Jīntiān èr hào.","วันนี้วันที่สอง","Today is the 2nd.","Hôm nay là ngày mùng 2.","今日は2日です。","二"],["今天二十二号。","Jīntiān èrshí èr hào.","วันนี้วันที่ 22","Today is the 22nd.","Hôm nay là ngày 22.","今日は22日です。","二"],["我们有两个老师。","Wǒmen yǒu liǎng ge lǎoshī.","พวกเรามีครูสองคน","We have two teachers.","Chúng tôi có hai giáo viên.","私たちには先生が二人います。","两"]],"err":[["我有二个苹果。","我有两个苹果。","หน้าลักษณนาม (个, 本, 杯) ต้องใช้ 两 ไม่ใช่ 二","Before a measure word, always use 两, not 二.","量词前表示数量用“两”，不用“二”。","Trước lượng từ dùng 两, không dùng 二.","量詞の前は「二」ではなく「两」を使う。"],["今天两号。","今天二号。","วันที่และเดือนใช้ 二 ไม่ใช่ 两","Dates and months use 二, not 两.","日期和月份用“二”，不用“两”。","Ngày và tháng dùng 二, không dùng 两.","日付や月は「两」ではなく「二」を使う。"],["现在二点。","现在两点。","เวลา 2 นาฬิกาใช้ 两点 ไม่ใช่ 二点","Two o'clock is always 两点, never 二点.","钟点“2点”固定说“两点”。","Hai giờ luôn nói 两点, không nói 二点.","時刻の2時は必ず「两点」と言う。"]],"rel":["g3-1-012","g3-1-069","g3-1-070"]},"g3-1-012":{"t":["ลักษณนามเฉพาะ: 本 / 个 / 家 / 口 / 块 / 件 / 只 / 元","Noun measure words: 本 / 个 / 家 / 口 / 块 / 件 / 只 / 元","专用名量词：本、个、家、口、块、件、只、元","Lượng từ danh từ: 本 / 个 / 家 / 口 / 块 / 件 / 只 / 元","名量詞：本・个・家・口・块・件・只・元"],"f":["数词 / 这 / 那 / 几 + 量词 + 名词（一本书 / 一只猫）"],"why":["ภาษาจีนต้องมีลักษณนาม (量词) คั่นระหว่างตัวเลข (หรือ 这/那/几) กับคำนามเสมอ เหมือนภาษาไทยแต่สลับลำดับ: จีนวาง 'จำนวน + ลักษณนาม' ไว้หน้าคำนาม (一本书 ไม่ใช่ 书一本) · ลักษณนามหลัก HSK 1: 个 (ทั่วไป/คน/ผลไม้), 本 (หนังสือ/สมุด), 件 (เสื้อผ้าท่อนบน/เรื่อง), 只 (สัตว์เล็กเช่น แมว หมา), 家 (ร้านค้า/โรงแรม/โรงพยาบาล), 口 (นับคนในครอบครัว), 块/元 (เงินหยวน: 块 ภาษาพูด, 元 ภาษาเขียน)","Chinese always needs a measure word between a numeral (or 这/那/几) and a noun, placed BEFORE the noun (一本书). · Core HSK 1 measure words: 个 (general/people/fruit), 本 (books), 件 (upper clothes/matters), 只 (small animals like cats/dogs), 家 (shops/restaurants/hospitals), 口 (family members), 块/元 (yuan: 块 spoken, 元 written).","数词或“这、那、几”与名词之间必须加量词，且放在名词前（一本书）。 · HSK 1 常用名量词：个（通用）、本（书籍）、件（上衣／事情）、只（猫狗等小动物）、家（商店／饭店／医院）、口（家庭人口）、块／元（货币：口语用“块”，书面用“元”）。","Tiếng Trung luôn cần lượng từ giữa số từ (hoặc 这/那/几) và danh từ, đặt TRƯỚC danh từ (一本书). · Lượng từ HSK 1: 个 (chung), 本 (sách), 件 (áo/việc), 只 (động vật nhỏ), 家 (cửa hàng/bệnh viện), 口 (thành viên gia đình), 块/元 (tệ).","数詞（または这・那・几）と名詞の間には必ず量詞を置き、名詞の前に並べる（一本书）。 · HSK1の名量詞：个（汎用）、本（本）、件（上着・用件）、只（猫・犬など小動物）、家（店・病院）、口（家族人数）、块／元（通貨：口語は块、書き言葉は元）。"],"use":[{"ok":true,"zh":"我有一本书。","fix":"","py":"Wǒ yǒu yī běn shū.","tr":["ฉันมีหนังสือหนึ่งเล่ม","I have a book.","Tôi có một cuốn sách.","本を一冊持っています。"],"h":["ใช้ลักษณนามเฉพาะตรงชนิดคำนาม (หนังสือ → 本)","Match the specific measure word to the noun (book → 本)","按名词类别搭配专用量词（一本书）","Dùng đúng lượng từ riêng cho từng danh từ (sách → 本)","名詞に合った専用量詞を選ぶ（本→本）"],"w":["ทำได้และเป็นธรรมชาติเหมือนภาษาไทยใช้ 'เล่ม' สำหรับหนังสือ (เสื้อใช้ 一件衣服, แมวใช้ 一只猫, ร้านอาหารใช้ 一家饭店)","Works naturally just like specific classifiers: 本 for books, 件 for clothes, 只 for cats/dogs, 家 for shops/restaurants.","书用“本”、衣服用“件”、猫狗用“只”、饭店用“家”，搭配准确地道。","Đúng và tự nhiên: sách dùng 本, áo dùng 件, mèo chó dùng 只, nhà hàng dùng 家.","本は「本」、服は「件」、猫犬は「只」、店は「家」と正しく対応させる。"],"ref":"เสริม w3-00010 · VOL 10 量词"},{"ok":true,"zh":"我家有四口人。","fix":"","py":"Wǒ jiā yǒu sì kǒu rén.","tr":["ครอบครัวฉันมีสี่คน","There are four people in my family.","Nhà tôi có bốn người.","私の家族は4人です。"],"h":["นับสมาชิกในครอบครัวใช้ 口 (แต่คนทั่วไปใช้ 个)","Use 口 for family members (个 for people in general)","说家庭人口用“口”，一般人数用“个”","Đếm người trong nhà dùng 口, người nói chung dùng 个","家族人数は「口」、一般の人は「个」"],"w":["ทำได้เพราะ 口 ในภาษาจีนใช้นับจำนวน 'ปากท้อง' ในครอบครัวโดยเฉพาะ (四口人) ส่วนถ้านับนักเรียนหรือเพื่อนทั่วไปใช้ 个 (四个学生)","Works because 口 specifically counts family members ('mouths to feed'), whereas ordinary groups of people take 个 (四个学生).","“口”专用于统计家庭人口（四口人），说学生、朋友等一般人数时用“个”。","Đúng vì 口 chuyên đếm thành viên trong gia đình, còn người nói chung dùng 个 (四个学生).","「口」は家族の人数専用。学生や友人など一般の人は「个」（四个学生）を使う。"],"ref":"กลุ่มเทียบคำ g10"},{"ok":false,"zh":"我有一个书。","fix":"我有一本书。","py":"Wǒ yǒu yī běn shū.","tr":["ฉันมีหนังสือหนึ่งเล่ม","I have a book.","Tôi có một cuốn sách.","本を一冊持っています。"],"h":["อย่าใช้ 个 แทนทุกอย่างเมื่อคำนั้นมีลักษณนามชัดเจน","Don't overuse 个 where a common specific measure word is expected","有明确常用量词时不随便用“个”","Không dùng 个 bừa bãi khi đã có lượng từ quen thuộc","定着した量詞がある語に安易に「个」を使わない"],"w":["ไม่ถูกต้องตามมาตรฐาน แม้ 个 จะใช้กว้าง แต่หนังสือเป็นคำพื้นฐานที่บังคับใช้ 本 (เช่นเดียวกับ 一件衣服, 一只猫 — ไม่พูด 一个书)","Unnatural/incorrect for core nouns: books strongly take 本 (and clothes take 件, cats take 只) — avoid 一个书.","不规范，虽然“个”用途广，但“书”固定配“本”（一本书），衣服配“件”，不说“一个书”。","Không chuẩn vì sách bắt buộc dùng 本 (一本书), áo dùng 件, mèo dùng 只 — không nói 一个书.","「个」は万能に近いが、「书」には必ず「本」（一本书）を使う。"],"ref":"เสริม w3-00010 · VOL 10 量词"},{"ok":false,"zh":"我有书一本。","fix":"我有一本书。","py":"Wǒ yǒu yī běn shū.","tr":["ฉันมีหนังสือหนึ่งเล่ม","I have a book.","Tôi có một cuốn sách.","本を一冊持っています。"],"h":["ห้ามวาง จำนวน + ลักษณนาม ไว้หลังคำนามแบบไทย","Never put numeral + measure word after the noun like Thai","数量词不能放在名词后面（除非列清单）","Không đặt số + lượng từ sau danh từ như tiếng Thái","数＋量詞を名詞の後ろに置かない"],"w":["ไม่ได้ในประโยคพูดปกติ เพราะภาษาไทยเรียง 'หนังสือ + หนึ่ง + เล่ม' แต่ภาษาจีนต้องเรียง 'หนึ่ง + เล่ม + หนังสือ' เสมอ (一本书)","Wrong in normal sentences because Thai puts 'book + 1 + CL' while Chinese always puts '1 + CL + book' (一本书).","不行，正常句子中数量短语必须在名词前（一本书），不能按泰语语序放后面。","Không được trong câu bình thường vì tiếng Trung luôn xếp 'số + lượng từ + danh từ' (一本书).","通常の文では必ず「数＋量詞＋名詞」（一本书）の順になる。"],"ref":"VOL 10 量词 · HSK 3.0 g3-1-032"}],"ex":[["我有一本书。","Wǒ yǒu yī běn shū.","ฉันมีหนังสือหนึ่งเล่ม","I have a book.","Tôi có một cuốn sách.","本を一冊持っています。","本"],["我买了两件衣服。","Wǒ mǎile liǎng jiàn yīfu.","ฉันซื้อเสื้อผ้ามาสองตัว","I bought two pieces of clothing.","Tôi đã mua hai chiếc áo.","服を二着買いました。","件"],["他有一只小猫。","Tā yǒu yī zhī xiǎo māo.","เขามีลูกแมวหนึ่งตัว","He has a kitten.","Anh ấy có một chú mèo con.","彼は子猫を一匹飼っています。","只"],["我家有四口人。","Wǒ jiā yǒu sì kǒu rén.","ครอบครัวฉันมีสี่คน","There are four people in my family.","Nhà tôi có bốn người.","私の家族は4人です。","口"],["这里有一家饭店。","Zhèlǐ yǒu yī jiā fàndiàn.","ที่นี่มีร้านอาหารหนึ่งร้าน","There is a restaurant here.","Ở đây có một nhà hàng.","ここにレストランが一軒あります。","家"],["这个苹果五块钱。","Zhège píngguǒ wǔ kuài qián.","แอปเปิลลูกนี้ราคาห้าหยวน","This apple costs five yuan.","Quả táo này giá năm tệ.","このりんごは5元です。","块"]],"err":[["我有一个书。","我有一本书。","หนังสือใช้ลักษณนาม 本 ไม่ใช่ 个","Books take 本, not 个.","书的量词是“本”，不是“个”。","Sách dùng lượng từ 本, không dùng 个.","本の量詞は「个」ではなく「本」。"],["我有书一本。","我有一本书。","ภาษาจีนวาง 'จำนวน + ลักษณนาม' ไว้หน้าคำนามเสมอ","Chinese always puts 'number + measure word' before the noun.","数量词必须放在名词前（一本书）。","Luôn đặt 'số + lượng từ' trước danh từ (一本书).","「数＋量詞」は常に名詞の前に置く。"]],"rel":["g3-1-011","g3-1-013","g3-1-032"]},"g3-1-013":{"t":["ลักษณนามยืมจากภาชนะ: 杯 (แก้ว/ถ้วย)","Container measure word: 杯 (cup/glass)","借用名量词：杯","Lượng từ mượn từ vật chứa: 杯 (cốc/ly)","借用量詞（容器）：杯（コップ1杯）"],"f":["数词 / 这 / 那 + 杯 + 饮品（一杯茶 / 两杯水）"],"why":["杯 เดิมเป็นคำนาม (ถ้วย/แก้ว, 杯子) ที่ถูก 'ยืม' มาใช้เป็นลักษณนามบอกปริมาณเครื่องดื่ม (借用名量词) · เวลาใช้เป็นลักษณนามให้ใช้แค่พยางค์เดียวว่า 杯 และห้ามใส่ 子 (一杯茶 ไม่ใช่ 一杯子茶) · เปลี่ยนเป็น 一杯水, 两杯牛奶, 这杯茶 ได้ทันที โดยไม่ต้องมี 的 คั่น","杯 comes from the container noun 杯子 ('cup/glass'), borrowed as a measure word for drinks. · When used as a measure word, use the bare syllable 杯 — NEVER keep 子 (一杯茶, not 一杯子茶). · Place it straight before the drink without 的: 一杯水, 两杯牛奶.","“杯”本是容器名词（杯子），借来作量词计量饮品。 · 作量词时只用单音节“杯”，不能带“子”（不说“一杯子茶”），且后接饮品名词时不加“的”。","杯 vốn là danh từ đồ chứa (杯子 = cái cốc), được mượn làm lượng từ đo đồ uống. · Khi làm lượng từ chỉ dùng 1 âm tiết 杯, KHÔNG giữ 子 (一杯茶, không nói 一杯子茶) và không cần 的.","「杯」は容器の名詞（杯子）を量詞として借用したもの。 · 量詞として使うときは必ず1音節の「杯」のみで「子」を付けず（一杯子茶は不可）、「的」も入れない。"],"use":[{"ok":true,"zh":"我要一杯茶。","fix":"","py":"Wǒ yào yī bēi chá.","tr":["ฉันขอชาหนึ่งแก้ว","I'd like a cup of tea.","Cho tôi một cốc trà.","お茶を一杯ください。"],"h":["ใช้ 杯 ตัวเดียวหน้าชื่อเครื่องดื่ม (ไม่ต้องมี 的)","Use bare 杯 directly before the drink (no 的)","“数词＋杯＋饮品”不加“的”","Dùng 杯 trực tiếp trước tên đồ uống (không có 的)","飲み物の前に「杯」だけを直接置く"],"w":["ทำได้เพราะ 杯 ทำหน้าที่เป็นลักษณนามบอกปริมาณ 1 แก้ว เหมือน 一杯水 (น้ำ 1 แก้ว), 两杯牛奶 (นม 2 แก้ว)","Works because 杯 acts as a container measure word measuring one cup of tea (just like 一杯水, 两杯牛奶).","“杯”直接充当量词计量茶水、牛奶等饮品。","Đúng vì 杯 làm lượng từ đo lượng đồ uống (như 一杯水, 两杯牛奶).","「杯」が飲み物の量を測る量詞として機能する（一杯水・两杯牛奶も同じ）。"],"ref":"HSK 3.0 g3-1-013 · VOL 10 量词"},{"ok":true,"zh":"我买了一个杯子。","fix":"","py":"Wǒ mǎile yī ge bēizi.","tr":["ฉันซื้อแก้วมาหนึ่งใบ","I bought a cup.","Tôi đã mua một cái cốc.","コップを一つ買いました。"],"h":["ถ้าพูดถึง 'ตัวแก้วเปล่า ๆ' (คำนาม) ใช้ 个 + 杯子","When referring to the cup itself as a noun, use 个 + 杯子","指杯子本身这个物体时用“一个杯子”","Nói về bản thân cái cốc (danh từ) dùng 一个杯子","コップという物自体を指すときは「一个杯子」"],"w":["ทำได้เพราะในประโยคนี้ไม่ได้นับปริมาณน้ำ แต่กำลังนับจำนวนภาชนะ จึงใช้คำนามเต็ม 杯子 คู่กับลักษณนาม 个","Works because here we are counting the physical cup itself (noun 杯子 with 个), not a cupful of liquid.","这里计量的是容器物体本身，所以用名词“杯子”配量词“个”。","Đúng vì đây là đếm vật thể cái cốc chứ không phải lượng nước bên trong.","ここでは容器のコップ自体を数えているので「一个杯子」になる。"],"ref":"HSK 3.0 g3-1-013"},{"ok":false,"zh":"我要一杯子茶。","fix":"我要一杯茶。","py":"Wǒ yào yī bēi chá.","tr":["ฉันขอชาหนึ่งแก้ว","I'd like a cup of tea.","Cho tôi một cốc trà.","お茶を一杯ください。"],"h":["ห้ามใส่ 子 เมื่อใช้ 杯 เป็นลักษณนาม","Never keep 子 when using 杯 as a measure word","作量词时绝不能说“一杯子茶”","Không giữ 子 khi dùng 杯 làm lượng từ","量詞の「杯」に「子」を付けない"],"w":["ไม่ได้ เพราะ 杯子 เป็นคำนามแปลว่า 'แก้ว 1 ใบ' ไม่ใช่ลักษณนาม เวลาบอกปริมาณเครื่องดื่มต้องตัด 子 ออกเหลือแค่ 一杯茶 (หรือ 一杯水)","Wrong because 杯子 is the noun 'cup', not the measure word; drop 子 when measuring drinks → 一杯茶.","不行，“杯子”是名词不能作量词，计量饮品必须去掉“子”说“一杯茶”。","Không được vì 杯子 là danh từ không phải lượng từ; phải bỏ 子 → 一杯茶.","「杯子」は名詞であり量詞ではない。飲み物を数えるときは「子」を取って「一杯茶」にする。"],"ref":"HSK 3.0 g3-1-013"}],"ex":[["我要一杯茶。","Wǒ yào yī bēi chá.","ฉันขอชาหนึ่งแก้ว","I'd like a cup of tea.","Cho tôi một cốc trà.","お茶を一杯ください。","杯"],["他喝了一杯水。","Tā hēle yī bēi shuǐ.","เขาดื่มน้ำไปหนึ่งแก้ว","He drank a glass of water.","Anh ấy uống một cốc nước.","彼は水を1杯飲みました。","杯"],["我早上喝两杯牛奶。","Wǒ zǎoshang hē liǎng bēi niúnǎi.","ตอนเช้าฉันดื่มนมสองแก้ว","I drink two glasses of milk in the morning.","Buổi sáng tôi uống hai cốc sữa.","朝、牛乳を2杯飲みます。","杯"],["这杯茶很好喝。","Zhè bēi chá hěn hǎohē.","ชาแก้วนี้อร่อยมาก","This cup of tea tastes great.","Cốc trà này rất ngon.","このお茶はとてもおいしいです。","杯"],["请给我一杯热茶。","Qǐng gěi wǒ yī bēi rè chá.","กรุณาขอชาร้อนให้ฉันหนึ่งแก้ว","Please give me a cup of hot tea.","Xin cho tôi một cốc trà nóng.","熱いお茶を一杯ください。","杯"]],"err":[["我要一杯子茶。","我要一杯茶。","ใช้เป็นลักษณนามต้องตัด 子 ออก (一杯茶 ไม่ใช่ 一杯子茶)","Drop 子 when using 杯 as a measure word (一杯茶).","作量词时去掉“子”（一杯茶）。","Làm lượng từ thì bỏ 子 (一杯茶).","量詞として使うときは「子」を取る（一杯茶）。"]],"rel":["g3-1-012","g3-1-011"]},"g3-1-014":{"t":["ลักษณนามเวลา: 日 / 号 / 岁 / 点 / 分 / 年 / 天","Time measure words: 日 / 号 / 岁 / 点 / 分 / 年 / 天","时量词：日、号、岁、点、分、年、天","Lượng từ thời gian: 日 / 号 / 岁 / 点 / 分 / 年 / 天","時間量詞：日・号・岁・点・分・年・天"],"f":["数词 + 年 / 天 / 岁（不加“个”：三年 / 两天 / 五岁）","几月 + 几号（口语）/ 几日（书面）"],"why":["คำบอกหน่วยเวลาอย่าง 年 (ปี), 天 (วัน), 岁 (ขวบ/ปีอายุ), 点 (โมง), 分 (นาที) เป็นลักษณนามในตัวเอง (时量词) อยู่แล้ว จึงวางติดตัวเลขได้เลย ห้ามใส่ 个 คั่นเด็ดขาด! (เช่น 两天 ไม่ใช่ 两个天, 三年 ไม่ใช่ 三个年) · แต่ระวังคำที่ต้องมี 个: 两个月 (สองเดือน), 两个小时 (สองชั่วโมง), 两个星期 (สองสัปดาห์) · ส่วน 号 (ภาษาพูด) และ 日 (ภาษาเขียน) ใช้บอกวันที่ ส่วน 岁 ใช้นับอายุ (ต่างจาก 年 ที่ใช้นับปีปฏิทิน)","Time units 年 (year), 天 (day), 岁 (years old), 点 (o'clock), and 分 (minute) are self-measuring time words — put them straight after numbers with NO 个 (两天, 三年, 五岁). · Contrast words that DO take 个: 两个月 (two months), 两个小时 (two hours), 两个星期 (two weeks). · 号 (spoken) vs 日 (written) give calendar dates; 岁 is for age (not 年).","“年、天、岁、点、分”本身属于时量词，直接跟在数词后，绝不能加“个”（两天、三年、五岁）。 · 对比必须加“个”的时间名词：两个月、两个小时、两个星期。 · 日期口语用“号”、书面用“日”；年龄用“岁”不用“年”。","Các đơn vị 年 (năm), 天 (ngày), 岁 (tuổi), 点 (giờ), 分 (phút) tự là lượng từ thời gian nên nối thẳng số từ, KHÔNG thêm 个 (两天, 三年, 五岁). · Ngược lại, 两个月 (2 tháng), 两个小时 (2 tiếng), 两个星期 (2 tuần) bắt buộc có 个. · Ngày: 号 (nói) / 日 (viết); tuổi dùng 岁 (không dùng 年).","「年・天・岁・点・分」はそれ自体が時間量詞なので、数詞の直後に置き「个」は入れない（两天・三年・五岁）。 · 一方「两个月・两个小时・两个星期」には「个」が必要。 · 日付は口語「号」・書き言葉「日」、年齢は「年」ではなく「岁」。"],"use":[{"ok":true,"zh":"我在北京住了三年。","fix":"","py":"Wǒ zài Běijīng zhùle sān nián.","tr":["ฉันอยู่ปักกิ่งมาสามปี","I lived in Beijing for three years.","Tôi đã sống ở Bắc Kinh ba năm.","私は北京に3年住みました。"],"h":["年 / 天 / 岁 ไม่ต้องมี 个 คั่น","年 / 天 / 岁 take no 个 before them","“年、天、岁”前不加“个”","年 / 天 / 岁 không thêm 个 phía trước","「年・天・岁」の前に「个」は入れない"],"w":["ทำได้เพราะ 年, 天, 岁 เป็นลักษณนามเวลาในตัว (时量词) จึงพูด 三年, 两天, 八岁 ได้เลยทันที","Works because 年, 天, and 岁 are already measure words themselves, so 三年, 两天, 八岁 need no 个.","“年、天、岁”本身就是量词，直接与数词组合（三年、两天、八岁）。","Đúng vì 年, 天, 岁 vốn là lượng từ sẵn nên ghép thẳng số từ (三年, 两天, 八岁).","「年・天・岁」は自体が量詞なので数詞と直接結びつく（三年・两天・八岁）。"],"ref":"HSK 3.0 g3-1-014 · กลุ่มเทียบคำ g19"},{"ok":true,"zh":"我学习了两个小时。","fix":"","py":"Wǒ xuéxíle liǎng ge xiǎoshí.","tr":["ฉันเรียนไปสองชั่วโมง","I studied for two hours.","Tôi đã học hai tiếng đồng hồ.","2時間勉強しました。"],"h":["小时 / 月 / 星期 เป็นคำนามเวลา ต้องมี 个 คั่น","小时 / 月 / 星期 require 个 when counting duration","“小时、月、星期”计数量时要加“个”","小时 / 月 / 星期 khi đếm thời lượng cần có 个","「小时・月・星期」の期間を数えるときは「个」が必要"],"w":["ทำได้เพราะต่างจาก 天/年 คำว่า 小时 (ชั่วโมง), 月 (เดือน), 星期 (สัปดาห์) เป็นคำนาม จึงต้องมีลักษณนาม 个 คั่นเป็น 两个小时, 三个月, 两个星期","Works because unlike 天/年, 小时 (hour), 月 (month), and 星期 (week) are nouns that take 个 for durations (两个小时, 三个月).","与“天、年”不同，“小时、月、星期”表时长时须加量词“个”（两个小时、三个月）。","Đúng vì khác với 天/年, 小时, 月, 星期 là danh từ nên cần 个 khi đếm thời lượng.","「天・年」と異なり「小时・月・星期」は名詞なので期間を数えるとき「个」を挟む。"],"ref":"HSK 3.0 g3-1-014"},{"ok":false,"zh":"我在北京住了三个年。","fix":"我在北京住了三年。","py":"Wǒ zài Běijīng zhùle sān nián.","tr":["ฉันอยู่ปักกิ่งมาสามปี","I lived in Beijing for three years.","Tôi đã sống ở Bắc Kinh ba năm.","北京に3年住みました。"],"h":["ห้ามใส่ 个 หน้า 年 / 天 / 岁","Never put 个 before 年 / 天 / 岁","“年、天、岁”前绝不能加“个”","Tuyệt đối không thêm 个 trước 年 / 天 / 岁","「年・天・岁」の前に「个」を入れない"],"w":["ไม่ได้ เพราะ 年 กับ 天 เป็นลักษณนามอยู่แล้ว การใส่ 个 เข้าไปจะกลายเป็นลักษณนามซ้อนสองตัว ต้องตัดออกเป็น 三年 / 两天","Wrong because 年 and 天 are already measure words; adding 个 creates double measure words. Say 三年 / 两天.","不行，“年、天”本身已是量词，加“个”造成量词重叠，应说“三年、两天”。","Không được vì 年, 天 đã là lượng từ sẵn, thêm 个 bị trùng lượng từ. Phải nói 三年 / 两天.","「年・天」はすでに量詞なので「个」を付けると量詞が重複する。「三年・两天」にする。"],"ref":"HSK 3.0 g3-1-014"},{"ok":false,"zh":"我的孩子五年龄。","fix":"我的孩子五岁。","py":"Wǒ de háizi wǔ suì.","tr":["ลูกของฉันอายุห้าขวบ","My child is five years old.","Con tôi năm tuổi.","私の子どもは5歳です。"],"h":["บอกอายุใช้ 岁 ไม่ใช้ 年","Use 岁 for age, never 年","说年龄用“岁”，不用“年”","Nói tuổi dùng 岁, không dùng 年","年齢は「年」ではなく「岁」"],"w":["ไม่ได้ เพราะในภาษาไทยพูด 'ห้าปี / ห้าขวบ' แต่ภาษาจีนแยกชัดเจน: อายุคนใช้ 岁 (五岁) ส่วนระยะเวลาปีปฏิทินใช้ 年 (五年)","Wrong because Chinese strictly separates age (岁: 五岁) from calendar years (年: 五年).","不行，汉语严格区分年龄用“岁”（五岁）、时间长度用“年”（五年）。","Không được vì tiếng Trung tách rõ tuổi dùng 岁 (五岁), còn số năm dùng 年 (五年).","年齢は必ず「岁」（五岁）、年数は「年」（五年）と厳密に区別する。"],"ref":"กลุ่มเทียบคำ g19"}],"ex":[["我在中国住了三年。","Wǒ zài Zhōngguó zhùle sān nián.","ฉันอยู่ประเทศจีนมาสามปี","I lived in China for three years.","Tôi đã sống ở Trung Quốc ba năm.","中国に3年住みました。","年"],["他休息了两天。","Tā xiūxile liǎng tiān.","เขาพักผ่อนไปสองวัน","He rested for two days.","Anh ấy đã nghỉ hai ngày.","彼は2日間休みました。","天"],["我的孩子五岁。","Wǒ de háizi wǔ suì.","ลูกของฉันอายุห้าขวบ","My child is five years old.","Con tôi năm tuổi.","私の子どもは5歳です。","岁"],["今天五月十号。","Jīntiān wǔ yuè shí hào.","วันนี้วันที่ 10 พฤษภาคม","Today is May 10th.","Hôm nay là ngày 10 tháng 5.","今日は5月10日です。","号"],["现在八点十分。","Xiànzài bā diǎn shí fēn.","ตอนนี้แปดโมงสิบนาที","It is 8:10 now.","Bây giờ là 8 giờ 10 phút.","今8時10分です。","分"]],"err":[["我在中国住了三个年。","我在中国住了三年。","年 กับ 天 เป็นลักษณนามเวลาในตัว ห้ามใส่ 个 คั่น","年 and 天 are self-measuring — never insert 个.","“年、天”本身是量词，不能加“个”。","年 và 天 vốn là lượng từ, không thêm 个.","「年・天」は自体が量詞なので「个」を入れない。"],["我的孩子五年。","我的孩子五岁。","บอกอายุคนใช้ 岁 ไม่ใช่ 年","Use 岁 for a person's age, not 年.","年龄用“岁”，不用“年”。","Nói tuổi dùng 岁, không dùng 年.","年齢には「年」ではなく「岁」を使う。"]],"rel":["g3-1-069","g3-1-070","g3-1-012"]},"g3-1-015":{"t":["很 / 非常 / 太 / 真 / 有点儿: คำบอกระดับ","很 / 非常 / 太 / 真 / 有点儿: degree adverbs","很、非常、太、真、有点儿：程度副词","很 / 非常 / 太 / 真 / 有点儿: phó từ chỉ mức độ","很・非常・太・真・有点儿：程度副詞"],"f":["主语 + 很 / 非常 + 形容词（他很高）","主语 + 太 + 形容词 + 了！（太贵了！）","主语 + 有点儿 + 形容词（今天有点儿冷）"],"why":["ภาษาจีนเวลาบรรยายลักษณะด้วยคำคุณศัพท์มักต้องมี 很 นำหน้าแม้ไม่ได้เน้นว่า 'มาก' (他很高 = เขาสูง) เพราะถ้าไม่มี 很 จะฟังเหมือนกำลังเปรียบเทียบ · 非常 เน้นระดับสูงกว่า 很 · 太…了 ใช้บอกว่าเกินพอดี (太贵了) หรืออุทานชม (太好了！) · 真 ใช้อุทานความรู้สึกจริง และไม่ใช้ขยายคำนาม · 有点儿 วางหน้าคำคุณศัพท์แปลว่า '…ไปหน่อย' (มักไม่ค่อยพอใจ) ตรงข้ามกับ 一点儿 ที่วางหลังกริยาหรือหน้าคำนาม","Chinese adjective predicates normally take 很 even without strong emphasis (他很高 'he is tall'); omitting 很 implies contrast. · 非常 is stronger than 很. · 太…了 means 'too…' or enthusiastic praise (太好了！). · 真 is for exclamations and cannot modify a noun phrase directly. · 有点儿 goes BEFORE adjectives ('a bit too…', usually negative), unlike 一点儿 which follows verbs/adjectives.","汉语形容词作谓语时前面常加“很”，不一定强调“非常”（他很高）；不加“很”往往带有对比意味。 · “非常”程度比“很”更强。 · “太……了”表程度过头（太贵了）或赞叹（太好了！）。 · “真”多用于感叹，一般不修饰定语。 · “有点儿”放在形容词前，多表不如意；与放在动词／形容词后的“一点儿”位置相反。","Vị ngữ tính từ thường cần 很 phía trước dù không nhấn mạnh 'rất' (他很高 = anh ấy cao). · 非常 mạnh hơn 很. · 太…了 diễn tả quá mức (太贵了) hoặc cảm thán (太好了！). · 真 dùng để cảm thán, không làm định ngữ trước danh từ. · 有点儿 đứng TRƯỚC tính từ ('hơi… quá'), ngược vị trí với 一点儿.","中国語の形容詞述語は強調しなくても「很」を付けるのが普通（他很高＝彼は背が高い）。付けないと対比の意味が出る。 · 「非常」は「很」より強い。 · 「太…了」は過度（太贵了）や感嘆（太好了！）。 · 「真」は感嘆専用で名詞の修飾には使わない。 · 「有点儿」は形容詞の前（「ちょっと〜すぎる」、不満寄り）で、後ろに置く「一点儿」と位置が逆。"],"use":[{"ok":true,"zh":"他很高。","fix":"","py":"Tā hěn gāo.","tr":["เขาสูง","He is tall.","Anh ấy cao.","彼は背が高いです。"],"h":["ประโยคคุณศัพท์ใส่ 很 เพื่อเชื่อมให้เป็นธรรมชาติ","Add 很 before an adjective predicate for natural phrasing","形容词谓语加“很”最自然","Thêm 很 trước vị ngữ tính từ cho tự nhiên","形容詞述語には「很」を添えるのが自然"],"w":["ทำได้และควรทำ เพราะในภาษาจีนถ้าพูดแค่ 他高 จะฟังเหมือนประโยคยังไม่จบหรือกำลังเทียบว่า 'เขาสูง (ส่วนอีกคนเตี้ย)' การใส่ 很 ทำให้เป็นประโยคบรรยายธรรมดา (ไม่ต้องใส่ 是 ด้วย!)","Natural and standard: bare 他高 sounds contrastive ('he is the tall one…'). Adding 很 turns it into a neutral statement — and never insert 是 before adjectives!","单说“他高”有对比意味，加上“很”才成为自然陈述；形容词谓语前也不用加“是”。","Tự nhiên và chuẩn mực: nói trơn 他高 nghe như đang so sánh. Thêm 很 thành câu trần thuật bình thường (và không thêm 是).","「他高」だけだと対比の響きになる。「很」を添えて普通の描写にする（また「是」は入れない）。"],"ref":"กลุ่มเทียบคำ g14 · เสริม w3-00079"},{"ok":true,"zh":"今天有点儿冷。","fix":"","py":"Jīntiān yǒudiǎnr lěng.","tr":["วันนี้หนาวไปหน่อย","Today is a bit cold.","Hôm nay hơi lạnh một chút.","今日は少し寒いです。"],"h":["วาง 有点儿 หน้าคำคุณศัพท์ (มักเป็นเรื่องที่ไม่ค่อยพอใจ)","Place 有点儿 before an adjective (often a mild complaint)","“有点儿”放在形容词前","Đặt 有点儿 trước tính từ","「有点儿」は形容詞の前"],"w":["ทำได้เพราะ 有点儿 เป็นคำวิเศษณ์บอกระดับ จึงวางหน้าคำคุณศัพท์ 冷 เพื่อบอกว่าหนาวเกินไปนิดหน่อย (ไม่สบายตัว)","Works because 有点儿 is a degree adverb that precedes adjectives like 冷 to express a mild undesired degree.","“有点儿”是程度副词，放在形容词前，多表达说话人不太满意的程度。","Đúng vì 有点儿 là phó từ chỉ mức độ, đứng trước tính từ 冷 để nói hơi quá mức mong muốn.","「有点儿」は程度副詞なので形容詞「冷」の前に置き、少し望ましくない程度を表す。"],"ref":"กลุ่มเทียบคำ g15 · ประโยคตัวอย่าง_300"},{"ok":true,"zh":"我会说一点儿汉语。","fix":"","py":"Wǒ huì shuō yīdiǎnr Hànyǔ.","tr":["ฉันพูดภาษาจีนได้นิดหน่อย","I can speak a little Chinese.","Tôi biết nói một chút tiếng Trung.","中国語が少し話せます。"],"h":["วาง 一点儿 หลังกริยา / หน้าคำนาม เพื่อบอกปริมาณน้อย","Place 一点儿 after a verb / before a noun for a small amount","“一点儿”放动词后、名词前表少量","Đặt 一点儿 sau động từ / trước danh từ chỉ lượng ít","「一点儿」は動詞の後・名詞の前で少量を表す"],"w":["ทำได้เพราะ 一点儿 บอกปริมาณเล็กน้อย ('นิดหน่อย') จึงวางหลังกริยา 说 และหน้าคำนาม 汉语 ได้อย่างเป็นธรรมชาติ","Works because 一点儿 quantifies a small amount ('a little') right after the verb 说 and before the noun 汉语.","“一点儿”表少量，自然用在动词后、名词前（说一点儿汉语、喝一点儿水）。","Đúng vì 一点儿 chỉ số lượng ít, đứng sau động từ 说 và trước danh từ 汉语.","「一点儿」は少量を表し、動詞の後・名詞の前に置く（说一点儿汉语・喝一点儿水）。"],"ref":"กลุ่มเทียบคำ g15 · ประโยคตัวอย่าง_300"},{"ok":false,"zh":"我很是学生。","fix":"我是学生。","py":"Wǒ shì xuésheng.","tr":["ฉันเป็นนักเรียน","I am a student.","Tôi là học sinh.","私は学生です。"],"h":["ห้ามใช้ 很 นำหน้า 是 หรือคำกริยาทั่วไป","Never put 很 before 是 or ordinary action verbs","“很”不能修饰“是”和一般动作动词","Không đặt 很 trước 是 hoặc động từ hành động","「很」は「是」や一般動作動詞の前に置けない"],"w":["ไม่ได้ เพราะ 很 ขยายได้เฉพาะคำคุณศัพท์ (很好, 很贵) และกริยาบอกความรู้สึก (很喜欢, 很想) เท่านั้น ไม่สามารถขยาย 是 หรือกริยาการกระทำอย่าง 吃/去 ได้","Wrong because 很 only modifies adjectives (很好) and psychological verbs (很喜欢, 很想) — never 是 or action verbs like 吃/去.","不行，“很”只能修饰形容词和心理动词（很好、很喜欢），不能用在“是”或一般动作动词前。","Không được vì 很 chỉ bổ nghĩa cho tính từ và động từ tâm lý (很好, 很喜欢), không đứng trước 是.","「很」は形容詞と心理動詞（很好・很喜欢）のみ修飾でき、「是」や一般動作動詞の前には置けない。"],"ref":"เสริม w3-00079"},{"ok":false,"zh":"今天一点儿冷。","fix":"今天有点儿冷。","py":"Jīntiān yǒudiǎnr lěng.","tr":["วันนี้หนาวไปหน่อย","Today is a bit cold.","Hôm nay hơi lạnh một chút.","今日は少し寒いです。"],"h":["ห้ามวาง 一点儿 หน้าคำคุณศัพท์","Never put 一点儿 before an adjective","形容词前不能用“一点儿”","Không đặt 一点儿 trước tính từ","形容詞の前に「一点儿」は置けない"],"w":["ไม่ได้ เพราะตำแหน่งสลับกัน: หน้าคำคุณศัพท์ต้องใช้ 有点儿 (有点儿冷) ส่วน 一点儿 ใช้บอกปริมาณหลังกริยาหรือวางหลังคุณศัพท์เพื่อเปรียบเทียบ","Wrong because their positions are opposite: BEFORE an adjective use 有点儿 (有点儿冷); 一点儿 goes AFTER a verb/adjective.","不行，两者位置相反：形容词前必须用“有点儿”（有点儿冷），“一点儿”用于动词后或形容词后。","Không được vì ngược vị trí: trước tính từ phải dùng 有点儿 (有点儿冷), còn 一点儿 đứng sau động từ/tính từ.","位置が逆。形容詞の前は必ず「有点儿」（有点儿冷）を使い、「一点儿」は動詞や形容詞の後ろに置く。"],"ref":"กลุ่มเทียบคำ g15"},{"ok":false,"zh":"他是一个真好的人。","fix":"他是一个很好的人。","py":"Tā shì yī ge hěn hǎo de rén.","tr":["เขาเป็นคนดีมาก","He is a very good person.","Anh ấy là một người rất tốt.","彼はとてもいい人です。"],"h":["ไม่ใช้ 真 ขยายคำนาม (定语) แบบ 很","Don't use 真 inside a noun modifier","“真”一般不用于定语修饰名词","Không dùng 真 trong cụm bổ nghĩa danh từ","名詞を修飾する定語には「真」を使わない"],"w":["ไม่ได้ เพราะ 真 เป็นคำวิเศษณ์เชิงอุทาน ใช้เป็นภาคแสดงจบความรู้สึก (今天天气真好！) แต่ถ้าจะขยายคำนาม (…的人) ต้องใช้ 很 หรือ 非常","Wrong because 真 is exclamatory for predicates (今天天气真好！); to modify a noun (…的人), use 很 or 非常.","不行，“真”带强烈感叹语气，一般只用于谓语（天气真好！）；作定语修饰名词时应换用“很”或“非常”。","Không được vì 真 mang sắc thái cảm thán dùng ở vị ngữ (天气真好！); khi bổ nghĩa cho danh từ dùng 很 hoặc 非常.","「真」は感嘆の述語専用（天气真好！）。名詞を修飾する「〜的人」には「很／非常」を使う。"],"ref":"กลุ่มเทียบคำ g14"}],"ex":[["他很高。","Tā hěn gāo.","เขาสูง","He is tall.","Anh ấy cao.","彼は背が高いです。","很"],["今天天气非常热。","Jīntiān tiānqì fēicháng rè.","วันนี้อากาศร้อนมาก ๆ","Today's weather is extremely hot.","Thời tiết hôm nay vô cùng nóng.","今日はとても暑いです。","非常"],["这个手机太贵了。","Zhège shǒujī tài guì le.","โทรศัพท์เครื่องนี้แพงเกินไป","This phone is too expensive.","Chiếc điện thoại này đắt quá.","このスマホは高すぎます。","太"],["今天天气真好！","Jīntiān tiānqì zhēn hǎo!","วันนี้อากาศดีจริง ๆ!","The weather is really great today!","Thời tiết hôm nay thật đẹp!","今日は本当にいい天気ですね！","真"],["今天有点儿冷。","Jīntiān yǒudiǎnr lěng.","วันนี้หนาวไปหน่อย","Today is a bit cold.","Hôm nay hơi lạnh.","今日は少し寒いです。","有点儿"],["我很喜欢看书。","Wǒ hěn xǐhuan kàn shū.","ฉันชอบอ่านหนังสือมาก","I really like reading.","Tôi rất thích đọc sách.","私は読書がとても好きです。","很"]],"err":[["我很是学生。","我是学生。","很 ใช้กับคำคุณศัพท์และกริยาบอกความรู้สึก ไม่ใช้หน้า 是","很 modifies adjectives and feeling verbs, never 是.","“很”修饰形容词和心理动词，不能用在“是”前。","很 đi với tính từ và động từ tâm lý, không đứng trước 是.","「很」は形容詞や心理動詞に使い、「是」の前には置かない。"],["今天一点儿冷。","今天有点儿冷。","วางหน้าคำคุณศัพท์ต้องใช้ 有点儿 ไม่ใช่ 一点儿","Before an adjective, use 有点儿, not 一点儿.","形容词前用“有点儿”，不用“一点儿”。","Trước tính từ dùng 有点儿, không dùng 一点儿.","形容詞の前は「一点儿」ではなく「有点儿」。"],["他是一个真好的人。","他是一个很好的人。","ขยายคำนามใช้ 很 (หรือ 非常) ไม่ใช้ 真","Use 很 (or 非常) inside noun modifiers, not 真.","修饰名词作定语用“很／非常”，不用“真”。","Bổ nghĩa danh từ dùng 很 / 非常, không dùng 真.","名詞を修飾するときは「真」ではなく「很／非常」。"]],"rel":["g3-1-043","g3-1-051"]},"g3-1-016":{"t":["都: ทั้งหมด / ล้วน / ต่างก็","都: 'all / both' (position & negation)","副词“都”：总括全部与位置","都: 'đều / tất cả' (vị trí & phủ định)","副詞「都」：すべて・どちらも（語順と否定）"],"f":["复数主语 + 都 + 动词 / 形容词（我们都去）","都不（全都不）vs 不都（不是全部都）"],"why":["都 แปลว่า 'ทั้งหมด / ล้วน / ต่างก็' ทำหน้าที่เป็นคำวิเศษณ์ (副词) จึงต้องวางหลังประธานและหน้ากริยาหรือคุณศัพท์เสมอ ไม่วางต้นประโยคแบบคำว่า 'ทุกคน' ในภาษาไทย · ประธานข้างหน้าต้องเป็นพหูพจน์ (ตั้งแต่ 2 ขึ้นไป เช่น 我们, 爸爸和妈妈, 这些书) · ข้อควรระวังสำคัญ: ลำดับการปฏิเสธเปลี่ยนความหมาย! 都不 = ไม่เลยสักคน (ปฏิเสธทั้งหมด) ส่วน 不都 = ไม่ได้ทั้งหมด (บางคนใช่ บางคนไม่ใช่)","都 ('all / both') is an adverb, so it ALWAYS goes after the subject and before the verb or adjective — never at the very start of the sentence. · The noun before 都 must be plural (at least two: 我们, 爸爸和妈妈, 这些书). · Watch negation order: 都不 means 'none of them', whereas 不都 means 'not all of them'.","“都”是范围副词，表示总括前面提到的全部人或事物，必须放在主语之后、动词／形容词之前，绝不能放在句首。 · “都”所总括的对象须为复数（我们、爸爸和妈妈、这些书等）。 · 注意否定语序：“都不”表全部否定（一个也不），“不都”表部分否定（不是全部都）。","都 ('đều / tất cả') là phó từ, luôn đứng sau chủ ngữ và trước động từ / tính từ, không bao giờ đứng đầu câu. · Chủ ngữ trước 都 phải là số nhiều (từ 2 trở lên). · Chú ý phủ định: 都不 = tất cả đều không; 不都 = không phải tất cả đều.","「都」は範囲副詞で、必ず主語の後・動詞や形容詞の前に置き、文頭には置けない。 · 前に来る対象は複数（我们・爸爸和妈妈・这些书など）。 · 否定の語順に注意：「都不」は全否定（どれも〜ない）、「不都」は部分否定（すべてが〜なわけではない）。"],"use":[{"ok":true,"zh":"我们都是学生。","fix":"","py":"Wǒmen dōu shì xuésheng.","tr":["พวกเราทุกคนเป็นนักเรียน","We are all students.","Chúng tôi đều là học sinh.","私たちはみんな学生です。"],"h":["วาง 都 หลังประธานพหูพจน์และหน้ากริยา","Place 都 after a plural subject and before the verb","“都”放复数主语后、动词前","Đặt 都 sau chủ ngữ số nhiều, trước động từ","「都」は複数主語の後・動詞の前"],"w":["ทำได้เพราะ 我们 เป็นพหูพจน์ และ 都 วางอยู่หน้ากริยา 是 เพื่อรวบยอดประธานทั้งหมดข้างหน้า (ภาษาจีนรวบสิ่งที่อยู่ 'ข้างหน้า' 都 เสมอ)","Works because 我们 is plural and 都 sits before 是, summarizing everything that precedes it.","“我们”是复数，“都”紧跟在动词“是”前，总括前面的主语。","Đúng vì 我们 là số nhiều và 都 đứng ngay trước động từ 是 để bao quát toàn bộ chủ ngữ phía trước.","「我们」が複数で、動詞「是」の直前に「都」を置くことで前の主語全体をまとめる。"],"ref":"เสริม w3-00041 · ชนิดของคำ_12ชนิด"},{"ok":true,"zh":"他们都不喝茶。","fix":"","py":"Tāmen dōu bù hē chá.","tr":["พวกเขาไม่มีใครดื่มชาเลย","None of them drink tea.","Họ đều không uống trà.","彼らは誰も茶を飲みません。"],"h":["都不 = ปฏิเสธทั้งหมด (ไม่เลยสักคน)","都不 = total negation ('none of them')","“都不”表示全部否定","都不 = phủ định hoàn toàn (không ai cả)","「都不」は全否定（誰も〜ない）"],"w":["ทำได้เมื่อต้องการบอกว่า 'ทุกคนล้วนไม่…' (100% ไม่ดื่มชา) เพราะ 都 ครอบคลุมกริยาปฏิเสธ 不喝 อยู่ข้างหลังทั้งหมด","Works for total negation ('every single one of them does not drink tea') because 都 scopes over 不喝.","“都”在“不”前，总括后面整个否定动作，表示“所有人一个都不喝”。","Đúng khi muốn phủ định hoàn toàn ('tất cả đều không uống trà').","「都」が「不」の前にあると「全員が飲まない（ゼロ）」という全否定になる。"],"ref":"HSK 3.0 g3-1-016 · g3-1-020"},{"ok":true,"zh":"他们不都是学生。","fix":"","py":"Tāmen bù dōu shì xuésheng.","tr":["พวกเขาไม่ได้เป็นนักเรียนทุกคน (บางคนใช่ บางคนไม่ใช่)","Not all of them are students.","Họ không phải tất cả đều là học sinh.","彼ら全員が学生というわけではない。"],"h":["不都 = ปฏิเสธบางส่วน (ไม่ได้ทั้งหมด)","不都 = partial negation ('not all')","“不都”表示部分否定","不都 = phủ định một phần (không phải tất cả)","「不都」は部分否定（全員ではない）"],"w":["ทำได้เมื่อต้องการบอกว่า 'ไม่ได้เป็นทุกคน' เพราะ 不 วางหน้า 都 จึงไปปฏิเสธคำว่า 'ทั้งหมด' โดยตรง","Works for partial negation ('some are, some aren't') because 不 precedes and negates 'all' (都).","“不”放在“都”前，直接否定“全部”，表示一部分是、一部分不是。","Đúng khi muốn nói 'không phải ai cũng là học sinh' vì 不 đứng trước phủ định trực tiếp 都.","「不」を「都」の前に置くと「すべて」を否定し、部分否定（一部はそうでない）になる。"],"ref":"HSK 3.0 g3-1-016 · g3-1-020"},{"ok":false,"zh":"都我们去。","fix":"我们都去。","py":"Wǒmen dōu qù.","tr":["พวกเราไปกันหมด","We are all going.","Chúng tôi đều đi.","私たちはみんな行きます。"],"h":["ห้ามวาง 都 ไว้หน้าประธาน","Never put 都 before the subject","“都”绝对不能放在主语前","Không bao giờ đặt 都 trước chủ ngữ","「都」は主語の前に置けない"],"w":["ไม่ได้ เพราะภาษาไทยพูดว่า 'ทุกคนไป' หรือ 'ทั้งหมดเราไป' ได้ แต่ในภาษาจีน 都 เป็นคำวิเศษณ์ (ไม่ใช่สรรพนาม) จึงวางหน้าประธานไม่ได้เด็ดขาด ต้องเป็น 我们都去","Wrong because 都 is an adverb, not a pronoun like 'all/everyone' — it can never start a clause before the subject. Say 我们都去.","不行，“都”是副词而非代词，不能放在主语之前，必须说“我们都去”。","Không được vì 都 là phó từ chứ không phải đại từ, không thể đứng đầu câu trước chủ ngữ. Phải nói 我们都去.","「都」は代名詞ではなく副詞なので主語の前には置けない。「我们都去」とする。"],"ref":"เสริม w3-00041"},{"ok":false,"zh":"我都买苹果和茶。","fix":"苹果和茶我都买。","py":"Píngguǒ hé chá wǒ dōu mǎi.","tr":["ทั้งแอปเปิลและชา ฉันซื้อหมดเลย","I'll buy both the apples and the tea.","Táo và trà tôi đều mua.","りんごもお茶も両方買います。"],"h":["都 ไม่สามารถรวบกรรมที่อยู่ข้างหลังได้","都 only summarizes what comes BEFORE it, never after","“都”只总括前面的成分，不管后面","都 chỉ bao quát phần đứng TRƯỚC nó","「都」は前にある語しかまとめられない"],"w":["ไม่ได้ เพราะ 都 มองย้อนไปข้างหน้าเท่านั้น ข้างหน้า 都 มีแค่ 我 (คนเดียว) จึงผิดหลักพหูพจน์ ถ้าจะรวบทั้งแอปเปิลและชา ต้องย้าย 苹果和茶 มาไว้หน้า 都 เป็น 苹果和茶我都买","Wrong because 都 only looks backward, and 我 is singular. Move the plural object before 都: 苹果和茶我都买.","不行，“都”只能总括前面的复数成分，这里前面只有单数“我”。须把复数宾语提前：苹果和茶我都买。","Không được vì 都 chỉ gom phần phía trước, mà 我 là số ít. Phải đưa tân ngữ số nhiều lên trước: 苹果和茶我都买.","「都」は後ろではなく前の要素しかまとめられない。「我」は単数なので、複数の目的語を前に出して「苹果和茶我都买」とする。"],"ref":"เสริม w3-00041 · HSK 3.0 g3-1-016"}],"ex":[["我们都去。","Wǒmen dōu qù.","พวกเราไปกันทั้งหมด","We are all going.","Chúng tôi đều đi.","私たちはみんな行きます。","都"],["我们都是学生。","Wǒmen dōu shì xuésheng.","พวกเราล้วนเป็นนักเรียน","We are all students.","Chúng tôi đều là học sinh.","私たちはみんな学生です。","都"],["爸爸和妈妈都在家。","Bàba hé māma dōu zài jiā.","พ่อและแม่อยู่บ้านทั้งคู่","Both Mom and Dad are at home.","Bố và mẹ đều ở nhà.","父も母も家にいます。","都"],["他们都不喝茶。","Tāmen dōu bù hē chá.","พวกเขาไม่มีใครดื่มชาเลย","None of them drink tea.","Họ đều không uống trà.","彼らは誰も茶を飲みません。","都不"],["他们不都是学生。","Tāmen bù dōu shì xuésheng.","พวกเขาไม่ได้เป็นนักเรียนทุกคน","Not all of them are students.","Họ không phải tất cả đều là học sinh.","彼ら全員が学生というわけではない。","不都"],["这些书我都喜欢。","Zhèxiē shū wǒ dōu xǐhuan.","หนังสือพวกนี้ฉันชอบหมดเลย","I like all of these books.","Những cuốn sách này tôi đều thích.","これらの本は全部好きです。","都"]],"err":[["都我们去。","我们都去。","都 เป็นคำวิเศษณ์ วางหลังประธานและหน้ากริยา ไม่วางต้นประโยค","都 is an adverb: put it after the subject and before the verb, never at the start.","“都”放主语后、动词前，不放句首。","都 đứng sau chủ ngữ, trước động từ, không đặt đầu câu.","「都」は主語の後・動詞の前に置き、文頭には置かない。"],["我都买苹果和茶。","苹果和茶我都买。","都 รวบเฉพาะสิ่งที่อยู่ข้างหน้า ต้องย้ายคำพหูพจน์ (苹果和茶) ไปไว้หน้า 都","都 only covers what precedes it — move 苹果和茶 before 都.","“都”只总括前面的成分，要把“苹果和茶”提前。","都 chỉ gom phần đứng trước, phải đưa 苹果和茶 lên trước 都.","「都」は前の語しかまとめないので「苹果和茶」を前に出す。"]],"rel":["g3-1-020","g3-1-019"]},"g3-1-017":{"t":["在 / 正在: กำลังทำอยู่","在 / 正在: 'in the middle of doing'","时间副词：在、正在","在 / 正在: đang làm gì","時間副詞：在・正在（進行）"],"f":["主语 + 在 / 正在 + 动词 +（宾语）+（呢）","主语 + 没（有）在 + 动词（否定，不用“不”）"],"why":["在 และ 正在 วางหน้ากริยาเพื่อบอกว่าการกระทำกำลังดำเนินอยู่ในขณะนั้น (我正在吃饭 = ฉันกำลังกินข้าว) โดย 正在 เน้นความ 'กำลังทำอยู่เดี๋ยวนี้เลย' ชัดกว่า 在 และใส่ 呢 ท้ายประโยคเพิ่มได้ · ข้อควรระวังสำคัญ: (1) ปฏิเสธว่า 'ไม่ได้กำลังทำ' ใช้ 没(有)ใน + กริยา ห้ามใช้ 不在 + กริยา (2) ห้ามใช้ 正在 กับกริยาบอกสภาวะที่ทำต่อเนื่องเป็นอาการไม่ได้ เช่น 是, 有, 认识, 知道 (3) ห้ามใส่ 了1 ปนในประโยคกำลังทำ","在 and 正在 before a verb mean an action is in progress ('be doing'), with 正在 more emphatic; optional 呢 can close the sentence. · Key cautions: (1) Negate with 没(有)在 + verb (never 不在 + verb for progressive). (2) Do NOT use 正在 with static verbs like 是, 有, 认识, 知道. (3) Never add completed 了1.","“在、正在”放在动词前表示动作正在进行，“正在”语气更强调，句末可加“呢”。 · 关键注意：（1）否定用“没（有）在＋动词”，不用“不在”；（2）不能用于“是、有、认识、知道”等静态动词；（3）不能和表示完成的“了1”连用。","在 và 正在 đặt trước động từ chỉ hành động đang diễn ra (正在 nhấn mạnh hơn), cuối câu có thể thêm 呢. · Lưu ý: (1) Phủ định dùng 没(有)在 + động từ (không dùng 不在); (2) Không dùng với động từ trạng thái như 是, 有, 认识, 知道; (3) Không đi chung với 了1.","「在・正在」を動詞の前に置くと進行中「〜している」を表し、文末に「呢」も添えられる。 · 注意：（1）否定は「没（有）在＋動詞」（「不在」は不可）、（2）「是・有・认识・知道」など状態動詞には使えない、（3）完了の「了1」と併用不可。"],"use":[{"ok":true,"zh":"我正在吃饭呢。","fix":"","py":"Wǒ zhèngzài chīfàn ne.","tr":["ฉันกำลังกินข้าวอยู่เลย","I'm eating right now.","Tôi đang ăn cơm đây.","今ちょうどご飯を食べているところです。"],"h":["กำลังทำกริยาที่ดำเนินต่อเนื่องได้ ใช้ 在/正在 + กริยา (+ 呢)","Use 在/正在 + action verb (+ 呢) for ongoing actions","持续动作进行中用“在／正在＋动词（＋呢）”","Hành động đang diễn ra dùng 在/正在 + động từ (+ 呢)","動作の進行中は「在／正在＋動詞（＋呢）」"],"w":["ทำได้เพราะ 吃饭 เป็นกริยาการกระทำที่มีช่วงเวลาต่อเนื่องชัดเจน (เช่นเดียวกับ 看书, 睡觉, 说话, 工作) และเติม 呢 ท้ายประโยคให้น้ำเสียงเป็นกันเองขึ้นได้","Works because 吃饭 is an ongoing dynamic action (like 看书, 睡觉, 说话, 工作), and 呢 adds a lively conversational tone.","“吃饭、看书、睡觉”等动作可持续进行，前加“正在”、尾加“呢”非常地道。","Đúng vì 吃饭 là hành động có quá trình kéo dài, thêm 呢 cuối câu nghe rất tự nhiên.","「吃饭・看书・睡觉」は継続する動作なので「正在…呢」が自然。"],"ref":"HSK 3.0 g3-1-017 · g3-1-065 · 教育部國語辭典"},{"ok":true,"zh":"他没在看电视，他在看书。","fix":"","py":"Tā méi zài kàn diànshì, tā zài kàn shū.","tr":["เขาไม่ได้กำลังดูทีวี เขากำลังอ่านหนังสือ","He isn't watching TV; he's reading.","Anh ấy không đang xem TV, anh ấy đang đọc sách.","彼はテレビを見ているのではなく、本を読んでいます。"],"h":["ปฏิเสธ 'ไม่ได้กำลังทำ' ใช้ 没(有)在 + กริยา","Negate ongoing actions with 没(有)在 + verb","否定进行态用“没（有）在＋动词”","Phủ định đang làm dùng 没(有)在 + động từ","進行形の否定は「没（有）在＋動詞」"],"w":["ทำได้เพราะการปฏิเสธความกำลังดำเนินอยู่ต้องใช้ 没 นำหน้า 在 (หรือพูดสั้น ๆ ว่า 他没看电视) โดยไม่ใช้ 正在 ในรูปปฏิเสธ","Works because progressive negation uses 没(有) + 在 + verb (and drops 正 from 正在).","否定正在进行的动作要用“没（有）在＋动词”，一般不说“没正在”。","Đúng vì phủ định thể tiếp diễn dùng 没(有)在 + động từ (bỏ 正).","進行形の否定は「没（有）在＋動詞」を使い、「正」は入れない。"],"ref":"HSK 3.0 g3-1-017 · g3-1-064"},{"ok":false,"zh":"我正在认识他。","fix":"我认识他。","py":"Wǒ rènshi tā.","tr":["ฉันรู้จักเขา","I know him.","Tôi quen anh ấy.","私は彼を知っています。"],"h":["ห้ามใช้ 正在 กับกริยาสภาวะ (是 / 有 / 认识 / 知道)","Never use 正在 with stative verbs (是 / 有 / 认识 / 知道)","静态动词不能用“正在”","Không dùng 正在 với động từ trạng thái (是/有/认识/知道)","状態動詞（是・有・认识・知道）に「正在」は不可"],"w":["ไม่ได้ เพราะ 认识 (รู้จัก), 知道 (รู้), 是 (เป็น), 有 (มี) เป็นสภาวะที่เกิดขึ้นแล้ว ไม่ใช่การกระทำที่กำลังขยับทำอยู่ต่อหน้า จึงใช้ 正在 ไม่ได้","Wrong because 认识, 知道, 是, and 有 are states rather than ongoing activities — drop 正在.","不行，“认识、知道、是、有”表静态状态，没有进行过程，不能加“正在”。","Không được vì 认识, 知道, 是, 有 là trạng thái tĩnh, không có quá trình đang diễn ra.","「认识・知道・是・有」は状態であり動作の進行ではないため「正在」は付けられない。"],"ref":"HSK 3.0 g3-1-017 · g3-1-064"},{"ok":false,"zh":"我正在吃了饭。","fix":"我正在吃饭。","py":"Wǒ zhèngzài chīfàn.","tr":["ฉันกำลังกินข้าวอยู่","I am eating.","Tôi đang ăn cơm.","ご飯を食べています。"],"h":["ห้ามใช้ 正在 คู่กับ 了1 (ทำเสร็จแล้ว)","Never combine 正在 with completed 了1","“正在”不能与表完成的“了1”同用","Không dùng 正在 chung với 了1 (đã xong)","「正在」と完了の「了1」は併用不可"],"w":["ไม่ได้ เพราะ 正在 แปลว่ากำลังทำอยู่ (ยังไม่เสร็จ) แต่ 了1 หลังกริยาแปลว่าทำสำเร็จไปแล้ว ความหมายขัดแย้งกันโดยตรง","Wrong because 正在 means still in progress while 了1 means already completed — they directly contradict each other.","不行，“正在”表未完进行中，“了1”表动作完成，语义冲突。","Không được vì 正在 là đang làm (chưa xong) còn 了1 là đã xong, mâu thuẫn nhau.","「正在」（進行中）と「了1」（完了）は意味が矛盾するため同時に使えない。"],"ref":"HSK 3.0 g3-1-017 · g3-1-025"}],"ex":[["我正在吃饭。","Wǒ zhèngzài chīfàn.","ฉันกำลังกินข้าวอยู่","I am eating right now.","Tôi đang ăn cơm.","今ご飯を食べています。","正在"],["孩子在睡觉。","Háizi zài shuìjiào.","ลูกกำลังนอนหลับอยู่","The child is sleeping.","Đứa bé đang ngủ.","子どもは寝ています。","在"],["他们在说话呢。","Tāmen zài shuōhuà ne.","พวกเขากำลังคุยกันอยู่","They are talking.","Họ đang nói chuyện đấy.","彼らは話していますよ。","在"],["爸爸正在看书。","Bàba zhèngzài kàn shū.","พ่อกำลังอ่านหนังสืออยู่","Dad is reading a book.","Bố đang đọc sách.","父は本を読んでいます。","正在"],["我没在看电视。","Wǒ méi zài kàn diànshì.","ฉันไม่ได้กำลังดูทีวี","I am not watching TV.","Tôi không đang xem TV.","テレビを見ていません。","没在"]],"err":[["我正在认识他。","我认识他。","กริยาสภาวะ (认识, 知道, 是, 有) ใช้ 正在 ไม่ได้","Stative verbs (认识, 知道, 是, 有) cannot take 正在.","“认识、知道、是、有”等静态动词不能用“正在”。","Động từ trạng thái (认识, 知道, 是, 有) không dùng 正在.","状態動詞（认识・知道・是・有）には「正在」を使えない。"],["我正在吃了饭。","我正在吃饭。","กำลังทำอยู่ (正在) ห้ามใส่ 了1 ที่แปลว่าทำเสร็จแล้ว","Do not combine ongoing 正在 with completed 了1.","进行中的“正在”不能和“了1”同用。","Đang làm (正在) không dùng chung với 了1.","進行中の「正在」と完了の「了1」は併用できない。"]],"rel":["g3-1-064","g3-1-065","g3-1-021"]},"g3-1-018":{"t":["再: ทำอีก (ในอนาคต)","再: 'again' (future / not yet happened)","频率副词：再1","再: 'lại / nữa' (trong tương lai)","頻度副詞「再1」：もう一度（これから）"],"f":["主语 +（时间）+ 再 + 动词（未发生的重复）","主语 + 不再 / 没再 + 动词"],"why":["再 แปลว่า 'อีก / ใหม่ / ค่อย…อีกที' ใช้กับเหตุการณ์ที่ 'ยังไม่เกิด' คือตั้งใจจะทำซ้ำในอนาคตหรือบอกคำสั่ง/คำชวน (明天再来, 请再说一遍) · ตำแหน่ง: วางหลังประธาน/เวลา และหน้ากริยาเสมอ · ข้อควรระวังสำคัญ: ถ้าเหตุการณ์นั้นเกิดซ้ำไปแล้วในอดีต ห้ามใช้ 再 ต้องใช้ 又 (HSK 3) แทน (เช่น 昨天他又来了 ไม่ใช่ 昨天他再来了)","再 ('again') is strictly for actions that have NOT happened yet — future plans, wishes, or requests (明天再来). · Place 再 after the subject/time and directly before the verb. · Key caution: for an action that ALREADY repeated in the past, NEVER use 再 (use 又 in HSK 3).","“再”表示动作将要重复，用于尚未发生的事、计划、请求或劝告（明天再来吧）。 · 位于主语／时间之后、动词之前。 · 重要区分：已经发生的重复不能用“再”，要用“又”。","再 ('lại / nữa') chỉ dùng cho việc CHƯA xảy ra — kế hoạch tương lai hoặc đề nghị (明天再来吧). · Đặt sau chủ ngữ/thời gian, trước động từ. · Lưu ý: việc ĐÃ lặp lại trong quá khứ không dùng 再 mà dùng 又.","「再」はまだ起きていない未来の反復・予定・依頼に使う（明天再来吧）。 · 主語・時間の後、動詞の前に置く。 · 注意：すでに過去に再び起きたことには「再」は使えず「又」を使う。"],"use":[{"ok":true,"zh":"明天再来吧。","fix":"","py":"Míngtiān zài lái ba.","tr":["พรุ่งนี้ค่อยมาใหม่นะ","Come again tomorrow.","Ngày mai lại đến nhé.","明日また来てくださいね。"],"h":["เหตุการณ์ที่จะทำซ้ำในอนาคตใช้ 再","Use 再 for future repetitions or invitations","未发生的重复动作、邀请用“再”","Hành động lặp lại trong tương lai dùng 再","これからの反復・誘いには「再」"],"w":["ทำได้เพราะ 'พรุ่งนี้' ยังมาไม่ถึง เป็นการชวนให้กลับมาอีกครั้งในอนาคต ซึ่งตรงกับหน้าที่หลักของ 再","Works because tomorrow hasn't happened yet — inviting someone to repeat an action in the future is the exact job of 再.","“明天”尚未发生，邀请或计划再次做某事必须用“再”。","Đúng vì ngày mai chưa đến, rủ làm lại trong tương lai dùng 再 là chuẩn xác.","「明日」はまだ来ていない未来のことなので「再」がぴったり合う。"],"ref":"กลุ่มเทียบคำ g16 · ประโยคตัวอย่าง_300"},{"ok":true,"zh":"我想再喝一杯茶。","fix":"","py":"Wǒ xiǎng zài hē yī bēi chá.","tr":["ฉันอยากดื่มชาอีกสักแก้ว","I'd like to drink another cup of tea.","Tôi muốn uống thêm một cốc trà nữa.","お茶をもう一杯飲みたいです。"],"h":["ความต้องการ/ตั้งใจจะทำเพิ่มอีกที วาง 再 หน้ากริยาหลัก","Put 再 before the main verb after 想/要/可以","跟在“想、要、可以”后、主要动词前","Đặt 再 sau 想/要 và trước động từ chính","「想・要」の後・本動詞の前に「再」を置く"],"w":["ทำได้เพราะเป็นความอยากจะดื่มเพิ่มอีกแก้ว (ยังไม่ได้ดื่ม) และวาง 再 หลังกริยานำ 想 และหน้ากริยาหลัก 喝 ถูกต้อง","Works because drinking one more cup hasn't happened yet, and 再 sits cleanly between 想 and 喝.","愿望中的“再喝一杯”尚未实现，“再”放在能愿动词“想”后、动词“喝”前。","Đúng vì việc uống thêm chưa xảy ra và 再 đứng giữa 想 và 喝.","もう一杯飲むのはこれからの願望なので、助動詞「想」の後・動詞「喝」の前に置く。"],"ref":"HSK 3.0 g3-1-018"},{"ok":false,"zh":"昨天他再来了。","fix":"明天他再来。","py":"Míngtiān tā zài lái.","tr":["พรุ่งนี้เขาค่อยมาใหม่","He will come again tomorrow.","Ngày mai anh ấy lại đến.","明日彼がまた来ます。"],"h":["ห้ามใช้ 再 กับเรื่องที่เกิดซ้ำไปแล้วในอดีต","Never use 再 for an action that already repeated","已经发生的重复不能用“再”","Không dùng 再 cho việc đã lặp lại trong quá khứ","すでに繰り返された過去の出来事に「再」は不可"],"w":["ไม่ได้ เพราะ 昨天…了 บอกชัดว่าเหตุการณ์เกิดซ้ำไปแล้วในอดีต ภาษาจีนแยกคำชัด: อนาคตใช้ 再 (明天他再来) ส่วนอดีตที่เกิดไปแล้วจะใช้ 又 ในระดับ HSK 3","Wrong because 昨天…了 already happened in the past; Chinese splits 'again' into 再 (future: 明天他再来) vs 又 (past, HSK 3).","不行，“昨天……了”表示已经发生的重复，不能用“再”；“再”只用于将来（明天他再来），已发生的重复用“又”。","Không được vì 昨天…了 đã xảy ra rồi; 再 chỉ dùng cho tương lai (明天他再来), còn quá khứ dùng 又.","「昨天…了」はすでに起きた過去の反復なので「再」は不可。「再」は未来（明天他再来）専用で過去は「又」を使う。"],"ref":"กลุ่มเทียบคำ g16"},{"ok":false,"zh":"我明天去再。","fix":"我明天再去。","py":"Wǒ míngtiān zài qù.","tr":["พรุ่งนี้ฉันค่อยไปอีกที","I'll go again tomorrow.","Ngày mai tôi lại đi.","明日また行きます。"],"h":["ห้ามวาง 再 ไว้ท้ายประโยคแบบคำว่า 'อีก' ในภาษาไทย","Never put 再 at the end of the sentence like Thai 'อีก'","“再”是副词，必须放在动词前","Không đặt 再 ở cuối câu","「再」は副詞なので動詞の後ろに置けない"],"w":["ไม่ได้ เพราะในภาษาไทยวางคำว่า 'อีก / ใหม่' ไว้หลังกริยา ('ไปอีก') แต่ในภาษาจีน 再 เป็นคำวิเศษณ์ ต้องอยู่หน้ากริยาเสมอ (再去)","Wrong because Thai puts 'again' after the verb, while Chinese 再 is an adverb that must precede the verb (再去).","不行，“再”作副词只能位于动词前，不能放句尾。","Không được vì 再 là phó từ bắt buộc đứng trước động từ (再去).","「再」は副詞なので必ず動詞の前（再去）に置き、文末には置けない。"],"ref":"HSK 3.0 g3-1-018"}],"ex":[["我明天再去。","Wǒ míngtiān zài qù.","พรุ่งนี้ฉันค่อยไปอีกที","I'll go again tomorrow.","Ngày mai tôi lại đi.","明日また行きます。","再"],["明天再来吧。","Míngtiān zài lái ba.","พรุ่งนี้ค่อยมาใหม่นะ","Come again tomorrow.","Ngày mai lại đến nhé.","明日また来てくださいね。","再"],["我想再买一本书。","Wǒ xiǎng zài mǎi yī běn shū.","ฉันอยากซื้อหนังสืออีกเล่ม","I want to buy one more book.","Tôi muốn mua thêm một cuốn sách nữa.","本をもう一冊買いたいです。","再"],["你再喝一杯茶吧。","Nǐ zài hē yī bēi chá ba.","คุณดื่มชาอีกสักแก้วนะ","Have another cup of tea.","Bạn uống thêm một cốc trà nữa đi.","お茶をもう一杯どうぞ。","再"],["我们明天再见！","Wǒmen míngtiān zàijiàn!","พรุ่งนี้เจอกันใหม่นะ!","See you tomorrow!","Ngày mai gặp lại nhé!","また明日会いましょう！","再"]],"err":[["我明天去再。","我明天再去。","再 เป็นคำวิเศษณ์ ต้องวางหน้ากริยา (再去) ไม่วางท้ายประโยค","再 is an adverb and must go before the verb (再去).","“再”放在动词前（再去），不放句尾。","再 đứng trước động từ (再去), không đặt cuối câu.","「再」は動詞の前（再去）に置く。"],["我明天再去来。","我明天再来。","ใส่กริยาหลักหลัง 再 ตัวเดียวให้ตรงความหมาย","Place the target verb directly after 再.","“再”后直接接主要动词。","Đặt động từ chính ngay sau 再.","「再」の直後に本動詞を置く。"]],"rel":["g3-1-019","g3-1-040"]},"g3-1-019":{"t":["还 / 也: “ยัง / …อีก” กับ “ก็…เหมือนกัน”","还 / 也: 'still / also' vs 'also / too'","关联副词：还1、也","还 / 也: 'vẫn / còn' và 'cũng'","関連副詞：还1・也"],"f":["主语 + 也 + 动词 / 形容词（我也去 / 我也是学生）","主语 + 还 + 在/想/要/没 + 动词（他还在睡觉 / 我还想买…）"],"why":["也 แปลว่า 'ก็…เหมือนกัน' ใช้เทียบว่าคน/สิ่งหนึ่งเหมือนกับอีกคนหรืออีกเรื่อง (我也是学生) · 还 มี 2 ความหมายหลักใน HSK 1: (1) 'ยัง…อยู่' คือสภาพเดิมยังดำเนินต่อ (他还在睡觉, 还没吃) และ (2) '…อีก/เพิ่ม' (我还想买苹果) · ข้อควรระวัง: (1) ทั้ง 也 และ 还 ต้องอยู่หลังประธานและหน้ากริยาเสมอ ห้ามวางต้นประโยคหรือท้ายประโยค (2) เวลาซ้อนกับ 不 ให้วาง 也 ไว้หน้า 不 (也不 = ก็ไม่…) ไม่ใช่ 不也","也 ('also / too') shows similarity between people or things (我也是学生). · 还 has two HSK 1 meanings: (1) 'still' continuing (他还在睡觉, 还没吃), and (2) 'in addition' (我还想买苹果). · Cautions: (1) Both go after the subject and before the verb — never at the end like 'too'. (2) With 不, ALWAYS put 也 before 不 (也不, never 不也).","“也”表示相同（我也是学生）。 · “还”在 HSK 1 中主要表：（1）动作或状态仍在持续（他还在睡觉、还没吃）；（2）补充增加（我还想买苹果）。 · 注意：（1）“也、还”均放主语后、动词前，不能放句首或句尾；（2）否定式一定是“也不／还没”，绝不说“不也”。","也 ('cũng') chỉ sự giống nhau (我也是学生). · 还 có 2 nghĩa chính ở HSK 1: (1) 'vẫn còn' tiếp diễn (他还在睡觉, 还没吃), (2) 'còn / thêm' (我还想买苹果). · Lưu ý: cả hai đứng sau chủ ngữ, trước động từ; khi phủ định luôn là 也不 / 还没 (không nói 不也).","「也」は同様「〜も」（我也是学生）。 · 「还」は（1）継続「まだ」（他还在睡觉・还没吃）、（2）追加「さらに」（我还想买苹果）。 · 注意：どちらも主語の後・動詞の前。否定は必ず「也不／还没」（不也は不可）。"],"use":[{"ok":true,"zh":"我也是学生。","fix":"","py":"Wǒ yě shì xuésheng.","tr":["ฉันก็เป็นนักเรียนเหมือนกัน","I am also a student.","Tôi cũng là học sinh.","私も学生です。"],"h":["เปรียบเทียบว่าเหมือนกัน ใช้ ประธาน + 也 + กริยา","Put 也 right after the subject to show similarity","表示相同：主语＋也＋动词","Chỉ sự giống nhau: Chủ ngữ + 也 + động từ","同様を表すときは「主語＋也＋動詞」"],"w":["ทำได้เพราะ 也 วางระหว่างประธาน 我 กับกริยา 是 เพื่อเชื่อมว่าฉันเหมือนกับคนก่อนหน้า","Works because 也 sits between subject 我 and verb 是 to link you with the previous person.","“也”位于主语和动词之间，表示与前文情况相同。","Đúng vì 也 đứng giữa chủ ngữ 我 và động từ 是.","主語「我」と動詞「是」の間に「也」を置いて同様を表す。"],"ref":"กลุ่มเทียบคำ g16 · ประโยคตัวอย่าง_300"},{"ok":true,"zh":"他还在睡觉。","fix":"","py":"Tā hái zài shuìjiào.","tr":["เขายังนอนหลับอยู่เลย","He is still sleeping.","Anh ấy vẫn đang ngủ.","彼はまだ寝ています。"],"h":["สภาพเดิมยังดำเนินอยู่ ใช้ 还 (+ 在/没)","Use 还 (+ 在/没) for 'still / not yet'","表示持续不变用“还在／还没”","Trạng thái tiếp diễn dùng 还在 / 还没","状態の継続は「还在／还没」"],"w":["ทำได้เพราะ 还 + 在 แปลว่า 'ยังคงกำลัง…อยู่' และ 还 + 没 แปลว่า 'ยังไม่ได้…' (เช่น 我还没吃饭 = ฉันยังไม่ได้กินข้าว)","Works because 还在 means 'still doing' and 还没 means 'not yet' (我还没吃饭).","“还在”表动作仍在持续，“还没”表至今尚未发生（我还没吃饭）。","Đúng vì 还在 = vẫn đang, 还没 = vẫn chưa (我还没吃饭).","「还在」はまだ〜している、「还没」はまだ〜していない（我还没吃饭）。"],"ref":"กลุ่มเทียบคำ g16 · เสริม w3-00067"},{"ok":true,"zh":"我也不喝茶。","fix":"","py":"Wǒ yě bù hē chá.","tr":["ฉันก็ไม่ดื่มชาเหมือนกัน","I don't drink tea either.","Tôi cũng không uống trà.","私もお茶を飲みません。"],"h":["ปฏิเสธแบบ 'ก็ไม่…เหมือนกัน' ใช้ 也不 (หรือ 也没)","For 'neither / not…either', put 也 BEFORE 不/没 (也不/也没)","否定相同用“也不／也没”","Phủ định giống nhau dùng 也不 / 也没","「〜も〜ない」は「也不／也没」"],"w":["ทำได้เพราะในภาษาจีน 也 ต้องวางหน้าคำปฏิเสธเสมอ (也不 / 也没) ไม่ว่าจะแปลว่า 'ก็ไม่' หรือ 'ก็ไม่ได้'","Works because 也 always precedes 不 or 没 in Chinese to mean 'also not / neither'.","汉语中“也”必须放在否定词“不／没”前面。","Đúng vì 也 luôn phải đứng trước 不 hoặc 没.","「也」は必ず否定詞「不／没」の前に置く。"],"ref":"HSK 3.0 g3-1-019 · g3-1-020"},{"ok":false,"zh":"我是学生也。","fix":"我也是学生。","py":"Wǒ yě shì xuésheng.","tr":["ฉันก็เป็นนักเรียนเหมือนกัน","I am a student too.","Tôi cũng là học sinh.","私も学生です。"],"h":["ห้ามวาง 也 ไว้ท้ายประโยคแบบ 'too / เหมือนกัน'","Never put 也 at the end of a sentence like 'too'","“也”不能放在句尾","Không đặt 也 ở cuối câu","「也」は文末に置けない"],"w":["ไม่ได้ เพราะในภาษาอังกฤษวาง too ไว้ท้ายประโยค และภาษาไทยวาง 'เหมือนกัน' ไว้ท้ายประโยค แต่ภาษาจีน 也 เป็นคำวิเศษณ์ ต้องอยู่หน้ากริยาเท่านั้น (我也是学生)","Wrong because unlike English 'too' at sentence end, Chinese 也 is an adverb that MUST come before the verb (我也是学生).","不行，“也”作副词只能放动词前，绝不能放句尾（也不能放主语前说“也我是学生”）。","Không được vì 也 là phó từ bắt buộc đứng trước động từ, không đứng cuối câu hay đầu câu.","「也」は副詞なので文末（や文頭）には置けず、必ず動詞の前に置く。"],"ref":"กลุ่มเทียบคำ g16"},{"ok":false,"zh":"我不也喝茶。","fix":"我也不喝茶。","py":"Wǒ yě bù hē chá.","tr":["ฉันก็ไม่ดื่มชาเหมือนกัน","I don't drink tea either.","Tôi cũng không uống trà.","私もお茶を飲みません。"],"h":["ห้ามสลับเป็น 不也 (ต้องเป็น 也不 เสมอ)","Never write 不也 — always put 也 before 不","只能说“也不”，不能说“不也”","Luôn nói 也不, không bao giờ nói 不也","「不也」は不可、必ず「也不」"],"w":["ไม่ได้ เพราะลำดับคำวิเศษณ์บังคับให้ 也 อยู่หน้า 不/没 เสมอ (也不, 也没, 还没 — ไม่ใช่ 不也 หรือ 没还)","Wrong because Chinese adverb order strictly puts 也/还 before 不/没: 也不, 也没, 还没.","不行，副词连用语序固定为“也不、也没、还没”，不能颠倒。","Không được vì trật tự phó từ cố định là 也不, 也没, 还没, không đảo ngược.","副詞の語順は「也不・也没・还没」で固定されており、逆にできない。"],"ref":"HSK 3.0 g3-1-019"}],"ex":[["我也是学生。","Wǒ yě shì xuésheng.","ฉันก็เป็นนักเรียนเหมือนกัน","I am also a student.","Tôi cũng là học sinh.","私も学生です。","也"],["他还在睡觉。","Tā hái zài shuìjiào.","เขายังนอนหลับอยู่","He is still sleeping.","Anh ấy vẫn đang ngủ.","彼はまだ寝ています。","还"],["我还没吃饭。","Wǒ hái méi chīfàn.","ฉันยังไม่ได้กินข้าวเลย","I haven't eaten yet.","Tôi vẫn chưa ăn cơm.","まだご飯を食べていません。","还"],["我买了书，还买了苹果。","Wǒ mǎile shū, hái mǎile píngguǒ.","ฉันซื้อหนังสือ แล้วก็ซื้อแอปเปิลด้วย","I bought books, and also bought apples.","Tôi mua sách, còn mua cả táo nữa.","本を買い、さらにりんごも買いました。","还"],["我也不喝茶。","Wǒ yě bù hē chá.","ฉันก็ไม่ดื่มชาเหมือนกัน","I don't drink tea either.","Tôi cũng không uống trà.","私もお茶を飲みません。","也"]],"err":[["我是学生也。","我也是学生。","也 อยู่หน้ากริยา (我也是学生) ไม่วางท้ายประโยค","Place 也 before the verb (我也是学生), never at the end.","“也”放在动词前，不放句尾。","Đặt 也 trước động từ, không đặt cuối câu.","「也」は動詞の前に置き、文末には置かない。"],["我不也喝茶。","我也不喝茶。","也 ต้องอยู่หน้า 不 เสมอ (也不 ไม่ใช่ 不也)","Always put 也 before 不 (也不, never 不也).","固定语序是“也不”，不是“不也”。","Luôn là 也不, không phải 不也.","語順は必ず「也不」で「不也」ではない。"]],"rel":["g3-1-060","g3-1-061","g3-1-018"]},"g3-1-020":{"t":["不 / 没（有） / 不要: ปฏิเสธสามแบบ","不 / 没（有） / 不要: three kinds of 'not'","不、没（有）、不要：三种否定","不 / 没（有） / 不要: ba kiểu phủ định","不・没（有）・不要：三つの否定"],"f":["不 + 动词 / 形容词（现在、将来、习惯、意愿）","没（有）+ 动词（没发生）· 没有 + 名词（没有某物）","不要 + 动词（劝阻、命令）· 不要 + 名词（不想要）"],"why":["不 ใช้ปฏิเสธเรื่องปัจจุบัน อนาคต นิสัย ความตั้งใจ (我不喝茶 = ฉันไม่ดื่มชาเป็นนิสัย) และใช้กับคำคุณศัพท์ (不贵, 不好) รวมถึง 是 (不是) · 没 หรือ 没有 ใช้ปฏิเสธการกระทำที่ 'ไม่ได้เกิดขึ้น/ยังไม่ได้ทำ' ในอดีตหรือจนถึงตอนนี้ (我昨天没去) และปฏิเสธการมีอยู่ของสิ่งของ (没有钱) · กฎเหล็ก: ปฏิเสธ 有 ต้องใช้ 没 เท่านั้น ห้ามใช้ 不有 · 不要 + กริยา แปลว่า 'อย่า' (ห้ามปราม) และ 不要 + คำนาม แปลว่า 'ไม่เอา'","不 negates the present, future, habits, and intentions (我不喝茶), adjectives (不贵), and 是 (不是). · 没 / 没有 says an action did not or has not happened (我昨天没去) or expresses 'do not have' before nouns (没有钱). · Iron rule: 有 is negated ONLY with 没 (never 不有). · 不要 + verb means 'don't!' (prohibition), and 不要 + noun means 'don't want this'.","“不”否定现在、将来、习惯和意愿（我不喝茶），也用于形容词（不贵）和“是”（不是）。 · “没／没有”否定已经发生或实现的事（我昨天没去），接名词表“没有某物”（没有钱）。 · 铁律：“有”只能用“没”否定，绝不说“不有”。 · “不要＋动词”表劝阻禁止；“不要＋名词”表“不想要”。","不 phủ định hiện tại, tương lai, thói quen, ý muốn (我不喝茶), tính từ (不贵) và 是 (不是). · 没 / 没有 phủ định việc đã không xảy ra (我昨天没去) hoặc 'không có' trước danh từ (没有钱). · Quy tắc cứng: 有 chỉ phủ định bằng 没 (tuyệt đối không nói 不有). · 不要 + động từ = 'đừng'; 不要 + danh từ = 'không lấy'.","「不」は現在・未来・習慣・意志（我不喝茶）、形容詞（不贵）、「是」（不是）を否定する。 · 「没・没有」は起きなかったこと（我昨天没去）や名詞の前で「持っていない」（没有钱）を表す。 · 鉄則：「有」は「没」でのみ否定し、「不有」は不可。 · 「不要＋動詞」は禁止「〜しないで」、「不要＋名詞」は「要らない」。"],"use":[{"ok":true,"zh":"我不喝茶。","fix":"","py":"Wǒ bù hē chá.","tr":["ฉันไม่ดื่มชา (เป็นนิสัย/ความตั้งใจ)","I don't drink tea (habit/preference).","Tôi không uống trà (thói quen).","私はお茶を飲みません（習慣）。"],"h":["นิสัย ความตั้งใจ ปัจจุบัน/อนาคต ใช้ 不","Use 不 for habits, intentions, present & future","习惯、意愿、现在和将来用“不”","Thói quen, ý muốn, hiện tại/tương lai dùng 不","習慣・意志・現在・未来は「不」"],"w":["ทำได้เพราะไม่ได้พูดถึงเหตุการณ์ครั้งเดียวในอดีต แต่บอกนิสัยส่วนตัวหรือการปฏิเสธด้วยความตั้งใจ (ใช้กับคุณศัพท์อย่าง 这个不贵 และ 是 อย่าง 我不是老师 ด้วย)","Works because it states a personal habit or refusal rather than an uncompleted past event (also use 不 with adjectives like 不贵 and 是 like 不是).","表示个人习惯、主观意愿以及修饰形容词（不贵）和“是”（不是）都用“不”。","Đúng vì đây là thói quen hoặc ý muốn chủ quan (cũng dùng 不 với tính từ 不贵 và 是).","習慣や本人の意志を表すため「不」を使う（形容詞「不贵」や「是」も「不」）。"],"ref":"กลุ่มเทียบคำ g6 · เสริม w3-00013"},{"ok":true,"zh":"我昨天没去学校。","fix":"","py":"Wǒ zuótiān méi qù xuéxiào.","tr":["เมื่อวานฉันไม่ได้ไปโรงเรียน","I didn't go to school yesterday.","Hôm qua tôi không đi học.","昨日、学校へ行きませんでした。"],"h":["เหตุการณ์ที่ไม่ได้เกิดขึ้นจริงในอดีตใช้ 没(有)","Use 没(有) for actions that didn't happen","过去未发生的动作常用“没（有）”","Việc đã không xảy ra dùng 没(有)","過去に起きなかった動作は「没（有）」"],"w":["ทำได้เพราะเป็นการเล่าข้อเท็จจริงว่าเมื่อวานเหตุการณ์ 'ไปโรงเรียน' ไม่ได้เกิดขึ้น (ละ 有 เหลือแค่ 没 หน้ากริยาได้ในภาษาพูด และต้องไม่มี 了)","Works because it objectively states that going to school did not happen yesterday (before a verb, 没有 can shorten to 没, and never keep 了).","客观陈述过去某动作没有发生，用“没（有）＋动词”，且不能带“了”。","Đúng vì kể lại sự thật khách quan là việc đi học hôm qua đã không xảy ra (và bỏ 了).","昨日学校へ行かなかったという客観的な事実の否定なので「没（有）＋動詞」（「了」は付けない）。"],"ref":"กลุ่มเทียบคำ g6 · เสริม w3-00013"},{"ok":true,"zh":"我没有钱。","fix":"","py":"Wǒ méiyǒu qián.","tr":["ฉันไม่มีเงิน","I have no money.","Tôi không có tiền.","お金がありません。"],"h":["ปฏิเสธ 有 ใช้ 没 เท่านั้น (没有 + คำนาม)","Always negate 有 with 没 (没有 + noun)","否定“有”只能用“没”","Phủ định 有 chỉ dùng 没 (没有 + danh từ)","「有」の否定は「没」のみ（没有＋名詞）"],"w":["ทำได้เพราะ 没 เป็นคำปฏิเสธคู่เดียวของ 有 ทั้งในความหมาย 'ไม่มีสิ่งของ' และ 'ไม่มีคน/สถานที่' (ในภาษาพูดบางครั้งย่อสั้นลงเหลือ 我没钱 ได้เช่นกัน)","Works because 没 is the only valid negator of 有 for non-existence/lack (in casual speech it may shorten to 我没钱).","“有”只接受“没”否定，口语中也可简说“我没钱”。","Đúng vì 没 là từ phủ định duy nhất của 有 (khẩu ngữ có thể nói gọn 我没钱).","「有」は「没」とだけ結びつく（口語では「我没钱」と略すこともある）。"],"ref":"กลุ่มเทียบคำ g6 · 教育部國語辭典"},{"ok":true,"zh":"不要说话。","fix":"","py":"Bùyào shuōhuà.","tr":["อย่าพูด","Don't talk.","Đừng nói chuyện.","話さないで。"],"h":["ห้ามปรามใช้ 不要 + กริยา (และ 不要 + คำนาม = ไม่เอา)","Use 不要 + verb to forbid (不要 + noun = don't want)","“不要＋动词”表劝阻，“不要＋名词”表不想要","Cấm đoán dùng 不要 + động từ (不要 + danh từ = không lấy)","禁止は「不要＋動詞」（「不要＋名詞」は要らない）"],"w":["ทำได้เพราะ 不要 ตามด้วยกริยาเป็นประโยคคำสั่ง/ห้ามปราม ('อย่า…') ซึ่งใช้ได้ทั้งประโยคสั้น ๆ และระบุผู้ฟัง (你不要说) และถ้าตามด้วยคำนามอย่าง 我不要这个 แปลว่า 'ฉันไม่เอาอันนี้'","Works because 不要 + verb forms an imperative prohibition ('don't…'), and 不要 + noun means 'don't want' (我不要这个).","“不要”接动词表劝阻命令（你不要说），接名词则表“不想要”（我不要这个）。","Đúng vì 不要 + động từ là câu cầu khiến ngăn cản ('đừng…'), còn 不要 + danh từ là 'không lấy'.","「不要＋動詞」は禁止の命令文、「不要＋名詞」（我不要这个）は「これは要らない」となる。"],"ref":"กลุ่มเทียบคำ g7 · 教育部國語辭典"},{"ok":false,"zh":"我不有钱。","fix":"我没有钱。","py":"Wǒ méiyǒu qián.","tr":["ฉันไม่มีเงิน","I have no money.","Tôi không có tiền.","お金がありません。"],"h":["ห้ามพูด 不有 เด็ดขาด","Never say 不有","绝不能说“不有”","Tuyệt đối không nói 不有","「不有」は絶対に使えない"],"w":["ไม่ได้ เพราะคำกริยา 有 เป็นข้อยกเว้นตายตัวในภาษาจีนสมัยใหม่ที่ปฏิเสธด้วย 没 เท่านั้น ไม่ว่าจะพูดถึงอดีต ปัจจุบัน หรืออนาคต (เช่น 明天我没有时间 = พรุ่งนี้ฉันไม่มีเวลา ก็ยังใช้ 没有!)","Wrong because 有 is strictly negated only by 没 in modern Chinese — even for the future (明天我没有时间 'I won't have time tomorrow' still uses 没有!).","不行，现代汉语中“有”无论过去、现在还是将来，都只能用“没”否定（明天我没有时间）。","Không được vì 有 luôn chỉ phủ định bằng 没 kể cả ở tương lai (明天我没有时间 = ngày mai tôi không có thời gian).","現代中国語の「有」は過去・現在・未来を問わず常に「没」で否定する（明日でも「明天我没有时间」）。"],"ref":"กลุ่มเทียบคำ g6"},{"ok":false,"zh":"这个没贵。","fix":"这个不贵。","py":"Zhège bù guì.","tr":["อันนี้ไม่แพง","This isn't expensive.","Cái này không đắt.","これは高くありません。"],"h":["ห้ามใช้ 没 ปฏิเสธคุณศัพท์บอกสภาพทั่วไป (หรือ 是)","Don't use 没 to negate static adjectives or 是","不能用“没”否定一般状态形容词或“是”","Không dùng 没 phủ định tính từ trạng thái hoặc 是","状態を表す形容詞や「是」は「没」で否定しない"],"w":["ไม่ได้ เพราะ 没 ใช้ปฏิเสธการเกิดขึ้น/การเปลี่ยนแปลง ไม่ใช่คุณสมบัติคงที่ของสิ่งของ การบอกว่า 'ไม่แพง / ไม่ดี / ไม่ใช่' ต้องใช้ 不 (不贵, 不好, 不是)","Wrong because 没 negates actions/changes, not static properties or identity. Negate adjectives and 是 with 不 (不贵, 不好, 不是).","不行，“没”否定动作发生而非固有属性；否定形容词性状和“是”必须用“不”（不贵、不是）。","Không được vì 没 phủ định hành động chứ không phủ định tính chất tĩnh hay 是. Phải dùng 不 (不贵, 不是).","「没」は動作の発生を否定するため、性質の形容詞や「是」には使わない。「不贵・不是」とする。"],"ref":"กลุ่มเทียบคำ g6 · ชนิดของคำ_12ชนิด"}],"ex":[["我不喝茶。","Wǒ bù hē chá.","ฉันไม่ดื่มชา","I don't drink tea.","Tôi không uống trà.","私はお茶を飲みません。","不"],["这个不贵。","Zhège bù guì.","อันนี้ไม่แพง","This isn't expensive.","Cái này không đắt.","これは高くありません。","不"],["我昨天没去学校。","Wǒ zuótiān méi qù xuéxiào.","เมื่อวานฉันไม่ได้ไปโรงเรียน","I didn't go to school yesterday.","Hôm qua tôi không đi học.","昨日、学校へ行きませんでした。","没"],["我没有钱。","Wǒ méiyǒu qián.","ฉันไม่มีเงิน","I have no money.","Tôi không có tiền.","お金がありません。","没有"],["不要说话。","Bùyào shuōhuà.","อย่าพูด","Don't talk.","Đừng nói chuyện.","話さないで。","不要"],["我没吃早饭。","Wǒ méi chī zǎofàn.","ฉันไม่ได้กินข้าวเช้า","I didn't eat breakfast.","Tôi chưa ăn sáng.","朝ご飯を食べませんでした。","没"]],"err":[["我不有钱。","我没有钱。","有 ปฏิเสธด้วย 没 เท่านั้น (แม้จะเป็นเรื่องอนาคต)","有 is negated only with 没 (even for the future).","“有”只能用“没”否定。","有 chỉ phủ định bằng 没.","「有」は「没」でしか否定できない。"],["我昨天不去学校。","我昨天没去学校。","เรื่องที่ไม่ได้เกิดขึ้นในอดีตใช้ 没 ไม่ใช่ 不","Something that didn't happen in the past takes 没, not 不.","过去没发生的事用“没”，不用“不”。","Việc đã không xảy ra trong quá khứ dùng 没, không dùng 不.","過去にしなかったことは「没」で、「不」ではない。"],["这个没贵。","这个不贵。","ปฏิเสธคำคุณศัพท์บอกลักษณะทั่วไป (贵, 好, 大) ใช้ 不 ไม่ใช่ 没","Negate static adjectives (贵, 好, 大) with 不, not 没.","否定一般形容词用“不”，不用“没”。","Phủ định tính từ thông thường dùng 不, không dùng 没.","通常の形容詞の否定は「没」ではなく「不」。"]],"rel":["g3-1-025","g3-1-005","g3-2-018"]},"g3-1-021":{"t":["คำบุพบท 在: ที่… (ระบุสถานที่/เวลาที่เกิดเหตุ)","Preposition 在: 'at / in' (place or time of an action)","介词：在（引出时间、处所）","Giới từ 在: 'ở / tại / vào lúc'","前置詞「在」：動作の場所・時を示す"],"f":["主语 + 在 + 处所 + 动词（他在学校学习）","主语 + 在 + 处所（“在”作动词：他在学校）"],"why":["คำว่า 在 มี 3 บทบาทใน HSK 1 ที่ต้องแยกให้ชัด: (1) เป็นบุพบทนำสถานที่หน้ากริยาอื่น (他在医院工作 = เขาทำงานที่โรงพยาบาล) (2) เป็นกริยาหลักแปลว่า 'อยู่ที่…' (他在医院 = เขาอยู่ที่โรงพยาบาล) (3) เป็นวิเศษณ์บอกกำลังทำ (他在工作 = เขากำลังทำงาน) · ข้อควรระวัง: ห้ามเอาคำนามทั่วไปที่ไม่ใช่สถานที่มาตามหลัง 在 ตรง ๆ โดยไม่ใส่คำบอกตำแหน่ง (เช่น 在桌子 ผิด ต้องเป็น 在桌子上) และปฏิเสธ 在 ใช้ 不在","在 has three HSK 1 roles: (1) preposition introducing where an action happens before the verb (他在医院工作), (2) main verb 'be located at' (他在医院), (3) progressive adverb 'be doing' (他在工作). · Caution: ordinary objects are NOT places — add a position word after them (在桌子上, never 在桌子).","“在”在 HSK 1 有三种常见身份：（1）介词，引出动作处所放动词前（他在医院工作）；（2）动词，表存在位置（他在医院）；（3）副词，表进行（他在工作）。 · 注意：普通物品名词不能直接跟“在”作处所，必须加方位词（在桌子上，不说“在桌子”）。","在 có 3 vai trò ở HSK 1: (1) giới từ chỉ nơi hành động xảy ra trước động từ (他在医院工作), (2) động từ 'ở tại' (他在医院), (3) phó từ 'đang' (他在工作). · Lưu ý: đồ vật không phải địa điểm nên phải thêm phương vị từ (在桌子上, không nói 在桌子).","「在」には3つの働きがある：（1）前置詞で動作の場所を動詞の前に置く（他在医院工作）、（2）本動詞「〜にいる／ある」（他在医院）、（3）進行副詞「〜している」（他在工作）。 · 注意：普通の物名詞には必ず方位詞を付ける（在桌子上）。"],"use":[{"ok":true,"zh":"他在医院工作。","fix":"","py":"Tā zài yīyuàn gōngzuò.","tr":["เขาทำงานที่โรงพยาบาล","He works at a hospital.","Anh ấy làm việc ở bệnh viện.","彼は病院で働いています。"],"h":["บุพบท 在 + ชื่อสถานที่ + กริยา","Preposition 在 + place + verb","介词“在＋处所＋动词”","Giới từ 在 + địa điểm + động từ","前置詞「在＋場所＋動詞」"],"w":["ทำได้เพราะ 医院 เป็นคำนามสถานที่อยู่แล้ว จึงต่อหลัง 在 แล้ววางหน้ากริยา 工作 ได้ทันทีโดยไม่ต้องเติม 里","Works because 医院 is inherently a place noun, so 在医院 sits directly before 工作 with no extra 里 needed.","“医院、学校、家、北京”本身是处所词，可直接作“在”的宾语放在动词前。","Đúng vì 医院 vốn là danh từ địa điểm nên đi thẳng sau 在 rồi đứng trước 工作.","「医院」は場所名詞なのでそのまま「在医院＋動詞」と続けられる。"],"ref":"HSK 3.0 g3-1-021 · ชนิดของคำ_12ชนิด"},{"ok":true,"zh":"书在桌子上。","fix":"","py":"Shū zài zhuōzi shàng.","tr":["หนังสืออยู่บนโต๊ะ","The book is on the table.","Sách ở trên bàn.","本は机の上にあります。"],"h":["สิ่งของทั่วไปต้องเติมคำบอกตำแหน่ง (上/下/里) หลังคำนาม","Add a position word (上/下/里) after ordinary object nouns","普通名词后须加方位词才能跟“在”","Danh từ đồ vật phải thêm phương vị từ (上/下/里) sau 在","一般の物名詞は方位詞（上・下・里）を添えて場所化する"],"w":["ทำได้เพราะการเติม 上 เปลี่ยนคำนามสิ่งของ 桌子 ให้กลายเป็นตำแหน่งสถานที่ 桌子上 (บนโต๊ะ) ทำให้ตามหลัง 在 ได้ถูกต้อง","Works because adding 上 converts the object 桌子 into a location 桌子上 ('on the table'), which 在 accepts.","加上方位词“上”把物体“桌子”转化为处所“桌子上”，就能跟在“在”后面。","Đúng vì thêm 上 biến đồ vật 桌子 thành vị trí 桌子上 nên dùng sau 在 được.","「上」を付けて物名詞「桌子」を場所化することで「在」の後ろに置ける。"],"ref":"HSK 3.0 g3-1-021 · g3-1-003"},{"ok":false,"zh":"书在桌子。","fix":"书在桌子上。","py":"Shū zài zhuōzi shàng.","tr":["หนังสืออยู่บนโต๊ะ","The book is on the table.","Sách ở trên bàn.","本は机の上にあります。"],"h":["ห้ามเอาคำนามสิ่งของ (หรือคน) ตามหลัง 在 ตรง ๆ","Never put an ordinary object (or person) straight after 在","不能说“在桌子”“在我”","Không đặt thẳng đồ vật (hoặc người) sau 在","物名詞や人を直接「在」の後ろに置けない"],"w":["ไม่ได้ เพราะ 桌子 เป็นสิ่งของ ไม่ใช่สถานที่ (รวมถึงคนด้วย เช่น ห้ามพูด 书在我 ต้องพูดว่า 书在我这儿 = หนังสืออยู่ที่ฉัน) ต้องเติมคำบอกตำแหน่งเสมอ","Wrong because 桌子 is an object, not a place (same for people: say 在我这儿, never 在我). Always add a position word.","不行，“桌子”是普通物体不是处所（人也一样，要说“在我这儿”不能说“在我”），必须加方位词。","Không được vì 桌子 là đồ vật không phải địa điểm (với người cũng vậy: 在我这儿, không nói 在我).","「桌子」は場所ではないため不可（人も同様に「在我这儿」と言う）。必ず方位詞・这儿などを補う。"],"ref":"HSK 3.0 g3-1-021"},{"ok":false,"zh":"他工作在医院。","fix":"他在医院工作。","py":"Tā zài yīyuàn gōngzuò.","tr":["เขาทำงานที่โรงพยาบาล","He works at a hospital.","Anh ấy làm việc ở bệnh viện.","彼は病院で働いています。"],"h":["ห้ามวาง 在 + สถานที่ หลังกริยาการกระทำ","Don't place 在 + location after an action verb","动作发生的处所不能放动词后","Không đặt 在 + nơi chốn sau động từ hành động","動作の場所「在＋場所」を動詞の後ろに置けない"],"w":["ไม่ได้ เพราะ 在医院 บอกสถานที่ที่การกระทำ 工作 เกิดขึ้น ต้องวางหน้ากริยาเสมอเป็น 他在医院工作","Wrong because 在医院 tells where the action 工作 happens — it must go before the verb: 他在医院工作.","不行，“在医院”交代“工作”发生的地点，必须放在动词“工作”之前。","Không được vì 在医院 chỉ nơi diễn ra hành động 工作, phải đứng trước động từ.","「在医院」は「工作」の場所を示すため必ず動詞の前に置く。"],"ref":"HSK 3.0 g3-1-021 · g3-1-040"}],"ex":[["他在医院工作。","Tā zài yīyuàn gōngzuò.","เขาทำงานที่โรงพยาบาล","He works at a hospital.","Anh ấy làm việc ở bệnh viện.","彼は病院で働いています。","在"],["我们在学校学习。","Wǒmen zài xuéxiào xuéxí.","พวกเราเรียนหนังสือที่โรงเรียน","We study at school.","Chúng tôi học tập ở trường.","私たちは学校で勉強します。","在"],["爸爸不在家。","Bàba bù zài jiā.","พ่อไม่อยู่บ้าน","Dad is not at home.","Bố không có ở nhà.","父は家にいません。","不在"],["猫在桌子下。","Māo zài zhuōzi xià.","แมวอยู่ใต้โต๊ะ","The cat is under the table.","Con mèo ở dưới bàn.","猫は机の下にいます。","在"],["书在我这儿。","Shū zài wǒ zhèr.","หนังสืออยู่ที่ฉัน","The book is with me.","Sách ở chỗ tôi.","本は私のところにあります。","在"]],"err":[["书在桌子。","书在桌子上。","คำนามสิ่งของต้องเติมคำบอกตำแหน่ง (上/下/里) หลังคำนาม","Object nouns need a position word (上/下/里) after them.","普通物体名词后须加方位词（在桌子上）。","Danh từ đồ vật phải thêm phương vị từ (在桌子上).","物名詞には方位詞（上・下・里）を補う。"],["他工作在医院。","他在医院工作。","在 + สถานที่ที่ทำกริยา ต้องวางหน้ากริยาเสมอ","Put 在 + place before the verb.","“在＋处所”放在动词前。","Đặt 在 + địa điểm trước động từ.","「在＋場所」は動詞の前に置く。"]],"rel":["g3-1-040","g3-1-003","g3-1-017"]},"g3-1-022":{"t":["คำบุพบท 和 / 对: ทำร่วมกับ… / พูดกับ… / ดีต่อ…","Prepositions 和 / 对: 'with' and 'to / toward'","介词：和1、对（引出对象）","Giới từ 和 / 对: 'với' và 'đối với'","前置詞「和1・对」：対象を導く"],"f":["主语 + 和 + 对象 + 动词（我和朋友去饭店）","主语 + 对 + 对象 + 说 / 很好（他对我说 / 妈妈对我很好）"],"why":["และบุพบท 和1 และ 对 ต่างใช้ระบุ 'บุคคลหรือเป้าหมายที่เกี่ยวข้อง' โดยต้องวาง 'บุพบท + เป้าหมาย' ไว้หน้ากริยาหรือคุณศัพท์เสมอ (ตรงข้ามกับภาษาไทยที่วาง 'กับเพื่อน / กับฉัน' ไว้ท้ายประโยค) · 和 + คน + กริยา = ทำสิ่งนั้นร่วมกับใคร (我和朋友吃饭) · 对 + คน/สิ่ง + กริยา/คุณศัพท์ = พูดต่อ/มีท่าทีต่อ/มีผลต่อ (他对我说, 妈妈对我很好) · ระวัง: เวลาปฏิเสธหรือมีคำวิเศษณ์ ให้วาง 不 / 很 ไว้หน้า 和/对 (我不和他去)","Both 和1 ('with') and 对 ('to / toward') introduce a person or target BEFORE the verb or adjective — opposite to Thai/English 'go with a friend / say to me'. · 和 + person + verb = do something together with someone. · 对 + target + verb/adj = speak to / be good to (他对我说, 妈妈对我很好). · Put negation before the preposition (我不和他去).","介词“和1、对”用来引出动作或态度的对象，介宾短语必须放在动词或形容词前（与泰语、英语相反）。 · “和＋人＋动词”表一起做某事；“对＋对象＋动词／形容词”表朝向或对待（他对我说、妈妈对我很好）。 · 否定词放在介词前（我不和他去）。","Giới từ 和1 ('cùng với') và 对 ('với / đối với') luôn đứng TRƯỚC động từ hoặc tính từ — ngược tiếng Việt/Thái. · 和 + người + động từ = làm cùng ai; 对 + đối tượng + động từ/tính từ = nói với / tốt với ai. · Phủ định đặt trước giới từ (我不和他去).","前置詞「和1（〜と）」「对（〜に対して）」は対象を導き、必ず動詞・形容詞の前に置く。 · 「和＋人＋動詞」は一緒にする、「对＋対象＋動詞／形容詞」は「〜に言う／〜に優しい」。 · 否定詞は前置詞の前（我不和他去）。"],"use":[{"ok":true,"zh":"他对我说再见。","fix":"","py":"Tā duì wǒ shuō zàijiàn.","tr":["เขาพูดลาก่อนกับฉัน","He said goodbye to me.","Anh ấy nói tạm biệt với tôi.","彼は私にさようならと言いました。"],"h":["พูดกับใคร / มีท่าทีต่อใคร ใช้ ประธาน + 对 + คน + กริยา","Use Subject + 对 + person + verb ('say to someone')","向某人说／对待某人：主语＋对＋对象＋动词","Nói với / đối xử với ai: Chủ ngữ + 对 + người + động từ","「〜に言う」は「主語＋对＋人＋動詞」"],"w":["ทำได้เพราะ 对 นำหน้าผู้รับคำพูด (我) และวางไว้หน้ากริยา 说 เสมอ (เช่นเดียวกับ 妈妈对我很好 = แม่ดีกับฉันมาก)","Works because 对 introduces the listener (我) right before the verb 说 (just like 妈妈对我很好 'Mom is very good to me').","“对我”作状语放在动词“说”前，清楚标出说话对象。","Đúng vì 对我 đặt trước động từ 说 để chỉ rõ đối tượng nghe.","「对我」を動詞「说」の前に置いて話し相手を明示する。"],"ref":"HSK 3.0 g3-1-022 · g3-1-033"},{"ok":true,"zh":"我和朋友去学校。","fix":"","py":"Wǒ hé péngyou qù xuéxiào.","tr":["ฉันไปโรงเรียนกับเพื่อน","I go to school with my friend.","Tôi cùng bạn đi học.","友達と学校へ行きます。"],"h":["ทำร่วมกับใคร ใช้ ประธาน + 和 + คน + กริยา","Use Subject + 和 + person + verb ('do with someone')","与某人同做：主语＋和＋人＋动词","Làm cùng ai: Chủ ngữ + 和 + người + động từ","一緒に行動するときは「主語＋和＋人＋動詞」"],"w":["ทำได้เพราะ 和朋友 ('กับเพื่อน') วางหน้ากริยา 去 โดยตรง ตรงตามลำดับ 状语 + 动词 ของภาษาจีน","Works naturally because 和朋友 ('with my friend') sits right before the verb 去.","“和朋友”作状语放在动词“去”前面，符合汉语“介宾短语＋动词”语序。","Đúng vì cụm giới từ 和朋友 đặt ngay trước động từ 去.","前置詞句「和朋友」を動詞「去」の前に置く自然な中国語の語順。"],"ref":"HSK 3.0 g3-1-022 · กลุ่มเทียบคำ g37"},{"ok":false,"zh":"他说再见对我。","fix":"他对我说再见。","py":"Tā duì wǒ shuō zàijiàn.","tr":["เขาพูดลาก่อนกับฉัน","He said goodbye to me.","Anh ấy nói tạm biệt với tôi.","彼は私にさようならと言いました。"],"h":["ห้ามวาง 对 + คน ไว้ท้ายประโยคแบบภาษาไทย/อังกฤษ","Never put 对 + person after the verb like English 'to me'","“对＋对象”不能放在动词后","Không đặt 对 + người sau động từ","「对＋人」を動詞の後ろに置けない"],"w":["ไม่ได้ เพราะในภาษาไทยพูดว่า 'พูดลาก่อน + กับฉัน' และอังกฤษพูด 'say goodbye + to me' แต่ในภาษาจีนกลุ่มบุพบท 对我 ต้องอยู่หน้ากริยา 说 เสมอ","Wrong because Chinese prepositional phrases like 对我 must precede the verb 说, never trail at the end.","不行，汉语介宾短语“对我”必须放在动词“说”之前，不能放句尾。","Không được vì cụm giới từ 对我 bắt buộc phải đứng trước động từ 说.","中国語の前置詞句「对我」は必ず動詞「说」の前に置き、文末には置けない。"],"ref":"HSK 3.0 g3-1-022 · g3-1-033"},{"ok":false,"zh":"我去学校和朋友。","fix":"我和朋友去学校。","py":"Wǒ hé péngyou qù xuéxiào.","tr":["ฉันไปโรงเรียนกับเพื่อน","I go to school with my friend.","Tôi đi học với bạn.","友達と学校へ行きます。"],"h":["ห้ามวาง 和 + คน ไว้ท้ายประโยค","Never put 和 + person at the end of the sentence","“和＋人”不能放在句尾","Không đặt 和 + người ở cuối câu","「和＋人」を文末に置けない"],"w":["ไม่ได้ เพราะ 和朋友 เป็นส่วนขยายกริยา (状语) บอกว่าไปกับใคร ต้องย้ายมาวางหน้ากริยา 去 เป็น 我和朋友去学校","Wrong because 和朋友 modifies the verb 去 ('go with a friend') and must sit before 去: 我和朋友去学校.","不行，“和朋友”修饰动词“去”，必须放在动词前：我和朋友去学校。","Không được vì 和朋友 bổ nghĩa cho động từ 去 nên phải đứng trước 去.","「和朋友」は動詞「去」を修飾するため「我和朋友去学校」と前に置く。"],"ref":"HSK 3.0 g3-1-022 · g3-1-033"}],"ex":[["我和朋友去饭店。","Wǒ hé péngyou qù fàndiàn.","ฉันไปร้านอาหารกับเพื่อน","I go to the restaurant with my friend.","Tôi đi nhà hàng với bạn.","友達とレストランへ行きます。","和"],["他对我说谢谢。","Tā duì wǒ shuō xièxie.","เขาพูดขอบคุณกับฉัน","He said thank you to me.","Anh ấy nói cảm ơn với tôi.","彼は私にありがとうと言いました。","对"],["妈妈对我很好。","Māma duì wǒ hěn hǎo.","แม่ดีกับฉันมาก","Mom is very kind to me.","Mẹ rất tốt với tôi.","母は私にとても優しいです。","对"],["我不和他去商店。","Wǒ bù hé tā qù shāngdiàn.","ฉันไม่ไปร้านค้ากับเขา","I'm not going to the shop with him.","Tôi không đi cửa hàng với anh ấy.","彼とは店に行きません。","和"],["老师对学生说请坐。","Lǎoshī duì xuésheng shuō qǐng zuò.","ครูบอกนักเรียนว่าเชิญนั่ง","The teacher told the students 'please sit down'.","Thầy giáo nói với học sinh 'mời ngồi'.","先生は生徒に「どうぞ座ってください」と言いました。","对"]],"err":[["他说谢谢对我。","他对我说谢谢。","บุพบท 对 + บุคคล ต้องวางหน้ากริยา (对我说)","Place 对 + person before the verb (对我说).","“对＋人”必须放在动词前（对我说）。","Đặt 对 + người trước động từ (对我说).","「对＋人」は動詞の前に置く（对我说）。"],["我去饭店和朋友。","我和朋友去饭店。","บุพบท 和 + บุคคล ต้องวางหน้ากริยา (我和朋友去)","Place 和 + person before the verb (我和朋友去).","“和＋人”必须放在动词前（我和朋友去）。","Đặt 和 + người trước động từ (我和朋友去).","「和＋人」は動詞の前に置く（我和朋友去）。"]],"rel":["g3-1-023","g3-1-033","g3-1-040"]},"g3-1-023":{"t":["和: เชื่อมคำนามและวลี (ห้ามเชื่อมประโยค)","和: linking nouns & phrases (not clauses)","连词“和”：连接词语，不连接句子","和: nối danh từ và cụm từ (không nối hai câu)","接続詞「和」：名詞・句をつなぐ（文はつながない）"],"f":["名词 A + 和 + 名词 B（爸爸和妈妈 / 苹果和茶）","分句 1，分句 2（两个句子用逗号，不用“和”）"],"why":["和 แปลว่า 'และ / กับ' ทำหน้าที่เชื่อมคำนามหรือคำสรรพนามเข้าด้วยกัน (我和你, 爸爸和妈妈, 书和杯子) · ข้อควรระวังที่คนไทยและคนพูดอังกฤษพลาดบ่อยที่สุด: ห้ามใช้ 和 เชื่อมประโยคเต็ม 2 ประโยคเข้าด้วยกันแบบคำว่า 'และ / and' · ถ้าจะต่อสองเหตุการณ์ ให้คั่นด้วยเครื่องหมายจุลภาค (，) หรือใช้คำเชื่อมประโยคอื่นแทน เช่น 也 หรือ 还","和 ('and') links nouns, pronouns, and noun phrases (我和你, 爸爸和妈妈). · The #1 mistake for Thai and English speakers: NEVER use 和 to join two full clauses the way 'และ / and' does! · Separate two full clauses with a comma (，) or use a clause adverb like 也 or 还.","连词“和”用来连接名词、代词或名词性短语（我和你、爸爸和妈妈）。 · 泰语和英语学习者最常犯的错：绝不能用“和”连接两个完整的分句！ · 两个分句之间应用逗号隔开，或改用“也、还”等关联副词。","和 ('và') nối danh từ, đại từ hoặc cụm danh từ (我和你, 爸爸和妈妈). · Lỗi phổ biến nhất: KHÔNG dùng 和 để nối hai mệnh đề/câu đầy đủ như 'và / and'! · Hãy tách hai câu bằng dấu phẩy (，) hoặc dùng phó từ 也 / 还.","接続詞「和」は名詞・代名詞・名詞句をつなぐ（我和你・爸爸和妈妈）。 · 最も多い誤用：英語の and のように二つの完全な文を「和」でつないではいけない！ · 文と文は読点（，）で区切るか「也・还」などを使う。"],"use":[{"ok":true,"zh":"爸爸和妈妈在家。","fix":"","py":"Bàba hé māma zài jiā.","tr":["พ่อและแม่อยู่บ้าน","Dad and Mom are at home.","Bố và mẹ ở nhà.","父と母は家にいます。"],"h":["เชื่อมคำนามหรือสรรพนามตั้งแต่สองคำขึ้นไปใช้ 和","Use 和 to link two or more nouns/pronouns","连接两个或多个名词用“和”","Nối hai hay nhiều danh từ dùng 和","二つ以上の名詞をつなぐのは「和」"],"w":["ทำได้เพราะ 爸爸 กับ 妈妈 ต่างเป็นคำนามที่มีฐานะเท่ากันในประโยค (ถ้ามี 3 คำขึ้นไป ใช้เครื่องหมาย 、 คั่นแล้ววาง 和 หน้าคำสุดท้าย เช่น 爸爸、妈妈和我)","Works because 爸爸 and 妈妈 are parallel nouns (for 3+ items, separate earlier ones with 、 and put 和 before the last one).","“爸爸”和“妈妈”是并列名词，用“和”连接完全正确（三项以上前面用顿号，最后一项前用“和”）。","Đúng vì 爸爸 và 妈妈 là hai danh từ song song (từ 3 mục trở lên ngăn bằng dấu 、 và đặt 和 trước mục cuối).","「爸爸」と「妈妈」は対等な名詞なので「和」でつなげる（3つ以上は「、」で区切り最後の前に「和」）。"],"ref":"กลุ่มเทียบคำ g37 · ประโยคตัวอย่าง_300"},{"ok":true,"zh":"我吃饭，他喝茶。","fix":"","py":"Wǒ chīfàn, tā hē chá.","tr":["ฉันกินข้าว ส่วนเขาดื่มชา","I eat, and he drinks tea.","Tôi ăn cơm, anh ấy uống trà.","私はご飯を食べ、彼はお茶を飲みます。"],"h":["สองประโยคเต็ม คั่นด้วยจุลภาค (，) ไม่ใส่ 和","Separate two full clauses with a comma, not 和","两个完整分句用逗号隔开","Tách hai câu đầy đủ bằng dấu phẩy, không dùng 和","二つの文は「和」なしで読点（，）でつなぐ"],"w":["ทำได้และเป็นธรรมชาติที่สุดในภาษาจีน เพราะแต่ละท่อนมีประธาน+กริยาครบสมบูรณ์อยู่แล้ว แค่ใช้จุลภาคคั่น (หรือเติม 也 เช่น 我吃苹果，他也吃苹果) ก็สื่อความหมาย 'และ' ได้ครบ","Natural Chinese joins two full subject+verb clauses with a comma (or adds 也 / 还), never with 和.","前后各有完整的主谓结构，汉语只需用逗号隔开（或加“也、还”），完全不需要“和”。","Đúng và tự nhiên nhất: mỗi vế đã đủ chủ-vị nên chỉ cần dấu phẩy (hoặc thêm 也 / 还).","それぞれ主語＋述語がそろった文なので、中国語では読点だけで自然につながる（必要に応じて「也・还」を補う）。"],"ref":"เสริม w3-00078 · HSK 3.0 g3-1-059"},{"ok":true,"zh":"我和朋友去饭店。","fix":"","py":"Wǒ hé péngyou qù fàndiàn.","tr":["ฉันไปร้านอาหารกับเพื่อน","I go to a restaurant with my friend.","Tôi đi nhà hàng với bạn.","友達とレストランへ行きます。"],"h":["和 ยังเป็นคำบุพบทแปลว่า 'กับ' (ทำร่วมกัน) ได้ด้วย","和 also works as a preposition 'with' before the verb","“和”作介词表“同、跟”放在动词前","和 cũng là giới từ 'cùng với' đứng trước động từ","「和」は前置詞「〜と一緒に」として動詞の前にも置ける"],"w":["ทำได้เพราะใน HSK 1 คำว่า 和 มี 2 หน้าที่: เชื่อมคำนาม (和2, 连词) และเป็นบุพบทนำหน้าผู้ร่วมกระทำ (和1, 介词) โดยวาง '和 + บุคคล' ไว้หน้ากริยาเสมอ","Works because 和 has two HSK 1 roles: conjunction (和2) and preposition 'with' (和1), placed before the verb (和 + person + verb).","HSK 1中“和”兼作连词（和2）和介词（和1，引出对象），作介词时“和＋人”放在动词前。","Đúng vì 和 có hai vai trò: liên từ (和2) và giới từ 'cùng với' (和1) đặt trước động từ.","HSK1の「和」は接続詞（和2）と前置詞「〜と」（和1）の両方があり、前置詞は「和＋人＋動詞」の順になる。"],"ref":"HSK 3.0 g3-1-022 · g3-1-023 · ชนิดของคำ_12ชนิด"},{"ok":false,"zh":"我吃饭和他喝茶。","fix":"我吃饭，他喝茶。","py":"Wǒ chīfàn, tā hē chá.","tr":["ฉันกินข้าว และเขาดื่มชา","I eat, and he drinks tea.","Tôi ăn cơm, anh ấy uống trà.","私はご飯を食べ、彼はお茶を飲みます。"],"h":["ห้ามใช้ 和 เชื่อมประโยคเต็ม 2 ประโยค","Never use 和 to connect two full clauses","不能用“和”连接两个完整句子","Không dùng 和 để nối hai câu đầy đủ","二つの完全な文を「和」でつなげない"],"w":["ไม่ได้ เพราะ 和 เป็นคำเชื่อมระดับคำ/วลีเท่านั้น ไม่สามารถเชื่อมประโยคที่มีประธาน+กริยาแยกกันสองท่อนแบบ 'และ' ในภาษาไทยได้ ต้องเปลี่ยนเป็นจุลภาค (，)","Wrong because 和 only joins words/noun phrases, never two independent clauses like English 'and' or Thai 'และ'. Replace 和 with a comma.","不行，“和”只连接名词性词语或短语，不能连接两个完整分句，必须改为逗号。","Không được vì 和 chỉ nối danh từ/cụm danh từ, không nối hai mệnh đề độc lập. Phải thay bằng dấu phẩy.","「和」は名詞や句のみをつなぐため、主語＋動詞が別々の二文はつなげない。読点に変える。"],"ref":"เสริม w3-00078 · กลุ่มเทียบคำ g37"},{"ok":false,"zh":"我去学校和买书。","fix":"我去学校买书。","py":"Wǒ qù xuéxiào mǎi shū.","tr":["ฉันไปโรงเรียนซื้อหนังสือ","I go to school to buy books.","Tôi đi học mua sách.","学校へ本を買いに行きます。"],"h":["ห้ามใช้ 和 เชื่อมกริยาที่ทำต่อเนื่องเป็นลำดับ","Don't use 和 between sequential actions","先后发生的连动行为不用“和”","Không dùng 和 giữa hai hành động nối tiếp","連続する二つの動作の間に「和」を入れない"],"w":["ไม่ได้ เพราะ 'ไปโรงเรียน' แล้ว 'ซื้อหนังสือ' เป็นการกระทำต่อเนื่องที่มีจุดประสงค์ (连动句) ภาษาจีนวางกริยาต่อกันได้เลยโดยไม่ต้องมี 和 คั่น","Wrong because 'go to school (in order to) buy books' is a serial-verb sentence (连动句) — chain the verbs directly without 和.","不行，“去学校”后“买书”是表目的的连动句，两个动词短语直接相连，不用“和”。","Không được vì đây là câu liên động (đi học để mua sách), nối thẳng hai động từ không cần 和.","「学校へ行って本を買う」は目的を表す連動文なので、「和」を入れず動詞句をそのまま並べる。"],"ref":"HSK 3.0 g3-1-056 · เสริม w3-00078"}],"ex":[["爸爸和妈妈在家。","Bàba hé māma zài jiā.","พ่อและแม่อยู่บ้าน","Dad and Mom are at home.","Bố và mẹ ở nhà.","父と母は家にいます。","和"],["我和他是朋友。","Wǒ hé tā shì péngyou.","ฉันกับเขาเป็นเพื่อนกัน","He and I are friends.","Tôi và anh ấy là bạn.","私と彼は友達です。","和"],["我买了苹果和茶。","Wǒ mǎile píngguǒ hé chá.","ฉันซื้อแอปเปิลและชา","I bought apples and tea.","Tôi đã mua táo và trà.","りんごとお茶を買いました。","和"],["我和妈妈去饭店。","Wǒ hé māma qù fàndiàn.","ฉันไปร้านอาหารกับแม่","I go to the restaurant with Mom.","Tôi cùng mẹ đi nhà hàng.","母とレストランへ行きます。","和"],["老师和学生都在学校。","Lǎoshī hé xuésheng dōu zài xuéxiào.","ครูและนักเรียนต่างอยู่ที่โรงเรียน","Both teachers and students are at school.","Thầy cô và học sinh đều ở trường.","先生も生徒も学校にいます。","和"]],"err":[["我吃饭和他喝茶。","我吃饭，他喝茶。","和 เชื่อมได้เฉพาะคำนาม/วลี ไม่ใช้เชื่อมสองประโยคเต็ม ให้ใช้จุลภาค (，)","和 links nouns/phrases, not two full clauses — use a comma.","“和”不连接两个分句，应改用逗号。","和 không nối hai mệnh đề đầy đủ, hãy dùng dấu phẩy.","「和」は二つの文をつなげない。読点を使う。"],["我去学校和买书。","我去学校买书。","กริยาต่อเนื่องบอกจุดประสงค์ (ไป…เพื่อ…) วางต่อกันได้เลย ไม่ใส่ 和","Serial verbs expressing purpose chain directly without 和.","连动句前后动词直接连用，不加“和”。","Hai động từ nối tiếp chỉ mục đích không dùng 和.","目的を表す連動文では「和」を入れない。"]],"rel":["g3-1-022","g3-1-056","g3-1-059"]},"g3-1-024":{"t":["的: แสดงความเป็นเจ้าของและขยายคำนาม","的: possession & noun modifiers","结构助词“的”：领属与定语","的: sở hữu và định ngữ bổ nghĩa danh từ","構造助詞「的」：所有と名詞修飾"],"f":["修饰语 + 的 + 名词（我的书 / 好吃的菜）","人称代词 + 亲属/集体（可省“的”：我妈妈 / 我们学校）"],"why":["的 วางไว้ระหว่าง 'ส่วนขยาย' กับ 'คำนาม' โดยลำดับตรงข้ามกับภาษาไทย: ภาษาจีนเอาส่วนขยายไว้หน้าคำนามเสมอ (我的书 = ของฉัน + 的 + หนังสือ, 好吃的菜 = อร่อย + 的 + อาหาร) · ละ 的 ได้ในกรณีความสัมพันธ์ใกล้ชิด เช่น สรรพนาม + ญาติสนิทหรือองค์กรของเรา (我妈妈, 我们学校) หรือคุณศัพท์ 1 พยางค์ที่ติดกันแน่น (好人, 新书) · แต่ถ้าเป็นสิ่งของทั่วไปหรือส่วนขยายยาว (เช่น 2 พยางค์ขึ้นไปอย่าง 好吃的菜, 漂亮的衣服) ต้องใส่ 的 เสมอ","的 links a modifier to the noun that follows — the opposite order of Thai: modifier + 的 + noun (我的书, 好吃的菜). · You may drop 的 for close relationships with pronouns (我妈妈, 我们学校) or tight 1-syllable adjectives (好人, 新书). · Keep 的 for ordinary possessions (我老师的书) and 2-syllable or phrase modifiers (好吃的菜, 漂亮的衣服).","“的”用在定语和中心语名词之间，汉语定语一律放在名词前（我的书、好吃的菜）。 · 代词后接亲属或所属集体（我妈妈、我们学校），或单音节形容词紧密修饰名词（好人、新书）时常可省“的”。 · 一般物品领属或双音节形容词／短语作定语（好吃的菜、我老师的书）通常必须用“的”。","的 nối phần bổ nghĩa với danh từ phía sau — ngược trật tự tiếng Việt/Thái: bổ ngữ + 的 + danh từ (我的书, 好吃的菜). · Có thể bỏ 的 với người thân hoặc tập thể của mình (我妈妈, 我们学校) hay tính từ đơn âm tiết (好人, 新书). · Phải giữ 的 với đồ vật thông thường hoặc tính từ 2 âm tiết (好吃的菜).","「的」は修飾語と後ろの名詞をつなぐ（我的书・好吃的菜）。 · 代名詞＋親族や所属集団（我妈妈・我们学校）、密着した1音節形容詞（好人・新书）では「的」を省ける。 · 一般の所有物（我老师的书）や2音節形容詞・句の修飾（好吃的菜・漂亮的衣服）では通常「的」が必要。"],"use":[{"ok":true,"zh":"这是我的书。","fix":"","py":"Zhè shì wǒ de shū.","tr":["นี่คือหนังสือของฉัน","This is my book.","Đây là sách của tôi.","これは私の本です。"],"h":["แสดงความเป็นเจ้าของสิ่งของใส่ 的 (เจ้าของ + 的 + สิ่งของ)","Use owner + 的 + noun for possessions","物品领属用“领有者＋的＋名词”","Chỉ sở hữu đồ vật dùng chủ sở hữu + 的 + danh từ","物の所有は「所有者＋的＋名詞」"],"w":["ทำได้เพราะ 书 เป็นสิ่งของทั่วไป (ไม่ใช่ญาติสนิท) จึงใส่ 的 เชื่อมระหว่าง 我 กับ 书 (และสังเกตลำดับ: ส่วนขยาย 我 อยู่หน้า 书)","Works because 书 is an ordinary object (not a close family member), so 的 clearly marks possession before the noun.","“书”是一般物品，用“的”标明领属关系最规范，且定语“我”在中心语“书”前。","Đúng vì 书 là đồ vật thông thường nên cần 的 nối chủ sở hữu với danh từ.","「书」は一般の物なので「的」で所有を示し、修飾語を名詞の前に置く。"],"ref":"เสริม w3-00030 · กลุ่มเทียบคำ g36 · ประโยคตัวอย่าง_300"},{"ok":true,"zh":"这是我妈妈。","fix":"","py":"Zhè shì wǒ māma.","tr":["นี่คือแม่ของฉัน","This is my mom.","Đây là mẹ tôi.","こちらは私の母です。"],"h":["ญาติสนิทหรือกลุ่มของเรา ละ 的 ได้ (我妈妈 / 我们学校)","Omit 的 with close family or your own group","亲属或所属集体前可省“的”","Có thể bỏ 的 với người thân hoặc tập thể của mình","家族や自分の所属先の前は「的」を省略可"],"w":["ทำได้และเป็นธรรมชาติกว่าในภาษาพูด เพราะความสัมพันธ์ระหว่างผู้พูดกับครอบครัว/โรงเรียนของตนใกล้ชิดมาก (แต่พูดว่า 我的妈妈 ก็ไม่ผิด)","Works and sounds more natural than 我的妈妈 because family and one's own school/group have an inherent close tie.","亲属（我妈妈、我爸爸）和所属集体（我们学校、我们老师）关系紧密，省略“的”更地道自然。","Đúng và tự nhiên hơn vì quan hệ gia đình / tập thể của mình rất gần gũi (nói 我的妈妈 cũng không sai).","家族（我妈妈）や自分の所属先（我们学校）は結びつきが強いため「的」を省く方が自然。"],"ref":"เสริม w3-00030"},{"ok":true,"zh":"我喜欢好吃的菜。","fix":"","py":"Wǒ xǐhuan hǎochī de cài.","tr":["ฉันชอบอาหารที่อร่อย","I like delicious food.","Tôi thích món ăn ngon.","おいしい料理が好きです。"],"h":["คุณศัพท์ 2 พยางค์ขึ้นไปขยายคำนาม ใส่ 的 คั่น","Use 的 after 2-syllable adjectives modifying a noun","双音节形容词修饰名词一般加“的”","Tính từ 2 âm tiết bổ nghĩa danh từ dùng 的","2音節形容詞が名詞を修飾するときは「的」を入れる"],"w":["ทำได้เพราะ 好吃 (2 พยางค์) ขยายคำนาม 菜 ต้องมี 的 เชื่อม และวางไว้หน้า 菜 เสมอ (เช่นเดียวกับ 漂亮的衣服 เสื้อผ้าที่สวย)","Works because 2-syllable adjectives like 好吃 or 漂亮 normally take 的 before the noun they modify.","“好吃、漂亮”等双音节形容词作定语修饰名词时，中间通常必须加“的”。","Đúng vì tính từ 2 âm tiết như 好吃, 漂亮 bổ nghĩa cho danh từ thường cần có 的 ở giữa.","「好吃・漂亮」など2音節の形容詞が名詞を修飾するときは通常「的」を挟む。"],"ref":"เสริม w3-00030 · 教育部國語辭典"},{"ok":false,"zh":"这是我老师书。","fix":"这是我老师的书。","py":"Zhè shì wǒ lǎoshī de shū.","tr":["นี่คือหนังสือของครูฉัน","This is my teacher's book.","Đây là sách của thầy giáo tôi.","これは私の先生の本です。"],"h":["ห้ามละ 的 หน้าสิ่งของทั่วไป","Don't drop 的 before ordinary objects","一般物品领属前不能省“的”","Không bỏ 的 trước đồ vật thông thường","一般の所有物の前で「的」は省けない"],"w":["ไม่ได้ เพราะแม้จะละ 的 ระหว่าง 我 กับ 老师 ได้ (我老师 = ครูของฉัน) แต่ระหว่าง 'ครูของฉัน' กับ 'หนังสือ' เป็นความเป็นเจ้าของสิ่งของ ต้องใส่ 的 เป็น 我老师的书","Wrong: you can omit the first 的 in 我老师 ('my teacher'), but the final possession before an object (书) MUST keep 的 → 我老师的书.","不行，“我老师”之间可省“的”，但“老师”和物品“书”之间的领属“的”不能省，须说“我老师的书”。","Không được: có thể bỏ 的 đầu ở 我老师, nhưng 的 trước đồ vật 书 bắt buộc phải giữ → 我老师的书.","「我老师」の間の「的」は省けても、物である「书」の前の「的」は省けない。「我老师的书」にする。"],"ref":"เสริม w3-00030"},{"ok":false,"zh":"这是书的我。","fix":"这是我的书。","py":"Zhè shì wǒ de shū.","tr":["นี่คือหนังสือของฉัน","This is my book.","Đây là sách của tôi.","これは私の本です。"],"h":["ห้ามวางส่วนขยายไว้หลังคำนามแบบภาษาไทย","Never put the modifier after the noun like Thai","定语不能放在中心语名词后面","Không đặt phần bổ nghĩa sau danh từ như tiếng Việt/Thái","修飾語を名詞の後ろに置かない"],"w":["ไม่ได้ เพราะภาษาไทยพูด 'หนังสือ ของ ฉัน' (คำนาม + ของ + เจ้าของ) แต่ภาษาจีนสลับด้านกันเสมอ คำนามหลักต้องอยู่ท้ายสุด (我的书)","Wrong because Thai puts the noun first ('book of me'), whereas Chinese ALWAYS puts the head noun last after 的 (我的书).","不行，汉语与泰语语序相反，中心语名词“书”必须放在“的”的后面。","Không được vì tiếng Trung ngược trật tự với tiếng Việt/Thái: danh từ chính 书 luôn phải đứng sau 的.","修飾される中心の名詞「书」は必ず「的」の後ろに来る（我的书）。"],"ref":"HSK 3.0 g3-1-039 · กลุ่มเทียบคำ g36"}],"ex":[["这是我的书。","Zhè shì wǒ de shū.","นี่คือหนังสือของฉัน","This is my book.","Đây là sách của tôi.","これは私の本です。","的"],["这是我老师的书。","Zhè shì wǒ lǎoshī de shū.","นี่คือหนังสือของครูฉัน","This is my teacher's book.","Đây là sách của thầy tôi.","これは私の先生の本です。","的"],["我喜欢好吃的菜。","Wǒ xǐhuan hǎochī de cài.","ฉันชอบอาหารที่อร่อย","I like delicious dishes.","Tôi thích món ăn ngon.","おいしい料理が好きです。","的"],["她买了漂亮的衣服。","Tā mǎile piàoliang de yīfu.","เธอซื้อเสื้อผ้าสวย ๆ มา","She bought pretty clothes.","Cô ấy đã mua quần áo đẹp.","彼女はきれいな服を買いました。","的"],["那是爸爸的手机。","Nà shì bàba de shǒujī.","นั่นคือโทรศัพท์มือถือของพ่อ","That is Dad's phone.","Đó là điện thoại của bố.","あれは父のスマホです。","的"]],"err":[["这是我老师书。","这是我老师的书。","ความเป็นเจ้าของสิ่งของต้องมี 的 คั่น (ละได้แค่ญาติสนิทหรือกลุ่มของเรา)","Possession of an object requires 的 (drop only with close family/groups).","表示物品领属必须用“的”（我老师的书）。","Sở hữu đồ vật phải có 的 (我老师的书).","物の所有には「的」が必要（我老师的书）。"],["这是书的我。","这是我的书。","ภาษาจีนวางส่วนขยายไว้หน้าคำนามเสมอ (我的书)","Chinese always places modifiers before the noun (我的书).","汉语定语一律在名词前（我的书）。","Tiếng Trung luôn đặt định ngữ trước danh từ (我的书).","中国語では修飾語は必ず名詞の前に置く（我的书）。"]],"rel":["g3-1-039","g3-2-030","g3-2-035"]},"g3-1-025":{"t":["了 หลังกริยา: บอกว่าทำไปแล้ว (了1)","了 after the verb: completed action (了1)","动词后的“了”：动作完成（了1）","了 sau động từ: hành động hoàn thành (了1)","動詞の後の「了」：動作の完了（了1）"],"f":["主语 + 动词 + 了 + 数量 / 定语 + 宾语","主语 + 动词 + 宾语 + 了（光杆宾语时，“了2”放句末）","主语 + 没 + 动词 + 宾语（不用“了”）"],"why":["了1 วางหลังกริยาทันทีเพื่อบอกว่าการกระทำนั้น 'เกิดขึ้นหรือทำสำเร็จแล้ว' โดยกรรมข้างหลังมักมีจำนวนหรือคำขยาย (我买了三本书) · ถ้ากรรมเป็นคำเดี่ยว ๆ ไม่มีคำขยาย (我买了书) ประโยคจะฟังเหมือนยังพูดไม่จบ ต้องต่อประโยคถัดไป หรือย้าย 了 ไปท้ายประโยคเป็น 了2 (我买书了) · ปฏิเสธการกระทำที่ยังไม่เกิดใช้ 没 + กริยา และต้องตัด 了 ออกเสมอ (我没买书) · ระวัง: 了 ไม่ใช่รูปอดีต (past tense) เรื่องที่เป็นนิสัยในอดีตหรือการบรรยายทั่วไปไม่ต้องใส่ 了","Verb-final 了1 says an action has been realized or completed, usually followed by a quantified or modified object (我买了三本书). · With a bare object (我买了书), the sentence sounds unfinished — either continue the sentence or move 了 to the sentence end as 了2 (我买书了). · To negate, use 没 + verb and ALWAYS drop 了 (我没买书). · Careful: 了 is NOT a past tense; past habits or general descriptions take no 了.","动态助词“了1”紧跟动词后，表示动作实现或完成，宾语前常有数量词或定语（我买了三本书）。 · 宾语如果是光杆名词（我买了书），句子听起来没说完，要续说下文，或把“了”移到句末作语气助词“了2”（我买书了）。 · 否定用“没＋动词”并必须去掉“了”（我没买书）。 · 注意：“了”不是过去时，过去的习惯、心理状态或一般描写不用“了”。","Trợ từ động thái 了1 đặt ngay sau động từ chỉ hành động đã hoàn thành, trước tân ngữ thường có số lượng hoặc định ngữ (我买了三本书). · Nếu tân ngữ là danh từ trơn (我买了书) thì câu nghe chưa xong — phải nói tiếp hoặc chuyển 了 xuống cuối câu (我买书了). · Phủ định dùng 没 + động từ và bỏ 了 (我没买书). · Lưu ý: 了 không phải thì quá khứ.","動態助詞「了1」は動詞の直後に置いて動作の実現・完了を表し、目的語の前に数量や修飾語を伴うことが多い（我买了三本书）。 · 目的語が裸の名詞だけ（我买了书）だと文が途中で切れた感じになるため、続けるか文末の「了2」にする（我买书了）。 · 否定は「没＋動詞」で「了」を取る（我没买书）。 · 注意：「了」は過去形ではない。"],"use":[{"ok":true,"zh":"我买了三本书。","fix":"","py":"Wǒ mǎile sān běn shū.","tr":["ฉันซื้อหนังสือมาสามเล่ม","I bought three books.","Tôi đã mua ba cuốn sách.","本を三冊買いました。"],"h":["กริยา + 了 + จำนวน/คำขยาย + กรรม (สมบูรณ์ในตัว)","Verb + 了 + quantity/modifier + object","动词＋了＋数量／定语＋宾语","Động từ + 了 + số lượng/định ngữ + tân ngữ","動詞＋了＋数量・修飾語＋目的語"],"w":["ทำได้และเป็นโครงสร้างหลักของ 了1 เพราะกรรม (书) มีคำบอกจำนวน 三本 ขยายอยู่ข้างหน้า ทำให้ประโยคจบสมบูรณ์ชัดเจน","Works cleanly as the core pattern of 了1: the quantified object 三本书 completes the sentence naturally.","宾语“书”前带有数量定语“三本”，是动词后“了1”最标准、完整的句式。","Đúng và chuẩn nhất cho 了1 vì trước tân ngữ 书 có số lượng 三本 giúp câu hoàn chỉnh.","目的語「书」の前に数量「三本」があるため、動詞後の「了1」として完全に自然な文になる。"],"ref":"HSK 3.0 g3-1-025 · g3-1-062"},{"ok":true,"zh":"我买书了。","fix":"","py":"Wǒ mǎi shū le.","tr":["ฉันซื้อหนังสือแล้ว","I bought books / I've bought the book.","Tôi mua sách rồi.","本を買いました。"],"h":["กรรมคำเดี่ยวไม่มีจำนวน ให้วาง 了 ไว้ท้ายประโยค (了2)","With a bare object, place 了 at the end of the sentence","光杆宾语时把“了”放句末","Tân ngữ trơn thì đặt 了 ở cuối câu","裸の名詞なら「了」を文末に置く"],"w":["ทำได้เพราะพอไม่มีจำนวนหรือคำขยายหน้า 书 การวาง 了 ท้ายประโยค (了2) จะบอกการเปลี่ยนแปลง/เหตุการณ์ที่เกิดขึ้นแล้วและจบประโยคได้สมบูรณ์","Works because placing 了 at sentence end (了2) wraps up a bare verb+object phrase as a complete realized event/change.","宾语没有数量或定语修饰时，把“了”放到句末（了2）即可自然结句，表示情况已发生。","Đúng vì khi không có số lượng trước 书, đặt 了 cuối câu (了2) giúp câu kết thúc tự nhiên.","「书」に数量や修飾がない場合、文末の「了2」にすると事態の成立・変化としてきれいに結べる。"],"ref":"HSK 3.0 g3-1-063 · 教育部國語辭典"},{"ok":true,"zh":"我没买书。","fix":"","py":"Wǒ méi mǎi shū.","tr":["ฉันไม่ได้ซื้อหนังสือ","I didn't buy any books.","Tôi không mua sách.","本は買いませんでした。"],"h":["ปฏิเสธเหตุการณ์ที่ยังไม่ทำ ใช้ 没 และตัด 了 ออก","Negate with 没 and remove 了","否定用“没”并去掉“了”","Phủ định bằng 没 và bỏ 了","否定は「没」にして「了」を取る"],"w":["ทำได้เพราะ 没 แปลว่า 'ไม่ได้เกิดขึ้น' ส่วน 了1 แปลว่า 'เกิดขึ้นสำเร็จแล้ว' ความหมายขัดกันโดยตรง จึงต้องตัด 了 ทิ้งเสมอเมื่อปฏิเสธด้วย 没","Works because 没 means 'did not happen' while 了1 means 'realized/completed' — they contradict each other, so 了 must be dropped.","“没”表未发生，“了1”表已实现，二者语义冲突，否定时必须去掉“了”。","Đúng vì 没 nghĩa là chưa xảy ra, mâu thuẫn với 了1 (đã hoàn thành), nên bắt buộc bỏ 了.","「没」（起きていない）と「了1」（完了した）は意味が矛盾するため、否定では必ず「了」を省く。"],"ref":"HSK 3.0 g3-1-020 · g3-1-025"},{"ok":false,"zh":"我没买了书。","fix":"我没买书。","py":"Wǒ méi mǎi shū.","tr":["ฉันไม่ได้ซื้อหนังสือ","I didn't buy any books.","Tôi không mua sách.","本は買いませんでした。"],"h":["ห้ามใช้ 没 คู่กับ กริยา + 了1","Never combine 没 with verb + 了1","“没”和动词后的“了1”不能同现","Không dùng 没 chung với động từ + 了1","「没」と動詞後の「了1」は併用不可"],"w":["ไม่ได้ เพราะ 没 บอกว่ายังไม่เกิด แต่ 买了 บอกว่าซื้อสำเร็จไปแล้ว ขัดแย้งกันในประโยคเดียว ต้องตัด 了 ออกเป็น 我没买书","Wrong because 没 ('did not happen') directly clashes with 买了 ('already bought'). Drop 了 → 我没买书.","不行，“没”否定发生，“买了”肯定完成，自相矛盾，必须去掉“了”。","Không được vì 没 (chưa xảy ra) mâu thuẫn với 买了 (đã mua xong). Phải bỏ 了 → 我没买书.","「没」と「买了」は意味が衝突する。「了」を取って「我没买书」にする。"],"ref":"HSK 3.0 g3-1-025"},{"ok":false,"zh":"我昨天了去学校。","fix":"我昨天去学校了。","py":"Wǒ zuótiān qù xuéxiào le.","tr":["เมื่อวานฉันไปโรงเรียนแล้ว","I went to school yesterday.","Hôm qua tôi đã đi học rồi.","昨日学校へ行きました。"],"h":["ห้ามวาง 了 หลังคำบอกเวลา","Never put 了 after a time word","不能把“了”放在时间词后面","Không đặt 了 sau từ chỉ thời gian","時間の語の後ろに「了」を置けない"],"w":["ไม่ได้ เพราะ 了 เป็นคำช่วยของกริยา (วางติดหลังกริยา) หรือคำช่วยท้ายประโยค ไม่ใช่เครื่องหมายอดีตของคำบอกเวลา ต้องย้ายไปหลังกริยาหรือท้ายประโยค","Wrong because 了 attaches only after a verb or at the end of a sentence — never after a time word like 昨天.","不行，“了”只能紧跟动词后或放句末，不是时间词的过去标记。","Không được vì 了 là trợ từ đi sau động từ hoặc cuối câu, không gắn sau từ chỉ thời gian.","「了」は動詞の直後か文末に置く助詞であり、時間の語の後ろには置けない。"],"ref":"HSK 3.0 g3-1-025 · g3-1-063"},{"ok":false,"zh":"我买了书。","fix":"我买书了。","py":"Wǒ mǎi shū le.","tr":["ฉันซื้อหนังสือแล้ว","I bought books.","Tôi mua sách rồi.","本を買いました。"],"h":["ระวัง กริยา + 了 + กรรมคำเดี่ยว ฟังเหมือนยังพูดไม่จบ","Bare V + 了 + noun sounds unfinished on its own","单说“我买了书”像话没说完","V + 了 + danh từ trơn nghe chưa hết câu","裸の名詞だけの「V＋了＋名詞」は言いさしに聞こえる"],"w":["พูดจบแค่นี้ไม่เป็นธรรมชาติ เพราะคนฟังจะรอประโยคต่อ (เช่น 我买了书就回家 = ฉันซื้อหนังสือเสร็จก็กลับบ้าน) ถ้าจะจบประโยคให้เติมจำนวน (我买了一本书) หรือย้าย 了 ไปท้ายประโยค (我买书了)","Sounds incomplete by itself — listeners expect a follow-up clause. To end the sentence, add a quantity (我买了一本书) or move 了 to the end (我买书了).","单独说“我买了书”听感未完，好像后面还有下文；要完整结句，应加数量（买了一本书）或改“我买书了”。","Nói cụt 我买了书 nghe như sắp nói tiếp vế sau. Để kết câu hãy thêm số lượng (我买了一本书) hoặc chuyển 了 ra cuối (我买书了).","「我买了书」だけだと後ろに文が続く感じがする。完結させるには数量を足す（我买了一本书）か文末の「我买书了」にする。"],"ref":"HSK 3.0 g3-1-025 · g3-1-063"}],"ex":[["我买了三本书。","Wǒ mǎile sān běn shū.","ฉันซื้อหนังสือมาสามเล่ม","I bought three books.","Tôi đã mua ba cuốn sách.","本を三冊買いました。","了"],["他喝了一杯茶。","Tā hēle yī bēi chá.","เขาดื่มชาไปหนึ่งแก้ว","He drank a cup of tea.","Anh ấy đã uống một cốc trà.","彼はお茶を一杯飲みました。","了"],["我吃了一个苹果。","Wǒ chīle yī ge píngguǒ.","ฉันกินแอปเปิลไปหนึ่งลูก","I ate an apple.","Tôi đã ăn một quả táo.","りんごを一つ食べました。","了"],["我吃了一个鸡蛋。","Wǒ chīle yī ge jīdàn.","ฉันกินไข่ไก่ไปหนึ่งฟอง","I ate an egg.","Tôi đã ăn một quả trứng.","卵を一つ食べました。","了"],["我买书了。","Wǒ mǎi shū le.","ฉันซื้อหนังสือแล้ว","I bought books.","Tôi mua sách rồi.","本を買いました。","了"],["我没买书。","Wǒ méi mǎi shū.","ฉันไม่ได้ซื้อหนังสือ","I didn't buy any books.","Tôi không mua sách.","本は買いませんでした。","没"]],"err":[["我没买了书。","我没买书。","ปฏิเสธด้วย 没 แล้วต้องตัด 了 ออก","With the negative 没, drop 了.","用“没”否定时要去掉“了”。","Phủ định bằng 没 thì bỏ 了.","「没」で否定するときは「了」を取る。"],["我昨天了去学校。","我昨天去学校了。","了 อยู่หลังกริยาหรือท้ายประโยค ไม่วางหลังคำบอกเวลา","了 goes after the verb or at the end of the sentence, not after the time word.","“了”放在动词后或句末，不放在时间词后。","了 đứng sau động từ hoặc cuối câu, không đứng sau từ chỉ thời gian.","「了」は動詞の後か文末に置き、時間の語の後には置かない。"],["我买了书。","我买书了。","กรรมคำเดี่ยวไม่มีจำนวน ให้ย้าย 了 ไปท้ายประโยค (หรือเติมจำนวนเช่น 一本书)","With a bare object, move 了 to the end (我买书了) or add a quantity (一本书).","光杆宾语时应把“了”放句末（我买书了），或给宾语加数量。","Tân ngữ trơn nên chuyển 了 ra cuối câu (我买书了) hoặc thêm số lượng.","裸の名詞だけなら文末の「我买书了」にするか数量を付ける。"]],"rel":["g3-1-063","g3-1-062","g3-1-020"]},"g3-1-026":{"t":["吗 / 吧 / 呢: คำช่วยท้ายประโยค","吗 / 吧 / 呢: sentence-final particles","语气助词：吗、吧、呢","吗 / 吧 / 呢: trợ từ ngữ khí cuối câu","語気助詞：吗・吧・呢"],"f":["陈述句 + 吗？（一般是非问）","句子 + 吧（商量、提议、推测）","名词 / 代词 + 呢？（反问“……怎么样 / 在哪儿”）"],"why":["คำช่วยทั้งสามวางท้ายประโยคเพื่อเปลี่ยนน้ำเสียง · 吗 เปลี่ยนประโยคบอกเล่าธรรมดาเป็นคำถามใช่/ไม่ใช่ (你是学生 → 你是学生吗？) โดยไม่ต้องสลับตำแหน่งคำ · 吧 ใช้ชักชวน (我们去吧 = ไปกันเถอะ) หรือเดาไว้แล้วถามเพื่อยืนยัน (你是学生吧？ = คุณเป็นนักเรียนใช่ไหม) · 呢 ใช้ถามย้อนเรื่องเดิมหรือถามว่าอยู่ที่ไหน (我很好，你呢？ / 你爸爸呢？) · ข้อห้ามสำคัญ: ประโยคที่มีคำแสดงคำถามอยู่แล้ว (什么, 谁, 哪儿, 几) ห้ามเติม 吗 ต่อท้าย","All three sit at the end of a sentence to set its mood. · 吗 turns a statement into a neutral yes/no question without changing word order. · 吧 makes a suggestion ('let's…') or checks a guess ('…right?'). · 呢 bounces a question back ('and you?') or asks 'where is…?'. · Key rule: NEVER add 吗 when a question word (什么, 谁, 哪儿, 几) is already in the sentence.","三个语气助词均放在句末。 · “吗”把陈述句直接变成是非问句，语序不变（你是学生吗？）。 · “吧”表示商量提议（我们去吧）或带推测的确认（你是学生吧？）。 · “呢”承接上文反问或询问人／物在哪儿（我很好，你呢？／你爸爸呢？）。 · 重要禁令：句中已有疑问代词（什么、谁、哪儿、几）时，绝不能再加“吗”。","Cả ba đứng cuối câu để tạo ngữ khí. · 吗 biến câu trần thuật thành câu hỏi đúng/sai không cần đổi trật tự từ. · 吧 dùng để rủ rê ('đi thôi') hoặc phỏng đoán xác nhận ('…phải không?'). · 呢 hỏi ngược lại ('còn… thì sao?') hoặc hỏi ở đâu. · Cấm kỵ: câu đã có từ để hỏi (什么, 谁, 哪儿, 几) thì KHÔNG thêm 吗.","いずれも文末に置いて語気を表す。 · 「吗」は平叙文の語順のまま疑問文にする（你是学生吗？）。 · 「吧」は誘い（我们去吧）や推測の確認（你是学生吧？）。 · 「呢」は聞き返し（你呢？）や所在の質問（你爸爸呢？）。 · 重要ルール：疑問詞（什么・谁・哪儿・几）がある文に「吗」は付けない。"],"use":[{"ok":true,"zh":"你是学生吗？","fix":"","py":"Nǐ shì xuésheng ma?","tr":["คุณเป็นนักเรียนหรือเปล่า","Are you a student?","Bạn là học sinh phải không?","あなたは学生ですか。"],"h":["ประโยคบอกเล่า + 吗？ = คำถามใช่/ไม่ใช่ (ไม่สลับคำ)","Statement + 吗？ = neutral yes/no question","陈述句＋吗？＝是非问句","Câu trần thuật + 吗？ = câu hỏi đúng/sai","平叙文＋吗？＝はい・いいえの疑問文"],"w":["ทำได้เพราะในภาษาจีนแค่เติม 吗 ท้ายประโยคบอกเล่า 你是学生 ก็เป็นคำถามได้ทันที โดยไม่ต้องสลับคำหรือเติมกริยาช่วยแบบภาษาอังกฤษ","Works because Chinese turns any plain statement directly into a yes/no question just by appending 吗 — no word-order inversion needed.","只需在陈述句尾直接加“吗”，不改动语序就能变成中性的“是不是”问句。","Đúng vì chỉ cần thêm 吗 cuối câu trần thuật mà không cần đảo ngữ.","平叙文の語順を変えずに文末へ「吗」を足すだけで中立な疑問文になる。"],"ref":"กลุ่มเทียบคำ g13 · ประโยคตัวอย่าง_300"},{"ok":true,"zh":"我们去吧。","fix":"","py":"Wǒmen qù ba.","tr":["พวกเราไปกันเถอะ","Let's go.","Chúng ta đi thôi.","行きましょう。"],"h":["ชวนหรือขอความเห็นแบบนุ่มนวลใช้ 吧","Use 吧 for suggestions or checking a guess","商量、提议或推测用“吧”","Rủ rê, đề nghị hoặc đoán dùng 吧","誘い・提案・推測の確認は「吧」"],"w":["ทำได้เพราะ 吧 ทำให้น้ำเสียงดูชวนคุย ไม่แข็งเหมือนคำสั่ง และเมื่อใช้กับประโยคคำถาม (你是学生吧？) แสดงว่าผู้พูดพอจะเดาคำตอบไว้แล้ว แค่อยากให้ยืนยัน","Works because 吧 softens proposals ('let's…') and in questions (你是学生吧？) signals you already expect 'yes' and are confirming.","“吧”缓和语气，可用于提议（我们去吧），也可用于心里有底时的推测确认（你是学生吧？）。","Đúng vì 吧 làm mềm câu đề nghị ('đi thôi') và khi hỏi (你是学生吧？) thể hiện người nói đã đoán trước.","「吧」は提案を柔らかくし、疑問文（你是学生吧？）では予想を確かめるニュアンスを出す。"],"ref":"กลุ่มเทียบคำ g13 · ชุด w3-00004 · 教育部國語辭典"},{"ok":true,"zh":"你爸爸呢？","fix":"","py":"Nǐ bàba ne?","tr":["พ่อของคุณล่ะ (อยู่ไหน)","And where is your dad?","Còn bố bạn đâu?","お父さんはどこですか。"],"h":["คำนาม + 呢？ = ถามว่า '...ล่ะ / อยู่ไหน'","Noun + 呢？ = 'what about… / where is…?'","名词＋呢？＝询问下落或承前反问","Danh từ + 呢？ = hỏi ngược lại hoặc hỏi ở đâu","名詞＋呢？＝「〜は？（どこ？／どう？）」"],"w":["ทำได้เพราะ 呢 วางหลังคำนามหรือสรรพนามสั้น ๆ เพื่อถามย้อนตามบริบทก่อนหน้า (我很好，你呢？) หรือถามหาว่าคน/สิ่งของนั้นอยู่ที่ไหน","Works because 呢 after a bare noun/pronoun asks a context-dependent follow-up ('how about you?') or asks where someone/something is.","“呢”接在名词或代词后，既可承接上文反问（你呢？），也可直接问人或物在哪里。","Đúng vì 呢 đứng sau danh từ/đại từ để hỏi ngược theo ngữ cảnh (你呢？) hoặc hỏi đang ở đâu.","名詞や代名詞の後ろの「呢」は文脈を受けた聞き返し（你呢？）や人や物の所在を尋ねるのに使える。"],"ref":"กลุ่มเทียบคำ g13 · ประโยคตัวอย่าง_300"},{"ok":false,"zh":"你去哪儿吗？","fix":"你去哪儿？","py":"Nǐ qù nǎr?","tr":["คุณจะไปไหน","Where are you going?","Bạn đi đâu thế?","どこへ行きますか。"],"h":["ห้ามเติม 吗 เมื่อมีคำแสดงคำถามอยู่แล้ว","Never add 吗 when a question word is present","有疑问词的句子不能再加“吗”","Đã có từ để hỏi thì KHÔNG thêm 吗","疑問詞がある文に「吗」は付けられない"],"w":["ไม่ได้ เพราะคำว่า 哪儿 (ไหน) ทำให้ประโยคเป็นคำถามเฉพาะเจาะจงอยู่แล้ว (เช่นเดียวกับ 什么, 谁, 几, 多少, 怎么) การเติม 吗 เข้าไปจะซ้ำซ้อนและผิดไวยากรณ์ (แต่ถ้าเติม 呢 เพื่อทำให้น้ำเสียงนุ่มนวลขึ้นเป็น 你去哪儿呢？ ทำได้!)","Wrong because 哪儿 ('where') already makes it a wh-question (same for 什么, 谁, 几, 多少, 怎么); adding 吗 clashes. (Softening with 呢 is fine.)","不行，句中已有疑问词“哪儿”（以及什么、谁、几等），本身就是特指问句，绝不能再加“吗”（可加“呢”缓和语气）。","Không được vì 哪儿 đã tạo thành câu hỏi rồi (cũng như 什么, 谁, 几); thêm 吗 là sai ngữ pháp.","すでに疑問詞「哪儿」があるため「吗」を足すと疑問が重複して誤用になる（語気を和らげる「呢」なら可）。"],"ref":"กลุ่มเทียบคำ g13 · HSK 3.0 g3-1-047/048"},{"ok":false,"zh":"你好不好吗？","fix":"你好不好？","py":"Nǐ hǎo bù hǎo?","tr":["คุณสบายดีไหม / ดีหรือไม่ดี","Are you okay? / Is that okay?","Bạn có khỏe không? / Được không?","元気ですか／いいですか。"],"h":["ห้ามเติม 吗 ท้ายคำถามแบบ V-ไม่-V (正反问)","Never add 吗 to an A-not-A question","正反问句末尾不能加“吗”","Không thêm 吗 cuối câu hỏi chính phản (A不A)","反復疑問文（A不A）の文末に「吗」は付けない"],"w":["ไม่ได้ เพราะรูป '好不好 / 是不是 / 去不去' เป็นโครงสร้างคำถามในตัวอยู่แล้ว (正反问句) เลือกใช้แบบใดแบบหนึ่งเท่านั้น: 你好吗？ หรือ 你好不好？","Wrong because A-not-A (好不好 / 是不是 / 去不去) is already a yes/no question pattern; pick either 你好吗？ OR 你好不好？, never both.","不行，“好不好／是不是”本身已是正反问句，不能和“吗”叠加使用，二者只能选其一。","Không được vì 好不好 bản thân đã là câu hỏi chính phản rồi, chỉ chọn 1 trong 2: 你好吗？ hoặc 你好不好？.","「好不好」はそれ自体が反復疑問文なので「吗」と重ねられない。「你好吗？」か「你好不好？」のどちらか一方にする。"],"ref":"HSK 3.0 g3-1-047 · g3-1-049"}],"ex":[["你是学生吗？","Nǐ shì xuésheng ma?","คุณเป็นนักเรียนหรือเปล่า","Are you a student?","Bạn là học sinh phải không?","あなたは学生ですか。","吗"],["你是学生吧？","Nǐ shì xuésheng ba?","คุณเป็นนักเรียนใช่ไหม (เดาไว้แล้ว)","You're a student, right?","Bạn là học sinh phải không nhỉ?","学生さんですよね。","吧"],["我们去吧。","Wǒmen qù ba.","พวกเราไปกันเถอะ","Let's go.","Chúng ta đi thôi.","行きましょう。","吧"],["我很好，你呢？","Wǒ hěn hǎo, nǐ ne?","ฉันสบายดี แล้วคุณล่ะ","I'm fine, and you?","Tôi khỏe, còn bạn?","私は元気です、あなたは？","呢"],["你爸爸呢？","Nǐ bàba ne?","พ่อของคุณอยู่ไหนล่ะ","Where is your dad?","Bố bạn đâu rồi?","お父さんはどこですか。","呢"],["你喝茶吗？","Nǐ hē chá ma?","คุณดื่มชาไหม","Do you drink tea?","Bạn có uống trà không?","お茶を飲みますか。","吗"]],"err":[["你去哪儿吗？","你去哪儿？","มีคำแสดงคำถาม (哪儿, 什么, 谁, 几) แล้ว ห้ามเติม 吗","Never add 吗 when a question word (哪儿, 什么, 谁, 几) is already used.","有疑问词（哪儿、什么、谁等）的句子不能加“吗”。","Đã có từ để hỏi (哪儿, 什么, 谁) thì không thêm 吗.","疑問詞（哪儿・什么・谁など）がある文には「吗」を付けない。"],["你是学生不是吗？","你是不是学生？","คำถามแบบ 是不是 ห้ามใช้คู่กับ 吗 (เลือกอย่างใดอย่างหนึ่ง)","Do not combine an A-not-A question with 吗 — pick one.","正反问句“是不是”不能和“吗”同时用。","Không dùng chung câu hỏi chính phản 是不是 với 吗.","反復疑問文「是不是」と「吗」は同時に使えない。"]],"rel":["g3-1-047","g3-1-048","g3-1-049"]},"g3-1-027":{"t":["คำอุทาน 喂: “ฮัลโหล / เฮ้”","Interjection 喂: 'hello (phone) / hey'","叹词：喂","Thán từ 喂: 'a lô / này'","感嘆詞「喂」：もしもし・おい"],"f":["喂，请问……？（接打电话）","喂，你去哪儿？（引起注意，仅对熟人）"],"why":["喂 เป็นคำอุทานที่ยืนเดี่ยวหน้าประโยค (คั่นด้วยจุลภาคหรือเครื่องหมายคำถาม) ใช้หลัก 2 แบบ: (1) รับหรือโทรออกทางโทรศัพท์ = 'ฮัลโหล' (喂，你好！ / 喂，请问王老师在吗？) ออกเสียงได้ทั้ง wéi (เสียง 2 สุภาพกว่าตอนรับสาย) และ wèi (เสียง 4) (2) เรียกความสนใจ = 'เฮ้ / นี่' · ข้อควรระวัง: ห้ามใช้ 喂 เรียกครูหรือผู้ใหญ่ต่อหน้า เพราะฟังห้วนและไม่สุภาพ (ต่อหน้าให้ใช้ 请问 หรือเรียกชื่อ/ตำแหน่ง)","喂 stands independently at the start of a sentence for two uses: (1) answering or starting a phone call ('hello?' — pronounced wéi or wèi), (2) getting someone's attention ('hey!'). · Caution: NEVER call out 喂 face-to-face to a teacher, elder, or stranger — it sounds rude; use 请问 or their title instead.","“喂”作为叹词独立位于句首，主要有两种用法：（1）接打电话时的招呼语（常读 wéi 或 wèi）；（2）呼叫对方引起注意。 · 注意：面对面切忌对老师、长辈或陌生人喊“喂”，显得不礼貌，应说“请问”或称呼对方。","喂 đứng độc lập đầu câu với 2 cách dùng: (1) nghe/gọi điện thoại ('a lô', đọc wéi hoặc wèi), (2) gọi gây chú ý ('này!'). · Lưu ý: KHÔNG gọi 喂 trực diện với thầy cô, người lớn tuổi hay người lạ vì bất lịch sự; hãy dùng 请问.","「喂」は文頭に独立して置き、（1）電話の「もしもし」（wéi／wèi）、（2）呼びかけの「おい・ねえ」に使う。 · 注意：対面で先生・目上の人・見知らぬ人に「喂」と呼びかけるのは失礼。「请问」や敬称を使う。"],"use":[{"ok":true,"zh":"喂，请问王老师在吗？","fix":"","py":"Wèi, qǐngwèn Wáng lǎoshī zài ma?","tr":["ฮัลโหล ขอถามหน่อยครับ/คะ อาจารย์หวังอยู่ไหม","Hello, excuse me, is Teacher Wang there?","A lô, xin hỏi thầy Vương có ở đó không ạ?","もしもし、すみませんが王先生はいらっしゃいますか。"],"h":["รับสายหรือโทรหาทางโทรศัพท์ใช้ 喂 ได้อย่างสุภาพ","Use 喂 naturally on the phone (paired with 请问 / 你好)","打电话时说“喂，请问……”自然礼貌","Nghe/gọi điện dùng 喂 kèm 请问 / 你好 rất lịch sự","電話で「喂，请问…」と言うのは自然で丁寧"],"w":["ทำได้และเป็นมาตรฐานของการคุยโทรศัพท์ในภาษาจีน โดยเฉพาะเมื่อต่อด้วย 你好 หรือ 请问 (พจนานุกรมมาตรฐานเขียนเสียง wèi และในภาษาพูดรับสายมักออกเสียง wéi ให้นุ่มนวล)","Works as the standard Chinese phone greeting, especially with 你好 or 请问 (dictionary standard is wèi; colloquially often softened to wéi).","接打电话说“喂”是汉语标准用法（规范注音 wèi，口语接电话常读 wéi），配“你好／请问”礼貌得体。","Đúng và là cách mở đầu cuộc gọi chuẩn (phiên âm chuẩn wèi, khẩu ngữ hay đọc wéi cho nhẹ nhàng).","電話の冒頭の「喂」は標準的（辞書表記は wèi、口語では wéi と柔らかく発音することも）。"],"ref":"HSK 3.0 g3-1-027 · ชนิดของคำ_12ชนิด"},{"ok":true,"zh":"请问，学校在哪儿？","fix":"","py":"Qǐngwèn, xuéxiào zài nǎr?","tr":["ขอโทษนะครับ/คะ โรงเรียนอยู่ที่ไหน","Excuse me, where is the school?","Xin hỏi, trường học ở đâu ạ?","すみません、学校はどこですか。"],"h":["ถามทาง/ทักคนแปลกหน้าต่อหน้าใช้ 请问 แทน 喂","Face-to-face with strangers, use 请问 instead of 喂","面对面问路或叫陌生人用“请问”","Gặp mặt hỏi người lạ dùng 请问 thay vì 喂","対面で見知らぬ人に声をかけるときは「请问」"],"w":["ทำได้และสุภาพกว่ามาก เพราะ 请问 ('ขอเรียนถาม') เป็นวิธีเรียกความสนใจที่นุ่มนวลสำหรับคนแปลกหน้า ผู้ใหญ่ หรือครู","Works politely because 请问 ('may I ask') is the proper respectful way to get a stranger's or elder's attention in person.","面对面叫陌生人或长辈时，“请问”礼貌得体，避免“喂”带来的生硬感。","Đúng và lịch sự hơn nhiều khi hỏi đường hoặc gọi người lạ ngoài đời.","対面で呼びかけるときは「请问」が丁寧で角が立たない。"],"ref":"HSK 3.0 g3-1-027"},{"ok":false,"zh":"喂，老师，这是什么？","fix":"请问，老师，这是什么？","py":"Qǐngwèn, lǎoshī, zhè shì shénme?","tr":["ขอถามครับ/ค่ะ อาจารย์ นี่คืออะไร","Excuse me, teacher, what is this?","Xin hỏi thầy/cô, đây là cái gì ạ?","すみません先生、これは何ですか。"],"h":["ห้ามตะโกนเรียก 喂 ใส่ครูหรือผู้ใหญ่ต่อหน้า","Never shout 喂 at a teacher or elder in person","面对面不可对老师或长辈喊“喂”","Không gọi 喂 trực tiếp với thầy cô/người lớn","対面で先生や目上の人に「喂」と呼びかけない"],"w":["ไม่ได้ในมารยาทภาษาจีน เพราะ 喂 นอกโทรศัพท์จะฟังเหมือน 'เฮ้ย!' ไม่ให้เกียรติผู้ฟัง ควรเรียก 老师 หรือใช้ 请问 นำหน้าแทน","Impolite in person: outside phone calls, 喂 sounds like a blunt 'hey!'; address them with 老师 or 请问 instead.","不礼貌，非电话场合喊“喂”语气生硬，对老师应直接称“老师”或用“请问”。","Bất lịch sự vì ngoài điện thoại, 喂 nghe cộc lốc như 'này!'; hãy gọi 老师 hoặc 请问.","電話以外で「喂」と呼ぶと「おい！」とぶっきらぼうに聞こえる。「请问／老师」を使う。"],"ref":"HSK 3.0 g3-1-027 · ชนิดของคำ_12ชนิด"}],"ex":[["喂，你好！","Wèi, nǐ hǎo!","ฮัลโหล สวัสดีครับ/ค่ะ!","Hello! (on the phone)","A lô, xin chào!","もしもし、こんにちは！","喂"],["喂，请问王老师在吗？","Wèi, qǐngwèn Wáng lǎoshī zài ma?","ฮัลโหล ขอถามหน่อยครับ/คะ อาจารย์หวังอยู่ไหม","Hello, is Teacher Wang there?","A lô, xin hỏi thầy Vương có đó không?","もしもし、王先生はいらっしゃいますか。","喂"],["喂，你现在在哪儿？","Wèi, nǐ xiànzài zài nǎr?","ฮัลโหล ตอนนี้คุณอยู่ที่ไหน","Hello, where are you right now?","A lô, bây giờ bạn đang ở đâu?","もしもし、今どこにいますか。","喂"],["喂，你是小王吗？","Wèi, nǐ shì Xiǎo Wáng ma?","ฮัลโหล คุณคือเสี่ยวหวังใช่ไหม","Hello, is this Xiao Wang?","A lô, bạn là Tiểu Vương phải không?","もしもし、王さんですか。","喂"],["喂，妈妈，我到学校了。","Wèi, māma, wǒ dào xuéxiào le.","ฮัลโหลแม่ หนูถึงโรงเรียนแล้วนะ","Hello Mom, I arrived at school.","A lô mẹ ơi, con đến trường rồi.","もしもしお母さん、学校に着いたよ。","喂"]],"err":[["喂，老师，这是什么？","请问，老师，这是什么？","ต่อหน้าห้ามเรียกครูหรือผู้ใหญ่ว่า 喂 ให้ใช้ 请问 หรือเรียกตำแหน่ง","Don't call a teacher 喂 in person; use 请问 or their title.","面对面不对老师喊“喂”，应说“请问”。","Gặp trực tiếp không gọi thầy cô là 喂, hãy dùng 请问.","対面で先生に「喂」は失礼。「请问」を使う。"]],"rel":["g3-1-045","g3-1-047"]},"g3-1-028":{"t":["วลีเชื่อมคู่ขนาน (联合短语): A 和 B","Coordinated phrases (联合短语): A 和 B","短语结构（1）：联合短语","Cụm từ đẳng lập (联合短语): A 和 B","並列句（联合短语）：A 和 B"],"f":["名词1 + 和 + 名词2（爸爸和妈妈 / 苹果和牛奶）","词1、词2 + 和 + 词3（只放一个“和”在最后一项前）"],"why":["联合短语 คือกลุ่มคำที่นำคำชนิดเดียวกันที่มีน้ำหนักเท่ากันมาวางคู่กัน เช่น คำนามคู่กับคำนาม (爸爸和妈妈, 老师和学生) หรือกริยา/คุณศัพท์คู่กัน · วิธีเชื่อมคำนาม 2 ตัวขึ้นไปใช้ 和 วางหน้าตัวสุดท้ายเพียงครั้งเดียว ส่วนรายการก่อนหน้าใช้เครื่องหมายจุลภาคจีน 、 (顿号) คั่น · ข้อควรระวัง: ห้ามใช้ 和 เชื่อมประโยคเต็มสองประโยค (ใช้เครื่องหมายจุลภาค หรือ 也/还 แทน) และถ้ามี 3 รายการ ห้ามใส่ 和 ซ้ำทุกช่อง","A coordinated phrase (联合短语) joins words of the same grammatical class on equal footing, most commonly nouns with 和 (爸爸和妈妈, 老师和学生). · With 3+ nouns, separate earlier items with the Chinese enumeration comma 、 and place ONE 和 before the last item. · Caution: NEVER use 和 to join two full clauses, and do not repeat 和 between every item.","联合短语由词性相同、地位平等的词语并列组成（爸爸和妈妈、老师和学生）。 · 三项及以上并列时，前面用顿号“、”，只在最后两项之间用一个“和”。 · 注意：“和”不能连接两个完整分句，也不要每两项间都重复加“和”。","Cụm từ đẳng lập (联合短语) ghép các từ cùng từ loại bình đẳng với nhau (爸爸和妈妈, 老师和学生). · Từ 3 mục trở lên dùng dấu phẩy liệt kê 、 và chỉ đặt MỘT chữ 和 trước mục cuối. · Lưu ý: KHÔNG dùng 和 nối hai mệnh đề hoàn chỉnh.","联合短语は同じ品詞の語を対等に並べる構造（爸爸和妈妈・老师和学生）。 · 3つ以上並べるときは「、」で区切り、最後の項目の前だけに「和」を1回置く。 · 注意：「和」で2つの文をつないではいけない。"],"use":[{"ok":true,"zh":"爸爸和妈妈都在家。","fix":"","py":"Bàba hé māma dōu zài jiā.","tr":["พ่อกับแม่อยู่บ้านทั้งคู่","Both Dad and Mom are at home.","Bố và mẹ đều ở nhà.","父と母はどちらも家にいます。"],"h":["เชื่อมคำนาม 2 ตัวเป็นประธานร่วมด้วย 和 (+ 都)","Join two nouns with 和 as a shared subject (+ 都)","用“和”连接两个名词作并列主语（常配“都”）","Nối hai danh từ bằng 和 làm chủ ngữ chung (+ 都)","2つの名詞を「和」で並べて主語にする（よく「都」と併用）"],"w":["ทำได้เพราะ 爸爸 และ 妈妈 ต่างเป็นคำนามที่มีสถานะเท่ากัน เชื่อมด้วย 和 แล้วรวมเป็นประธานพหูพจน์จับคู่กับ 都 ได้อย่างสมบูรณ์","Works because 爸爸 and 妈妈 are equal nouns joined by 和 to form a plural subject paired with 都.","“爸爸”和“妈妈”都是名词，用“和”构成联合短语作主语，配“都”非常自然。","Đúng vì 爸爸 và 妈妈 cùng là danh từ, ghép bằng 和 rồi đi với 都 rất chuẩn.","「爸爸」と「妈妈」は対等な名詞で「和」で結び「都」でまとめる自然な文。"],"ref":"HSK 3.0 g3-1-028 · g3-1-023"},{"ok":true,"zh":"我买了苹果、面包和牛奶。","fix":"","py":"Wǒ mǎile píngguǒ, miànbāo hé niúnǎi.","tr":["ฉันซื้อแอปเปิล ขนมปัง และนม","I bought apples, bread, and milk.","Tôi đã mua táo, bánh mì và sữa.","りんご、パン、そして牛乳を買いました。"],"h":["เรียง 3 รายการขึ้นไป ใช้ 、 คั่น แล้วใส่ 和 หน้าตัวสุดท้ายเท่านั้น","For 3+ items, use 、 between earlier items and ONE 和 before the last","三项并列用“A、B 和 C”，只用一次“和”","3 mục trở lên dùng 、 và chỉ đặt MỘT chữ 和 trước mục cuối","3つ以上並べるときは「A、B 和 C」と最後に1回だけ「和」"],"w":["ทำได้และเป็นมาตรฐานการเขียนภาษาจีนที่ถูกต้องตามแบบเรียน (顿号 、 ใช้เฉพาะคั่นคำเรียงระดับเดียวกัน)","Works as standard Chinese punctuation: enumeration comma 、 separates parallel nouns, with a single 和 before the final item.","“苹果、面包和牛奶”符合汉语并列多项的规范用法，清爽不啰嗦。","Đúng chuẩn tiếng Trung: dùng dấu 、 giữa các mục đầu và một chữ 和 trước mục cuối.","「、」で並列し最後の項目の前だけ「和」を置くのが標準的な中国語。"],"ref":"HSK 3.0 g3-1-028"},{"ok":false,"zh":"我买了苹果和面包和牛奶。","fix":"我买了苹果、面包和牛奶。","py":"Wǒ mǎile píngguǒ, miànbāo hé niúnǎi.","tr":["ฉันซื้อแอปเปิล ขนมปัง และนม","I bought apples, bread, and milk.","Tôi đã mua táo, bánh mì và sữa.","りんごとパンと牛乳を買いました。"],"h":["ไม่ใส่ 和 ซ้ำทุกช่องเวลาเรียงหลายรายการ","Don't repeat 和 between every single item","多项并列不重复加多个“和”","Không lặp lại 和 ở mọi khoảng giữa","すべての項目の間に「和」を繰り返さない"],"w":["ไม่เป็นธรรมชาติ เพราะการซ้ำ 和 หลายรอบทำให้ประโยคเยิ่นเย้อ ภาษาจีนใช้เครื่องหมาย 、 คั่นรายการแรก ๆ แล้วใส่ 和 แค่หน้าตัวสุดท้าย","Unnatural because repeating 和 clutters the phrase; use 、 between earlier items and put 和 only before the last.","不自然，反复用“和”显得累赘；多项并列应前用“、”，最后用一次“和”。","Không tự nhiên vì lặp nhiều 和 bị rườm rà; hãy dùng 、 và chỉ giữ một 和 ở cuối.","「和」を何度も重ねると不自然。「、」を使い最後の1回だけ「和」にする。"],"ref":"HSK 3.0 g3-1-028"},{"ok":false,"zh":"我喝茶和他喝牛奶。","fix":"我喝茶，他喝牛奶。","py":"Wǒ hē chá, tā hē niúnǎi.","tr":["ฉันดื่มชา ส่วนเขาดื่มนม","I drink tea, and he drinks milk.","Tôi uống trà, anh ấy uống sữa.","私はお茶を飲み、彼は牛乳を飲みます。"],"h":["ห้ามใช้ 和 เชื่อมประโยคเต็มสองประโยค","Never use 和 to connect two full clauses","不能用“和”连接两个完整分句","Không dùng 和 để nối hai câu hoàn chỉnh","2つの文を「和」でつないではいけない"],"w":["ไม่ได้ เพราะ 和 ใช้สร้างวลีเชื่อมคำนาม/กลุ่มคำเท่านั้น ไม่ใช่คำเชื่อมประโยคแบบ 'and / และ' ถ้าเชื่อมสองประโยคให้คั่นด้วยจุลภาค ， แทน","Wrong because 和 joins nouns/phrases, not full clauses like English 'and'. Separate the two clauses with a comma.","不行，“和”不连接分句，两个完整分句之间直接用逗号“，”即可。","Không được vì 和 chỉ nối danh từ/cụm từ, không nối mệnh đề; hãy dùng dấu phẩy.","「和」は名詞・句の並列専用。文と文は読点「，」でつなぐ。"],"ref":"HSK 3.0 g3-1-028 · g3-1-023"}],"ex":[["爸爸和妈妈都在家。","Bàba hé māma dōu zài jiā.","พ่อกับแม่อยู่บ้านทั้งคู่","Both Dad and Mom are at home.","Bố và mẹ đều ở nhà.","父と母はどちらも家にいます。","和"],["我喜欢猫和狗。","Wǒ xǐhuan māo hé gǒu.","ฉันชอบแมวและหมา","I like cats and dogs.","Tôi thích mèo và chó.","私は猫と犬が好きです。","和"],["我和朋友去书店。","Wǒ hé péngyou qù shūdiàn.","ฉันกับเพื่อนไปร้านหนังสือ","My friend and I go to the bookstore.","Tôi và bạn đi hiệu sách.","私と友達は本屋へ行きます。","和"],["桌子上有一本书和一杯水。","Zhuōzi shàng yǒu yī běn shū hé yī bēi shuǐ.","บนโต๊ะมีหนังสือหนึ่งเล่มกับน้ำหนึ่งแก้ว","On the table there is a book and a glass of water.","Trên bàn có một cuốn sách và một cốc nước.","机の上に本が1冊と水が1杯あります。","和"],["我买了苹果、面包和牛奶。","Wǒ mǎile píngguǒ, miànbāo hé niúnǎi.","ฉันซื้อแอปเปิล ขนมปัง และนม","I bought apples, bread, and milk.","Tôi đã mua táo, bánh mì và sữa.","りんご、パン、牛乳を買いました。","和"]],"err":[["我喝茶和他喝牛奶。","我喝茶，他喝牛奶。","ห้ามใช้ 和 เชื่อมประโยคเต็มสองประโยค ให้ใช้จุลภาคคั่น","Never join two full clauses with 和; use a comma.","“和”不能连接两个完整分句，应用逗号。","Không dùng 和 nối hai câu hoàn chỉnh, hãy dùng dấu phẩy.","「和」は文同士をつなげないので読点にする。"],["我买了苹果和面包和牛奶。","我买了苹果、面包和牛奶。","เรียง 3 รายการขึ้นไป ใส่ 和 หน้าตัวสุดท้ายเท่านั้น","With 3+ items, place 和 only before the final item.","多项并列只在最后一项前用一个“和”。","Từ 3 mục trở lên chỉ đặt một chữ 和 trước mục cuối.","3つ以上の並列は最後の項目の前だけ「和」を使う。"]],"rel":["g3-1-023","g3-1-035","g3-1-059"]},"g3-1-029":{"t":["วลีขยาย-คำหลัก (偏正短语): ตัวขยายอยู่หน้า คำหลักอยู่หลัง","Modifier-head phrases (偏正短语): modifier ALWAYS comes first","短语结构（2）：偏正短语","Cụm chính phụ (偏正短语): định/trạng ngữ luôn đứng TRƯỚC","修飾構造（偏正短语）：修飾語＋中心語"],"f":["修饰语（定语）+（的）+ 名词（新书 / 我的朋友 / 漂亮的衣服）","修饰语（状语）+ 动词 / 形容词（很好看 / 明天去 / 很高兴）"],"why":["偏正短语 เป็นโครงสร้างหัวใจของภาษาจีนที่ตรงข้ามกับภาษาไทยอย่างสิ้นเชิง: คำขยาย (偏) วางข้างหน้า ส่วนคำหลักที่ถูกขยาย (正) วางข้างหลังเสมอ! · มี 2 แบบใหญ่: (1) ขยายคำนาม เช่น 新书 (หนังสือใหม่), 中国菜 (อาหารจีน), 我的书 (หนังสือของฉัน) (2) ขยายกริยาหรือคุณศัพท์ เช่น 很好看 (สวยมาก), 明天去 (ไปพรุ่งนี้), 都在家 (อยู่บ้านกันหมด) · ข้อควรระวัง: อย่าเรียงแบบไทย 'คำนามก่อน + คำขยายหลัง' (เช่น 书新, 菜中国, 书我的 — ผิดทั้งหมด!)","Modifier-head phrases (偏正短语) follow the #1 rule of Chinese word order — the exact opposite of Thai: the MODIFIER always comes BEFORE the HEAD word! · Two types: (1) modifying a noun: 新书 ('new book'), 中国菜 ('Chinese food'), 我的书 ('my book'); (2) modifying a verb/adjective: 很好看 ('very pretty'), 明天去 ('go tomorrow'). · Never put noun modifiers after the noun.","偏正短语是汉语最核心的结构，顺序与泰语完全相反：修饰成分（偏）永远在前，中心语（正）永远在后！ · 分两类：（1）定中短语修饰名词（新书、中国菜、我的书）；（2）状中短语修饰动词或形容词（很好看、明天去）。 · 切忌按泰语语序把修饰语放后面。","Cụm chính phụ (偏正短语) tuân theo quy tắc số 1 của tiếng Trung — ngược hoàn toàn tiếng Việt/Thái: thành phần bổ nghĩa (偏) LUÔN đứng TRƯỚC từ trung tâm (正)! · Gồm 2 loại: bổ nghĩa danh từ (新书, 中国菜, 我的书) và bổ nghĩa động/tính từ (很好看, 明天去).","偏正短语は中国語の最重要構造で、常に「修飾語（偏）＋中心語（正）」の順になる。 · （1）名詞修飾：新书・中国菜・我的书、（2）動詞／形容詞修飾：很好看・明天去。 · 中心語の後ろに修飾語を置かない。"],"use":[{"ok":true,"zh":"我买了一件新衣服。","fix":"","py":"Wǒ mǎile yī jiàn xīn yīfu.","tr":["ฉันซื้อเสื้อผ้าชุดใหม่หนึ่งตัว","I bought a new piece of clothing.","Tôi đã mua một chiếc áo mới.","新しい服を一着買いました。"],"h":["คุณศัพท์พยางค์เดียว + คำนาม: 新衣服 (ไม่ต้องใส่ 的)","1-syllable adj + noun: 新衣服 (no 的 needed)","单音节形容词可直接修饰名词（新衣服）","Tính từ 1 âm tiết + danh từ: 新衣服 (không cần 的)","1音節形容詞＋名詞は「的」不要（新衣服）"],"w":["ทำได้เพราะ 新 (ใหม่) เป็นตัวขยายวางหน้าคำหลัก 衣服 (เสื้อผ้า) โดยคุณศัพท์พยางค์เดียวเกาะติดคำนามได้เลยไม่ต้องมี 的","Works because modifier 新 ('new') precedes head noun 衣服 ('clothes'), and 1-syllable adjectives attach tightly without 的.","修饰语“新”在中心语“衣服”前，单音节形容词常直接组合不加“的”。","Đúng vì định ngữ 新 đứng trước danh từ 衣服 và tính từ 1 âm tiết nối thẳng không cần 的.","修飾語「新」が中心語「衣服」の前に来、1音節形容詞は「的」なしで直接結びつく。"],"ref":"HSK 3.0 g3-1-029 · g3-1-024"},{"ok":true,"zh":"我很喜欢中国菜。","fix":"","py":"Wǒ hěn xǐhuan Zhōngguó cài.","tr":["ฉันชอบอาหารจีนมาก","I really like Chinese food.","Tôi rất thích món ăn Trung Quốc.","私は中華料理がとても好きです。"],"h":["ทั้ง 很喜欢 และ 中国菜 ล้วนเป็น 偏正短语 (ขยายอยู่หน้า)","Both 很喜欢 and 中国菜 are modifier-head phrases","“很喜欢”（状中）与“中国菜”（定中）都是偏正短语","Cả 很喜欢 và 中国菜 đều là cụm chính phụ (bổ nghĩa trước)","「很喜欢」も「中国菜」も修飾語が前の偏正構造"],"w":["ทำได้เพราะในประโยคเดียวมีทั้งวลีขยายกริยา (很 + 喜欢 = ชอบมาก) และวลีขยายคำนาม (中国 + 菜 = อาหารจีน) ที่วางตัวขยายนำหน้าทั้งหมด","Works cleanly with two modifier-head phrases in one sentence: 很 + 喜欢 (adv + verb) and 中国 + 菜 (noun + noun).","句中“很＋喜欢”和“中国＋菜”严格遵循“修饰语在前、中心语在后”。","Đúng vì cả hai cụm 很+喜欢 và 中国+菜 đều đặt phần bổ nghĩa lên trước.","「很＋喜欢」も「中国＋菜」も「修飾語＋中心語」の語順通り。"],"ref":"HSK 3.0 g3-1-029"},{"ok":false,"zh":"我买了一件衣服新。","fix":"我买了一件新衣服。","py":"Wǒ mǎile yī jiàn xīn yīfu.","tr":["ฉันซื้อเสื้อผ้าใหม่หนึ่งตัว","I bought a new piece of clothing.","Tôi mua một chiếc áo mới.","新しい服を一着買いました。"],"h":["ห้ามวางคำขยายไว้หลังคำนามแบบภาษาไทย ('เสื้อผ้าใหม่')","Never place the adjective after the noun like Thai","形容词定语绝不能放在名词后面","Không đặt tính từ bổ nghĩa sau danh từ như tiếng Việt/Thái","形容詞を名詞の後ろに置けない"],"w":["ไม่ได้ เพราะภาษาไทยเรียง 'เสื้อผ้า + ใหม่' แต่ภาษาจีนต้องเอาตัวขยาย 新 ขึ้นหน้าคำหลัก 衣服 เสมอ: 新衣服 (เช่นเดียวกับ 好朋友, 热水, 汉语书)","Wrong because Thai puts 'clothes + new' while Chinese strictly puts the modifier first: 新衣服 (also 好朋友, 热水, 汉语书).","不行，汉语修饰语必须在中心语前，须说“新衣服”，不能说“衣服新”。","Không được vì tiếng Trung bắt buộc đặt tính từ trước danh từ: 新衣服.","中国語では修飾語が必ず前になるため「新衣服」とし、「衣服新」とは言えない。"],"ref":"HSK 3.0 g3-1-029 · g3-1-039"},{"ok":false,"zh":"我喜欢很中国菜。","fix":"我很喜欢中国菜。","py":"Wǒ hěn xǐhuan Zhōngguó cài.","tr":["ฉันชอบอาหารจีนมาก","I like Chinese food very much.","Tôi rất thích món Trung Quốc.","中華料理がとても好きです。"],"h":["ห้ามวางคำวิเศษณ์ระดับ (很 / 非常) ไว้หลังกริยาหรือคุณศัพท์","Never place degree adverbs (很 / 非常) after the verb or adjective","程度副词“很、非常”必须放在动词／形容词前","Không đặt phó từ mức độ (很/非常) sau động/tính từ","程度副詞（很・非常）は動詞・形容詞の後ろに置けない"],"w":["ไม่ได้ เพราะในภาษาไทยพูดว่า 'ชอบ + มาก' แต่ในภาษาจีน 很 เป็นคำขยายกริยา (状语) ต้องวางหน้ากริยา 喜欢 เสมอเป็น 很喜欢","Wrong because Thai says 'like + very much', whereas Chinese puts degree adverbs BEFORE the verb/adj: 很喜欢.","不行，副词“很”作状语必须在“喜欢”前面，说“很喜欢”。","Không được vì 很 là trạng ngữ phải đứng trước động từ 喜欢 (很喜欢).","「很」は動詞「喜欢」の前（很喜欢）に置き、後ろには置けない。"],"ref":"HSK 3.0 g3-1-029 · g3-1-040"}],"ex":[["我买了一件新衣服。","Wǒ mǎile yī jiàn xīn yīfu.","ฉันซื้อเสื้อผ้าใหม่หนึ่งตัว","I bought a new piece of clothing.","Tôi mua một chiếc áo mới.","新しい服を1着買いました。","新衣服"],["我很喜欢中国菜。","Wǒ hěn xǐhuan Zhōngguó cài.","ฉันชอบอาหารจีนมาก","I really like Chinese food.","Tôi rất thích món ăn Trung Quốc.","中華料理がとても好きです。","中国菜"],["她是我的好朋友。","Tā shì wǒ de hǎo péngyou.","เธอคือเพื่อนสนิทของฉัน","She is my good friend.","Cô ấy là bạn tốt của tôi.","彼女は私の親友です。","好朋友"],["我想喝一杯热茶。","Wǒ xiǎng hē yī bēi rè chá.","ฉันอยากดื่มชาร้อนสักแก้ว","I want to drink a cup of hot tea.","Tôi muốn uống một cốc trà nóng.","熱いお茶を一杯飲みたいです。","热茶"],["这是一本汉语书。","Zhè shì yī běn Hànyǔ shū.","นี่คือหนังสือภาษาจีนหนึ่งเล่ม","This is a Chinese textbook.","Đây là một cuốn sách tiếng Trung.","これは中国語の本です。","汉语书"]],"err":[["我买了一件衣服新。","我买了一件新衣服。","ภาษาจีนวางคำขยายไว้หน้าคำนามเสมอ (新衣服)","Chinese always puts modifiers before nouns (新衣服).","修饰语在名词前（新衣服）。","Định ngữ luôn đứng trước danh từ (新衣服).","修飾語は常に名詞の前（新衣服）。"],["我喜欢很中国菜。","我很喜欢中国菜。","คำขยายกริยา (很) ต้องวางหน้ากริยา (很喜欢)","Place degree adverb 很 before the verb (很喜欢).","副词“很”必须放在动词前（很喜欢）。","Phó từ 很 phải đặt trước động từ (很喜欢).","副詞「很」は動詞の前（很喜欢）に置く。"]],"rel":["g3-1-039","g3-1-040","g3-1-024"]},"g3-1-030":{"t":["วลีกริยา-กรรม (动宾短语): กริยา + กรรม","Verb-object phrases (动宾短语): Verb + Object","短语结构（3）：动宾短语","Cụm động tân (动宾短语): Động từ + Tân ngữ","動目構造（动宾短语）：動詞＋目的語"],"f":["动词 + 宾语（看书 / 喝茶 / 买苹果 / 学汉语 / 去北京）"],"why":["动宾短语 คือกลุ่มคำที่ประกอบด้วย 'กริยา (动) + กรรมที่รับการกระทำ (宾)' ซึ่งเป็นโครงสร้างเดียวกับภาษาไทยและอังกฤษ เช่น 看书 (อ่านหนังสือ), 喝茶 (ดื่มชา), 买苹果 (ซื้อแอปเปิล), 去学校 (ไปโรงเรียน) · ข้อควรระวังสำคัญ: (1) เวลาเติม 了1 (ทำเสร็จแล้ว) หรือจำนวน (一本书) ต้องแทรกไว้ 'หลังกริยา หน้ากรรม' เช่น 看了一本书, 喝一杯茶 (2) คำกริยาบางตัวในภาษาจีนมีกรรมติดมาแล้ว (离合词 เช่น 吃饭, 睡觉, 说话) จึงห้ามใส่กรรมอีกตัวต่อท้ายตรง ๆ (เช่น ไม่พูด 吃饭米饭)","A verb-object phrase (动宾短语) pairs a verb with its object in the same V + O order as Thai and English: 看书 ('read a book'), 喝茶 ('drink tea'), 买苹果 ('buy apples'), 去学校 ('go to school'). · Key cautions: (1) Insert 了1 or numeral+CL BETWEEN the verb and object (看了一本书). (2) Don't tack an extra direct object onto verbs that already include an object (like 吃饭, 睡觉 — never 吃饭米饭).","动宾短语由“动词＋宾语”构成（看书、喝茶、买苹果、去学校），语序与泰语、英语一致。 · 注意：（1）“了1”或数量定语插在动词和宾语之间（看了一本书）；（2）像“吃饭、睡觉”这类已带宾语的词语，后面不能再直接加宾语（不说“吃饭米饭”）。","Cụm động tân (动宾短语) gồm 'Động từ + Tân ngữ' giống tiếng Việt/Thái: 看书, 喝茶, 买苹果, 去学校. · Lưu ý: (1) 了1 và số lượng đặt GIỮA động từ và tân ngữ (看了一本书); (2) Không thêm tân ngữ thừa sau động từ đã có tân ngữ sẵn như 吃饭 (không nói 吃饭米饭).","动宾短语は「動詞＋目的語」の構造（看书・喝茶・买苹果・去学校）。 · 注意：（1）「了1」や数量詞は動詞と目的語の間に挟む（看了一本书）。（2）「吃饭・睡觉」のようにすでに目的語を含む語に別の目的語を直結しない（吃饭米饭は不可）。"],"use":[{"ok":true,"zh":"我买了一本书。","fix":"","py":"Wǒ mǎile yī běn shū.","tr":["ฉันซื้อหนังสือหนึ่งเล่ม","I bought a book.","Tôi đã mua một cuốn sách.","本を1冊買いました。"],"h":["แทรก 了1 และจำนวนไว้ระหว่างกริยากับกรรม (买 + 了 + 一本 + 书)","Insert 了1 and quantity between Verb and Object","“动词＋了1＋数量词＋宾语”结构清晰","Chèn 了1 và số lượng giữa động từ và tân ngữ","「動詞＋了1＋数量詞＋目的語」の順"],"w":["ทำได้เพราะ 买 เป็นกริยา 书 เป็นกรรม การแทรก 了1 หลังกริยาและวางจำนวน 一本 หน้าคำนาม 书 ทำให้ประโยคสมบูรณ์และเป็นธรรมชาติ","Works because 了1 attaches to the verb 买 and the quantity 一本 modifies the object 书.","“了1”紧跟动词“买”，“一本”修饰宾语“书”，是动宾短语最典型的扩展方式。","Đúng vì 了1 đi sát động từ 买, còn 一本 bổ nghĩa cho tân ngữ 书.","「了1」は動詞「买」の直後、数量詞「一本」は目的語「书」の前に置く。"],"ref":"HSK 3.0 g3-1-030 · g3-1-025"},{"ok":true,"zh":"他去北京工作。","fix":"","py":"Tā qù Běijīng gōngzuò.","tr":["เขาไปทำงานที่ปักกิ่ง","He goes to Beijing to work.","Anh ấy đi Bắc Kinh làm việc.","彼は北京へ働きに行きます。"],"h":["กริยาบอกการเคลื่อนที่ (去 / 来 / 回 / 到) + ชื่อสถานที่ เป็น 动宾短语 ได้เลย","Motion verbs (去/来/回/到) take a place directly as their object","趋向／位移词“去、来、回、到”直接带处所宾语","Động từ di chuyển (去/来/回/到) nhận thẳng địa điểm làm tân ngữ","移動動詞（去・来・回・到）は場所を直接目的語に取る"],"w":["ทำได้เพราะ 去 + 北京 เป็นวลีกริยา-กรรมโดยตรง ไม่ต้องใส่บุพบท 在 คั่นกลาง (พูด 去北京 ได้เลย ห้ามพูด 去在北京)","Works because 去 takes place noun 北京 directly as its object — no preposition 在 needed (never 去在北京).","“去北京、回家、到学校”直接构成动宾短语，中间不加“在”。","Đúng vì 去 nhận thẳng 北京 làm tân ngữ, không thêm 在 ở giữa.","「去北京」「回家」のように場所を直接目的語に取り「在」は入れない。"],"ref":"HSK 3.0 g3-1-030 · g3-1-038"},{"ok":false,"zh":"我吃米饭饭。","fix":"我吃米饭。","py":"Wǒ chī mǐfàn.","tr":["ฉันกินข้าวสวย","I eat rice.","Tôi ăn cơm.","ご飯を食べます。"],"h":["ห้ามใส่กรรมซ้ำซ้อนเมื่อใช้คำที่มีกรรมอยู่แล้ว (吃饭 vs 吃米饭)","Don't double up objects (use 吃饭 OR 吃米饭, not both)","不能在已有宾语的动宾词后再重复加宾语","Không lặp tân ngữ thừa (chọn 吃饭 hoặc 吃米饭)","目的語が重複しないようにする（吃饭か吃米饭のどちらか）"],"w":["ไม่ได้ เพราะในคำว่า 吃饭 มี 饭 เป็นกรรมอยู่แล้ว ถ้าจะระบุชนิดอาหารให้ตัด 饭 เดิมออกแล้วใส่ชื่ออาหารหลัง 吃 โดยตรง: 吃米饭, 吃包子, 吃苹果","Wrong because 吃饭 already has 饭 as its object; to specify the food, replace 饭 after 吃: 吃米饭, 吃包子, 吃苹果.","不行，“吃饭”本身已有宾语“饭”，要指明食物就直接说“吃米饭／吃包子”。","Không được vì 吃饭 đã có tân ngữ 饭 sẵn; muốn nói rõ món ăn hãy thay trực tiếp: 吃米饭, 吃包子.","「吃饭」の「饭」がすでに目的語なので、具体的な食べ物を言うときは「吃米饭」「吃包子」にする。"],"ref":"HSK 3.0 g3-1-030 · g3-1-007"},{"ok":false,"zh":"我去在北京。","fix":"我去北京。","py":"Wǒ qù Běijīng.","tr":["ฉันไปปักกิ่ง","I am going to Beijing.","Tôi đi Bắc Kinh.","私は北京へ行きます。"],"h":["หลัง 去 / 来 / 回 / 到 ห้ามใส่ 在 คั่นหน้าสถานที่","Never insert 在 between 去/来/回/到 and the destination","“去、来、回、到”与处所宾语间不加“在”","Không chèn 在 giữa 去/来/回/到 và địa điểm","「去・来・回・到」と場所の間に「在」を入れない"],"w":["ไม่ได้ เพราะกริยา 去 (ไป), 来 (มา), 回 (กลับ), 到 (ถึง) รับชื่อสถานที่เป็นกรรมตรงได้เลย การใส่ 在 เข้าไปจะผิดโครงสร้าง","Wrong because 去, 来, 回, and 到 take the destination directly as their object without 在.","不行，“去、来、回、到”直接带处所宾语（去北京、到学校），加“在”属语法错误。","Không được vì 去, 来, 回, 到 nhận thẳng địa điểm làm tân ngữ, thêm 在 là sai.","「去・来・回・到」は直接場所を目的語に取るため「在」は不要。"],"ref":"HSK 3.0 g3-1-030"}],"ex":[["我喜欢看书。","Wǒ xǐhuan kàn shū.","ฉันชอบอ่านหนังสือ","I like reading books.","Tôi thích đọc sách.","私は本を読むのが好きです。","看书"],["爸爸在喝茶。","Bàba zài hē chá.","พ่อกำลังดื่มชา","Dad is drinking tea.","Bố đang uống trà.","父はお茶を飲んでいます。","喝茶"],["我在学校学习汉语。","Wǒ zài xuéxiào xuéxí Hànyǔ.","ฉันเรียนภาษาจีนที่โรงเรียน","I study Chinese at school.","Tôi học tiếng Trung ở trường.","学校で中国語を勉強しています。","学习汉语"],["他明天去北京。","Tā míngtiān qù Běijīng.","พรุ่งนี้เขาไปปักกิ่ง","He is going to Beijing tomorrow.","Ngày mai anh ấy đi Bắc Kinh.","彼は明日北京へ行きます。","去北京"],["妈妈买了很多水果。","Māma mǎile hěn duō shuǐguǒ.","แม่ซื้อผลไม้มาเยอะมาก","Mom bought a lot of fruit.","Mẹ đã mua rất nhiều hoa quả.","母は果物をたくさん買いました。","水果"]],"err":[["我去在北京。","我去北京。","กริยา 去/来/回/到 ตามด้วยสถานที่ได้เลย ไม่ต้องใส่ 在","去/来/回/到 take a place directly without 在.","“去”直接接处所宾语，不加“在”。","去 đi thẳng với địa điểm, không thêm 在.","「去」は場所を直接目的語に取る（「在」不要）。"],["我书看。","我看书。","วลีกริยา-กรรมวาง กริยาไว้หน้า กรรมไว้หลัง (看书)","Verb-object phrases put Verb before Object (看书).","动宾短语语序为“动词＋宾语”（看书）。","Cụm động tân xếp 'Động từ + Tân ngữ' (看书).","動目構造は「動詞＋目的語」（看书）の順。"]],"rel":["g3-1-007","g3-1-038","g3-1-042"]},"g3-1-031":{"t":["วลีประธาน-ภาคแสดง (主谓短语): กลุ่มคำที่มีประธาน+กริยา/คุณศัพท์ข้างใน","Subject-predicate phrases (主谓短语)","短语结构（4）：主谓短语","Cụm chủ vị (主谓短语)","主述構造（主谓短语）：主語＋述語のかたまり"],"f":["主语 + 谓语 → 作整句的主语、谓语或宾语","例如：今天天气很好 / 我觉得汉语很有意思 / 他个子很高"],"why":["主谓短语 คือกลุ่มคำที่ข้างในมีทั้ง 'ประธาน + ภาคแสดง' ครบคู่ เช่น 天气很好 (อากาศดีมาก), 他去北京 (เขาไปปักกิ่ง) · จุดเด่นของภาษาจีนคือสามารถยกก้อน 主谓短语 ทั้งก้อนไปซ้อนอยู่ในประโยคใหญ่ได้หลายตำแหน่ง: (1) เป็นกรรมหลัง 知道 / 觉得 (我知道他很忙 = ฉันรู้ว่าเขายุ่งมาก) (2) เป็นภาคแสดงอธิบายหัวข้อใหญ่ (今天 + 天气很好 = วันนี้อากาศดีมาก, 北京 + 天气很冷) · ข้อควรระวัง: หลัง 知道 / 觉得 ไม่ต้องเติมคำเชื่อม 'ว่า' (ห้ามแปลตรงตัวแล้วเติม 是 หรือ 说 เกินความจำเป็น)","A subject-predicate phrase (主谓短语) contains its own subject + predicate (e.g., 天气很好 'the weather is nice', 他很忙 'he is busy'). · Chinese lets you embed this entire block inside a larger sentence: as the object of 知道/觉得 (我知道他很忙 'I know he is busy') or as the predicate of a topic (今天天气很好). · Caution: do NOT insert an extra 'that' word after 知道/觉得.","主谓短语内部包含主语和谓语（天气很好、他很忙）。 · 汉语里主谓短语可以整体充当大句子的宾语（我知道他很忙）、谓语（今天天气很好）或定语。 · 注意：“知道、觉得”后直接接主谓短语，不用像英语或泰语那样加“that／ว่า”。","Cụm chủ vị (主谓短语) có sẵn chủ ngữ + vị ngữ bên trong (天气很好, 他很忙). · Trong tiếng Trung, cả cụm này có thể làm tân ngữ sau 知道/觉得 (我知道他很忙) hoặc làm vị ngữ cho chủ đề (今天天气很好). · Lưu ý: không thêm từ nối 'rằng' sau 知道/觉得.","主谓短语は内部に「主語＋述語」を含むかたまり（天气很好・他很忙）。 · 中国語ではこれをそのまま大文の目的語（我知道他很忙）や述語（今天天气很好）に組み込める。 · 注意：「知道・觉得」の後ろに接続詞は不要。"],"use":[{"ok":true,"zh":"我知道他今天很忙。","fix":"","py":"Wǒ zhīdao tā jīntiān hěn máng.","tr":["ฉันรู้ว่าวันนี้เขายุ่งมาก","I know he is very busy today.","Tôi biết hôm nay anh ấy rất bận.","私は今日彼がとても忙しいと知っています。"],"h":["วาง 主谓短语 ทั้งก้อนเป็นกรรมหลัง 知道 / 觉得 ได้เลย","Embed a full subject-predicate phrase directly after 知道 / 觉得","“知道／觉得”后可直接带主谓短语作宾语","Đặt thẳng cụm chủ vị làm tân ngữ sau 知道 / 觉得","「知道・觉得」の後ろに主述句を直接目的語として置ける"],"w":["ทำได้เพราะ 他今天很忙 เป็น 主谓短语 ที่ทำหน้าที่เป็นกรรมของ 知道 โดยไม่ต้องมีคำเชื่อม 'ว่า' คั่นกลาง","Works cleanly because 他今天很忙 acts as a single subject-predicate clause object of 知道 with no extra conjunction.","“他今天很忙”整个主谓短语充当“知道”的宾语，中间无需任何连词。","Đúng vì cả cụm 他今天很忙 làm tân ngữ của 知道 mà không cần từ nối.","「他今天很忙」という主述句全体が「知道」の目的語になる。"],"ref":"HSK 3.0 g3-1-031 · g3-1-038"},{"ok":true,"zh":"今天天气很好。","fix":"","py":"Jīntiān tiānqì hěn hǎo.","tr":["วันนี้อากาศดีมาก","The weather is very nice today.","Hôm nay thời tiết rất đẹp.","今日は天気がとても良いです。"],"h":["หัวข้อใหญ่ (今天 / 北京) + 主谓短语 (天气很好)","Topic (今天 / 北京) + subject-predicate phrase (天气很好)","大主语＋主谓短语作谓语（今天天气很好）","Chủ đề lớn + cụm chủ vị làm vị ngữ (今天天气很好)","大きな主題＋主述句が述語になる（今天天气很好）"],"w":["ทำได้และเป็นโครงสร้างจีนแท้มาก (主谓谓语句): ยกหัวข้อ 今天 ขึ้นก่อน แล้วให้ก้อน 天气很好 มาบรรยายต่อโดยไม่ต้องใส่ 的 หรือ 是","Works as a classic Chinese topic-comment pattern: state the topic (今天) and describe it with 天气很好 — no 的 or 是 needed.","“今天”作大主语，“天气很好”作主谓谓语，不必加“的”或“是”。","Đúng và rất chuẩn tiếng Trung: nêu chủ đề 今天 rồi dùng cụm chủ vị 天气很好 miêu tả.","「今天」を主題に「天气很好」が述語になる中国語らしい文。"],"ref":"HSK 3.0 g3-1-031 · ประโยคตัวอย่าง_300"},{"ok":false,"zh":"我觉得是苹果很好吃。","fix":"我觉得苹果很好吃。","py":"Wǒ juéde píngguǒ hěn hǎochī.","tr":["ฉันคิดว่าแอปเปิลอร่อยมาก","I think apples are very delicious.","Tôi thấy táo rất ngon.","りんごはとてもおいしいと思います。"],"h":["หลัง 觉得 / 知道 ห้ามใส่ 是 หรือ 说 แปลคำว่า 'ว่า' ตรงตัว","Don't add 是 after 觉得 / 知道 to translate 'that'","“觉得／知道”后不要多加“是”","Không thêm 是 thừa sau 觉得 / 知道","「觉得・知道」の後ろに余計な「是」を入れない"],"w":["ไม่ได้ เพราะผู้เรียนไทยมักเผลอเติมคำเชื่อม 'ว่า' (เช่น 是 หรือ 说) หลัง 觉得/知道 แต่ในภาษาจีนให้ต่อ 主谓短语 (苹果很好吃) ได้ทันที","Wrong because learners often insert extra filler words like 是 for 'that'; attach the subject-predicate phrase directly: 我觉得苹果很好吃.","不行，“觉得”后面直接接“苹果很好吃”，加“是”会破坏主谓宾语结构。","Không được vì sau 觉得 nối thẳng cụm chủ vị 苹果很好吃, không chèn 是.","「觉得」の後ろに直接「苹果很好吃」を続け、余計な「是」は入れない。"],"ref":"HSK 3.0 g3-1-031"}],"ex":[["今天天气很好。","Jīntiān tiānqì hěn hǎo.","วันนี้อากาศดีมาก","The weather is very nice today.","Hôm nay thời tiết rất đẹp.","今日は天気がとても良いです。","天气很好"],["我知道他很忙。","Wǒ zhīdao tā hěn máng.","ฉันรู้ว่าเขายุ่งมาก","I know he is very busy.","Tôi biết anh ấy rất bận.","彼がとても忙しいことを知っています。","他很忙"],["我觉得苹果很好吃。","Wǒ juéde píngguǒ hěn hǎochī.","ฉันคิดว่าแอปเปิลอร่อยมาก","I think apples are very delicious.","Tôi thấy táo rất ngon.","りんごはとてもおいしいと思います。","苹果很好吃"],["我看见他来了。","Wǒ kànjiàn tā lái le.","ฉันเห็นว่าเขามาแล้ว","I saw him arrive.","Tôi nhìn thấy anh ấy đến rồi.","彼が来たのが見えました。","他来了"],["北京今天很冷。","Běijīng jīntiān hěn lěng.","วันนี้ที่ปักกิ่งหนาวมาก","It is very cold in Beijing today.","Hôm nay ở Bắc Kinh rất lạnh.","北京は今日とても寒いです。","很冷"]],"err":[["我觉得是苹果很好吃。","我觉得苹果很好吃。","หลัง 觉得 / 知道 ต่อกลุ่มคำประธาน-กริยาได้เลย ไม่ต้องเติม 是","Follow 觉得 / 知道 directly with the clause — no extra 是.","“觉得”后直接接主谓短语，不加“是”。","Sau 觉得 nối thẳng cụm chủ vị, không thêm 是.","「觉得」の後ろに余計な「是」は入れない。"],["我知道说他很忙。","我知道他很忙。","หลัง 知道 ไม่ต้องใส่ 说 แปลคำว่า 'ว่า' แบบภาษาไทย","Don't add 说 ('say') after 知道 to mean 'that'.","“知道”后直接接主谓宾语，不加“说”。","Sau 知道 không thêm 说 như tiếng Thái.","「知道」の後ろに「说」を挟まない。"]],"rel":["g3-1-035","g3-1-037","g3-1-038"]},"g3-1-032":{"t":["วลีจำนวน-ลักษณนาม (数量短语): ตัวเลข + ลักษณนาม","Numeral-measure phrases (数量短语): Number + Measure Word","短语结构：数量短语","Cụm số lượng (数量短语): Số từ + Lượng từ","数量詞句（数量短语）：数詞＋量詞"],"f":["数词 + 量词（+ 名词）：一个人 / 两本书 / 三杯茶","数词 + 时量词：三天 / 两年 / 五岁（不加“个”）"],"why":["数量短语 คือการจับคู่ 'ตัวเลข + ลักษณนาม' (เช่น 一本, 两个, 三只, 四天) ซึ่งเป็นหน่วยสำคัญที่ใช้ขยายคำนาม (一本书), ทำหน้าที่เป็นภาคแสดงบอกราคา/อายุ (五块钱, 八岁) หรือบอกระยะเวลา (住了三年) · กฎทอง 3 ข้อ: (1) เลข 2 หน้าลักษณนามใช้ 两 เสมอ (两本书, 两个人) ยกเว้นเลขหลายหลักเช่น 十二本书 (2) ห้ามวางตัวเลขติดคำนามโดยไม่มีลักษณนาม (不说 一书, 两猫) (3) ลำดับต้องเป็น จำนวน + ลักษณนาม + คำนาม เสมอ","A numeral-measure phrase (数量短语) combines a number + measure word (一本, 两个, 三只, 四天). It modifies nouns (一本书), acts as a predicate for prices/ages (五块钱, 八岁), or measures duration (住了三年). · Three golden rules: (1) Use 两 before measure words for standalone '2' (两本书, 两个人), but 二 in compound numbers (十二本书). (2) Never omit the measure word between a number and noun. (3) Always place it BEFORE the noun.","数量短语由“数词＋量词”组成（一本、两个、三只、四天），常作定语（一本书）、谓语（五块钱）或补语（住了三年）。 · 三条要点：（1）单用“2”配量词用“两”（两本书），多位数用“二”（十二本书）；（2）数词与名词间不能省量词；（3）作定语时放在名词前。","Cụm số lượng (数量短语) gồm 'Số từ + Lượng từ' (一本, 两个, 三只, 四天). · 3 quy tắc vàng: (1) Số 2 đứng riêng trước lượng từ dùng 两 (两本书), số ghép dùng 二 (十二本书); (2) Không bỏ lượng từ giữa số và danh từ; (3) Luôn đặt TRƯỚC danh từ.","数量短语は「数詞＋量詞」（一本・两个・三只・四天）。 · 3つの鉄則：（1）単独の「2」＋量詞は「两」（两本书）、二桁以上は「二」（十二本书）。（2）数詞と名詞の間の量詞を省かない。（3）常に名詞の前に置く。"],"use":[{"ok":true,"zh":"我有两个朋友。","fix":"","py":"Wǒ yǒu liǎng ge péngyou.","tr":["ฉันมีเพื่อนสองคน","I have two friends.","Tôi có hai người bạn.","友達が二人います。"],"h":["เลข 2 หน้าลักษณนามใช้ 两 (两个人 / 两本书)","Use 两 (not 二) for standalone '2' before a measure word","单个“2”加量词必须用“两”（两个、两本）","Số 2 đứng riêng trước lượng từ dùng 两 (两个, 两本)","単独の「2」＋量詞は「两」（两个・两本）"],"w":["ทำได้เพราะเป็นจำนวน 2 โดด ๆ นำหน้าลักษณนาม 个 จึงต้องใช้ 两 (ส่วนเลข 12, 22 ใช้ 二: 十二个朋友)","Works because standalone '2' before a measure word takes 两 (whereas 12/22 use 二: 十二个朋友).","表示数量“2”且紧接量词时用“两”（两个朋友）；十几、二十几则用“二”（十二个）。","Đúng vì số 2 đứng riêng trước lượng từ dùng 两 (còn 12 dùng 二: 十二个).","単独の2＋量詞は「两」（两个朋友）、12や22は「二」（十二个）。"],"ref":"กลุ่มเทียบคำ g9 · HSK 3.0 g3-1-032"},{"ok":true,"zh":"苹果五块钱。","fix":"","py":"Píngguǒ wǔ kuài qián.","tr":["แอปเปิลราคาห้าหยวน","The apples are five yuan.","Táo giá năm tệ.","りんごは5元です。"],"h":["ใช้ 数量短语 เป็นภาคแสดงบอกราคา/อายุได้โดยไม่ต้องมี 是","Numeral-measure phrases work as predicates for price/age without 是","数量短语可直接作谓语表价格、年龄","Cụm số lượng làm vị ngữ chỉ giá/tuổi không cần 是","価格・年齢の述語には数量短语をそのまま置ける"],"w":["ทำได้เพราะ 五块钱 (ห้าหยวน) ทำหน้าที่เป็นภาคแสดงบอกราคาของ 苹果 โดยตรง (เช่นเดียวกับ 我妹妹六岁 = น้องสาวฉันหกขวบ)","Works because 五块钱 directly serves as the predicate giving the price of 苹果 (just like 我妹妹六岁).","“五块钱”直接充当谓语说明价格，与“我妹妹六岁”同属名词／数量谓语句。","Đúng vì 五块钱 trực tiếp làm vị ngữ báo giá, không cần 是.","「五块钱」がそのまま価格を表す述語になる（「我妹妹六岁」も同じ）。"],"ref":"HSK 3.0 g3-1-032 · g3-1-036"},{"ok":false,"zh":"我有二个朋友。","fix":"我有两个朋友。","py":"Wǒ yǒu liǎng ge péngyou.","tr":["ฉันมีเพื่อนสองคน","I have two friends.","Tôi có hai người bạn.","友達が二人います。"],"h":["ห้ามใช้ 二 หน้าลักษณนามเมื่อนับจำนวน 2","Never use 二 directly before 个/本/只/杯 for quantity 2","表数量“2”加量词不能说“二个／二本”","Không nói 二个 / 二本 khi đếm số lượng 2","個数2のとき「二个・二本」とは言えない"],"w":["ไม่ได้ เพราะการนับจำนวน '2' หน้าลักษณนามบังคับใช้ 两 เสมอ (两个, 两本, 两只, 两杯, 两点) ส่วน 二 ใช้กับการนับเลข 1-2-3, เลขลำดับ (第二) และเดือน/วัน (二月)","Wrong because quantity '2' before a measure word requires 两 (两个, 两本, 两杯); 二 is for counting, ordinals (第二), and months (二月).","不行，表数量配量词必须用“两”；“二”用于报数、序数（第二）和月份（二月）。","Không được vì đếm số lượng 2 trước lượng từ bắt buộc dùng 两; 二 dùng cho số thứ tự (第二) và tháng (二月).","量詞の前の2は必ず「两」。「二」は数唱・序数（第二）・月（二月）に使う。"],"ref":"กลุ่มเทียบคำ g9"},{"ok":false,"zh":"我买三苹果。","fix":"我买三个苹果。","py":"Wǒ mǎi sān ge píngguǒ.","tr":["ฉันซื้อแอปเปิลสามลูก","I buy three apples.","Tôi mua ba quả táo.","りんごを3個買います。"],"h":["ห้ามตัดลักษณนามออกระหว่างตัวเลขกับคำนาม","Never drop the measure word between a number and noun","数词和名词之间不能省略量词","Không lược bỏ lượng từ giữa số và danh từ","数詞と名詞の間の量詞は省けない"],"w":["ไม่ได้ เพราะในภาษาจีนตัวเลขกับคำนามไม่สามารถเชื่อมกันตรง ๆ ได้เหมือนภาษาอังกฤษ ('three apples') ต้องมีลักษณนามคั่นเสมอ: 三个苹果","Wrong because Chinese numbers cannot modify nouns directly like English 'three apples'; always insert the measure word: 三个苹果.","不行，汉语数词不能直接修饰名词，必须加量词：三个苹果。","Không được vì tiếng Trung bắt buộc có lượng từ giữa số và danh từ: 三个苹果.","英語の three apples と違い、中国語は数詞と名詞の間に必ず量詞を入れる（三个苹果）。"],"ref":"HSK 3.0 g3-1-032 · g3-1-012"}],"ex":[["我有两个朋友。","Wǒ yǒu liǎng ge péngyou.","ฉันมีเพื่อนสองคน","I have two friends.","Tôi có hai người bạn.","私には友達が2人います。","两个"],["他买了三本书。","Tā mǎile sān běn shū.","เขาซื้อหนังสือสามเล่ม","He bought three books.","Anh ấy đã mua ba cuốn sách.","彼は本を3冊買いました。","三本"],["我喝了两杯水。","Wǒ hēle liǎng bēi shuǐ.","ฉันดื่มน้ำไปสองแก้ว","I drank two glasses of water.","Tôi đã uống hai cốc nước.","水を2杯飲みました。","两杯"],["我家有五口人。","Wǒ jiā yǒu wǔ kǒu rén.","บ้านฉันมีห้าคน","There are five people in my family.","Nhà tôi có năm người.","私の家族は5人です。","五口"],["苹果五块钱。","Píngguǒ wǔ kuài qián.","แอปเปิลห้าหยวน","The apples cost five yuan.","Táo năm tệ.","りんごは5元です。","五块"]],"err":[["我有二个朋友。","我有两个朋友。","จำนวน 2 หน้าลักษณนามใช้ 两 ไม่ใช้ 二","Use 两 (not 二) before measure words for quantity 2.","表数量“2”加量词用“两”，不用“二”。","Số lượng 2 trước lượng từ dùng 两, không dùng 二.","数量の2＋量詞は「二」ではなく「两」。"],["我买三苹果。","我买三个苹果。","ระหว่างตัวเลขกับคำนามต้องมีลักษณนามเสมอ","Always put a measure word between a number and a noun.","数词和名词间必须加量词（三个苹果）。","Giữa số và danh từ luôn phải có lượng từ (三个苹果).","数詞と名詞の間には必ず量詞を入れる（三个苹果）。"]],"rel":["g3-1-011","g3-1-012","g3-1-039"]},"g3-1-033":{"t":["วลีบุพบท-กรรม (介宾短语): 在… / 和… / 对…","Prepositional phrases (介宾短语): 在… / 和… / 对…","短语结构：介宾短语","Cụm giới tân (介宾短语): 在… / 和… / 对…","前置詞句（介宾短语）：在…・和…・对…"],"f":["主语 +（在 / 和 / 对 + 宾语）+ 动词 / 形容词","主语 + 不 / 没 + 介宾短语 + 动词（否定词放介词前）"],"why":["介宾短语 คือกลุ่มคำที่ขึ้นต้นด้วยคำบุพบทแล้วตามด้วยกรรม ซึ่งใน HSK 1 มี 3 ตัวหลักคือ 在 + สถานที่ (在学校), 和 + บุคคล (和朋友), และ 对 + เป้าหมาย (对我) · กฎทองของ 介宾短语 ในภาษาจีน: ทั้งก้อนนี้ทำหน้าที่เป็นส่วนขยายกริยา (状语) จึงต้องวาง 'หน้ากริยา/คุณศัพท์' เสมอ ตรงข้ามกับภาษาไทยและอังกฤษ! (เช่น 在学校学习 = เรียนที่โรงเรียน, 和朋友去书店 = ไปร้านหนังสือกับเพื่อน, 对我说 = พูดกับฉัน) · ข้อควรระวัง: (1) ห้ามย้ายกลุ่มบุพบทไปไว้ท้ายประโยค (2) เวลาปฏิเสธต้องวาง 不 / 没 ไว้ 'หน้าบุพบท' เสมอ (我不和他去 ไม่ใช่ 我和他不去)","A prepositional phrase (介宾短语) pairs a preposition + object — in HSK 1: 在 + place (在学校), 和 + person (和朋友), and 对 + target (对我). · Golden rule: place the ENTIRE prepositional phrase BEFORE the verb or adjective — opposite to Thai/English (在学校学习, 和朋友去书店, 对我说). · Cautions: (1) Never put the prepositional phrase at the end of the sentence. (2) Put negation 不 / 没 BEFORE the preposition (我不和他去, never 我和他不去).","介宾短语由“介词＋宾语”构成，HSK 1 主要是“在＋处所”（在学校）、“和＋人”（和朋友）、“对＋对象”（对我）。 · 核心规律：介宾短语作状语时，必须整体放在动词或形容词前面（与泰语、英语相反）。 · 注意：（1）不能把介宾短语放句尾；（2）否定词“不／没”放在介词前面（我不和他去）。","Cụm giới tân (介宾短语) gồm 'Giới từ + Tân ngữ' — ở HSK 1 là 在 + địa điểm (在学校), 和 + người (和朋友), 对 + đối tượng (对我), luôn đặt TRƯỚC động/tính từ — ngược tiếng Việt/Thái. · Lưu ý: không đặt cụm giới từ ở cuối câu; từ phủ định 不/没 đặt TRƯỚC giới từ (我不和他去).","介宾短语は「前置詞＋目的語」— HSK1は「在＋場所」（在学校）、「和＋人」（和朋友）、「对＋対象」（对我）。連用修飾語として必ず動詞・形容詞の前に置く。 · 注意：（1）文末に置かない。（2）否定詞「不・没」は前置詞の前に置く（我不和他去）。"],"use":[{"ok":true,"zh":"我在学校学习汉语。","fix":"","py":"Wǒ zài xuéxiào xuéxí Hànyǔ.","tr":["ฉันเรียนภาษาจีนที่โรงเรียน","I study Chinese at school.","Tôi học tiếng Trung ở trường.","私は学校で中国語を勉強します。"],"h":["ก้อน 在 + สถานที่ วางหน้ากริยาเสมอ","Put 在 + place right before the verb","“在＋处所”放在动词前面","Cụm 在 + địa điểm luôn đứng trước động từ","「在＋場所」は常に動詞の前"],"w":["ทำได้เพราะ 在学校 เป็น 介宾短语 บอกสถานที่เกิดการกระทำ จึงวางชิดหน้ากริยา 学习汉语 เสมอ","Works because the prepositional phrase 在学校 ('at school') sits right before 学习汉语.","介宾短语“在学校”交代动作地点，必须放在动词“学习”前。","Đúng vì cụm giới từ 在学校 đứng trước động từ 学习汉语.","前置詞句「在学校」が動作「学习汉语」の前に来ている。"],"ref":"HSK 3.0 g3-1-033 · g3-1-021"},{"ok":true,"zh":"我不和他去商店。","fix":"","py":"Wǒ bù hé tā qù shāngdiàn.","tr":["ฉันไม่ไปร้านค้ากับเขา","I'm not going to the shop with him.","Tôi không đi cửa hàng với anh ấy.","彼とはお店に行きません。"],"h":["ปฏิเสธประโยคที่มีบุพบท ให้วาง 不 / 没 ไว้ 'หน้าบุพบท'","Put negation 不 / 没 BEFORE the preposition","否定词“不／没”放在介词“和／在／对”前面","Đặt 不 / 没 TRƯỚC giới từ (不和他 / 不在…)","否定詞「不・没」は前置詞の前に置く"],"w":["ทำได้เพราะ 不 นำหน้าทั้งก้อนบุพบท-กรรม 和他 เพื่อปฏิเสธการไปด้วยกัน (เช่นเดียวกับ 我不在家吃饭 = ฉันไม่กินข้าวที่บ้าน)","Works because 不 negates the whole phrase starting before 和 (just like 我不在家吃饭 'I don't eat at home').","否定介宾短语修饰的动作时，否定词放在介词前：不和他去、不在家吃饭。","Đúng vì 不 đứng trước giới từ 和 để phủ định cả cụm (tương tự 不在家吃饭).","前置詞句ごと否定するため「不」を「和」の前に置く（「不在家吃饭」も同じ）。"],"ref":"HSK 3.0 g3-1-033 · g3-1-022"},{"ok":false,"zh":"我在家不吃饭。","fix":"我不在家吃饭。","py":"Wǒ bù zài jiā chīfàn.","tr":["ฉันไม่กินข้าวที่บ้าน","I don't eat at home.","Tôi không ăn cơm ở nhà.","家ではご飯を食べません。"],"h":["ห้ามเอา 不 แทรกไว้หลังกลุ่มบุพบท (ต้องเป็น 不在家吃饭)","Don't place 不 after the prepositional phrase — put it before 在","否定词应放介词前（不在家吃饭），一般不插在后面","Đặt 不 trước 在 (不在家吃饭), không đặt sau 在家","「不」は「在家」の後ろではなく前（不在家吃饭）に置く"],"w":["ไม่เป็นธรรมชาติในประโยคปฏิเสธทั่วไป เพราะภาษาจีนวางคำปฏิเสธ 不 / 没 หน้าคำบุพบทเสมอ: 不在家吃饭, 没在学校看书, 不和他去","Unnatural in normal negation: Chinese puts 不 / 没 BEFORE the preposition (不在家吃饭, 没在学校看书, 不和他去).","不自然，正常否定须将“不／没”置于介词前：不在家吃饭、不和他去。","Không tự nhiên: phủ định thông thường đặt 不/没 trước giới từ (不在家吃饭).","通常の否定では「不・没」を前置詞の前に置く（不在家吃饭・不和他去）。"],"ref":"HSK 3.0 g3-1-033"},{"ok":false,"zh":"他学习在学校。","fix":"他在学校学习。","py":"Tā zài xuéxiào xuéxí.","tr":["เขาเรียนอยู่ที่โรงเรียน","He studies at school.","Anh ấy học tập ở trường.","彼は学校で勉強します。"],"h":["ห้ามวางวลีบุพบท 在… / 和… / 对… ไว้หลังกริยา","Never trail 在… / 和… / 对… after the verb like Thai/English","介宾短语“在…／和…／对…”作状语不能放动词后","Không đặt cụm giới từ 在… / 和… / 对… sau động từ","前置詞句（在…・和…・对…）は動詞の後ろに置けない"],"w":["ไม่ได้ เพราะในภาษาไทยพูดว่า 'เรียน + ที่โรงเรียน' แต่ภาษาจีนบังคับยกทั้งก้อน 在学校 มาวางหน้ากริยา 学习 เสมอ: 他在学校学习","Wrong because unlike Thai/English 'study at school', Chinese requires the entire phrase 在学校 BEFORE 学习.","不行，“在学校”修饰动词“学习”，必须放在动词前：他在学校学习。","Không được vì cụm giới từ 在学校 phải đặt TRƯỚC động từ 学习.","前置詞句「在学校」は動詞「学习」の前に置く（他在学校学习）。"],"ref":"HSK 3.0 g3-1-033 · g3-1-040"}],"ex":[["我在学校学习。","Wǒ zài xuéxiào xuéxí.","ฉันเรียนที่โรงเรียน","I study at school.","Tôi học ở trường.","学校で勉強します。","在学校"],["爸爸在医院工作。","Bàba zài yīyuàn gōngzuò.","พ่อทำงานที่โรงพยาบาล","Dad works at a hospital.","Bố làm việc ở bệnh viện.","父は病院で働いています。","在医院"],["我和朋友去书店。","Wǒ hé péngyou qù shūdiàn.","ฉันไปร้านหนังสือกับเพื่อน","I go to the bookstore with my friend.","Tôi đi hiệu sách với bạn.","友達と本屋へ行きます。","和朋友"],["妈妈对我很好。","Māma duì wǒ hěn hǎo.","แม่ดีกับฉันมาก","Mom is very kind to me.","Mẹ rất tốt với tôi.","母は私にとても優しいです。","对我"],["我不在家吃饭。","Wǒ bù zài jiā chīfàn.","ฉันไม่กินข้าวที่บ้าน","I don't eat at home.","Tôi không ăn cơm ở nhà.","家ではご飯を食べません。","不在家"]],"err":[["他学习在学校。","他在学校学习。","วลีบุพบท 在 + สถานที่ ต้องวางหน้ากริยาเสมอ","Prepositional phrases like 在学校 always precede the verb.","介宾短语“在学校”必须放在动词前。","Cụm giới từ 在学校 phải đứng trước động từ.","前置詞句「在学校」は動詞の前に置く。"],["他说再见对我。","他对我说再见。","วลีบุพบท 对 + บุคคล ต้องวางหน้ากริยา (对我说)","Place 对 + person before the verb (对我说).","介宾短语“对我”放在动词前（对我说）。","Cụm giới từ 对我 đặt trước động từ (对我说).","前置詞句「对我」は動詞の前（对我说）。"]],"rel":["g3-1-021","g3-1-022","g3-1-040"]},"g3-1-034":{"t":["วลีบอกตำแหน่ง (方位短语): คำนาม/เวลา + 上 / 下 / 里 / 外 / 前 / 后","Locative phrases (方位短语): Noun/Time + Position Word","短语结构：方位短语","Cụm phương vị (方位短语): Danh từ/Thời gian + Phương vị từ","方位句（方位短语）：名詞・時間＋方位詞"],"f":["名词 + 上 / 下 / 里 / 外 / 前 / 后（桌子上 / 房间里 / 椅子下）","时间 / 动作 + 前 / 后（上课前 / 下班后 / 三天后）"],"why":["方位短语 คือการนำคำนามหรือช่วงเวลามาต่อท้ายด้วยคำบอกตำแหน่ง (上, 下, 里, 外, 前, 后) เพื่อสร้าง 'คำสถานที่' หรือ 'จุดเวลา' · หน้าที่สำคัญมากของ 方位短语: (1) เปลี่ยนสิ่งของทั่วไปให้เป็นสถานที่ที่ตามหลัง 在 ได้ (桌子上, 椅子下, 房间里) (2) ใช้เป็นประธานในประโยคบอกการมีอยู่ (桌子上有一本书 = บนโต๊ะมีหนังสือเล่มหนึ่ง) (3) บอกก่อน/หลังเหตุการณ์ (上课前 = ก่อนเข้าเรียน, 下班后 = หลังเลิกงาน) · ข้อควรระวัง: ชื่อเมือง/ประเทศ (北京, 中国) ไม่เติม 里 หลัง 在 (พูด 在北京 ไม่พูด 在北京里)","A locative phrase (方位短语) attaches a position word (上, 下, 里, 外, 前, 后) AFTER a noun, time, or event to create a place or time point. · Key uses: (1) Turns ordinary objects into places usable after 在 (桌子上, 房间里); (2) Serves as the location subject in existence sentences (桌子上有一本书); (3) Marks 'before/after' an event (上课前, 下班后). · Caution: don't add 里 after city/country names (在北京, not 在北京里).","方位短语由“名词／时间／事件＋方位词”构成（桌子上、房间里、上课前、下班后）。 · 主要作用：（1）把普通物体转化为可跟“在”的处所；（2）作存现句主语（桌子上有一本书）；（3）表示时间先后（上课前、下班后）。 · 注意：国名、地名（北京、中国）作处所时不加“里”。","Cụm phương vị (方位短语) gắn phương vị từ (上, 下, 里, 外, 前, 后) SAU danh từ/thời gian/sự kiện: 桌子上, 房间里, 上课前, 下班后. · Lưu ý: không thêm 里 sau tên thành phố/quốc gia (在北京, không nói 在北京里).","方位短语は「名詞・時間・出来事＋方位詞」（桌子上・房间里・上课前・下班后）。 · 一般の名詞を場所化したり、存在文の主語（桌子上有一本书）や時間の前後（上课前・下班后）を表す。 · 注意：地名・国名には「里」を付けない（在北京）。"],"use":[{"ok":true,"zh":"桌子上有一本书。","fix":"","py":"Zhuōzi shàng yǒu yī běn shū.","tr":["บนโต๊ะมีหนังสือหนึ่งเล่ม","There is a book on the table.","Trên bàn có một cuốn sách.","机の上に本が1冊あります。"],"h":["วาง 方位短语 เป็นประธานหน้า 有 ได้เลย (ไม่ต้องมี 在)","Use a locative phrase directly as subject before 有 (no 在 needed)","方位短语直接作存现句主语：桌子上有一本书","Cụm phương vị đứng thẳng làm chủ ngữ trước 有 (không thêm 在)","方位短语は「在」なしでそのまま「有」の主語になれる"],"w":["ทำได้เพราะ 桌子上 (บนโต๊ะ) เป็นวลีบอกตำแหน่งที่ยืนเป็นประธานหน้า 有 ได้เลยในประโยคบอกการมีอยู่ (存现句)","Works because 桌子上 is a locative phrase that stands directly as the subject before 有 in existence sentences.","“桌子上”作为方位短语可直接作存现句的主语，前面不必加“在”。","Đúng vì 桌子上 là cụm phương vị đứng thẳng trước 有 trong câu tồn hiện.","「桌子上」はそのまま存在文「有」の主語になり、前に「在」は要らない。"],"ref":"HSK 3.0 g3-1-034 · g3-1-055"},{"ok":true,"zh":"下班后我去超市。","fix":"","py":"Xiàbān hòu wǒ qù chāoshì.","tr":["หลังเลิกงานฉันไปซูเปอร์มาร์เก็ต","After work I go to the supermarket.","Sau giờ tan làm tôi đi siêu thị.","仕事が終わったあとスーパーへ行きます。"],"h":["กิจกรรม + 前 / 后 = ก่อน / หลังทำสิ่งนั้น","Event + 前 / 后 = 'before / after doing…'","“动作／事件＋前／后”表时间先后（上课前、下班后）","Sự kiện + 前 / 后 = trước / sau khi làm gì (下班后)","「出来事＋前／后」＝〜の前／〜の後（下班后）"],"w":["ทำได้เพราะ 下班 (เลิกงาน) + 后 (หลัง) สร้างเป็นจุดเวลา 'หลังเลิกงาน' วางหน้าประธานหรือหน้ากริยาได้ทันที","Works cleanly because 下班 + 后 forms the time point 'after getting off work', placed before the subject or verb.","“下班后、上课前”构成表时间的方位短语，放在句首或主语后都可以。","Đúng vì 下班 + 后 tạo mốc thời gian 'sau khi tan làm' đặt trước chủ ngữ hay động từ đều được.","「下班后」「上课前」で時点を表す方位短语になる。"],"ref":"HSK 3.0 g3-1-034 · g3-1-003"},{"ok":false,"zh":"我在北京里工作。","fix":"我在北京工作。","py":"Wǒ zài Běijīng gōngzuò.","tr":["ฉันทำงานที่ปักกิ่ง","I work in Beijing.","Tôi làm việc ở Bắc Kinh.","私は北京で働いています。"],"h":["ห้ามเติม 里 หลังชื่อเมืองหรือประเทศ (北京 / 中国)","Never add 里 after city or country names (北京 / 中国)","城市、国家名作处所时不加“里”","Không thêm 里 sau tên thành phố hay quốc gia","都市名・国名の後ろに「里」は付けない"],"w":["ไม่ได้ เพราะ 北京 และ 中国 เป็นชื่อสถานที่ขนาดใหญ่โดยกำเนิดอยู่แล้ว ไม่ต้องเติม 里 มาแปลงเป็นสถานที่ (พูด 在北京, 在中国 ได้เลย)","Wrong because 北京 and 中国 are already proper place names — adding 里 is unnatural. Say 在北京 / 在中国.","不行，“北京、中国”本身就是地名处所，不能说“在北京里、在中国里”。","Không được vì 北京 và 中国 vốn là địa danh rồi, chỉ cần nói 在北京 / 在中国.","「北京・中国」はそれ自体が地名なので「里」を付けるのは誤用。"],"ref":"HSK 3.0 g3-1-034"},{"ok":false,"zh":"在桌子上有一本书。","fix":"桌子上有一本书。","py":"Zhuōzi shàng yǒu yī běn shū.","tr":["บนโต๊ะมีหนังสือหนึ่งเล่ม","There is a book on the table.","Trên bàn có một cuốn sách.","机の上に本が1冊あります。"],"h":["ประโยค 'ที่…มี…' (处所 + 有) ไม่ต้องใส่ 在 นำหน้า","In 'Place + 有' existence sentences, drop the leading 在","“处所＋有＋名词”前一般不加“在”","Câu tồn hiện 'Nơi chốn + 有' không cần thêm 在 ở đầu","存在文「場所＋有」の先頭に「在」は要らない"],"w":["ไม่เป็นธรรมชาติ เพราะถ้ามี 在 นำหน้า 桌子上 จะทำให้ทั้งประโยคขาดประธาน (กลายเป็นวลีบุพบท + 有) ให้ตัด 在 ออกเหลือ 桌子上有一本书","Awkward/wrong because leading 在 turns 桌子上 into a prepositional phrase, leaving 有 without a subject. Drop 在 → 桌子上有一本书.","不规范，前面加“在”会使“有”缺少主语，应去掉“在”直接说“桌子上有一本书”。","Không chuẩn vì thêm 在 khiến câu mất chủ ngữ; bỏ 在 đi thành 桌子上有一本书.","前に「在」を付けると主語が欠けるため、「桌子上有一本书」とする。"],"ref":"HSK 3.0 g3-1-034 · g3-1-055"}],"ex":[["桌子上有一本书。","Zhuōzi shàng yǒu yī běn shū.","บนโต๊ะมีหนังสือหนึ่งเล่ม","There is a book on the table.","Trên bàn có một cuốn sách.","机の上に本が1冊あります。","桌子上"],["小猫在椅子下。","Xiǎo māo zài yǐzi xià.","ลูกแมวอยู่ใต้เก้าอี้","The kitten is under the chair.","Mèo con ở dưới ghế.","子猫は椅子の下にいます。","椅子下"],["房间里有两个人。","Fángjiān lǐ yǒu liǎng ge rén.","ในห้องมีคนสองคน","There are two people in the room.","Trong phòng có hai người.","部屋の中に2人います。","房间里"],["下班后我去超市。","Xiàbān hòu wǒ qù chāoshì.","หลังเลิกงานฉันไปซูเปอร์มาร์เก็ต","After work I go to the supermarket.","Sau khi tan làm tôi đi siêu thị.","仕事の後スーパーへ行きます。","下班后"],["上课前我喝了一杯水。","Shàngkè qián wǒ hēle yī bēi shuǐ.","ก่อนเข้าเรียนฉันดื่มน้ำไปหนึ่งแก้ว","Before class I drank a glass of water.","Trước giờ học tôi uống một cốc nước.","授業の前に水を1杯飲みました。","上课前"]],"err":[["我在北京里工作。","我在北京工作。","ชื่อเมือง/ประเทศ (北京, 中国) ไม่เติม 里","Do not add 里 after city/country names (北京, 中国).","地名、国名后不加“里”（在北京）。","Không thêm 里 sau tên thành phố/quốc gia.","地名・国名の後ろに「里」は付けない。"],["在桌子上有一本书。","桌子上有一本书。","ประโยค 'สถานที่ + 有' ตัด 在 ข้างหน้าออก","Drop leading 在 before 'Place + 有'.","存现句“处所＋有”前去掉“在”。","Bỏ 在 trước 'Nơi chốn + 有'.","「場所＋有」の前に「在」は入れない。"]],"rel":["g3-1-003","g3-1-055","g3-1-021"]},"g3-1-035":{"t":["ประธานของประโยค (主语): คำนาม / สรรพนาม / วลีนาม","Sentence Subject (主语): nouns, pronouns & noun phrases","句子成分：主语","Chủ ngữ (主语): danh từ, đại từ, cụm danh từ","文の成分「主語（主语）」"],"f":["主语（名词 / 代词 / 名词性短语）+ 谓语"],"why":["主语 (ประธาน) คือผู้กระทำหรือหัวข้อที่ประโยคกำลังพูดถึง โดยทั่วไปวางอยู่ต้นประโยค · สิ่งที่ทำหน้าที่เป็นประธานใน HSK 1 มี 3 กลุ่มหลัก: (1) คำนาม (老师来了, 苹果很好吃) (2) สรรพนาม (我喜欢喝茶, 这是我的书) (3) วลีนาม (我的朋友是医生, 爸爸和妈妈都在家, 桌子上有一本书) · ข้อควรระวัง: ห้ามเอาคำบุพบท 在 / 对 มาแปะหน้าประธานจนประธานหายไป และในประโยคคำถามสั้นหรือเมื่อรู้กันอยู่แล้วสามารถละประธานได้","The subject (主语) is the topic or doer placed at the start of a Chinese sentence. · Three main HSK 1 subjects: (1) nouns (苹果很好吃), (2) pronouns (我喜欢喝茶, 这是书), (3) noun phrases (我的朋友是医生, 爸爸和妈妈都在家, 桌子上有一本书). · Caution: never bury the subject inside a preposition like 在… so the sentence loses its subject.","主语是句子的陈述对象，通常位于句首。 · HSK 1 常见主语：（1）名词（苹果很好吃）；（2）代词（我喜欢喝茶、这是书）；（3）名词性短语（我的朋友是医生、爸爸和妈妈、桌子上）。 · 注意：不要在主语前乱加介词（如“在桌子上有一本书”）导致句子缺主语。","Chủ ngữ (主语) là đối tượng được nói đến, thường đứng đầu câu. · 3 loại chính ở HSK 1: danh từ (苹果很好吃), đại từ (我喜欢喝茶), cụm danh từ (我的朋友是医生, 爸爸和妈妈, 桌子上). · Lưu ý: không thêm giới từ thừa trước chủ ngữ làm mất chủ ngữ.","主語（主语）は文の主題・動作主で通常は文頭に置く。 · HSK1では（1）名詞（苹果很好吃）、（2）代名詞（我喜欢喝茶）、（3）名詞句（我的朋友是医生・桌子上）が主語になる。 · 注意：主語の前に余計な前置詞を付けない。"],"use":[{"ok":true,"zh":"我的朋友是医生。","fix":"","py":"Wǒ de péngyou shì yīshēng.","tr":["เพื่อนของฉันเป็นหมอ","My friend is a doctor.","Bạn của tôi là bác sĩ.","私の友達は医者です。"],"h":["ใช้วลีนาม (我的朋友 / 那本书) ทั้งก้อนเป็นประธาน","A full noun phrase (我的朋友 / 那本书) serves as the subject","名词性短语整体作主语（我的朋友、那本书）","Cả cụm danh từ (我的朋友) làm chủ ngữ","名詞句全体（我的朋友・那本书）が主語になる"],"w":["ทำได้เพราะ 我的朋友 เป็นวลีนามที่มี 朋友 เป็นคำหลัก และ 我的 เป็นตัวขยายวางหน้า สามารถยืนเป็นประธานได้สมบูรณ์","Works because 我的朋友 is a modifier-head noun phrase acting cleanly as the sentence subject.","“我的朋友”构成名词性偏正短语，整体充当主语。","Đúng vì 我的朋友 là cụm danh từ làm chủ ngữ hoàn chỉnh.","「我的朋友」全体が名詞句として主語になっている。"],"ref":"HSK 3.0 g3-1-035 · g3-1-029"},{"ok":true,"zh":"这本书很好看。","fix":"","py":"Zhè běn shū hěn hǎokàn.","tr":["หนังสือเล่มนี้น่าอ่านมาก","This book is very good.","Cuốn sách này rất hay.","この本はとても面白いです。"],"h":["คำชี้เฉพาะ + ลักษณนาม + คำนาม ทำหน้าที่เป็นประธานเจาะจง","Demonstrative + CL + Noun makes a specific subject","“这／那＋量词＋名词”作特指主语","Đại từ chỉ định + lượng từ + danh từ làm chủ ngữ xác định","「这／那＋量詞＋名詞」で特定の主語を作る"],"w":["ทำได้เพราะประธานในภาษาจีนมักเป็นสิ่งที่ผู้พูด-ผู้ฟังชี้เฉพาะหรือรู้จักแล้ว (这本书, 那个苹果)","Works naturally because Chinese subjects tend to be definite/known items like 这本书 or 那个苹果.","汉语主语常为有定成分，“这本书”明确指出陈述对象。","Đúng vì chủ ngữ tiếng Trung thường là đối tượng xác định như 这本书.","中国語の主語は既知・特定のものが多く、「这本书」は理想的。"],"ref":"HSK 3.0 g3-1-035 · g3-1-010"},{"ok":false,"zh":"很喜欢喝茶我。","fix":"我很喜欢喝茶。","py":"Wǒ hěn xǐhuan hē chá.","tr":["ฉันชอบดื่มชามาก","I like drinking tea very much.","Tôi rất thích uống trà.","私はお茶を飲むのがとても好きです。"],"h":["ประโยคปกติวางประธานไว้หน้าภาคแสดงเสมอ","In standard sentences, put the subject BEFORE the predicate","正常语序中主语必须放在谓语前面","Trong câu chuẩn, chủ ngữ luôn đứng TRƯỚC vị ngữ","通常の文では主語は常に述語の前に置く"],"w":["ไม่ได้ในประโยคบอกเล่าทั่วไป เพราะลำดับพื้นฐานของจีนคือ 主语 + 谓语 (我 + 很喜欢喝茶)","Wrong in standard statements because Chinese follows Subject + Predicate order (我 + 很喜欢喝茶).","不行，正常陈述句须遵循“主语＋谓语”语序：我很喜欢喝茶。","Không được vì trật tự chuẩn là Chủ ngữ + Vị ngữ: 我很喜欢喝茶.","通常の平叙文は「主語＋述語」（我很喜欢喝茶）の語順を守る。"],"ref":"HSK 3.0 g3-1-035"}],"ex":[["苹果很好吃。","Píngguǒ hěn hǎochī.","แอปเปิลอร่อยมาก","Apples are very delicious.","Táo rất ngon.","りんごはとてもおいしいです。","苹果"],["她是我的老师。","Tā shì wǒ de lǎoshī.","เธอคือคุณครูของฉัน","She is my teacher.","Cô ấy là giáo viên của tôi.","彼女は私の先生です。","她"],["我的朋友是医生。","Wǒ de péngyou shì yīshēng.","เพื่อนของฉันเป็นหมอ","My friend is a doctor.","Bạn của tôi là bác sĩ.","私の友達は医者です。","我的朋友"],["爸爸和妈妈都工作。","Bàba hé māma dōu gōngzuò.","พ่อกับแม่ทำงานทั้งคู่","Both Dad and Mom work.","Bố và mẹ đều đi làm.","父も母も働いています。","爸爸和妈妈"],["这本书很便宜。","Zhè běn shū hěn piányi.","หนังสือเล่มนี้ถูกมาก","This book is very cheap.","Cuốn sách này rất rẻ.","この本はとても安いです。","这本书"]],"err":[["很喜欢喝茶我。","我很喜欢喝茶。","วางประธานไว้ต้นประโยคหน้าภาคแสดง","Place the subject before the predicate.","主语放在谓语前面（我很喜欢喝茶）。","Đặt chủ ngữ trước vị ngữ (我很喜欢喝茶).","主語は述語の前に置く（我很喜欢喝茶）。"]],"rel":["g3-1-009","g3-1-037","g3-1-042"]},"g3-1-036":{"t":["ภาคแสดงที่เป็นคำนาม/ตัวเลข (名词、数词作谓语)","Noun, Pronoun & Numeral Predicates (名词/数量短语作谓语)","句子成分：名词、代词、数词或数量短语作谓语","Vị ngữ là danh từ / đại từ / cụm số lượng","述語（名詞・代名詞・数量詞が述語になる文）"],"f":["主语 + 时间 / 年龄 / 钱数（不加“是”：今天星期一 / 他二十岁 / 这个十块）","否定：主语 + 不是 + 名词（今天不是星期一）"],"why":["จุดพิเศษที่สำคัญมากของภาษาจีน: เมื่อภาคแสดงบอก วัน-วันที่-เวลา (今天星期一, 现在八点), อายุ (他二十岁), ราคา (苹果五块钱) หรือภูมิลำเนา เราสามารถเอาคำนามหรือวลีจำนวนวางเป็นภาคแสดงต่อจากประธานได้เลย โดยไม่ต้องใส่กริยา 是! · ข้อควรระวัง 2 ข้อ: (1) ประโยคบอกเล่าละ 是 ได้ แต่ประโยคปฏิเสธต้องใส่ 不是 กลับมาเสมอ (今天不是星期一 — ห้ามพูด 今天不星期一!) (2) ใช้ได้เฉพาะหมวดเวลา/อายุ/ราคา/จำนวน ถ้าบอกอาชีพหรือสถานะบุคคลยังต้องใช้ 是 เสมอ (我是学生 ห้ามตัด 是)","A special Chinese feature: when the predicate gives a date/day/time (今天星期一, 现在八点), age (他二十岁), or price (苹果五块钱), you can place the noun or numeral phrase directly after the subject WITHOUT 是! · Two cautions: (1) Negation MUST bring back 不是 (今天不是星期一 — never 今天不星期一). (2) Identity/profession STILL requires 是 (我是学生 — never drop 是).","汉语允许名词、代词或数量短语直接作谓语，主要用于说明日期时间（今天星期一、现在八点）、年龄（他二十岁）、价格（苹果五块钱）等，肯定句可不用“是”。 · 两条注意：（1）否定句必须加“不是”（今天不是星期一，绝不说“今天不星期一”）；（2）表示身份职业仍须用“是”（我是学生）。","Điểm đặc biệt của tiếng Trung: khi nói ngày/giờ (今天星期一, 现在八点), tuổi (他二十岁), giá tiền (苹果五块钱), có thể đặt thẳng danh từ/số lượng làm vị ngữ KHÔNG cần 是! · Lưu ý: (1) Phủ định bắt buộc dùng 不是 (今天不是星期一, không nói 不星期一); (2) Nói nghề nghiệp/thân phận vẫn phải có 是 (我是学生).","中国語では日時（今天星期一・现在八点）、年齢（他二十岁）、価格（苹果五块钱）などを述べる際、「是」なしで名詞・数量詞をそのまま述語にできる。 · 注意：（1）否定文では必ず「不是」を補う（今天不是星期一）。（2）身分・職業は「是」を省けない（我是学生）。"],"use":[{"ok":true,"zh":"今天星期三。","fix":"","py":"Jīntiān xīngqīsān.","tr":["วันนี้วันพุธ","Today is Wednesday.","Hôm nay là thứ Tư.","今日は水曜日です。"],"h":["บอกวัน/วันที่/เวลา/อายุ/ราคา วางคำนามต่อประธานได้เลย","State day, date, time, age, or price directly after the subject","表日期、时间、年龄、价格时名词可直接作谓语","Nói thứ/ngày/giờ/tuổi/giá đặt thẳng sau chủ ngữ","日時・年齢・価格は「是」なしで名詞を直接述語にできる"],"w":["ทำได้และเป็นธรรมชาติกว่าใส่ 是 เสียอีก (今天星期三, 现在九点, 我弟弟八岁, 这个十块钱)","Works even more naturally than inserting 是 (今天星期三, 现在九点, 我弟弟八岁, 这个十块钱).","“今天星期三、现在九点、他二十岁”是汉语最地道的名词谓语句。","Đúng và tự nhiên hơn cả thêm 是 trong khẩu ngữ hằng ngày.","「今天星期三」「他二十岁」は「是」を省く方がむしろ自然。"],"ref":"HSK 3.0 g3-1-036 · g3-1-044"},{"ok":true,"zh":"今天不是星期三。","fix":"","py":"Jīntiān bù shì xīngqīsān.","tr":["วันนี้ไม่ใช่วันพุธ","Today is not Wednesday.","Hôm nay không phải thứ Tư.","今日は水曜日ではありません。"],"h":["รูปปฏิเสธต้องนำ 不是 กลับมาเสมอ","Negation MUST restore 不是","否定形式必须加上“不是”","Câu phủ định bắt buộc phải thêm 不是","否定文では必ず「不是」を補う"],"w":["ทำได้เพราะ 不 ไม่สามารถขยายคำนาม 星期三 ได้โดยตรง ต้องมีกริยา 是 มารับเป็น 不是","Works because 不 cannot negate a noun directly — 是 must be restored to form 不是.","“不”不能直接否定名词，否定名词谓语句必须补出“是”：不是星期三。","Đúng vì 不 không đứng trực tiếp trước danh từ được, phải có 是 thành 不是.","「不」は名詞を直接否定できないため、否定では必ず「不是」を使う。"],"ref":"HSK 3.0 g3-1-036 · g3-1-044"},{"ok":false,"zh":"今天不星期三。","fix":"今天不是星期三。","py":"Jīntiān bù shì xīngqīsān.","tr":["วันนี้ไม่ใช่วันพุธ","Today is not Wednesday.","Hôm nay không phải thứ Tư.","今日は水曜日ではありません。"],"h":["ห้ามวาง 不 หน้าคำนามโดยไม่มี 是","Never put bare 不 directly before a noun","不能说“不星期三／不二十岁”","Không đặt 不 trực tiếp trước danh từ","名詞の直前に「不」だけを置けない"],"w":["ไม่ได้ เพราะถึงแม้ประโยคบอกเล่าจะละ 是 ได้ (今天星期三) แต่พอปฏิเสธต้องใช้ 不是 เท่านั้น ห้ามใช้ 不 + คำนาม ตรง ๆ","Wrong because even though positive sentences drop 是, negative ones cannot put bare 不 before a noun — use 不是.","不行，肯定句虽可省略“是”，但否定句绝不能直接说“不＋名词”，须说“不是”。","Không được vì dù câu khẳng định bỏ 是 nhưng phủ định bắt buộc dùng 不是.","肯定で「是」を省けても、否定で「不＋名詞」は不可。必ず「不是」にする。"],"ref":"HSK 3.0 g3-1-036"},{"ok":false,"zh":"我学生。","fix":"我是学生。","py":"Wǒ shì xuésheng.","tr":["ฉันเป็นนักเรียน","I am a student.","Tôi là học sinh.","私は学生です。"],"h":["บอกอาชีพ/สถานะบุคคล ห้ามตัด 是 ทิ้ง","Never drop 是 for professions or identity","表身份、职业时不能省“是”","Nói nghề nghiệp/thân phận không được bỏ 是","職業・身分の文では「是」を省けない"],"w":["ไม่ได้ เพราะ 学生 เป็นอาชีพ/สถานะ ไม่ใช่เวลา อายุ หรือราคา จึงต้องมี 是 เป็นกริยาเชื่อมเสมอ (我是学生, 他是医生)","Wrong because 学生 is an identity/occupation (not date/age/price), so 是 is mandatory: 我是学生.","不行，“学生、医生”表身份职业，必须用“是”字句（我是学生），不能省“是”。","Không được vì 学生 là thân phận/nghề nghiệp, bắt buộc dùng 是 (我是学生).","「学生・医生」など職業・身分は名詞述語文にできず必ず「是」が要る。"],"ref":"HSK 3.0 g3-1-036 · g3-1-052"}],"ex":[["今天星期一。","Jīntiān xīngqīyī.","วันนี้วันจันทร์","Today is Monday.","Hôm nay là thứ Hai.","今日は月曜日です。","星期一"],["现在八点半。","Xiànzài bā diǎn bàn.","ตอนนี้แปดโมงครึ่ง","It is 8:30 now.","Bây giờ là 8 giờ rưỡi.","今8時半です。","八点半"],["我妹妹七岁。","Wǒ mèimei qī suì.","น้องสาวฉันอายุเจ็ดขวบ","My younger sister is seven years old.","Em gái tôi bảy tuổi.","妹は7歳です。","七岁"],["这个苹果三块钱。","Zhège píngguǒ sān kuài qián.","แอปเปิลลูกนี้สามหยวน","This apple is three yuan.","Quả táo này ba tệ.","このりんごは3元です。","三块钱"],["明天五月八号。","Míngtiān wǔ yuè bā hào.","พรุ่งนี้วันที่ 8 พฤษภาคม","Tomorrow is May 8th.","Ngày mai là ngày 8 tháng 5.","明日は5月8日です。","五月八号"]],"err":[["今天不星期三。","今天不是星期三。","ปฏิเสธคำนามต้องใส่ 不是 เสมอ ห้ามใช้ 不 โดด ๆ","Always restore 不是 when negating a noun predicate.","否定名词谓语必须用“不是”。","Phủ định vị ngữ danh từ bắt buộc dùng 不是.","名詞述語の否定は必ず「不是」を使う。"],["我学生。","我是学生。","บอกอาชีพ/สถานะบุคคลต้องมี 是 เสมอ","Professions and identities require 是.","身份职业必须用“是”（我是学生）。","Nghề nghiệp/thân phận bắt buộc phải có 是.","職業・身分は「是」を省けない。"]],"rel":["g3-1-044","g3-1-052","g3-1-069"]},"g3-1-037":{"t":["ภาคแสดงที่เป็นกริยา / คุณศัพท์ (动词、形容词作谓语)","Verbal & Adjectival Predicates (动词/形容词作谓语)","句子成分：动词、形容词作谓语","Vị ngữ là động từ hoặc tính từ","述語（動詞・形容詞が述語になる文）"],"f":["主语 + 动词（+ 宾语）：我喝茶 / 他看书","主语 + 很 / 非常 / 太 + 形容词：她很漂亮 / 今天非常热（不加“是”）"],"why":["ภาคแสดงที่พบบ่อยที่สุดในภาษาจีนมี 2 แบบ: (1) ภาคแสดงกริยา เช่น 我喝茶, 爸爸去上班 (2) ภาคแสดงคุณศัพท์ เช่น 她很漂亮, 今天很冷 · กฎเหล็กของภาคแสดงคุณศัพท์: ห้ามใส่ 是 หน้าคุณศัพท์เด็ดขาด! (ไม่พูด 她是漂亮 หรือ 今天是热 — ต่างจากภาษาอังกฤษ is/am/are) แต่ในประโยคบอกเล่าทั่วไปมักต้องใส่คำวิเศษณ์ระดับอย่าง 很, 非常, 真, 太 นำหน้าคุณศัพท์ เพื่อให้ประโยคสมบูรณ์และไม่ฟังเหมือนกำลังเปรียบเทียบ","The two most common predicates in Chinese are: (1) verb predicates (我喝茶, 爸爸去上班) and (2) adjective predicates (她很漂亮, 今天很冷). · Iron rule for adjectives: NEVER put 是 before an adjective like English 'is/am/are' (never 她是漂亮)! Instead, place a degree adverb like 很 / 非常 / 太 before it in plain affirmative statements.","汉语最常见的两类谓语是：（1）动词或动词性短语作谓语（我喝茶）；（2）形容词或形容词性短语作谓语（她很漂亮）。 · 形容词作谓语铁律：绝不能像英语那样在形容词前加“是”（不说“她是漂亮”）；肯定陈述句中通常需加“很、非常、太”等程度副词。","Hai loại vị ngữ phổ biến nhất: (1) vị ngữ động từ (我喝茶), (2) vị ngữ tính từ (她很漂亮). · Quy tắc thép của tính từ: KHÔNG BAO GIỜ thêm 是 trước tính từ (không nói 她是漂亮)! Câu khẳng định thường cần 很 / 非常 / 太 trước tính từ.","最も多い述語は（1）動詞述語（我喝茶）と（2）形容詞述語（她很漂亮）。 · 形容詞述語の鉄則：英語の be 動詞のように「是」を付けない（她是漂亮は不可）。肯定の平叙文では通常「很・非常・太」を前に置く。"],"use":[{"ok":true,"zh":"今天非常热。","fix":"","py":"Jīntiān fēicháng rè.","tr":["วันนี้ร้อนมาก ๆ","Today is extremely hot.","Hôm nay cực kỳ nóng.","今日はとても暑いです。"],"h":["ภาคแสดงคุณศัพท์: ประธาน + 很 / 非常 / 太 + คุณศัพท์","Adjective predicate: Subject + 很 / 非常 / 太 + Adjective","形容词谓语：主语＋程度副词＋形容词","Vị ngữ tính từ: Chủ ngữ + 很/非常/太 + Tính từ","形容詞述語：「主語＋程度副詞＋形容詞」"],"w":["ทำได้เพราะคุณศัพท์จีน (热, 冷, 高, 漂亮, 忙) ทำหน้าที่เป็นภาคแสดงได้ด้วยตัวเอง โดยใช้ 非常 / 很 ช่วยเสริมระดับโดยไม่ต้องมี 是","Works because Chinese adjectives act as predicates directly with a degree adverb (很/非常) and NO 是.","汉语形容词直接充当谓语，前加程度副词“很／非常”，不加“是”。","Đúng vì tính từ tiếng Trung tự làm vị ngữ, chỉ cần phó từ 很/非常 mà không dùng 是.","中国語の形容詞は「是」なしで述語になり、「很・非常」などを前に添える。"],"ref":"กลุ่มเทียบคำ g14 · HSK 3.0 g3-1-037"},{"ok":true,"zh":"他不高。","fix":"","py":"Tā bù gāo.","tr":["เขาไม่สูง","He is not tall.","Anh ấy không cao.","彼は背が高くないです。"],"h":["ปฏิเสธคุณศัพท์ใช้ 不 + คุณศัพท์ ได้เลย (ไม่จำเป็นต้องมี 很)","Negate an adjective directly with 不 + Adj (no 很 needed)","否定形容词直接用“不＋形容词”","Phủ định tính từ dùng thẳng 不 + Tính từ","形容詞の否定は「不＋形容詞」だけでよい"],"w":["ทำได้เพราะเมื่อมีคำปฏิเสธ 不 แล้ว ประโยคจะสมบูรณ์ทันทีโดยไม่ต้องใส่ 很 (ส่วน 不很高 จะแปลเบาลงว่า 'ไม่ได้สูงมาก')","Works because 不 itself balances the adjective predicate — no 很 is required (whereas 不很高 softens it to 'not very tall').","否定式“不＋形容词”结构已完整，不必再加“很”（“不很高”语气更委婉）。","Đúng vì có 不 là câu đã trọn vẹn, không cần 很.","否定の「不」があれば「很」は不要でそのまま自然な文になる。"],"ref":"HSK 3.0 g3-1-037 · g3-1-043"},{"ok":false,"zh":"她是漂亮。","fix":"她很漂亮。","py":"Tā hěn piàoliang.","tr":["เธอสวยมาก","She is pretty.","Cô ấy rất xinh đẹp.","彼女はとてもきれいです。"],"h":["ห้ามใส่ 是 หน้าคุณศัพท์ (漂亮 / 高 / 冷 / 忙)","Never put 是 directly before an adjective","形容词谓语前绝不能加“是”","Tuyệt đối không đặt 是 trước tính từ","形容詞述語の前に「是」を置けない"],"w":["ไม่ได้ เพราะ 是 ไม่ใช่ be (is/am/are) ในภาษาอังกฤษ คุณศัพท์จีนเป็นภาคแสดงได้เองทันที เพียงใช้ 很 / 非常 นำหน้าแทน เป็น 她很漂亮","Wrong because 是 is NOT English 'is/am/are' — adjectives take 很/非常 instead: 她很漂亮.","不行，“是”不能代替英语的 be 动词接形容词，应改为“她很漂亮”。","Không được vì 是 không dùng trước tính từ như 'to be'; phải sửa thành 她很漂亮.","「是」は形容詞の前には置けない。「她很漂亮」にする。"],"ref":"HSK 3.0 g3-1-037 · g3-1-043"},{"ok":false,"zh":"今天很下雨。","fix":"今天下雨了。","py":"Jīntiān xià yǔ le.","tr":["วันนี้ฝนตกแล้ว","It rained / started raining today.","Hôm nay trời mưa rồi.","今日は雨が降りました。"],"h":["ห้ามใส่ 很 หน้ากริยาการกระทำทั่วไป (เช่น 下雨 / 吃饭 / 去)","Never put 很 before ordinary action verbs (下雨 / 吃饭 / 去)","一般动作动词前不能加程度副词“很”","Không đặt 很 trước động từ hành động thông thường","一般の動作動詞の前に「很」は付けられない"],"w":["ไม่ได้ เพราะ 很 ใช้ขยายคุณศัพท์ (很高, 很冷) และกริยาความรู้สึก (很喜欢, 很爱, 很想) เท่านั้น ไม่ใช้หน้ากริยาการกระทำอย่าง 下雨, 吃, 看","Wrong because 很 only modifies adjectives (很高) and mental/feeling verbs (很喜欢, 很爱, 很想) — never ordinary action verbs like 下雨 or 吃.","不行，“很”只修饰形容词和心理动词（很喜欢、很想），不能修饰一般动作动词（不说“很下雨、很吃”）。","Không được vì 很 chỉ bổ nghĩa cho tính từ và động từ tâm lý (很喜欢, 很爱), không dùng trước 下雨 / 吃.","「很」は形容詞と心理動詞（很喜欢・很想）専用で、一般動作動詞（下雨・吃）の前には置けない。"],"ref":"HSK 3.0 g3-1-037 · g3-1-015"}],"ex":[["爸爸在看书。","Bàba zài kàn shū.","พ่อกำลังอ่านหนังสือ","Dad is reading a book.","Bố đang đọc sách.","父は本を読んでいます。","看书"],["她很漂亮。","Tā hěn piàoliang.","เธอสวยมาก","She is very pretty.","Cô ấy rất xinh đẹp.","彼女はとてもきれいです。","很漂亮"],["今天非常冷。","Jīntiān fēicháng lěng.","วันนี้หนาวมาก ๆ","Today is extremely cold.","Hôm nay cực kỳ lạnh.","今日は非常に寒いです。","非常冷"],["这个菜不好吃。","Zhège cài bù hǎochī.","อาหารจานนี้ไม่อร่อย","This dish is not delicious.","Món này không ngon.","この料理はおいしくないです。","不好吃"],["哥哥明天上班。","Gēge míngtiān shàngbān.","พรุ่งนี้พี่ชายไปทำงาน","Older brother goes to work tomorrow.","Ngày mai anh trai đi làm.","兄は明日出勤します。","上班"]],"err":[["她是漂亮。","她很漂亮。","ห้ามใส่ 是 หน้าคุณศัพท์ ให้ใช้ 很 / 非常 แทน","Never put 是 before an adjective; use 很 / 非常.","形容词前不加“是”，用“很”。","Không đặt 是 trước tính từ, dùng 很.","形容詞の前に「是」は置かず「很」を使う。"],["今天很下雨。","今天下雨了。","很 ไม่ใช้ขยายกริยาการกระทำทั่วไป (ใช้กับคุณศัพท์หรือ 喜欢/爱/想)","很 cannot modify ordinary action verbs like 下雨.","“很”不能修饰一般动作动词。","很 không bổ nghĩa cho động từ hành động thường.","「很」は一般動作動詞には付けられない。"]],"rel":["g3-1-042","g3-1-043","g3-1-015"]},"g3-1-038":{"t":["กรรมของประโยค (宾语): คำนาม / สรรพนาม / วลีนาม","Sentence Object (宾语): nouns, pronouns & noun phrases","句子成分：宾语","Tân ngữ (宾语): danh từ, đại từ, cụm danh từ","文の成分「目的語（宾语）」"],"f":["主语 + 动词 + 宾语（名词 / 代词 / 名词性短语）"],"why":["宾语 (กรรม) คือผู้รับการกระทำหรือสิ่งที่เกี่ยวข้องกับกริยา วางไว้ 'หลังกริยา' เสมอ (เหมือนภาษาไทย) · สิ่งที่ทำหน้าที่เป็นกรรมใน HSK 1 ได้: (1) คำนาม (喝茶, 买苹果) (2) สรรพนาม (我认识他, 我喜欢这个) (3) วลีนาม (我买了一本新书, 他有两个朋友) · ข้อควรระวัง: (1) สรรพนามกรรมภาษาจีนไม่ต้องเปลี่ยนรูป (我 = ฉัน/ตัวฉัน, 他 = เขา/ตัวเขา) (2) กริยาบางตัวไม่ต้องการกรรม เช่น 睡觉, 下雨, 起床, 上班 — ห้ามเติมกรรมต่อท้าย","The object (宾语) receives or completes the verb and always follows the verb (same as Thai/English). · HSK 1 objects can be: (1) nouns (喝茶), (2) pronouns (我认识他), (3) noun phrases (一本新书, 两个朋友). · Cautions: (1) Pronouns never change form as objects (他 = he/him). (2) Verbs that are intransitive or already verb-object (睡觉, 起床, 上班) cannot take another direct object.","宾语表示动作涉及的对象或结果，位于动词后面。 · 可作宾语的有：名词（喝茶）、代词（认识他）、名词性短语（一本新书）。 · 注意：（1）汉语人称代词作宾语不变形；（2）“睡觉、起床、上班”等不能再直接带宾语。","Tân ngữ (宾语) đứng SAU động từ: danh từ (喝茶), đại từ (认识他), cụm danh từ (一本新书). · Lưu ý: đại từ không đổi dạng khi làm tân ngữ; các từ như 睡觉, 起床, 上班 không nhận thêm tân ngữ trực tiếp.","目的語（宾语）は動詞の後ろに置く：名詞（喝茶）、代名詞（认识他）、名詞句（一本新书）。 · 注意：代名詞は目的語でも形が変わらない。「睡觉・起床・上班」などは後ろに直接目的語を取らない。"],"use":[{"ok":true,"zh":"我认识那个老师。","fix":"","py":"Wǒ rènshi nàge lǎoshī.","tr":["ฉันรู้จักคุณครูคนนั้น","I know that teacher.","Tôi quen thầy giáo kia.","あの先生を知っています。"],"h":["ใช้วลีนามเต็ม (那个老师 / 一本新书) เป็นกรรมหลังกริยา","Place a full noun phrase (那个老师 / 一本新书) as object after the verb","名词性短语整体作动词宾语（那个老师、一本新书）","Đặt cả cụm danh từ làm tân ngữ sau động từ","名詞句全体（那个老师・一本新书）を動詞の目的語に置ける"],"w":["ทำได้เพราะ 那个老师 เป็นวลีนามที่ขยายครบถ้วน วางหลังกริยา 认识 ได้ทันทีโดยไม่ต้องเปลี่ยนรูป","Works because 那个老师 is a complete noun phrase placed directly after the verb 认识.","“那个老师”作为名词性短语直接充当动词“认识”的宾语。","Đúng vì 那个老师 là cụm danh từ hoàn chỉnh đứng ngay sau 认识.","「那个老师」という名詞句全体が動詞「认识」の目的語になる。"],"ref":"HSK 3.0 g3-1-038 · g3-1-030"},{"ok":true,"zh":"我认识他，他也认识我。","fix":"","py":"Wǒ rènshi tā, tā yě rènshi wǒ.","tr":["ฉันรู้จักเขา เขาก็รู้จักฉัน","I know him, and he knows me too.","Tôi quen anh ấy, anh ấy cũng quen tôi.","私は彼を知っていて、彼も私を知っています。"],"h":["สรรพนามที่เป็นกรรม (他 / 我 / 你) ไม่เปลี่ยนรูปเหมือนภาษาอังกฤษ","Pronoun objects (他 / 我 / 你) never change form (unlike he→him)","人称代词作宾语不发生格变化（我、你、他）","Đại từ làm tân ngữ không đổi hình thức (我, 你, 他)","代名詞は目的語になっても語形変化しない（我・你・他）"],"w":["ทำได้เพราะในภาษาจีนสรรพนามเป็นประธานหรือกรรมก็ใช้รูปเดิม (我, 他) ต่างจากภาษาอังกฤษที่ต้องผัน I→me, he→him","Works because Chinese pronouns stay identical as subject or object (我/他), unlike English I/me, he/him.","汉语代词无主格、宾格变化，主语和宾语形式完全一致。","Đúng vì đại từ tiếng Trung giữ nguyên hình thức dù làm chủ ngữ hay tân ngữ.","英語の I/me のような格変化がなく、主語でも目的語でも同じ形を使う。"],"ref":"HSK 3.0 g3-1-038 · g3-1-009"},{"ok":false,"zh":"我睡觉床。","fix":"我在房间里睡觉。","py":"Wǒ zài fángjiān lǐ shuìjiào.","tr":["ฉันนอนหลับอยู่ในห้อง","I sleep in the room.","Tôi ngủ trong phòng.","私は部屋の中で寝ます。"],"h":["กริยาที่มีกรรมติดมาแล้ว (睡觉 / 上班 / 起床) ห้ามเติมกรรมต่อท้ายตรง ๆ","Don't tack a direct object onto verbs like 睡觉 / 上班 / 起床","“睡觉、上班、起床”后不能直接加宾语","Không thêm tân ngữ trực tiếp sau 睡觉 / 上班 / 起床","「睡觉・上班・起床」の後ろに直接目的語を付けない"],"w":["ไม่ได้ เพราะ 睡觉 มี 觉 เป็นกรรมอยู่ในตัวแล้ว ถ้าจะบอกสถานที่ที่นอน ให้วาง 在 + สถานที่ ไว้หน้า 睡觉: 我在房间里睡觉","Wrong because 睡觉 already contains its object 觉; express where you sleep with 在 + place BEFORE 睡觉.","不行，“睡觉”本身已是动宾离合词，不能再带直接宾语；地点须用“在……睡觉”放动词前。","Không được vì 睡觉 vốn đã có tân ngữ sẵn; địa điểm phải đặt 在… phía trước.","「睡觉」はすでに目的語「觉」を含む離合詞なので直接目的語を取れず、場所は前に「在…」で置く。"],"ref":"HSK 3.0 g3-1-038 · g3-1-007"}],"ex":[["我喜欢苹果。","Wǒ xǐhuan píngguǒ.","ฉันชอบแอปเปิล","I like apples.","Tôi thích táo.","私はりんごが好きです。","苹果"],["我认识他。","Wǒ rènshi tā.","ฉันรู้จักเขา","I know him.","Tôi quen anh ấy.","私は彼を知っています。","他"],["他买了一本新书。","Tā mǎile yī běn xīn shū.","เขาซื้อหนังสือใหม่หนึ่งเล่ม","He bought a new book.","Anh ấy mua một cuốn sách mới.","彼は新しい本を1冊買いました。","一本新书"],["我们去电影院。","Wǒmen qù diànyǐngyuàn.","พวกเราไปโรงภาพยนตร์","We are going to the movie theater.","Chúng tôi đi rạp chiếu phim.","映画館へ行きます。","电影院"],["我不知道他的名字。","Wǒ bù zhīdao tā de míngzi.","ฉันไม่รู้ชื่อของเขา","I don't know his name.","Tôi không biết tên anh ấy.","彼の名前を知りません。","他的名字"]],"err":[["我苹果喜欢。","我喜欢苹果。","กรรมต้องวางหลังกริยาเสมอ (喜欢苹果)","Place the object after the verb (喜欢苹果).","宾语通常放在动词后面（喜欢苹果）。","Tân ngữ đặt sau động từ (喜欢苹果).","目的語は動詞の後ろに置く（喜欢苹果）。"]],"rel":["g3-1-030","g3-1-042","g3-1-058"]},"g3-1-039":{"t":["ส่วนขยายคำนาม (定语): นาม / คุณศัพท์ / จำนวน +（的）+ คำนาม","Attributive Modifiers (定语): modifying a noun","句子成分：定语","Định ngữ (定语): thành phần bổ nghĩa danh từ","連体修飾語（定语）：名詞を修飾する成分"],"f":["定语（名词 / 形容词短语 / 数量短语）+（的）+ 中心名词","多音节 / 带“很”的形容词 + 的 + 名词（很多人 / 很好的朋友）"],"why":["定语 คือส่วนขยายที่วาง 'หน้าคำนาม' เพื่อระบุว่าเป็นของใคร แบบไหน หรือจำนวนเท่าไร · กฎสำคัญของ 定语 ใน HSK 1: (1) คุณศัพท์พยางค์เดียวบางคำอย่าง 多 (มาก) และ 少 (น้อย) ห้ามวางหน้าคำนามโดด ๆ (ห้ามพูด 多人 ต้องเติม 很 เป็น 很多人!) (2) คำว่า 真 (จริง ๆ) ใช้อุทานเท่านั้น ห้ามใช้เป็น 定语 ขยายคำนาม (ห้ามพูด 真好的人 ต้องพูด 很好的人!) (3) ถ้ามีหลายตัวขยายพร้อมกัน เรียงจาก เจ้าของ/ชี้เฉพาะ → จำนวน+ลักษณนาม → คุณศัพท์ → คำนาม (我的这本新书)","An attributive modifier (定语) sits BEFORE a noun to describe whose, which, how many, or what kind. · Key HSK 1 cautions: (1) Never put bare 多 or 少 right before a noun — always add 很 (很多人, NEVER 多人!). (2) 真 is for exclamations only and cannot modify a noun (say 很好的人, NEVER 真好的人!). (3) Stack multiple modifiers as Possessor/Demonstrative → Number+CL → Adjective → Noun.","定语放在名词前面起修饰限制作用。 · HSK 1 关键注意：（1）“多、少”不能单独直接修饰名词，必须加“很”等副词（很多人，绝不说“多人”）；（2）“真”只用于感叹谓语，不能作定语（说“很好的人”，不说“真好的人”）；（3）多项定语常按“领属／指代→数量→形容词→名词”排列。","Định ngữ (定语) đứng TRƯỚC danh từ. · Lưu ý HSK 1: (1) Không đặt 多/少 đứng lẻ trước danh từ — phải thêm 很 (很多人, không nói 多人); (2) 真 chỉ dùng cảm thán, không làm định ngữ (很好的人, không nói 真好的人); (3) Trật tự nhiều định ngữ: Sở hữu/Chỉ định → Số lượng → Tính từ → Danh từ.","定语は名詞の前に置く連体修飾語。 · HSK1の重要注意：（1）「多・少」は単独で名詞を修飾できず「很」を補う（很多人、「多人」は不可）。（2）「真」は感嘆専用で定语にできない（很好的人、「真好的人」は不可）。（3）語順は「所有・指示→数量→形容詞→名詞」。"],"use":[{"ok":true,"zh":"学校里有很多人。","fix":"","py":"Xuéxiào lǐ yǒu hěn duō rén.","tr":["ในโรงเรียนมีคนเยอะมาก","There are many people at school.","Trong trường có rất nhiều người.","学校にはたくさんの人がいます。"],"h":["ขยายคำนามด้วย 多 / 少 ต้องใส่ 很 นำหน้าเป็น 很多 / 很少","Always add 很 before 多 / 少 when modifying a noun (很多 / 很少)","“多、少”作定语前必须加“很”（很多人）","Định ngữ 多 / 少 bắt buộc thêm 很 (很多人)","「多・少」で名詞を修飾するときは必ず「很」を付ける（很多人）"],"w":["ทำได้เพราะ 很 + 多 กลายเป็นวลีคุณศัพท์ 2 พยางค์ (很多) ที่ขยายคำนาม 人 ได้อย่างถูกต้องตามกฎภาษาจีน (และไม่ต้องใส่ 的)","Works because 很 turns bare 多 into the 2-syllable modifier phrase 很多, which modifies 人 cleanly without 的.","加上“很”构成“很多”就能自然修饰名词“人、书、苹果”，且通常不加“的”。","Đúng vì thêm 很 tạo thành cụm 很多 bổ nghĩa trực tiếp cho danh từ 人.","「很」を足した「很多」なら名詞（人・书・苹果）を直接修飾できる。"],"ref":"เสริม w3-00046 · HSK 3.0 g3-1-039"},{"ok":true,"zh":"他是一个很好的人。","fix":"","py":"Tā shì yī ge hěn hǎo de rén.","tr":["เขาเป็นคนดีมากคนหนึ่ง","He is a very good person.","Anh ấy là một người rất tốt.","彼はとても良い人です。"],"h":["วลีคุณศัพท์ที่มี 很 ขยายคำนาม ต้องใส่ 的 คั่นเสมอ","An adjective phrase with 很 MUST take 的 before a noun","“很＋形容词”作定语必须加“的”（很好的人）","Cụm '很 + tính từ' làm định ngữ bắt buộc có 的","「很＋形容詞」が名詞を修飾するときは必ず「的」を入れる"],"w":["ทำได้เพราะ 很好 เป็นวลีที่มีคำวิเศษณ์ระดับ 很 นำหน้า จึงต้องใส่ 的 เชื่อมกับคำนาม 人 เสมอ (และใช้ 很 ไม่ใช่ 真)","Works because 很好 contains the adverb 很, so 的 is required before 人 (and uses 很, not 真).","形容词前带“很”作定语时，必须加“的”连接中心名词（很好的人、很贵的手机）。","Đúng vì cụm 很好 có phó từ mức độ nên bắt buộc dùng 的 nối với 人.","「很＋形容詞」が連体修飾語になるときは必ず「的」を挟む（很好的人）。"],"ref":"กลุ่มเทียบคำ g14 · HSK 3.0 g3-1-024"},{"ok":false,"zh":"学校里有多人。","fix":"学校里有很多人。","py":"Xuéxiào lǐ yǒu hěn duō rén.","tr":["ในโรงเรียนมีคนเยอะมาก","There are many people at school.","Trong trường có rất nhiều người.","学校にはたくさんの人がいます。"],"h":["ห้ามใช้ 多 ตัวเดียววางหน้าคำนาม (多人 / 多书)","Never put bare 多 directly before a noun (多人 / 多书)","绝不能说“多人／多书”","Không bao giờ nói 多人 / 多书","「多」単独で名詞の前に置けない（多人・多书は不可）"],"w":["ไม่ได้ เพราะในภาษาจีน 多 กับ 少 ไม่สามารถวางเดี่ยว ๆ หน้าคำนามได้ ต้องมีคำวิเศษณ์อย่าง 很 หรือ 太 นำหน้าเสมอเป็น 很多人 / 很多书","Wrong because bare 多/少 cannot directly modify nouns in Chinese — always add 很 or 太 (很多人 / 很多书).","不行，“多、少”单音节不能直接修饰名词，必须加“很”说“很多人、很多书”。","Không được vì 多/少 đứng lẻ không bổ nghĩa danh từ được; phải thêm 很 (很多人).","「多・少」は単独で名詞の前に置けず、必ず「很」を付けて「很多人」にする。"],"ref":"เสริม w3-00046"},{"ok":false,"zh":"他是一个真好的人。","fix":"他是一个很好的人。","py":"Tā shì yī ge hěn hǎo de rén.","tr":["เขาเป็นคนดีมากคนหนึ่ง","He is a very good person.","Anh ấy là một người rất tốt.","彼はとても良い人です。"],"h":["ห้ามใช้ 真 + คุณศัพท์ + 的 ขยายคำนาม (ให้ใช้ 很 แทน)","Never use 真 + Adj + 的 to modify a noun — use 很","“真”不能作定语，要改用“很”","Không dùng 真 + tính từ + 的 làm định ngữ (dùng 很)","「真＋形容詞＋的」で名詞を修飾できない（「很」を使う）"],"w":["ไม่ได้ เพราะตามกฎกลุ่มเทียบคำ g14 คำว่า 真 ใช้อุทานในภาคแสดงเท่านั้น (เช่น 他真好！) ถ้าจะขยายคำนามต้องเปลี่ยนเป็น 很: 很好的人","Wrong per comparison group g14: 真 is strictly for exclamatory predicates (他真好!), never noun modifiers — use 很好的人.","不行，“真”只用于感叹谓语（他真好！），作定语修饰名词须用“很”（很好的人）。","Không được vì 真 chỉ dùng trong vị ngữ cảm thán (他真好!), làm định ngữ phải dùng 很 (很好的人).","「真」は感嘆の述語専用（他真好！）。名詞修飾の定语には「很」（很好的人）を使う。"],"ref":"กลุ่มเทียบคำ g14"}],"ex":[["学校里有很多人。","Xuéxiào lǐ yǒu hěn duō rén.","ในโรงเรียนมีคนเยอะมาก","There are many people at school.","Trong trường có rất nhiều người.","学校に人がたくさんいます。","很多"],["他是一个很好的人。","Tā shì yī ge hěn hǎo de rén.","เขาเป็นคนดีมากคนหนึ่ง","He is a very good person.","Anh ấy là một người rất tốt.","彼はとても良い人です。","很好的"],["我买了一件漂亮的衣服。","Wǒ mǎile yī jiàn piàoliang de yīfu.","ฉันซื้อเสื้อผ้าสวย ๆ หนึ่งตัว","I bought a pretty piece of clothing.","Tôi mua một chiếc áo đẹp.","きれいな服を1着買いました。","漂亮的"],["这是王老师的书。","Zhè shì Wáng lǎoshī de shū.","นี่คือหนังสือของอาจารย์หวัง","This is Teacher Wang's book.","Đây là sách của thầy Vương.","これは王先生の本です。","王老师的"],["桌上有三个大苹果。","Zhuō shàng yǒu sān ge dà píngguǒ.","บนโต๊ะมีแอปเปิลลูกใหญ่สามลูก","There are three big apples on the table.","Trên bàn có ba quả táo lớn.","机の上に大きなりんごが3個あります。","三个大"]],"err":[["学校里有多人。","学校里有很多人。","多 / 少 ขยายคำนามต้องใส่ 很 นำหน้าเสมอ (很多人)","Always add 很 before 多 when modifying a noun (很多人).","“多”作定语前须加“很”（很多人）。","Trước 多 làm định ngữ phải thêm 很 (很多人).","「多」で名詞を修飾するときは「很」を付ける（很多人）。"],["他是一个真好的人。","他是一个很好的人。","真 ใช้อุทานเท่านั้น ขยายคำนามให้ใช้ 很 (很好的人)","真 is for exclamations only; use 很 before nouns (很好的人).","“真”不能作定语，改用“很好的人”。","真 không làm định ngữ, sửa thành 很好的人.","「真」は名詞修飾に使えず「很好的人」にする。"]],"rel":["g3-1-024","g3-1-029","g3-1-032"]},"g3-1-040":{"t":["คำบอกเวลาและสถานที่ วางหน้ากริยา","Time and place go before the verb","时间词和处所词放在动词前","Từ chỉ thời gian, nơi chốn đứng trước động từ","時間・場所の語は動詞の前に置く"],"f":["主语 + 时间 + 在 + 地点 + 动词 + 宾语","时间 + 主语 + 在 + 地点 + 动词 + 宾语"],"why":["ภาษาจีนบอกฉาก 'เมื่อไร' และ 'ที่ไหน' ก่อนบอกว่าทำอะไร ลำดับปกติคือ ประธาน + เวลา + สถานที่ + กริยา + กรรม ตรงข้ามกับภาษาไทยที่มักเอาเวลาและสถานที่ไว้ท้ายประโยค · คำบอกเวลาวางหลังประธาน (我今天…) หรือวางหน้าประธาน (今天我…) ก็ได้ · แต่สถานที่ที่นำด้วย 在 ต้องอยู่หลังประธานและหน้ากริยาเสมอ ไม่วางต้นประโยคก่อนประธาน และไม่วางท้ายประโยค · ถ้ามีทั้งเวลาและสถานที่ เวลามาก่อนสถานที่เสมอ","Chinese sets the scene ('when' and 'where') before saying what happens: subject + time + place + verb + object — the opposite of Thai and English. · A time word can go either after the subject (我今天…) or before it (今天我…). · A place phrase with 在 stays after the subject and before the verb — never at the end of the sentence. · When both appear, time always comes before place.","汉语先交代“什么时候”“在哪儿”，再说做什么，基本语序为：主语＋时间＋在＋处所＋动词＋宾语，与泰语、英语习惯把时间地点放句尾正好相反。 · 时间词既可在主语后（我今天……），也可在主语前（今天我……）。 · “在＋处所”通常紧跟主语后、动词前，不能放句尾。 · 两者同时出现时，时间在前，处所在后。","Tiếng Trung nêu bối cảnh 'khi nào', 'ở đâu' trước rồi mới nói làm gì: chủ ngữ + thời gian + 在 + nơi chốn + động từ + tân ngữ — ngược với tiếng Việt/Thái. · Từ chỉ thời gian đặt sau chủ ngữ (我今天…) hoặc trước chủ ngữ (今天我…) đều được. · Cụm '在 + nơi chốn' đứng sau chủ ngữ, trước động từ, không đặt cuối câu. · Có cả hai thì thời gian trước, nơi chốn sau.","中国語は「いつ」「どこで」を先に述べ、その後に動作を言う（主語＋時間＋在＋場所＋動詞＋目的語）。 · 時間の語は主語の後（我今天…）でも前（今天我…）でも置ける。 · 「在＋場所」は主語の後・動詞の前に置き、文末には置かない。 · 両方あるときは常に時間が先、場所が後。"],"use":[{"ok":true,"zh":"我今天在家吃饭。","fix":"","py":"Wǒ jīntiān zài jiā chīfàn.","tr":["วันนี้ฉันกินข้าวที่บ้าน","I'm eating at home today.","Hôm nay tôi ăn cơm ở nhà.","今日は家でご飯を食べます。"],"h":["ลำดับมาตรฐาน: ประธาน + เวลา + ในสถานที่ + กริยา","Standard order: Subject + Time + 在 Place + Verb","标准语序：主语＋时间＋在＋地点＋动词","Trật tự chuẩn: Chủ ngữ + Thời gian + 在 Nơi chốn + Động từ","基本語順：主語＋時間＋在＋場所＋動詞"],"w":["ทำได้และเป็นลำดับที่ปลอดภัยที่สุด: วางฉากเวลา (今天) ก่อน ตามด้วยฉากสถานที่ (在家) แล้วค่อยจบด้วยกริยา+กรรม (吃饭)","Works as the cleanest default order: set the time (今天) first, then the place (在家), and finish with the action (吃饭).","先交代时间（今天），再交代地点（在家），最后说动作（吃饭），是最标准的汉语状语顺序。","Đúng và an toàn nhất: thời gian (今天) trước, nơi chốn (在家) sau, rồi mới đến hành động (吃饭).","時間（今天）→場所（在家）→動作（吃饭）の順で、中国語の最も標準的な語順。"],"ref":"HSK 3.0 g3-1-040 · g3-1-021"},{"ok":true,"zh":"今天我在家吃饭。","fix":"","py":"Jīntiān wǒ zài jiā chīfàn.","tr":["วันนี้ฉันกินข้าวที่บ้าน (เน้นว่าวันนี้)","Today, I'm eating at home.","Hôm nay tôi ăn cơm ở nhà.","今日、私は家でご飯を食べます。"],"h":["ย้ายคำบอกเวลาไว้หน้าประธานได้","Time words may move before the subject","时间词可以提前到主语前","Có thể đặt từ chỉ thời gian trước chủ ngữ","時間の語は主語の前に出せる"],"w":["ทำได้เพราะคำบอกเวลา (今天, 明天, 晚上) เป็นกรอบเวลาของทั้งประโยค จึงสลับขึ้นต้นหน้าประธานเพื่อเน้นหรือเชื่อมเรื่องได้ โดยยังคงความหมายเดิม","Works because time words (今天, 明天, 晚上) frame the whole sentence, so placing them before the subject emphasizes the time cleanly.","时间词为全句设定时间背景，提前到主语前可起强调或衔接作用，语意自然。","Đúng vì từ chỉ thời gian làm khung bối cảnh cho cả câu, đặt trước chủ ngữ giúp nhấn mạnh thời điểm.","時間の語は文全体の枠組みを示すため、主語の前に出して時間を強調できる。"],"ref":"HSK 3.0 g3-1-040 · ชนิดของคำ_12ชนิด"},{"ok":true,"zh":"他在家里看书。","fix":"","py":"Tā zài jiālǐ kàn shū.","tr":["เขาอ่านหนังสืออยู่ที่บ้าน","He is reading at home.","Anh ấy đọc sách ở nhà.","彼は家で本を読んでいます。"],"h":["สถานที่ที่ทำกริยา ใช้ 在 + สถานที่ + กริยา","Use 在 + place + verb for where an action happens","动作发生的地点用“在＋处所＋动词”","Nơi diễn ra hành động dùng 在 + nơi chốn + động từ","動作の場所は「在＋場所＋動詞」"],"w":["ทำได้เพราะ 在 เป็นคำบุพบท (介词) นำหน้าสถานที่และขยายกริยา 看书 ว่าเกิดเหตุที่ไหน (ต่างจากกริยา 去/来 ที่สถานที่อยู่หลังกริยาเพราะเป็นจุดหมาย เช่น 去学校)","Works because 在 + place is a prepositional adverbial modifying the verb 看书 (note: directional verbs like 去/来 put the destination AFTER the verb: 去学校).","“在＋处所”作状语修饰动词“看书”（注意：“去、来”等趋向动词后接目的地放动词后，如“去学校”）。","Đúng vì cụm 在 + nơi chốn bổ nghĩa cho động từ 看书 (khác với động từ chỉ hướng 去/来 đặt đích đến phía sau: 去学校).","「在＋場所」は動詞「看书」を修飾する（「去・来」など移動の目的地は動詞の後ろ：去学校）。"],"ref":"HSK 3.0 g3-1-021 · 教育部國語辭典 · ประโยคตัวอย่าง_300"},{"ok":false,"zh":"我吃饭在家。","fix":"我在家吃饭。","py":"Wǒ zài jiā chīfàn.","tr":["ฉันกินข้าวที่บ้าน","I eat at home.","Tôi ăn cơm ở nhà.","私は家でご飯を食べます。"],"h":["ห้ามเอา 在 + สถานที่ ไปวางท้ายประโยคแบบภาษาไทย","Never put 在 + place after the verb like Thai/English","不能把“在＋地点”放在句尾","Không đặt 在 + nơi chốn ở cuối câu","「在＋場所」を文末に置けない"],"w":["ไม่ได้ เพราะภาษาจีนยึดหลัก 'ฉากมาก่อนการกระทำ' หากเอาสถานที่ไปวางหลังกริยาจะขัดหลักไวยากรณ์ (ยกเว้นกริยาบางกลุ่มที่บอกผลลัพธ์ของการย้ายที่ เช่น 住在北京 = อาศัยอยู่ที่ปักกิ่ง)","Wrong because Chinese places the setting before the action; putting 在家 at the end is ungrammatical (only a few placement verbs like 住 take 在 + place after).","不行，汉语状语在动词前，表动作发生地点的“在家”不能放句尾（少数动词如“住在北京”属补语例外）。","Không được vì tiếng Trung đặt trạng ngữ nơi chốn trước động từ (chỉ một vài động từ như 住在北京 mới đặt sau).","動作の場所を表す「在家」は必ず動詞の前に置く（「住在北京」など結果補語になる一部の動詞は例外）。"],"ref":"HSK 3.0 g3-1-040"},{"ok":false,"zh":"我去北京明天。","fix":"我明天去北京。","py":"Wǒ míngtiān qù Běijīng.","tr":["พรุ่งนี้ฉันไปปักกิ่ง","I'm going to Beijing tomorrow.","Ngày mai tôi đi Bắc Kinh.","明日北京へ行きます。"],"h":["ห้ามวางคำบอกเวลาไว้ท้ายประโยค","Never place a time word at the end of a sentence","时间词绝不能放在句尾","Không đặt từ chỉ thời gian ở cuối câu","時間の語を文末に置けない"],"w":["ไม่ได้ เพราะคำบอกเวลาเป็นส่วนขยายกริยา (状语) ต้องอยู่หน้ากริยาเสมอ จะวางหลังประธาน (我明天去北京) หรือหน้าประธาน (明天我去北京) ก็ได้ แต่ห้ามไว้ท้ายสุด","Wrong because time words are adverbials and must precede the verb — put 明天 either after 我 or at the very start, never at the end.","不行，时间词作状语必须位于动词之前，可说“我明天去北京”或“明天我去北京”，绝不能放句尾。","Không được vì từ chỉ thời gian là trạng ngữ phải đứng trước động từ (我明天去北京 hoặc 明天我去北京), không đứng cuối câu.","時間の語は動詞の前（我明天去北京／明天我去北京）に置き、文末には絶対に置かない。"],"ref":"HSK 3.0 g3-1-040"},{"ok":false,"zh":"我在家今天吃饭。","fix":"我今天在家吃饭。","py":"Wǒ jīntiān zài jiā chīfàn.","tr":["วันนี้ฉันกินข้าวที่บ้าน","I'm eating at home today.","Hôm nay tôi ăn cơm ở nhà.","今日は家でご飯を食べます。"],"h":["ห้ามวางสถานที่ก่อนเวลา","Don't put place before time","地点不能放在时间前面","Không đặt nơi chốn trước thời gian","場所を時間より前に置けない"],"w":["ไม่ได้ เพราะเมื่อมีทั้งเวลาและสถานที่ ภาษาจีนเรียงจากกรอบใหญ่ไปกรอบแคบ: เวลา (今天) มาก่อนสถานที่ (在家) เสมอ","Wrong because when both time and place appear, Chinese orders them strictly as Time before Place (今天 before 在家).","不行，时间和地点同时出现时，必须遵循“时间在前、地点在后”的顺序。","Không được vì khi có cả hai, tiếng Trung bắt buộc xếp Thời gian trước, Nơi chốn sau.","時間と場所が両方あるときは、必ず「時間が先・場所が後」の順に並べる。"],"ref":"HSK 3.0 g3-1-040"}],"ex":[["我今天在家吃饭。","Wǒ jīntiān zài jiā chīfàn.","วันนี้ฉันกินข้าวที่บ้าน","I'm eating at home today.","Hôm nay tôi ăn cơm ở nhà.","今日は家でご飯を食べます。","在家"],["明天我去学校。","Míngtiān wǒ qù xuéxiào.","พรุ่งนี้ฉันไปโรงเรียน","Tomorrow I'm going to school.","Ngày mai tôi đi học.","明日、学校へ行きます。","明天"],["他在医院工作。","Tā zài yīyuàn gōngzuò.","เขาทำงานที่โรงพยาบาล","He works at a hospital.","Anh ấy làm việc ở bệnh viện.","彼は病院で働いています。","在医院"],["我们晚上在饭店吃饭。","Wǒmen wǎnshang zài fàndiàn chīfàn.","ตอนเย็นพวกเรากินข้าวที่ร้านอาหาร","We eat at a restaurant in the evening.","Buổi tối chúng tôi ăn ở nhà hàng.","夜、私たちはレストランで食事をします。","晚上"],["他在家里看书。","Tā zài jiālǐ kàn shū.","เขาอ่านหนังสืออยู่ที่บ้าน","He reads books at home.","Anh ấy đọc sách ở nhà.","彼は家で本を読みます。","在家里"],["我明天回家。","Wǒ míngtiān huí jiā.","พรุ่งนี้ฉันกลับบ้าน","I'm going home tomorrow.","Ngày mai tôi về nhà.","明日家に帰ります。","明天"]],"err":[["我吃饭在家。","我在家吃饭。","สถานที่ (在家) ต้องอยู่หน้ากริยา ไม่วางท้ายแบบ 'กินข้าวที่บ้าน'","The place (在家) goes before the verb, not at the end.","处所（在家）要放在动词前，不能放在句尾。","Nơi chốn (在家) đứng trước động từ, không đặt cuối câu.","場所（在家）は動詞の前。文末には置かない。"],["我去北京明天。","我明天去北京。","เวลา (明天) อยู่หน้ากริยา หรือหน้าประธานก็ได้ แต่ไม่อยู่ท้ายประโยค","The time (明天) goes before the verb or before the subject, never at the end.","时间（明天）放在动词前或主语前，不放在句尾。","Thời gian (明天) đứng trước động từ hoặc trước chủ ngữ, không ở cuối câu.","時間（明天）は動詞の前か主語の前。文末には置かない。"],["我在家今天吃饭。","我今天在家吃饭。","มีทั้งเวลาและสถานที่ ให้เวลามาก่อน","With both, time comes before place.","时间和处所都有时，时间在前。","Có cả hai thì thời gian trước nơi chốn.","時間と場所が両方あれば時間が先。"]],"rel":["g3-1-021","g3-1-069","g3-1-070"]},"g3-1-041":{"t":["ส่วนเสริมบอกจำนวนครั้ง (数量补语1): กริยา + 一下","Verbal-measure complement (数量补语1): Verb + 一下","句子成分·数量补语1：动词+动量补语","Bổ ngữ động lượng (数量补语1): Động từ + 一下","動量補語（数量补语1）：動詞＋一下"],"f":["动词 + 一下（+ 宾语）：看一下 / 问一下老师 / 休息一下"],"why":["动量补语 คือคำบอกจำนวนครั้งหรือช่วงสั้น ๆ ของการกระทำที่วางไว้ 'หลังกริยา' เสมอ · ในระดับ HSK 1 ตัวหลักคือ 一下 (สักหน่อย / แป๊บหนึ่ง) ซึ่งทำให้คำสั่งหรือคำขอฟังนุ่มนวลและเป็นกันเองขึ้นมาก เช่น 请看一下 (ช่วยดูหน่อย), 我问一下老师 (ฉันขอถามครูหน่อย), 你休息一下吧 (คุณพักสักหน่อยเถอะ) · ข้อควรระวัง: (1) 一下 ต้องวาง 'หลังกริยา' เสมอ ห้ามวางหน้ากริยา (2) ถ้ามีกรรมที่เป็นคำนาม วางกรรมไว้หลัง 一下 (看一下书, 问一下老师) แต่ถ้ากรรมเป็นสรรพนามคน ให้วางสรรพนามไว้ก่อน 一下 (找他一下)","A verbal-measure complement follows a verb to show how many times or how briefly an action happens. · In HSK 1, the core pattern is Verb + 一下 ('a bit / for a moment'), which softens requests and makes speech sound natural: 请看一下, 我问一下老师, 休息一下. · Cautions: (1) ALWAYS place 一下 AFTER the verb, never before it. (2) Noun objects usually follow 一下 (看一下书), while personal pronoun objects come before 一下 (找他一下).","动量补语放在动词后面，说明动作的次数或短暂程度。 · HSK 1 的核心是“动词＋一下”（看一下、问一下老师、休息一下），语气轻松礼貌。 · 注意：（1）“一下”必须放在动词后，绝不能放动词前；（2）名词宾语放“一下”后（看一下书），人称代词宾语放“一下”前（找他一下）。","Bổ ngữ động lượng đặt SAU động từ để chỉ số lần hoặc làm nhanh/một chút. · Ở HSK 1 trọng tâm là 'Động từ + 一下' (看一下, 问一下老师, 休息一下) giúp câu nhẹ nhàng lịch sự. · Lưu ý: (1) 一下 luôn đứng SAU động từ; (2) Tân ngữ danh từ đứng sau 一下 (看一下书), đại từ nhân xưng đứng trước 一下 (找他一下).","動量補語は動詞の後ろに置き、動作の回数や軽さ・短さを表す。 · HSK1の中心は「動詞＋一下」（看一下・问一下老师・休息一下）で、依頼や勧めを柔らかくする。 · 注意：（1）「一下」は必ず動詞の後ろ。（2）名詞目的語は「一下」の後ろ（看一下书）、人称代名詞は前（找他一下）。"],"use":[{"ok":true,"zh":"我看一下这本书。","fix":"","py":"Wǒ kàn yīxià zhè běn shū.","tr":["ฉันขอดูหนังสือเล่มนี้หน่อย","Let me take a quick look at this book.","Để tôi xem qua cuốn sách này một chút.","この本をちょっと見てみます。"],"h":["กริยา + 一下 + กรรมที่เป็นคำนาม","Verb + 一下 + noun object","“动词＋一下＋名词宾语”","Động từ + 一下 + tân ngữ danh từ","「動詞＋一下＋名詞目的語」"],"w":["ทำได้เพราะ 一下 วางชิดหลังกริยา 看 แล้วค่อยตามด้วยกรรมคำนาม 这本书 สื่อว่าดูคร่าว ๆ แป๊บเดียว","Works cleanly because 一下 follows the verb 看 right away, with the noun object 这本书 after it.","“一下”紧跟动词“看”后，再接名词宾语“这本书”，表示随手翻看一会儿。","Đúng vì 一下 đi sát sau động từ 看 rồi mới tới tân ngữ danh từ 这本书.","「一下」を動詞「看」の直後に置き、名詞目的語「这本书」を続ける。"],"ref":"HSK 3.0 g3-1-041"},{"ok":true,"zh":"你休息一下吧。","fix":"","py":"Nǐ xiūxi yīxià ba.","tr":["คุณพักผ่อนสักหน่อยเถอะ","Take a little rest.","Bạn nghỉ ngơi một chút đi.","ちょっと休んでください。"],"h":["เติม 一下 + 吧 หลังกริยาเพื่อชวน/แนะนำอย่างนุ่มนวล","Add 一下 (+ 吧) to soften suggestions or requests","“动词＋一下（＋吧）”让劝告或请求更委婉","Thêm 一下 (+ 吧) giúp lời khuyên/nhờ vả nhẹ nhàng hơn","「動詞＋一下（＋吧）」で勧めや依頼が柔らかくなる"],"w":["ทำได้เพราะ 一下 ช่วยลดความแข็งของคำสั่ง ทำให้ 休息一下吧 ฟังอบอุ่นและสุภาพกว่าพูดแค่ 休息！","Works because 一下 softens imperatives, making 休息一下吧 far warmer and more polite than blunt 休息!","加上“一下”和“吧”缓和命令语气，听起来亲切礼貌。","Đúng vì 一下 và 吧 làm mềm giọng mệnh lệnh, nghe thân thiện hơn.","「一下」と「吧」を添えることで命令の響きが和らぎ丁寧になる。"],"ref":"HSK 3.0 g3-1-041 · g3-1-050"},{"ok":false,"zh":"我一下看这本书。","fix":"我看一下这本书。","py":"Wǒ kàn yīxià zhè běn shū.","tr":["ฉันขอดูหนังสือเล่มนี้หน่อย","Let me take a quick look at this book.","Tôi xem qua cuốn sách này một chút.","この本をちょっと見ます。"],"h":["ห้ามวาง 一下 ไว้หน้ากริยา","Never place 一下 before the verb","动量补语“一下”不能放在动词前","Không đặt 一下 trước động từ","「一下」を動詞の前に置けない"],"w":["ไม่ได้ เพราะ 一下 เป็นส่วนเสริม (补语) ซึ่งในภาษาจีนส่วนเสริมทุกชนิดต้องวาง 'หลังกริยา' เสมอ (看一下 ไม่ใช่ 一下看)","Wrong because 一下 is a complement (补语), and Chinese complements ALWAYS follow the verb (看一下, never 一下看).","不行，“一下”是补语，必须放在动词后面（看一下），不能放动词前。","Không được vì 一下 là bổ ngữ nên bắt buộc đứng SAU động từ (看一下).","「一下」は補語なので必ず動詞の後ろ（看一下）に置き、前には置けない。"],"ref":"HSK 3.0 g3-1-041"},{"ok":false,"zh":"我认识一下他。","fix":"我找他一下。","py":"Wǒ zhǎo tā yīxià.","tr":["ฉันขอไปหาเขาแป๊บหนึ่ง","I'll go look for him for a second.","Tôi đi tìm anh ấy một lát.","ちょっと彼を探してきます。"],"h":["กริยาสภาวะ (认识/知道/是/有) ใช้ 一下 ไม่ได้ และสรรพนามคนวางหน้า 一下","Stative verbs can't take 一下, and personal pronouns precede 一下","静态动词不加“一下”；人称代词宾语放“一下”前","Động từ trạng thái không dùng 一下; đại từ nhân xưng đặt trước 一下","状態動詞には「一下」不可、人称代名詞は「一下」の前"],"w":["ไม่ได้เพราะ 认识 (รู้จัก), 知道, 是 เป็นสภาวะ ไม่ใช่การกระทำชั่วคราว และเมื่อใช้กริยาการกระทำอย่าง 找 กับสรรพนาม 他 ต้องวาง 他 หน้า 一下 เป็น 找他一下","Wrong because stative verbs like 认识 cannot take 一下; with action verbs + personal pronoun, place the pronoun before 一下 (找他一下).","不行，“认识、知道”等静态动词不能带“一下”；带人称代词宾语时说“找他一下”。","Không được vì 认识 là trạng thái không đi với 一下; với đại từ người phải đặt trước 一下 (找他一下).","「认识」など状態動詞には「一下」は不可。動作動詞＋人称代名詞は「找他一下」の順。"],"ref":"HSK 3.0 g3-1-041"}],"ex":[["请看一下。","Qǐng kàn yīxià.","กรุณาช่วยดูสักหน่อย","Please take a look.","Xin hãy xem một chút.","ちょっと見てください。","一下"],["我问一下老师。","Wǒ wèn yīxià lǎoshī.","ฉันขอถามคุณครูสักหน่อย","Let me ask the teacher for a moment.","Để tôi hỏi thầy giáo một chút.","先生にちょっと聞いてみます。","一下"],["你休息一下吧。","Nǐ xiūxi yīxià ba.","คุณพักสักหน่อยเถอะ","Take a little rest.","Bạn nghỉ ngơi một chút đi.","ちょっと休んでください。","一下"],["请坐一下。","Qǐng zuò yīxià.","เชิญนั่งสักครู่ครับ/ค่ะ","Please have a seat for a moment.","Mời ngồi một lát.","少しお掛けください。","一下"],["我找他一下。","Wǒ zhǎo tā yīxià.","ฉันขอไปหาเขาแป๊บหนึ่ง","I'll go look for him for a moment.","Tôi đi tìm anh ấy một lát.","ちょっと彼を訪ねてきます。","一下"]],"err":[["我一下看书。","我看一下书。","一下 เป็นส่วนเสริม ต้องวางหลังกริยาเสมอ (看一下)","一下 is a complement and must follow the verb (看一下).","“一下”是补语，必须放在动词后。","一下 là bổ ngữ, luôn đứng sau động từ.","「一下」は補語なので必ず動詞の後ろに置く。"],["我找一下他。","我找他一下。","กรรมที่เป็นสรรพนามคน (他/你/我) วางไว้หน้า 一下 (找他一下)","Personal pronoun objects go BEFORE 一下 (找他一下).","人称代词宾语放在“一下”前面（找他一下）。","Tân ngữ đại từ nhân xưng đặt TRƯỚC 一下 (找他一下).","人称代名詞の目的語は「一下」の前（找他一下）。"]],"rel":["g3-1-030","g3-1-050"]},"g3-1-042":{"t":["ประโยคภาคแสดงกริยา (主谓句1：动词谓语句)","Verb-predicate sentences (动词谓语句)","句型·主谓句1：动词谓语句","Câu vị ngữ động từ (动词谓语句)","動詞述語文（动词谓语句）"],"f":["主语 +（时间/地点）+ 动词 +（宾语）：我明天去学校","否定：主语 + 不 / 没（有）+ 动词 +（宾语）"],"why":["动词谓语句 คือประโยคพื้นฐานที่มี 'กริยา' เป็นหัวใจของภาคแสดง เช่น 我喝茶, 爸爸在医院工作, 他买了一本书 · โครงสร้างเต็มเรียงตามลำดับ: ประธาน → เวลา → สถานที่ (在…) → กริยา → กรรม · ข้อควรระวัง: (1) เวลาปฏิเสธต้องเลือกให้ถูก: นิสัย/ปัจจุบัน/อนาคต ใช้ 不 (我不喝茶, 明天不去) ส่วนอดีตที่ไม่ได้ทำใช้ 没(有) (昨天没去 — ห้ามใส่ 了 ท้ายกริยาหลัง 没!) (2) ห้ามเอากริยา 是 มาใส่ซ้อนหน้ากริยาแท้อื่น (ห้ามพูด 我是去学校)","A verb-predicate sentence (动词谓语句) centers on a verb as its predicate: 我喝茶, 爸爸在医院工作, 他买了一本书. · Full order: Subject → Time → Place (在…) → Verb → Object. · Cautions: (1) Negate habits/present/future with 不 (我不喝茶), past non-events with 没(有) (昨天没去, dropping 了!). (2) NEVER insert extra 是 before an ordinary action verb (never 我是去学校).","动词谓语句是以动词或动词性短语为核心谓语的基本句型（我喝茶、爸爸在医院工作）。 · 语序：主语→时间→地点→动词→宾语。 · 注意：（1）否定习惯／意愿／将来用“不”，否定过去未发生用“没（有）”（且不带“了”）；（2）一般动词前不随便加“是”（不说“我是去学校”）。","Câu vị ngữ động từ lấy động từ làm trung tâm (我喝茶, 爸爸在医院工作). · Trật tự: Chủ ngữ → Thời gian → Địa điểm → Động từ → Tân ngữ. · Lưu ý: (1) Phủ định thói quen/tương lai dùng 不, quá khứ chưa làm dùng 没(有) (bỏ 了); (2) Không thêm 是 thừa trước động từ thường (không nói 我是去学校).","動詞述語文は動詞を述語の中心とする基本文型（我喝茶・爸爸在医院工作）。 · 語順：主語→時間→場所→動詞→目的語。 · 注意：（1）習慣・未来の否定は「不」、過去の未実現は「没（有）」（「了」は付けない）。（2）一般動詞の前に余計な「是」を入れない。"],"use":[{"ok":true,"zh":"我明天在学校学习汉语。","fix":"","py":"Wǒ míngtiān zài xuéxiào xuéxí Hànyǔ.","tr":["พรุ่งนี้ฉันเรียนภาษาจีนที่โรงเรียน","Tomorrow I will study Chinese at school.","Ngày mai tôi học tiếng Trung ở trường.","明日学校で中国語を勉強します。"],"h":["ลำดับมาตรฐาน: ประธาน → เวลา → สถานที่ → กริยา → กรรม","Standard order: Subject → Time → Place → Verb → Object","标准语序：主语＋时间＋地点＋动词＋宾语","Trật tự chuẩn: Chủ ngữ + Thời gian + Địa điểm + Động từ + Tân ngữ","標準語順：主語＋時間＋場所＋動詞＋目的語"],"w":["ทำได้เพราะเรียงส่วนประกอบครบทั้ง 5 ช่องเป๊ะตามลำดับภาษาจีน: 我 (ประธาน) → 明天 (เวลา) → 在学校 (สถานที่) → 学习 (กริยา) → 汉语 (กรรม)","Works cleanly with all 5 slots in strict Chinese order: Subject → Time → Place → Verb → Object.","严格按照“主语→时间→处所→动词→宾语”排列，清晰地道。","Đúng hoàn toàn trật tự 5 thành phần chuẩn của tiếng Trung.","「主語→時間→場所→動詞→目的語」の5要素が完璧な語順。"],"ref":"HSK 3.0 g3-1-042 · g3-1-040"},{"ok":true,"zh":"我昨天没去商店。","fix":"","py":"Wǒ zuótiān méi qù shāngdiàn.","tr":["เมื่อวานฉันไม่ได้ไปร้านค้า","I didn't go to the shop yesterday.","Hôm qua tôi không đi cửa hàng.","昨日店に行きませんでした。"],"h":["ปฏิเสธเหตุการณ์ในอดีตใช้ 没 + กริยา (และไม่ใส่ 了)","Negate past actions with 没 + verb (drop 了)","否定过去未发生的事用“没＋动词”（不加“了”）","Phủ định việc quá khứ dùng 没 + động từ (không thêm 了)","過去の否定は「没＋動詞」（「了」は付けない）"],"w":["ทำได้เพราะ 昨天 เป็นอดีต การบอกว่าไม่ได้ไปต้องใช้ 没 (ไม่ใช่ 不) และต้องตัด 了 ออกเสมอ","Works because 昨天 is in the past: 没 negates past events cleanly without 了.","“昨天”表过去，否定已过去未做的动作要用“没”，且绝不能加“了”。","Đúng vì 昨天 là quá khứ nên dùng 没 và không kèm 了.","過去の出来事の否定には「没」を使い、「了」は付けない。"],"ref":"กลุ่มเทียบคำ g6 · HSK 3.0 g3-1-020"},{"ok":false,"zh":"我是去学校。","fix":"我去学校。","py":"Wǒ qù xuéxiào.","tr":["ฉันไปโรงเรียน","I go to school.","Tôi đi học.","学校へ行きます。"],"h":["ห้ามใส่ 是 เกินหน้ากริยาการกระทำทั่วไป","Don't add unnecessary 是 before ordinary action verbs","一般动作动词前不能随便加“是”","Không thêm 是 thừa trước động từ hành động","一般動詞の前に不要な「是」を入れない"],"w":["ไม่ได้ในประโยคบอกเล่าปกติ เพราะ 去 เป็นกริยาแท้อยู่แล้ว ไม่ต้องมี 是 มาช่วย (ถ้าใส่ 是 จะเปลี่ยนเป็นประโยคเน้นย้ำเฉพาะกรณีพิเศษ ไม่ใช่ประโยคธรรมดา)","Wrong in normal statements because 去 is already the main verb — adding 是 makes it unnatural here.","不行，“去”本身就是谓语动词，普通陈述句前不能加“是”。","Không được vì 去 đã là động từ chính, câu bình thường không thêm 是.","「去」が本動詞なので普通の平叙文では「是」を入れない。"],"ref":"HSK 3.0 g3-1-042"},{"ok":false,"zh":"我昨天没去了商店。","fix":"我昨天没去商店。","py":"Wǒ zuótiān méi qù shāngdiàn.","tr":["เมื่อวานฉันไม่ได้ไปร้านค้า","I didn't go to the shop yesterday.","Hôm qua tôi đã không đi cửa hàng.","昨日店に行きませんでした。"],"h":["ห้ามใช้ 没 คู่กับ 了 ท้ายกริยา","Never combine 没 with completed 了","“没”和表完成的“了”绝不能同时出现","Không bao giờ dùng 没 chung với 了","「没」と完了の「了」は併用不可"],"w":["ไม่ได้ เพราะ 没 แปลว่า 'ไม่ได้เกิด/ยังไม่เกิด' ส่วน 了 หลังกริยาแปลว่า 'เกิดขึ้นสำเร็จแล้ว' จึงขัดแย้งกันโดยตรง","Wrong because 没 means the action didn't happen while 了 marks completion — they contradict each other.","不行，“没”表动作未发生，“了”表已完成，二者语义矛盾不能同用。","Không được vì 没 (chưa xảy ra) và 了 (đã xong) mâu thuẫn nhau.","「没」（未実現）と「了」（完了）は矛盾するため同時に使えない。"],"ref":"กลุ่มเทียบคำ g6 · HSK 3.0 g3-1-025"}],"ex":[["我早上看书。","Wǒ zǎoshang kàn shū.","ตอนเช้าฉันอ่านหนังสือ","I read books in the morning.","Buổi sáng tôi đọc sách.","朝、本を読みます。","看书"],["爸爸在医院工作。","Bàba zài yīyuàn gōngzuò.","พ่อทำงานที่โรงพยาบาล","Dad works at a hospital.","Bố làm việc ở bệnh viện.","父は病院で働いています。","工作"],["她买了一件新衣服。","Tā mǎile yī jiàn xīn yīfu.","เธอซื้อเสื้อผ้าใหม่หนึ่งตัว","She bought a new piece of clothing.","Cô ấy mua một chiếc áo mới.","彼女は新しい服を1着買いました。","买了"],["我不喝茶。","Wǒ bù hē chá.","ฉันไม่ดื่มชา","I don't drink tea.","Tôi không uống trà.","私はお茶を飲みません。","不喝"],["他昨天没去学校。","Tā zuótiān méi qù xuéxiào.","เมื่อวานเขาไม่ได้ไปโรงเรียน","He didn't go to school yesterday.","Hôm qua anh ấy không đi học.","彼は昨日学校に行きませんでした。","没去"]],"err":[["我是去学校。","我去学校。","ประโยคบอกเล่าปกติไม่ใส่ 是 หน้ากริยาแท้","Do not put 是 before an ordinary action verb.","一般动词谓语句前不加“是”。","Không thêm 是 trước động từ thường.","一般動詞の前に余計な「是」を入れない。"],["他昨天没去了学校。","他昨天没去学校。","หลัง 没 ห้ามใส่ 了","Never combine 没 with completed 了.","“没”后面不能加“了”。","Sau 没 không thêm 了.","「没」の後ろに「了」は付けない。"]],"rel":["g3-1-037","g3-1-020","g3-1-040"]},"g3-1-043":{"t":["ประโยคภาคแสดงคุณศัพท์ (主谓句2：形容词谓语句)","Adjective-predicate sentences (形容词谓语句)","句型·主谓句2：形容词谓语句","Câu vị ngữ tính từ (形容词谓语句)","形容詞述語文（形容词谓语句）"],"f":["肯定：主语 + 很 / 非常 / 真 / 太 + 形容词（今天很冷 / 苹果很好吃）","否定：主语 + 不 + 形容词（今天不冷 / 这个不贵）"],"why":["形容词谓语句 ใช้บรรยายลักษณะหรือสภาพของประธาน (เช่น สูง สวย ร้อน หนาว อร่อย แพง ยุ่ง) · กฎสำคัญ 3 ข้อที่ออกสอบบ่อยที่สุด: (1) ห้ามใส่ 是 หน้าคุณศัพท์เด็ดขาด! (今天很热 ไม่ใช่ 今天是热) (2) ประโยคบอกเล่าที่ไม่ได้เปรียบเทียบกับอะไร ต้องมีคำวิเศษณ์ระดับอย่าง 很, 非常, 太 นำหน้า (ถ้าพูดลอย ๆ ว่า 他高 คนจีนจะรู้สึกเหมือนประโยคยังไม่จบ รอคำเปรียบเทียบว่า 'เขาสูง แต่ฉันเตี้ย') (3) ประโยคปฏิเสธใช้ 不 + คุณศัพท์ (不冷, 不贵) และประโยคคำถามใช้ 吗 หรือ A不A (冷吗？ / 冷不冷？)","Adjective-predicate sentences describe qualities or states (tall, pretty, hot, cold, delicious, expensive, busy). · Three exam-critical rules: (1) NEVER use 是 before the adjective (今天很热, NOT 今天是热). (2) Plain affirmative statements need a degree adverb like 很/非常/太 (bare 他高 sounds incomplete/contrastive). (3) Negate with 不 + Adj (不冷, 不贵) and ask with 吗 or A不A (冷吗？ / 冷不冷？).","形容词谓语句用来描写主语的性质或状态。 · 三大要点：（1）绝不能加“是”（不说“今天是热”）；（2）肯定陈述句一般须加“很、非常、太”等程度副词，单用光杆形容词（他高）常含对比意味；（3）否定用“不＋形容词”（不冷），疑问用“吗”或“A不A”（冷不冷？）。","Câu vị ngữ tính từ miêu tả tính chất, trạng thái. · 3 quy tắc vàng: (1) KHÔNG thêm 是 trước tính từ (今天很热, không nói 今天是热); (2) Câu khẳng định thường cần 很/非常/太 (nếu nói trống 他高 sẽ mang nghĩa so sánh); (3) Phủ định dùng 不 + tính từ (不冷).","形容詞述語文は主語の性質・状態を表す。 · 3つの鉄則：（1）「是」を付けない（今天是热は不可）。（2）肯定の平叙文は「很・非常・太」を添える（裸の「他高」は対比の響き）。（3）否定は「不＋形容詞」（不冷）、疑問は「吗」か「A不A」。"],"use":[{"ok":true,"zh":"这个苹果很好吃。","fix":"","py":"Zhège píngguǒ hěn hǎochī.","tr":["แอปเปิลลูกนี้อร่อยมาก (อร่อย)","This apple is delicious.","Quả táo này rất ngon.","このりんごはおいしいです。"],"h":["บอกเล่าทั่วไปใส่ 很 นำหน้าคุณศัพท์ (แม้ไม่ได้เน้น 'มาก')","Use 很 before adjectives in neutral statements (even without strong 'very')","肯定陈述句常加“很”保持句调自然","Thêm 很 trước tính từ để câu khẳng định tự nhiên","普通の肯定文では「とても」と強調しなくても「很」を添える"],"w":["ทำได้และเป็นวิธีพูดที่เป็นธรรมชาติที่สุดในภาษาจีน ในบริบทนี้ 很 ทำหน้าที่พยุงจังหวะประโยคให้สมบูรณ์ไม่ได้แปลว่า 'มากจัด' เสมอไป","Works naturally: here 很 acts as a grammatical cushion rather than strong 'very', keeping the statement complete.","此处的“很”主要起平衡语法结构的作用，并不一定强调程度极高。","Đúng vì 很 ở đây giúp câu cân đối tự nhiên chứ không nhất thiết nhấn mạnh 'rất'.","ここでの「很」は文を整える働きがあり、強い「とても」でなくても自然に使う。"],"ref":"กลุ่มเทียบคำ g14 · HSK 3.0 g3-1-043"},{"ok":true,"zh":"手机贵，书便宜。","fix":"","py":"Shǒujī guì, shū piányi.","tr":["โทรศัพท์แพง (แต่) หนังสือถูก","Phones are expensive, while books are cheap.","Điện thoại đắt, sách rẻ.","スマホは高く、本は安いです。"],"h":["วางคุณศัพท์เดี่ยว ๆ ได้เมื่อกำลัง 'เปรียบเทียบ' สองอย่างชัดเจน","Bare adjectives work naturally when explicitly contrasting two items","两项明显对比时可用光杆形容词","Dùng tính từ đứng lẻ được khi đang so sánh đối chiếu hai thứ","2つを対比するときは「很」なしの裸の形容詞が自然"],"w":["ทำได้เพราะประโยคนี้จงใจเทียบสองฝั่ง (手机贵 เทียบกับ 书便宜) การไม่ใส่ 很 จึงเน้นความต่างได้คมชัดมาก","Works because the sentence explicitly contrasts two sides (phones expensive vs books cheap), where bare adjectives shine.","句中“手机贵”和“书便宜”构成鲜明对比，用光杆形容词最地道。","Đúng vì câu đang đối chiếu rõ hai vế (điện thoại đắt — sách rẻ).","「スマホは高い／本は安い」という明確な対比があるため裸の形容詞がぴったり。"],"ref":"HSK 3.0 g3-1-043"},{"ok":false,"zh":"这个手机是贵。","fix":"这个手机很贵。","py":"Zhège shǒujī hěn guì.","tr":["โทรศัพท์เครื่องนี้แพง","This phone is expensive.","Chiếc điện thoại này rất đắt.","このスマホは高いです。"],"h":["ห้ามใส่ 是 หน้าคุณศัพท์","Never put 是 before an adjective","形容词谓语句不能加“是”","Không bao giờ đặt 是 trước tính từ","形容詞述語文に「是」は入れない"],"w":["ไม่ได้ เพราะคุณศัพท์จีนทำหน้าที่เป็นภาคแสดงเองได้โดยไม่ต้องพึ่ง 是 ให้เปลี่ยน เป็น 很贵 / 太贵了 / 非常贵","Wrong because Chinese adjectives don't take 是 — replace 是 with 很 (很贵) or 太…了 (太贵了).","不行，形容词作谓语不加“是”，应改为“这个手机很贵”。","Không được vì tính từ không đi với 是, hãy đổi thành 这个手机很贵.","形容詞述語文では「是」を使わず「很」などに換える（这个手机很贵）。"],"ref":"HSK 3.0 g3-1-043"},{"ok":false,"zh":"你很高吗？","fix":"你高吗？","py":"Nǐ gāo ma?","tr":["คุณสูงไหม","Are you tall?","Bạn có cao không?","あなたは背が高いですか。"],"h":["ประโยคคำถามธรรมดา (…吗？) ไม่ต้องใส่ 很","Neutral yes/no questions (…吗？) usually drop 很","普通是非问句通常不加“很”（你高吗？／今天冷吗？）","Câu hỏi 吗 thông thường không cần 很 (你高吗？)","普通の疑問文（…吗？）では普通「很」を入れない"],"w":["ไม่เป็นธรรมชาติถ้าถามแบบกลาง ๆ เพราะ 你很高吗？ จะแปลว่า 'คุณสูงมากเลยเหรอ?' (เหมือนสงสัยหรือประหลาดใจ) ถ้าถามธรรมดาว่า 'สูงไหม/หนาวไหม/แพงไหม' ให้ตัด 很 ออก: 你高吗？ / 今天冷吗？","Loaded/unnatural for a neutral question: 你很高吗？ asks 'Are you REALLY tall?'. For neutral questions, omit 很: 你高吗？ / 今天冷吗？","日常中性提问不加“很”（今天冷吗？贵吗？）；加“很”会变成反问或确认“真有那么高吗？”。","Không tự nhiên nếu hỏi bình thường (加 很 nghĩa là 'cao lắm hả?'). Hỏi trung tính bỏ 很: 你高吗？ / 今天冷吗？","中立的な質問なら「很」を省く（今天冷吗？）。「很」を入れると「そんなに高いの？」という確認になる。"],"ref":"HSK 3.0 g3-1-043"}],"ex":[["今天很热。","Jīntiān hěn rè.","วันนี้ร้อนมาก","It is very hot today.","Hôm nay rất nóng.","今日はとても暑いです。","很热"],["这个手机很贵。","Zhège shǒujī hěn guì.","โทรศัพท์เครื่องนี้แพงมาก","This phone is very expensive.","Chiếc điện thoại này rất đắt.","このスマホはとても高いです。","很贵"],["妈妈今天很忙。","Māma jīntiān hěn máng.","วันนี้แม่ยุ่งมาก","Mom is very busy today.","Hôm nay mẹ rất bận.","母は今日とても忙しいです。","很忙"],["这件衣服不便宜。","Zhè jiàn yīfu bù piányi.","เสื้อตัวนี้ไม่ถูกเลย","This piece of clothing is not cheap.","Chiếc áo này không rẻ.","この服は安くないです。","不便宜"],["今天冷吗？","Jīntiān lěng ma?","วันนี้หนาวไหม","Is it cold today?","Hôm nay có lạnh không?","今日は寒いですか。","冷"]],"err":[["这个手机是贵。","这个手机很贵。","ห้ามใส่ 是 หน้าคุณศัพท์ ใช้ 很 / 非常 แทน","Never use 是 before an adjective; use 很 / 非常.","形容词谓语前不加“是”，用“很”。","Không dùng 是 trước tính từ, dùng 很.","形容詞の前に「是」は使わず「很」を使う。"],["天气是冷。","天气很冷。","บรรยายอากาศใช้ 很冷 ไม่ใช่ 是冷","Describe weather with 很冷, not 是冷.","说“天气很冷”，不说“天气是冷”。","Miêu tả thời tiết dùng 很冷, không dùng 是冷.","天気は「是冷」ではなく「很冷」。"]],"rel":["g3-1-037","g3-1-015","g3-1-051"]},"g3-1-044":{"t":["ประโยคภาคแสดงคำนาม (主谓句3：名词谓语句)","Noun-predicate sentences (名词谓语句)","句型·主谓句3：名词谓语句","Câu vị ngữ danh từ (名词谓语句)","名詞述語文（名词谓语句）"],"f":["主语 + 名词性词语（时间 / 日期 / 天气 / 年龄 / 价格 / 籍贯）","否定：主语 + 不是 + 名词性词语"],"why":["名词谓语句 คือประโยคที่ใช้คำนามหรือวลีคำนามเป็นภาคแสดงโดยตรงไม่ต้องมีกริยา 是 มักใช้ใน 5 สถานการณ์หลัก: (1) วันและวันที่ (今天星期五, 明天五月八号) (2) เวลา (现在十点) (3) อายุ (我女儿六岁) (4) ราคา (一杯茶十块钱) (5) เชื้อชาติ/ภูมิลำเนาแบบสั้น (他北京人) · ข้อควรระวัง: (1) เมื่อต้องการปฏิเสธต้องใส่ 不是 เสมอ (现在不是十点) (2) ถ้าไม่ได้อยู่ใน 5 หมวดนี้ (เช่น บอกชื่อ อาชีพ หรือนิยามของสิ่งของ) ต้องใช้ประโยค 是 เสมอ (这是书, 他是老师)","A noun-predicate sentence (名词谓语句) uses a noun or noun phrase directly as predicate with NO 是, mainly for 5 categories: (1) days/dates (今天星期五), (2) clock time (现在十点), (3) age (我女儿六岁), (4) prices (一杯茶十块钱), (5) hometown (他北京人). · Cautions: (1) Always add 不是 to negate (现在不是十点). (2) Outside these categories (e.g., professions/definitions), you MUST use 是 (这是书, 他是老师).","名词谓语句直接用名词性词语作谓语，不加“是”，主要用于五类场合：日期星期、钟点时间、年龄、价格、籍贯（今天星期五、现在十点、女儿六岁、一杯茶十块钱、他北京人）。 · 注意：（1）否定必须加“不是”；（2）介绍身份、定义事物仍须用“是”字句（这是书、他是老师）。","Câu vị ngữ danh từ dùng thẳng danh từ/cụm danh từ làm vị ngữ không cần 是, chủ yếu trong 5 nhóm: ngày/thứ, giờ, tuổi, giá tiền, quê quán. · Lưu ý: (1) Phủ định luôn thêm 不是; (2) Giới thiệu nghề nghiệp/định nghĩa vật vẫn bắt buộc dùng 是 (这是书, 他是老师).","名詞述語文は「是」なしで名詞・名詞句をそのまま述語にする文。主に日時・時刻・年齢・価格・出身地の5分野で使う（今天星期五・现在十点・女儿六岁・一杯茶十块钱・他北京人）。 · 注意：（1）否定は必ず「不是」を補う。（2）職業や物の定義には「是」が必要（这是书・他是老师）。"],"use":[{"ok":true,"zh":"他北京人。","fix":"","py":"Tā Běijīng rén.","tr":["เขาเป็นคนปักกิ่ง","He is from Beijing.","Anh ấy là người Bắc Kinh.","彼は北京出身です。"],"h":["บอกภูมิลำเนา/บ้านเกิดแบบภาษาพูด ละ 是 ได้","In casual speech, hometown/origin can drop 是 (他北京人)","口语说籍贯可构成名词谓语句（他北京人）","Khẩu ngữ nói quê quán có thể bỏ 是 (他北京人)","口語で出身地を言うとき「是」を省ける（他北京人）"],"w":["ทำได้ในภาษาพูดที่เป็นกันเอง (或 他是北京人 ก็ถูกต้องทั้งคู่) แต่ถ้าปฏิเสธต้องพูดว่า 他不是北京人 เสมอ","Works naturally in casual conversation (他是北京人 is also correct); negation always requires 不是 (他不是北京人).","口语中“他北京人”自然简洁（正式场合说“他是北京人”），否定一律用“不是”。","Đúng và gọn trong giao tiếp hằng ngày (nói 他是北京人 cũng đúng); phủ định luôn dùng 不是.","会話では「他北京人」と簡潔に言える（正式には「他是北京人」、否定は「他不是北京人」）。"],"ref":"HSK 3.0 g3-1-044"},{"ok":true,"zh":"现在不是十点，是九点半。","fix":"","py":"Xiànzài bù shì shí diǎn, shì jiǔ diǎn bàn.","tr":["ตอนนี้ไม่ใช่สิบโมง เป็นเก้าโมงครึ่ง","It's not ten o'clock now; it's nine-thirty.","Bây giờ không phải 10 giờ, là 9 giờ rưỡi.","今10時ではなく、9時半です。"],"h":["ปฏิเสธหรือแก้ข้อมูลผิดในประโยคคำนาม ต้องใช้ 不是…是…","To negate or correct a noun predicate, restore 不是…是…","否定或纠正时必须补出“不是……是……”","Phủ định hoặc đính chính phải dùng 不是…是…","否定や訂正では必ず「不是…是…」を補う"],"w":["ทำได้เพราะเมื่อปฏิเสธเวลา/วัน/ราคา ต้องเติม 不是 กลับมาทุกครั้ง และประโยคหลังมักใส่ 是 ช่วยย้ำความถูกต้องด้วย","Works because negating time/date/price always requires 不是, and the follow-up correction naturally pairs with 是.","否定钟点、日期或价格时须用“不是”，后半句纠正时常呼应“是”。","Đúng vì phủ định giờ/ngày/giá bắt buộc có 不是 và vế đính chính đi với 是.","時刻や日付の否定は「不是」が必須で、後ろの訂正も「是」で呼応させる。"],"ref":"HSK 3.0 g3-1-044"},{"ok":false,"zh":"这书。","fix":"这是书。","py":"Zhè shì shū.","tr":["นี่คือหนังสือ","This is a book.","Đây là sách.","これは本です。"],"h":["นิยามสิ่งของ/แนะนำคน (这是… / 他是…) ห้ามตัด 是 ทิ้ง","Never drop 是 when identifying objects or people (这是… / 他是…)","指认事物或介绍身份必须用“是”（这是书）","Chỉ vật hoặc giới thiệu người bắt buộc có 是 (这是书)","物の指し示しや身分紹介では「是」を省けない（这是书）"],"w":["ไม่ได้ เพราะ 这书 ไม่ใช่ประโยคสมบูรณ์ (ฟังเหมือนวลีที่ลืมลักษณนามว่า 这本书) ถ้าจะบอกว่า 'นี่คือหนังสือ' ต้องใส่ 是 เสมอ: 这是书","Wrong because 这书 is not a complete sentence; identifying objects or people always requires 是 (这是书).","不行，“这书”不能成句，介绍事物或身份必须用“是”字句：这是书。","Không được vì 这书 không thành câu; chỉ vật bắt buộc có 是: 这是书.","「这书」では文にならない。物の定義は必ず「这是书」と「是」を入れる。"],"ref":"HSK 3.0 g3-1-044 · g3-1-052"}],"ex":[["今天星期五。","Jīntiān xīngqīwǔ.","วันนี้วันศุกร์","Today is Friday.","Hôm nay là thứ Sáu.","今日は金曜日です。","星期五"],["现在九点。","Xiànzài jiǔ diǎn.","ตอนนี้เก้าโมง","It is nine o'clock now.","Bây giờ là 9 giờ.","今9時です。","九点"],["我女儿六岁。","Wǒ nǚ'ér liù suì.","ลูกสาวฉันหกขวบ","My daughter is six years old.","Con gái tôi sáu tuổi.","娘は6歳です。","六岁"],["一杯茶十块钱。","Yī bēi chá shí kuài qián.","ชาหนึ่งแก้วสิบหยวน","A cup of tea is ten yuan.","Một cốc trà mười tệ.","お茶1杯10元です。","十块钱"],["今天不是星期五。","Jīntiān bù shì xīngqīwǔ.","วันนี้ไม่ใช่วันศุกร์","Today is not Friday.","Hôm nay không phải thứ Sáu.","今日は金曜日ではありません。","不是"]],"err":[["这书。","这是书。","แนะนำหรือนิยามสิ่งของ/บุคคลต้องมี 是 เสมอ","Identifying people or objects always requires 是.","介绍事物或人物必须用“是”。","Giới thiệu người/vật bắt buộc phải có 是.","人や物の紹介には必ず「是」が必要。"],["现在不十点。","现在不是十点。","ปฏิเสธประโยคภาคแสดงคำนามต้องใช้ 不是 เสมอ","Negating a noun predicate always requires 不是.","否定名词谓语句必须加“不是”。","Phủ định vị ngữ danh từ luôn phải dùng 不是.","名詞述語文の否定は必ず「不是」。"]],"rel":["g3-1-036","g3-1-052","g3-1-070"]},"g3-1-045":{"t":["ประโยคไม่มีประธาน (非主谓句): 下雨了！/ 请坐！/ 谢谢！","Non-subject-predicate sentences (非主谓句)","句型·单句：非主谓句","Câu không chủ vị (非主谓句)","非主述文（非主谓句）"],"f":["自然现象：下雨了！","礼貌与招呼：请坐！/ 谢谢！/ 对不起！/ 再见！/ 喂！","简短应答：好！/ 对！/ 可以！"],"why":["非主谓句 คือประโยคที่สมบูรณ์ได้ด้วยตัวเองโดยไม่ต้องแบ่งเป็น 'ประธาน + ภาคแสดง' (และไม่ได้เกิดจากการละประธานที่เคยเอ่ยไว้) · พบ 3 กลุ่มหลักในชีวิตประจำวัน: (1) ปรากฏการณ์ธรรมชาติ เช่น 下雨了！(ฝนตกแล้ว!) — ภาษาจีนไม่ใส่ประธานปลอมอย่าง 'It' ในภาษาอังกฤษ (2) คำเชิญ/มารยาท/ทักทาย เช่น 请坐！(เชิญนั่ง), 谢谢！(ขอบคุณ), 对不起！(ขอโทษ), 没关系！(ไม่เป็นไร) (3) คำอุทานหรือคำตอบสั้น เช่น 好！(ตกลง!), 喂！(ฮัลโหล!) · ข้อควรระวัง: อย่าแปล 'It is raining' แบบอังกฤษแล้วใส่ 它 下雨了 (ผิดเด็ดขาด!)","A non-subject-predicate sentence (非主谓句) is complete without a subject+predicate split. · Three everyday types: (1) natural phenomena like 下雨了! ('It's raining!') — Chinese NEVER uses a dummy subject like English 'it'; (2) greetings/courtesies/invitations like 请坐!, 谢谢!, 对不起!, 没关系!; (3) short exclamations/replies like 好!, 喂!. · Caution: NEVER translate English 'It's raining' as 它下雨了!","非主谓句是不必分成主语和谓语就能独立成句的句子。 · 常见三类：（1）自然现象（下雨了！——绝不加英语式形式主语“它”）；（2）礼貌交际语（请坐！谢谢！对不起！没关系！）；（3）感叹或简短应答（好！喂！）。","Câu không chủ vị (非主谓句) tự hoàn chỉnh mà không tách chủ–vị: (1) hiện tượng tự nhiên (下雨了! — KHÔNG thêm chủ ngữ giả 它 như 'It'); (2) chào hỏi/lịch sự (请坐!, 谢谢!, 对不起!, 没关系!); (3) thán từ/đáp ngắn (好!, 喂!).","非主谓句は主語と述語に分けず単独で完結する文。 · （1）自然現象（下雨了！— 英語の仮主語 It に当たる「它」は絶対に入れない）、（2）挨拶・丁寧表現（请坐！谢谢！对不起！）、（3）感嘆・短い返答（好！喂！）。"],"use":[{"ok":true,"zh":"下雨了！","fix":"","py":"Xià yǔ le!","tr":["ฝนตกแล้ว!","It's raining!","Trời mưa rồi!","雨が降ってきました！"],"h":["บอกสภาพธรรมชาติเริ่มเกิด ใช้ กริยา + กรรม + 了 ได้เลยโดยไม่มีประธาน","Describe weather directly with Verb + Object + 了 (no subject)","自然现象直接说“下雨了！”，不加形式主语","Hiện tượng tự nhiên nói thẳng 下雨了, không cần chủ ngữ","自然現象は主語なしで「下雨了！」と言う"],"w":["ทำได้และถูกต้อง 100% (ถ้าอยากระบุสถานที่/เวลาก็วางไว้หน้าได้ เช่น 外边下雨了 = ข้างนอกฝนตกแล้ว)","Works 100% naturally; you may optionally add a time or place upfront (外边下雨了 'It's raining outside').","“下雨了！”是典型的动词性非主谓句，也可在前面加时间或地点（外边下雨了）。","Đúng 100% và tự nhiên (có thể thêm nơi chốn phía trước: 外边下雨了).","典型的な動詞性の非主述文。場所や時間を前に添えることもできる（外边下雨了）。"],"ref":"HSK 3.0 g3-1-045"},{"ok":true,"zh":"请坐，请喝茶！","fix":"","py":"Qǐng zuò, qǐng hē chá!","tr":["เชิญนั่ง เชิญดื่มชาครับ/ค่ะ!","Please sit down, please have some tea!","Mời ngồi, mời uống trà!","どうぞお掛けください、お茶をどうぞ！"],"h":["คำเชิญสุภาพขึ้นต้นด้วย 请 + กริยา ไม่ต้องใส่ 你","Polite invitations start straight with 请 + verb (no 你 needed)","礼貌邀请用“请＋动词”，不必加主语","Lời mời lịch sự bắt đầu thẳng bằng 请 + động từ","丁寧な勧めは主語なしで「请＋動詞」"],"w":["ทำได้และสุภาพมาก เป็นประโยคเชิญชวนแบบ非主谓句ที่ใช้บ่อยที่สุดเวลาต้อนรับแขก","Works warmly and politely as the standard way to welcome guests without repeating 你.","迎客常用礼貌非主谓句，自然得体。","Đúng và rất lịch sự khi đón tiếp khách.","来客を迎える定番の丁寧な非主述文。"],"ref":"HSK 3.0 g3-1-045 · g3-1-050"},{"ok":false,"zh":"它下雨了！","fix":"下雨了！","py":"Xià yǔ le!","tr":["ฝนตกแล้ว!","It's raining!","Trời mưa rồi!","雨が降ってきました！"],"h":["ห้ามใส่ 它 เป็นประธานปลอมแบบ 'It' ในภาษาอังกฤษ","Never put dummy subject 它 ('it') before 下雨了","绝不能受英语影响说“它下雨了”","Tuyệt đối không thêm chủ ngữ giả 它 trước 下雨了","英語の It のように「它」を付けてはいけない"],"w":["ไม่ได้ เพราะภาษาจีนไม่มีประธานปลอม (dummy subject) สำหรับสภาพอากาศ พูดแค่ 下雨了 หรือ 天下雨了 เท่านั้น ห้ามใช้ 它","Wrong because Chinese has no dummy pronoun 'it' for weather — say 下雨了 (or 外边下雨了), NEVER 它下雨了.","不行，汉语没有英语那样的形式主语“it”，表示下雨绝不能加“它”。","Không được vì tiếng Trung không có chủ ngữ giả như 'it' trong tiếng Anh; chỉ nói 下雨了.","中国語には天候の仮主語がないため、「它下雨了」は典型的な誤用。"],"ref":"HSK 3.0 g3-1-045"}],"ex":[["下雨了！","Xià yǔ le!","ฝนตกแล้ว!","It's raining!","Trời mưa rồi!","雨が降ってきました！","下雨了"],["请坐！","Qǐng zuò!","เชิญนั่งครับ/ค่ะ!","Please have a seat!","Mời ngồi!","どうぞお掛けください！","请坐"],["谢谢！","Xièxie!","ขอบคุณครับ/ค่ะ!","Thank you!","Cảm ơn!","ありがとうございます！","谢谢"],["对不起！","Duìbuqǐ!","ขอโทษครับ/ค่ะ!","I'm sorry!","Xin lỗi!","すみません！","对不起"],["没关系！","Méi guānxi!","ไม่เป็นไรครับ/ค่ะ!","It's okay / No problem!","Không sao đâu!","大丈夫ですよ！","没关系"]],"err":[["它下雨了！","下雨了！","ภาษาจีนไม่ใช้ 它 เป็นประธานปลอมของสภาพอากาศ","Never use dummy 它 ('it') for weather.","表示自然现象不加形式主语“它”。","Không thêm chủ ngữ giả 它 cho thời tiết.","天候表現に仮主語「它」は入れない。"]],"rel":["g3-1-027","g3-1-050","g3-1-063"]},"g3-1-046":{"t":["ประโยคบอกเล่า (陈述句): บอกเล่าและปฏิเสธ","Declarative sentences (陈述句): affirmative & negative","句类：陈述句","Câu trần thuật (陈述句): khẳng định & phủ định","平叙文（陈述句）：肯定文と否定文"],"f":["肯定：主语 + 谓语。（我是学生。/ 今天很冷。）","否定：主语 + 不 / 没（有）+ 谓语。（我不是老师。/ 我没有猫。）"],"why":["陈述句 คือประโยคบอกเล่าข้อเท็จจริงหรือความคิดเห็น (มีทั้งรูปบอกเล่าและรูปปฏิเสธ) ลงท้ายด้วยเครื่องหมายมหัพภาคจีน 。 (句号) และออกเสียงลดระดับลงท้ายประโยค · โครงสร้างหลักใน HSK 1 คือ ประธาน + (เวลา/สถานที่) + ภาคแสดง · ข้อควรระวังสำคัญ: (1) อย่าลืมใช้เครื่องหมาย 。 (วงกลมโปร่ง) แทนจุดทึบในงานเขียนจีน และไม่ใส่ 吗 ในประโยคบอกเล่า (2) รูปปฏิเสธของ 有 ต้องใช้ 没有 เท่านั้น ห้ามใช้ 不有","A declarative sentence (陈述句) states a fact or opinion — either affirmative or negative — ending with the Chinese period 。 (句号). · Core structure: Subject + (Time/Place) + Predicate. · Key cautions: (1) Never add 吗 to a declarative statement. (2) Always negate 有 with 没(有), NEVER 不有.","陈述句用来叙述事实或发表看法，包括肯定和否定两类，句末用句号“。”，语调平缓略降。 · 注意：（1）陈述句句末绝不加疑问词“吗”；（2）“有”的否定只能用“没有”，不能说“不有”。","Câu trần thuật (陈述句) kể sự thật hoặc nêu ý kiến (gồm khẳng định và phủ định), kết thúc bằng dấu chấm tròn 。. · Lưu ý: (1) Không thêm 吗 vào câu trần thuật; (2) Phủ định của 有 luôn là 没有 (không nói 不有).","平叙文（陈述句）は事実や意見を述べる文（肯定・否定を含み文末は「。」）。 · 注意：（1）平叙文に疑問助詞「吗」は付けない。（2）「有」の否定は必ず「没有」（「不有」は不可）。"],"use":[{"ok":true,"zh":"我是学生，我喜欢学习汉语。","fix":"","py":"Wǒ shì xuésheng, wǒ xǐhuan xuéxí Hànyǔ.","tr":["ฉันเป็นนักเรียน ฉันชอบเรียนภาษาจีน","I am a student; I like studying Chinese.","Tôi là học sinh, tôi thích học tiếng Trung.","私は学生で、中国語の勉強が好きです。"],"h":["ประโยคบอกเล่าข้อเท็จจริง จบด้วยเครื่องหมาย 。","State facts clearly and end with Chinese period 。","客观陈述事实，句末用句号“。”","Trình bày sự thật rõ ràng, kết thúc bằng dấu 。","事実を述べ文末は「。」で結ぶ"],"w":["ทำได้เพราะเป็นการให้ข้อมูลตรงไปตรงมา ใช้ลำดับประธาน-กริยา-กรรมครบถ้วน ไม่มีคำถามหรือคำอุทานปน","Works cleanly as a straightforward factual statement in Subject-Verb-Object order.","结构完整、语气平和，是最标准的陈述句。","Đúng vì trình bày thông tin trực tiếp theo trật tự chuẩn.","主語・動詞・目的語が整った標準的な平叙文。"],"ref":"HSK 3.0 g3-1-046"},{"ok":true,"zh":"我没有猫，我有一只狗。","fix":"","py":"Wǒ méiyǒu māo, wǒ yǒu yī zhī gǒu.","tr":["ฉันไม่มีแมว ฉันมีหมาหนึ่งตัว","I don't have a cat; I have a dog.","Tôi không có mèo, tôi có một con chó.","猫は飼っていません、犬が一匹います。"],"h":["ประโยคปฏิเสธก็เป็น 陈述句 (ปฏิเสธ 有 ใช้ 没有)","Negative statements are also declaratives (negate 有 with 没有)","否定陈述也是陈述句，“有”的否定用“没有”","Câu phủ định cũng là câu trần thuật (phủ định 有 dùng 没有)","否定文も平叙文（「有」の否定は「没有」）"],"w":["ทำได้เพราะปฏิเสธการครอบครองด้วย 没有 (ไม่ใช้ 不有) แล้วบอกข้อเท็จจริงอีกด้านด้วย 有","Works because possession is negated with 没有 (never 不有) and contrasted with affirmative 有.","否定领有用“没有”，与后半句肯定陈述自然对照。","Đúng vì phủ định sở hữu dùng 没有 rồi đối chiếu với câu khẳng định 有.","所有の否定は「没有」を使い、後半の肯定文と対比させている。"],"ref":"กลุ่มเทียบคำ g6 · HSK 3.0 g3-1-053"},{"ok":false,"zh":"我不有猫。","fix":"我没有猫。","py":"Wǒ méiyǒu māo.","tr":["ฉันไม่มีแมว","I don't have a cat.","Tôi không có mèo.","猫は飼っていません。"],"h":["ห้ามปฏิเสธ 有 ด้วย 不 (不有 ผิดเสมอ!)","NEVER negate 有 with 不 (不有 is always wrong!)","“有”绝不能用“不”否定（不说“不有”）","Tuyệt đối không nói 不有 (phải dùng 没有)","「有」は絶対に「不有」にしない（必ず「没有」）"],"w":["ไม่ได้ เพราะในภาษาจีนกริยา 有 มีกฎเหล็กเด็ดขาดว่าปฏิเสธได้ด้วย 没 เท่านั้น (没有 / 没) ไม่มีคำว่า 不有 ในภาษาจีน","Wrong because Chinese 有 has an absolute rule: its ONLY negation is 没(有); 不有 does not exist.","不行，“有”的唯一否定形式是“没有”（简称“没”），汉语里没有“不有”。","Không được vì 有 chỉ có một dạng phủ định duy nhất là 没有.","「有」の否定は「没有」のみ。「不有」という形は中国語に存在しない。"],"ref":"กลุ่มเทียบคำ g6 · HSK 3.0 g3-1-020"}],"ex":[["我是中国人。","Wǒ shì Zhōngguórén.","ฉันเป็นคนจีน","I am Chinese.","Tôi là người Trung Quốc.","私は中国人です。","是"],["我今天去医院。","Wǒ jīntiān qù yīyuàn.","วันนี้ฉันไปโรงพยาบาล","I'm going to the hospital today.","Hôm nay tôi đi bệnh viện.","今日病院へ行きます。","去"],["他不喝牛奶。","Tā bù hē niúnǎi.","เขาไม่ดื่มนม","He doesn't drink milk.","Anh ấy không uống sữa.","彼は牛乳を飲みません。","不"],["我没有电脑。","Wǒ méiyǒu diànnǎo.","ฉันไม่มีคอมพิวเตอร์","I don't have a computer.","Tôi không có máy tính.","パソコンを持っていません。","没有"],["今天天气很好。","Jīntiān tiānqì hěn hǎo.","วันนี้อากาศดีมาก","The weather is very nice today.","Hôm nay thời tiết rất đẹp.","今日は天気がとても良いです。","很好"]],"err":[["我不有电脑。","我没有电脑。","ปฏิเสธ 有 ใช้ 没有 เท่านั้น ห้ามใช้ 不有","Always negate 有 with 没有, never 不有.","“有”的否定只能用“没有”。","Phủ định của 有 luôn là 没有.","「有」の否定は必ず「没有」。"]],"rel":["g3-1-020","g3-1-042","g3-1-047"]},"g3-1-047":{"t":["ประโยคคำถามใช่/ไม่ใช่ (是非问句): …吗？","Yes-no questions (是非问句): …吗？","句类·疑问句（1）：是非问句","Câu hỏi Đúng/Sai (是非问句): …吗？","諾否疑問文（是非问句）：…吗？"],"f":["陈述句 + 吗？（你是学生吗？/ 今天冷吗？/ 你吃饭了吗？）"],"why":["是非问句 คือคำถามที่ต้องการคำตอบ 'ใช่ / ไม่ใช่' ทำง่ายที่สุดในภาษาจีน: แค่เอาประโยคบอกเล่าเต็ม ๆ มาเติม 吗 ไว้ท้ายประโยค โดยไม่ต้องสลับตำแหน่งประธาน-กริยาเลย! (ต่างจากภาษาอังกฤษ Are you… / Do you…) · ข้อควรระวังเด็ดขาด 2 ข้อ: (1) ห้ามเติม 吗 ในประโยคที่มีคำแสดงคำถามอยู่แล้ว (什么, 谁, 哪儿, 几, 多少, 怎么 — เช่น 你去哪儿吗？ ผิด!) (2) ห้ามเติม 吗 ในประโยคคำถามแบบซ้ำกริยา A不A (你是学生不是吗？ / 你去不去吗？ ผิด!)","Yes-no questions (是非问句) are the easiest question form in Chinese: simply append 吗 to ANY statement with ZERO word-order inversion! · Two strict rules: (1) NEVER add 吗 when the sentence already has a question word (什么, 谁, 哪儿, 几, 多少, 怎么 — never 你去哪儿吗？). (2) NEVER combine 吗 with A-not-A questions (never 你去不去吗？).","是非问句只需在陈述句末尾加“吗”，完全不必倒装语序（你是学生吗？今天冷吗？）。 · 两条铁律：（1）句中已有疑问代词（什么、谁、哪儿、几等）时绝不能再加“吗”；（2）正反问句（去不去、是不是）末尾绝不能加“吗”。","Câu hỏi Có/Không (是非问句) chỉ cần thêm 吗 vào cuối câu trần thuật, KHÔNG đảo ngữ! · 2 quy tắc cứng: (1) Không thêm 吗 khi câu đã có từ để hỏi (什么, 谁, 哪儿, 几…); (2) Không thêm 吗 vào câu hỏi chính phản (去不去).","諾否疑問文（是非问句）は平叙文の末尾に「吗」を付けるだけで語順を変えない。 · 鉄則2つ：（1）疑問詞（什么・誰・哪儿・几など）がある文には「吗」を付けない。（2）反復疑問文（去不去など）にも「吗」は付けない。"],"use":[{"ok":true,"zh":"你是学生吗？","fix":"","py":"Nǐ shì xuésheng ma?","tr":["คุณเป็นนักเรียนหรือเปล่า","Are you a student?","Bạn có phải học sinh không?","あなたは学生ですか。"],"h":["เติม 吗 ท้ายประโยคบอกเล่าได้เลย ไม่ต้องสลับคำ","Add 吗 directly at the end of a statement without changing word order","陈述句直接加“吗”，语序不变","Thêm thẳng 吗 vào cuối câu trần thuật, giữ nguyên trật tự","平叙文の末尾に「吗」を付けるだけ（語順はそのまま）"],"w":["ทำได้เพราะจากบอกเล่า 你是学生 แค่ใส่ 吗 + ？ ท้ายประโยคก็กลายเป็นคำถามสมบูรณ์ ตอบรับว่า 是 หรือปฏิเสธว่า 不是 ได้เลย","Works because 你是学生 + 吗 immediately forms a complete yes-no question (answer: 是 / 不是).","陈述句“你是学生”末尾加“吗”即可成问句，回答用“是／不是”。","Đúng vì chỉ cần thêm 吗 sau 你是学生 là thành câu hỏi hoàn chỉnh.","平叙文「你是学生」に「吗」を足すだけで疑問文が完成する。"],"ref":"กลุ่มเทียบคำ g13 · HSK 3.0 g3-1-047"},{"ok":true,"zh":"你吃饭了吗？","fix":"","py":"Nǐ chīfàn le ma?","tr":["คุณกินข้าวแล้วหรือยัง","Have you eaten yet?","Bạn ăn cơm chưa?","もうご飯を食べましたか。"],"h":["ถามว่าทำอะไรเสร็จแล้วหรือยัง ใช้ …了吗？","Ask 'have you done…yet?' with …了吗？","询问动作是否完成用“……了吗？”","Hỏi đã làm chưa dùng …了吗？","「もう〜しましたか」は「…了吗？」"],"w":["ทำได้เพราะ 了 บอกการเสร็จสิ้น และ 吗 เปลี่ยนเป็นคำถาม (ตอบว่า 吃了 = กินแล้ว หรือ 还没吃 = ยังไม่ได้กิน)","Works cleanly with 了 + 吗 (answer: 吃了 'yes, I ate' or 还没吃 'not yet').","“了”加“吗”询问是否已完成，肯定答“吃了”，否定答“还没吃”。","Đúng vì 了 + 吗 hỏi đã hoàn thành chưa (đáp: 吃了 / 还没吃).","「了＋吗」で完了を尋ねる（返答は「吃了」または「还没吃」）。"],"ref":"HSK 3.0 g3-1-047 · g3-1-026"},{"ok":false,"zh":"你去哪儿吗？","fix":"你去哪儿？","py":"Nǐ qù nǎr?","tr":["คุณจะไปไหน","Where are you going?","Bạn đi đâu vậy?","どこへ行きますか。"],"h":["ห้ามใส่ 吗 ในประโยคที่มีคำถาม (哪儿 / 什么 / 谁 / 几) อยู่แล้ว","NEVER add 吗 when a question word (哪儿/什么/谁/几) is already present","已有疑问代词的句子绝不能再加“吗”","Không thêm 吗 khi câu đã có từ để hỏi (哪儿/什么/谁/几)","疑問詞（哪儿・什么・谁・几）がある文に「吗」は付けない"],"w":["ไม่ได้ เพราะ 哪儿 (ที่ไหน) ทำให้ประโยคเป็นคำถามเจาะจงอยู่แล้ว การใส่ 吗 ซ้ำจะชนกันระหว่างคำถาม 2 ชนิด ต้องตัด 吗 ทิ้ง","Wrong because 哪儿 ('where') already makes it a wh-question; adding 吗 clashes with it — drop 吗.","不行，“哪儿”本身已构成特指问，不能再加是非问词“吗”。","Không được vì 哪儿 đã là từ để hỏi rồi, thêm 吗 là sai ngữ pháp.","「哪儿」自体が疑問詞なので「吗」を重ねてはいけない。"],"ref":"กลุ่มเทียบคำ g13 · HSK 3.0 g3-1-048"},{"ok":false,"zh":"你去不去吗？","fix":"你去不去？","py":"Nǐ qù bù qù?","tr":["คุณไปไหม","Are you going or not?","Bạn có đi không?","行きますか、行きませんか。"],"h":["ห้ามใส่ 吗 ท้ายคำถามแบบ A不A (去不去 / 是不是)","NEVER put 吗 at the end of an A-not-A question","正反问句末尾绝不能加“吗”","Không thêm 吗 vào cuối câu hỏi chính phản A不A","反復疑問文（A不A）の文末に「吗」は付けない"],"w":["ไม่ได้ เพราะโครงสร้าง 去不去 (ไปหรือไม่ไป) เป็นคำถามสมบูรณ์ในตัวอยู่แล้ว ใส่ 吗 ท้ายประโยคซ้ำไม่ได้ (ต้องเลือกอย่างใดอย่างหนึ่ง: 你去吗？ หรือ 你去不去？)","Wrong because 去不去 is already a complete question; choose either 你去吗？ OR 你去不去？, never both.","不行，是非问“吗”和正反问“去不去”二选一，绝不能混用。","Không được vì 去不去 đã là câu hỏi rồi; chỉ chọn 你去吗？ hoặc 你去不去？.","「吗」と反復疑問文「去不去」はどちらか一方のみを使い、併用できない。"],"ref":"HSK 3.0 g3-1-047 · g3-1-049"}],"ex":[["你是学生吗？","Nǐ shì xuésheng ma?","คุณเป็นนักเรียนหรือเปล่า","Are you a student?","Bạn có phải học sinh không?","あなたは学生ですか。","吗"],["你喜欢喝茶吗？","Nǐ xǐhuan hē chá ma?","คุณชอบดื่มชาไหม","Do you like drinking tea?","Bạn có thích uống trà không?","お茶を飲むのが好きですか。","吗"],["今天冷吗？","Jīntiān lěng ma?","วันนี้หนาวไหม","Is it cold today?","Hôm nay có lạnh không?","今日は寒いですか。","吗"],["你吃饭了吗？","Nǐ chīfàn le ma?","คุณกินข้าวแล้วหรือยัง","Have you eaten?","Bạn ăn cơm chưa?","もうご飯を食べましたか。","吗"],["王老师在吗？","Wáng lǎoshī zài ma?","อาจารย์หวังอยู่ไหมครับ/คะ","Is Teacher Wang in?","Thầy Vương có ở đây không?","王先生はいらっしゃいますか。","吗"]],"err":[["你去哪儿吗？","你去哪儿？","มีคำถาม 哪儿 อยู่แล้ว ห้ามใส่ 吗 ซ้ำ","Never add 吗 when 哪儿 is already in the sentence.","已有疑问词“哪儿”，不能加“吗”。","Đã có 哪儿 thì không thêm 吗.","疑問詞「哪儿」があるので「吗」は不要。"],["你去不去吗？","你去不去？","มีคำถามแบบ A不A (去不去) แล้ว ห้ามเติม 吗","Never add 吗 to an A-not-A question.","正反问句不能再加“吗”。","Câu hỏi chính phản không thêm 吗.","反復疑問文に「吗」は付けない。"]],"rel":["g3-1-026","g3-1-048","g3-1-049"]},"g3-1-048":{"t":["ประโยคคำถามเจาะจง (特指问句): 谁 / 什么 / 哪儿 / 几 / 多少 / 怎么","Wh-questions (特指问句): 谁 / 什么 / 哪儿 / 几 / 多少 / 怎么","句类·疑问句（2）：特指问句","Câu hỏi có từ để hỏi (特指问句)","疑問詞疑問文（特指问句）"],"f":["把陈述句中要问的部分换成疑问代词（语序不变，不加“吗”）","例如：他是谁？/ 你叫什么名字？/ 你去哪儿？/ 苹果多少钱？"],"why":["特指问句 คือคำถามที่ต้องการคำตอบเป็นข้อมูลเฉพาะเจาะจง (ใคร, อะไร, ที่ไหน, กี่, เท่าไร, อย่างไร) · กฎทองที่ทำให้ภาษาจีนง่ายกว่าภาษาอังกฤษมาก: ไม่ต้องย้ายคำถามไปต้นประโยค! แค่วางคำถาม (谁, 什么, 哪儿, 几, 多少) ไว้ในตำแหน่งเดียวกับคำตอบในประโยคบอกเล่าเป๊ะเลย (เช่น 我去学校 → 你去哪儿？, 这是苹果 → 这是什么？) · ข้อควรระวัง: (1) ห้ามเติม 吗 ท้ายประโยคเด็ดขาด (2) หลัง 几 ต้องมีลักษณนามเสมอ (几本书, 几个人) แต่ 多少 ละลักษณนามได้ (多少钱)","Wh-questions (特指问句) ask for specific information using 谁, 什么, 哪儿, 几, 多少, or 怎么. · Golden rule (much easier than English!): NEVER front the question word! Put it in the EXACT slot where the answer goes (我去学校 → 你去哪儿？; 这是苹果 → 这是什么？). · Cautions: (1) NEVER add 吗 at the end. (2) 几 requires a measure word (几本书), while 多少 can omit it (多少钱).","特指问句用“谁、什么、哪儿、几、多少、怎么”等疑问代词对特定信息提问。 · 黄金规律：语序与陈述句完全相同，答案在哪儿，疑问词就放哪儿（我去学校→你去哪儿？）。 · 注意：（1）句末绝不能加“吗”；（2）“几”后须加量词（几本书），“多少”常可省量词（多少钱）。","Câu hỏi đặc chỉ (特指问句) dùng 谁, 什么, 哪儿, 几, 多少, 怎么 hỏi thông tin cụ thể. · Quy tắc vàng: GIỮ NGUYÊN trật tự câu trần thuật — đáp án nằm ở đâu thì từ để hỏi đặt ở đó (我去学校 → 你去哪儿？). · Lưu ý: KHÔNG thêm 吗; sau 几 cần lượng từ (几本书).","疑問詞疑問文（特指问句）は「誰・什么・哪儿・几・多少・怎么」で具体情報を尋ねる。 · 鉄則：語順を変えず、答えが入る位置にそのまま疑問詞を置く（我去学校→你去哪儿？）。 · 注意：文末に「吗」は絶対に付けない。「几」の後には量詞が必要（几本书）。"],"use":[{"ok":true,"zh":"你在哪儿工作？","fix":"","py":"Nǐ zài nǎr gōngzuò?","tr":["คุณทำงานที่ไหน","Where do you work?","Bạn làm việc ở đâu?","どこで働いていますか。"],"h":["วาง 哪儿 ตรงช่องสถานที่หน้ากริยาเหมือนประโยคบอกเล่าเป๊ะ","Put 哪儿 in the exact place slot before the verb just like a statement","答案在动词前（在医院工作），疑问词“在哪儿”也在动词前","Đặt 哪儿 đúng vị trí địa điểm trước động từ như câu trần thuật","答え（在医院工作）と同じ位置、動詞の前に「在哪儿」を置く"],"w":["ทำได้เพราะคำตอบคือ 我在医院工作 (สถานที่อยู่หน้ากริยา 工作) คำถามจึงแค่เปลี่ยน 医院 เป็น 哪儿 ตรงจุดเดิม: 你在哪儿工作？","Works because the answer is 我在医院工作 (place before verb), so swap 医院 → 哪儿 right in place: 你在哪儿工作？","陈述句是“我在医院工作”，只需把“医院”换成“哪儿”，保持语序不变。","Đúng vì câu trả lời là 我在医院工作, chỉ cần thay 医院 bằng 哪儿 tại đúng vị trí đó.","平叙文「我在医院工作」の「医院」をそのまま「哪儿」に置き換えた自然な語順。"],"ref":"HSK 3.0 g3-1-048 · g3-1-008"},{"ok":true,"zh":"这个苹果多少钱？","fix":"","py":"Zhège píngguǒ duōshao qián?","tr":["แอปเปิลลูกนี้ราคาเท่าไร","How much is this apple?","Quả táo này bao nhiêu tiền?","このりんごはいくらですか。"],"h":["ถามราคา/จำนวนมาก ใช้ 多少 (ไม่ต้องใส่ 吗)","Ask price or larger quantities with 多少 (no 吗)","问价格或较大数量用“多少”，句末不加“吗”","Hỏi giá hoặc số lượng lớn dùng 多少 (không có 吗)","値段や大きめの数には「多少」（「吗」不要）"],"w":["ทำได้เพราะ 多少钱 วางตำแหน่งเดียวกับคำตอบราคา (เช่น 五块钱) และ 多少 ไม่ต้องมีลักษณนามคั่นหน้า 钱","Works because 多少钱 occupies the exact price predicate slot (五块钱) and 多少 needs no measure word before 钱.","“多少钱”占据价格谓语位置（对应“五块钱”），且“多少”后可不加量词。","Đúng vì 多少钱 nằm đúng vị trí giá tiền (五块钱) và không cần lượng từ.","「多少钱」がそのまま価格述語（五块钱）の位置に入り、量詞も不要。"],"ref":"กลุ่มเทียบคำ g8 · HSK 3.0 g3-1-048"},{"ok":false,"zh":"什么你喜欢吃？","fix":"你喜欢吃什么？","py":"Nǐ xǐhuan chī shénme?","tr":["คุณชอบกินอะไร","What do you like to eat?","Bạn thích ăn gì?","何を食べるのが好きですか。"],"h":["ห้ามย้าย 什么 / 哪儿 / 谁 ไปวางต้นประโยคแบบภาษาอังกฤษ ('What do you…')","NEVER move 什么/哪儿/谁 to the front like English 'What do you…'","不能按英语语序把“什么”提前到句首","Không đưa 什么/哪儿 lên đầu câu kiểu tiếng Anh","英語の What のように疑問詞を文頭に移動しない"],"w":["ไม่ได้ เพราะในประโยคบอกเล่ากรรมอยู่หลังกริยา (我喜欢吃苹果) ดังนั้น 什么 จึงต้องอยู่ที่ตำแหน่งกรรมหลัง 吃 เสมอ: 你喜欢吃什么？","Wrong because the object sits after 吃 in statements (我喜欢吃苹果), so 什么 must stay right after 吃: 你喜欢吃什么？","不行，宾语在动词后（我喜欢吃苹果），所以“什么”必须留在“吃”后面：你喜欢吃什么？","Không được vì tân ngữ đứng sau động từ 吃 nên 什么 phải giữ nguyên sau 吃: 你喜欢吃什么？","目的語は動詞「吃」の後ろなので、「什么」も「吃」の後ろにそのまま置く。"],"ref":"HSK 3.0 g3-1-048"},{"ok":false,"zh":"你叫什么名字吗？","fix":"你叫什么名字？","py":"Nǐ jiào shénme míngzi?","tr":["คุณชื่ออะไร","What is your name?","Bạn tên là gì?","お名前は何ですか。"],"h":["ห้ามเติม 吗 ท้ายประโยคที่มี 什么 / 谁 / 哪儿 / 几 / 多少","NEVER add 吗 to a wh-question","特指问句末尾绝不能加“吗”","Tuyệt đối không thêm 吗 cuối câu hỏi có từ để hỏi","疑問詞がある文の末尾に「吗」を付けない"],"w":["ไม่ได้ เพราะ 什么 ทำให้ประโยคเป็นคำถามเจาะจงอยู่แล้ว ถ้าเติม 吗 จะผิดไวยากรณ์ (แต่เติม 呢 เพื่อทำให้น้ำเสียงนุ่มนวลขึ้นได้ในบางบริบท)","Wrong because 什么 already marks the question; adding 吗 is always ungrammatical (drop 吗).","不行，已有“什么”构成特指问，不能再加“吗”。","Không được vì đã có 什么 rồi, thêm 吗 là sai.","「什么」が疑問を表すので「吗」を重ねるのは誤用。"],"ref":"กลุ่มเทียบคำ g13 · HSK 3.0 g3-1-048"}],"ex":[["你叫什么名字？","Nǐ jiào shénme míngzi?","คุณชื่ออะไร","What is your name?","Bạn tên là gì?","お名前は何ですか。","什么"],["他是谁？","Tā shì shéi?","เขาคือใคร","Who is he?","Anh ấy là ai?","彼は誰ですか。","谁"],["你去哪儿？","Nǐ qù nǎr?","คุณจะไปไหน","Where are you going?","Bạn đi đâu vậy?","どこへ行きますか。","哪儿"],["你有几本书？","Nǐ yǒu jǐ běn shū?","คุณมีหนังสือกี่เล่ม","How many books do you have?","Bạn có mấy cuốn sách?","本を何冊持っていますか。","几"],["这个苹果多少钱？","Zhège píngguǒ duōshao qián?","แอปเปิลลูกนี้ราคาเท่าไร","How much is this apple?","Quả táo này bao nhiêu tiền?","このりんごはいくらですか。","多少"]],"err":[["什么你喜欢吃？","你喜欢吃什么？","วางคำถามในตำแหน่งเดียวกับคำตอบ ไม่ย้ายไปต้นประโยค","Keep the question word in the answer slot — never front it.","疑问词放在答案原位，不提前。","Giữ từ để hỏi ở đúng vị trí đáp án, không đảo lên đầu.","疑問詞は答えの位置にそのまま置く。"],["你叫什么名字吗？","你叫什么名字？","มี 什么 อยู่แล้ว ห้ามเติม 吗 ท้ายประโยค","Never add 吗 when 什么 is already in the sentence.","特指问句句末不能加“吗”。","Câu đã có 什么 thì không thêm 吗.","疑問詞のある文末に「吗」は付けない。"]],"rel":["g3-1-008","g3-1-047","g3-1-049"]},"g3-1-049":{"t":["ประโยคคำถามบวก-ลบ (正反问句): 去不去？/ 是不是？/ 有没有？","A-not-A questions (正反问句): 去不去 / 是不是 / 有没有","句类·疑问句（3）：正反问句","Câu hỏi chính phản (正反问句): 去不去 / 是不是 / 有没有","反復疑問文（正反问句）：去不去・是不是・有没有"],"f":["主语 + V 不 V / Adj 不 Adj（你去不去？/ 今天冷不冷？）","双音节：AB 不 AB 或 A 不 AB（喜不喜欢？/ 高不高兴？）","“有”专用：主语 + 有没有 + 宾语（你有没有书？）"],"why":["正反问句 คือการเอารูปบอกเล่ากับรูปปฏิเสธมาวางติดกันเพื่อถามว่า '…หรือไม่…' เช่น 去不去 (ไปไหม), 是不是 (ใช่ไหม), 冷不冷 (หนาวไหม), 有没有 (มีไหม) · ถ้าเป็นคำ 2 พยางค์ (เช่น 喜欢, 高兴, 漂亮) นิยมพูดแบบย่อพยางค์แรก: 喜不喜欢？, 高不高兴？ (หรือ 喜欢不喜欢？ ก็ได้) · ข้อควรระวังเด็ดขาด 3 ข้อ: (1) ห้ามเติม 吗 ท้ายประโยค (去不去吗？ ผิด!) (2) ห้ามใส่คำวิเศษณ์ 很, 都, 也 หน้า A不A (你很忙不忙？ ผิด!) (3) คำว่า 有 ต้องใช้ 有没有 ห้ามใช้ 有不有","A-not-A questions (正反问句) juxtapose positive and negative forms: 去不去 ('go or not?'), 是不是 ('is it or not?'), 冷不冷 ('cold or not?'), 有没有 ('have or not?'). · 2-syllable words commonly shorten to A不AB: 喜不喜欢？, 高不高兴？ (or AB不AB). · Three strict cautions: (1) NEVER add 吗 at the end. (2) NEVER put adverbs like 很 / 都 / 也 before A-not-A (never 你很忙不忙？). (3) Always use 有没有 for 有 (never 有不有).","正反问句把肯定与否定并列提问：去不去、是不是、冷不冷、有没有。 · 双音节词常缩写为“A不AB”（喜不喜欢？高不高兴？）。 · 三条铁律：（1）句末绝不能加“吗”；（2）正反式前绝不能加“很、都、也”等副词（不说“你很忙不忙？”）；（3）“有”只能说“有没有”，不能说“有不有”。","Câu hỏi chính phản (正反问句) ghép khẳng định + phủ định: 去不去, 是不是, 冷不冷, 有没有. · Từ 2 âm tiết thường rút gọn thành A不AB (喜不喜欢？高不高兴？). · 3 quy tắc cứng: (1) Không thêm 吗; (2) Không đặt 很 / 都 / 也 trước A不A; (3) 有 luôn dùng 有没有 (không nói 有不有).","反復疑問文（正反问句）は肯定と否定を並べて尋ねる（去不去・是不是・冷不冷・有没有）。 · 2音節語は「A不AB」（喜不喜欢・高不高兴）と略すのが自然。 · 鉄則3つ：（1）文末に「吗」不可。（2）前に「很・都・也」など副詞不可。（3）「有」は必ず「有没有」（「有不有」は不可）。"],"use":[{"ok":true,"zh":"你喜不喜欢喝茶？","fix":"","py":"Nǐ xǐ bù xǐhuan hē chá?","tr":["คุณชอบดื่มชาไหม","Do you like drinking tea?","Bạn có thích uống trà không?","お茶を飲むのは好きですか。"],"h":["คำ 2 พยางค์ (喜欢 / 高兴 / 认识) ย่อเป็น A不AB ได้อย่างเป็นธรรมชาติ","2-syllable words naturally shorten to A不AB (喜不喜欢)","双音节词用“A不AB”（喜不喜欢、认不认识）最自然","Từ 2 âm tiết rút gọn thành A不AB (喜不喜欢) rất tự nhiên","2音節語は「A不AB」（喜不喜欢・认不认识）が自然"],"w":["ทำได้และคนจีนพูดแบบนี้บ่อยกว่า 喜欢不喜欢 เพราะกระชับกว่า (เช่นเดียวกับ 认不认识, 高不高兴, 漂不漂亮)","Works as the most natural spoken form for 2-syllable verbs/adjectives (just like 认不认识, 高不高兴, 漂不漂亮).","口语中双音节词最常用“A不AB”式，简洁流畅（喜不喜欢、高不高兴）。","Đúng và phổ biến nhất trong khẩu ngữ (tương tự 认不认识, 高不高兴).","会話では「喜不喜欢」「高不高兴」の省略形が最も自然でよく使われる。"],"ref":"HSK 3.0 g3-1-049"},{"ok":true,"zh":"你有没有汉语书？","fix":"","py":"Nǐ yǒu méiyǒu Hànyǔ shū?","tr":["คุณมีหนังสือภาษาจีนไหม","Do you have a Chinese book?","Bạn có sách tiếng Trung không?","中国語の本を持っていますか。"],"h":["กริยา 有 ใช้รูป 有没有 เสมอ (หรือ 有 + กรรม + 没有)","With 有, ALWAYS use 有没有 (never 有不有)","“有”的正反问固定用“有没有”","Với 有 luôn dùng 有没有 (không dùng 有不有)","「有」の反復疑問文は常に「有没有」"],"w":["ทำได้เพราะรูปปฏิเสธของ 有 คือ 没有 จึงจับคู่เป็น 有没有 (และยังวางกรรมคั่นกลางได้ด้วย เช่น 你有汉语书没有？)","Works because the negative of 有 is 没有, forming 有没有 (or split as 你有汉语书没有？).","“有”的否定是“没有”，正反问必须是“有没有”（也可说“你有汉语书没有？”）。","Đúng vì phủ định của 有 là 没有 nên tạo thành 有没有.","「有」の否定は「没有」なので必ず「有没有」にする。"],"ref":"HSK 3.0 g3-1-049 · g3-1-053"},{"ok":false,"zh":"你很忙不忙？","fix":"你忙不忙？","py":"Nǐ máng bù máng?","tr":["คุณยุ่งไหม","Are you busy?","Bạn có bận không?","忙しいですか。"],"h":["ห้ามใส่ 很 / 都 / 也 หน้าคำถาม A不A","NEVER put 很 / 都 / 也 before an A-not-A form","正反问句前不能加“很、都、也”等副词","Không đặt 很 / 都 / 也 trước dạng A不A","反復疑問文の前に「很・都・也」は置けない"],"w":["ไม่ได้ เพราะ 很 บอกระดับความมากในเชิงยืนยัน ซึ่งขัดกับคำถามปลายเปิด 'ยุ่งหรือไม่ยุ่ง' ต้องตัด 很 ออกเหลือ 你忙不忙？","Wrong because 很 clashes with the open A-not-A choice — drop 很 → 你忙不忙？ (similarly, say 你们都去吗？ instead of 你们都去不去？).","不行，程度副词“很”以及“都、也”不能用于正反问前，须去掉“很”：你忙不忙？","Không được vì 很 mâu thuẫn với câu hỏi mở A不A; phải bỏ 很 → 你忙不忙？.","副詞「很・都・也」は反復疑問文の前に置けない。「你忙不忙？」にする。"],"ref":"HSK 3.0 g3-1-049"},{"ok":false,"zh":"你今天去不去学校吗？","fix":"你今天去不去学校？","py":"Nǐ jīntiān qù bù qù xuéxiào?","tr":["วันนี้คุณไปโรงเรียนไหม","Are you going to school today?","Hôm nay bạn có đi học không?","今日学校へ行きますか。"],"h":["ห้ามใส่ 吗 ซ้ำท้ายประโยค A不A","NEVER add 吗 at the end of an A-not-A question","正反问句末尾绝不能加“吗”","Tuyệt đối không thêm 吗 cuối câu hỏi chính phản","反復疑問文の末尾に「吗」は付けない"],"w":["ไม่ได้ เพราะ 去不去 เป็นคำถามอยู่แล้ว การเติม 吗 ซ้ำถือเป็นคำถามซ้อนกันผิดไวยากรณ์ ต้องตัด 吗 ทิ้ง","Wrong because 去不去 is already a question; appending 吗 doubles the question marker illegally.","不行，“去不去”已构成疑问，再加“吗”属于句式杂糅。","Không được vì 去不去 đã là câu hỏi rồi, thêm 吗 là sai.","「去不去」自体が疑問文なので「吗」を重ねてはいけない。"],"ref":"HSK 3.0 g3-1-049 · g3-1-047"}],"ex":[["你明天去不去学校？","Nǐ míngtiān qù bù qù xuéxiào?","พรุ่งนี้คุณไปโรงเรียนไหม","Are you going to school tomorrow?","Ngày mai bạn có đi học không?","明日学校に行きますか。","去不去"],["他是不是中国人？","Tā shì bù shì Zhōngguórén?","เขาเป็นคนจีนใช่ไหม","Is he Chinese?","Anh ấy có phải người Trung Quốc không?","彼は中国人ですか。","是不是"],["你有没有手机？","Nǐ yǒu méiyǒu shǒujī?","คุณมีโทรศัพท์มือถือไหม","Do you have a phone?","Bạn có điện thoại không?","スマホを持っていますか。","有没有"],["今天冷不冷？","Jīntiān lěng bù lěng?","วันนี้หนาวไหม","Is it cold today?","Hôm nay có lạnh không?","今日は寒いですか。","冷不冷"],["你喜不喜欢吃苹果？","Nǐ xǐ bù xǐhuan chī píngguǒ?","คุณชอบกินแอปเปิลไหม","Do you like eating apples?","Bạn có thích ăn táo không?","りんごを食べるのは好きですか。","喜不喜欢"]],"err":[["你很忙不忙？","你忙不忙？","ห้ามใส่ 很 / 都 / 也 หน้าคำถาม A不A","Never put 很 / 都 / 也 before an A-not-A question.","正反问前不加“很、都、也”。","Không đặt 很 / 都 / 也 trước câu hỏi A不A.","反復疑問文の前に「很・都・也」は置けない。"],["你有不有书？","你有没有书？","คำถาม A不A ของ 有 ต้องใช้ 有没有 เท่านั้น","The A-not-A form of 有 is ALWAYS 有没有.","“有”的正反问固定用“有没有”。","Dạng chính phản của 有 luôn là 有没有.","「有」の反復疑問文は常に「有没有」。"]],"rel":["g3-1-047","g3-1-048","g3-1-020"]},"g3-1-050":{"t":["ประโยคคำสั่ง/ขอร้อง/ชวน/ห้าม (祈使句): 请… / …吧 / 不要…","Imperative sentences (祈使句): 请… / …吧 / 不要…","句类：祈使句","Câu cầu khiến (祈使句): 请… / …吧 / 不要…","命令・依頼・勧誘・禁止文（祈使句）"],"f":["礼貌请求：请 + 动词（请坐！/ 请喝茶！）","商量建议：主语 + 动词 + 吧（我们去吧！/ 你休息一下吧！）","禁止劝阻：不要 + 动词（不要说话！/ 不要喝冷水！）"],"why":["祈使句 ใช้สั่ง ขอร้อง เชิญชวน หรือห้ามไม่ให้ทำสิ่งใดสิ่งหนึ่ง มักละประธาน 你 ไว้และลงท้ายด้วย 。 หรือ ！ · รูปแบบหลัก 3 แบบใน HSK 1: (1) ขอร้อง/เชิญอย่างสุภาพ: 请 + กริยา (请坐, 请看, 请问) (2) ชวน/แนะนำอย่างนุ่มนวล: กริยา + 吧 (我们去吧, 喝茶吧) (3) ห้ามปราม: 不要 + กริยา (不要说话！= อย่าพูด!, 不要吃！= อย่ากิน!) · ข้อควรระวัง: ห้ามใช้ 不 เฉย ๆ มาสั่งห้าม (ห้ามพูด 不说话！ ให้ใช้ 不要说话！) และในภาษาจีน 不要 ยังแปลว่า 'ไม่เอา' ได้ด้วย (我不要这个)","Imperative sentences (祈使句) make requests, invitations, suggestions, or prohibitions, often omitting 你 and ending in 。 or !. · Three HSK 1 patterns: (1) Polite request/invitation: 请 + Verb (请坐, 请看); (2) Soft suggestion: Verb + 吧 (我们去吧, 喝茶吧); (3) Prohibition: 不要 + Verb (不要说话! 'Don't talk!'). · Caution: NEVER use bare 不 for prohibitions (say 不要说话!, not 不说话!). Also note 不要 can mean 'don't want' (我不要这个).","祈使句表示请求、邀请、商量或禁止，常省略主语“你”，句末用“。”或“！”。 · HSK 1 三大句式：（1）礼貌请托：“请＋动词”（请坐、请喝茶）；（2）商量建议：“……吧”（我们去吧）；（3）禁止劝阻：“不要＋动词”（不要说话！）。 · 注意：表示“别做某事”不能单用“不”（不说“不说话！”），必须用“不要＋动词”（或 HSK 2 的“别”）。","Câu cầu khiến (祈使句) dùng để nhờ vả, mời, rủ hoặc cấm đoán, thường lược chủ ngữ 你. · 3 mẫu chính ở HSK 1: (1) 请 + động từ (请坐); (2) …吧 (我们去吧); (3) Cấm đoán: 不要 + động từ (不要说话!). · Lưu ý: không dùng 不 đứng lẻ để cấm đoán (phải dùng 不要).","祈使句は依頼・勧め・禁止を表す文で、主語「你」を省くことが多い。 · HSK1の3型：（1）丁寧な依頼「请＋動詞」（请坐）、（2）勧誘「…吧」（我们去吧）、（3）禁止「不要＋動詞」（不要说话！）。 · 注意：禁止に裸の「不」は使えず必ず「不要」を使う。"],"use":[{"ok":true,"zh":"不要说话！","fix":"","py":"Bùyào shuōhuà!","tr":["อย่าพูดคุย!","Don't talk!","Đừng nói chuyện!","話さないで！"],"h":["สั่งห้ามไม่ให้ทำสิ่งใด ใช้ 不要 + กริยา","Use 不要 + verb for 'Don't…!' prohibitions","禁止劝阻用“不要＋动词”","Cấm đoán dùng 不要 + động từ","禁止は「不要＋動詞」"],"w":["ทำได้ตามกฎกลุ่มเทียบคำ g7: 不要 + กริยา แปลว่า 'อย่า…!' (พอขึ้น HSK 2 จะมีคำย่อว่า 别 ที่ใช้ห้ามเหมือนกัน แต่ใน HSK 1 ใช้ 不要 เป็นหลัก)","Works per comparison group g7: 不要 + verb means 'Don't…!' (in HSK 2, shorter 别 also works for prohibitions).","“不要＋动词”是 HSK 1 标准禁止句式（如“不要说话！不要看手机！”）。","Đúng theo nhóm g7: 不要 + động từ nghĩa là 'Đừng…!' (HSK 2 có thêm 别).","「不要＋動詞」はHSK1標準の禁止文（HSK2では短い「别」も登場）。"],"ref":"กลุ่มเทียบคำ g7 · HSK 3.0 g3-1-050"},{"ok":true,"zh":"我们回家吧！","fix":"","py":"Wǒmen huí jiā ba!","tr":["พวกเรากลับบ้านกันเถอะ!","Let's go home!","Chúng ta về nhà thôi!","家に帰りましょう！"],"h":["ชวนทำด้วยกันอย่างเป็นกันเอง ใช้ 我们 + กริยา + 吧","Make friendly 'let's…' suggestions with 我们 + verb + 吧","提议一起做用“我们＋动词＋吧”","Rủ rê thân mật dùng 我们 + động từ + 吧","「〜しましょう」の勧誘は「我们＋動詞＋吧」"],"w":["ทำได้เพราะ 吧 ท้ายประโยคคำสั่งเปลี่ยนน้ำเสียงจากการบังคับให้กลายเป็นการชวนหรือปรึกษาที่อบอุ่นเป็นกันเอง","Works because 吧 turns an imperative into a warm, collaborative suggestion ('Let's…').","句末加“吧”使语气变为亲切的商量和提议。","Đúng vì 吧 cuối câu biến mệnh lệnh thành lời rủ rê thân thiện.","文末の「吧」で命令ではなく親しみやすい勧誘・提案になる。"],"ref":"กลุ่มเทียบคำ g13 · HSK 3.0 g3-1-050"},{"ok":false,"zh":"不说话！","fix":"不要说话！","py":"Bùyào shuōhuà!","tr":["อย่าพูดคุย!","Don't talk!","Đừng nói chuyện!","話さないで！"],"h":["ห้ามใช้ 不 เฉย ๆ แทน 不要 ในประโยคคำสั่งห้าม","Never use bare 不 instead of 不要 for 'Don't…!'","禁止祈使句不能单用“不＋动词”","Không dùng 不 đứng lẻ thay cho 不要 để cấm đoán","禁止の命令文に裸の「不」は使えない"],"w":["ไม่ได้ เพราะ 不说话 เป็นคำบอกเล่าแปลว่า 'ไม่พูด' ไม่ใช่คำสั่งห้ามว่า 'อย่าพูด!' ถ้าจะห้ามต้องใช้ 不要说话！ (หรือ 别说话！ ใน HSK 2)","Wrong because 不说话 merely describes 'not talking' rather than forbidding it; prohibitions require 不要说话!","不行，“不说话”是陈述动作不发生，表达禁止“别做”必须说“不要说话！”。","Không được vì 不说话 là câu kể 'không nói', muốn cấm phải nói 不要说话!.","「不说话」は単なる否定の描写。禁止の「〜するな」は必ず「不要说话！」にする。"],"ref":"กลุ่มเทียบคำ g7 · HSK 3.0 g3-1-050"},{"ok":false,"zh":"请不要坐这儿吗？","fix":"请不要坐这儿。","py":"Qǐng bùyào zuò zhèr.","tr":["กรุณาอย่านั่งตรงนี้ครับ/ค่ะ","Please don't sit here.","Xin đừng ngồi ở đây.","ここには座らないでください。"],"h":["ประโยคคำสั่ง/ขอร้อง/ห้าม (祈使句) ห้ามลงท้ายด้วย 吗","Never end an imperative (请 / 不要) with 吗","祈使句末尾不能加疑问词“吗”","Câu cầu khiến (请 / 不要) không kết thúc bằng 吗","命令・禁止文の末尾に「吗」を付けない"],"w":["ไม่ได้ เพราะ 请不要… เป็นประโยคขอความร่วมมือ/ห้าม (祈使句) ไม่ใช่ประโยคคำถามจึงห้ามใส่ 吗 (ถ้าจะถามให้ใช้ 可以…吗？)","Wrong because 请不要… is a polite prohibition, not a question — drop 吗 (or use 可以…吗？ to ask).","不行，“请不要……”是祈使句，不能加疑问词“吗”。","Không được vì 请不要… là câu cầu khiến, không thêm 吗 ở cuối.","「请不要…」は禁止・依頼の文なので疑問助詞「吗」は付けられない。"],"ref":"HSK 3.0 g3-1-050"}],"ex":[["请坐！","Qǐng zuò!","เชิญนั่งครับ/ค่ะ!","Please sit down!","Mời ngồi!","どうぞお掛けください！","请"],["请喝茶！","Qǐng hē chá!","เชิญดื่มชาครับ/ค่ะ!","Please have some tea!","Mời uống trà!","お茶をどうぞ！","请"],["我们去商店吧！","Wǒmen qù shāngdiàn ba!","พวกเราไปร้านค้ากันเถอะ!","Let's go to the shop!","Chúng ta đi cửa hàng đi!","お店に行きましょう！","吧"],["不要说话！","Bùyào shuōhuà!","อย่าพูดคุย!","Don't talk!","Đừng nói chuyện!","話さないでください！","不要"],["请不要喝冷水。","Qǐng bùyào hē lěng shuǐ.","กรุณาอย่าดื่มน้ำเย็นครับ/ค่ะ","Please don't drink cold water.","Xin đừng uống nước lạnh.","冷たい水は飲まないでください。","不要"]],"err":[["不说话！","不要说话！","ประโยคห้ามใช้ 不要 + กริยา ไม่ใช้ 不 เฉย ๆ","Prohibitions take 不要 + verb, not bare 不.","禁止祈使句用“不要＋动词”，不单用“不”。","Cấm đoán dùng 不要 + động từ, không dùng 不 đứng lẻ.","禁止は「不」ではなく「不要＋動詞」。"],["请不要坐这儿吗？","请不要坐这儿。","ประโยคขอร้อง/ห้าม (祈使句) ไม่ใส่ 吗 ท้ายประโยค","Never put 吗 at the end of an imperative sentence.","祈使句句末不加“吗”。","Câu cầu khiến không thêm 吗 ở cuối.","祈使句の文末に「吗」は付けない。"]],"rel":["g3-1-026","g3-1-045","g3-1-005"]},"g3-1-051":{"t":["ประโยคอุทาน (感叹句): 太…了！/ 真…！","Exclamatory sentences (感叹句): 太…了！/ 真…！","句类：感叹句","Câu cảm thán (感叹句): 太…了！/ 真…！","感嘆文（感叹句）：太…了！・真…！"],"f":["主语 + 太 + 形容词 / 心理动词 + 了！（太好了！/ 太贵了！）","主语 + 真 + 形容词 / 心理动词！（今天天气真好！/ 你真漂亮！）"],"why":["感叹句 ใช้แสดงอารมณ์ความรู้สึกชัดเจน (ดีใจ ชื่นชม ตกใจ หรือบ่น) ลงท้ายด้วย ！ · โครงสร้างหลัก 2 แบบใน HSK 1: (1) 太 + คุณศัพท์ + 了！ ใช้ได้ทั้งชื่นชมสุด ๆ (太好了！= ดีเหลือเกิน!, 太好吃了！= อร่อยมาก!) และบ่นว่าเกินพอดี (太贵了！= แพงเกินไป!, 太冷了！= หนาวเกินไป!) (2) 真 + คุณศัพท์！ = '…จริง ๆ เลย!' แสดงความรู้สึกตรงจากใจผู้พูด (今天天气真好！, 你真高兴！) · ข้อควรระวัง: (1) ประโยคบอกเล่าของ 太 นิยมมี 了 ปิดท้ายเสมอ (太好了！ ไม่ใช่ 太好！) (2) ห้ามใช้ 真 หรือ 太 ในประโยคคำถาม (เช่น 今天天气真好吗？ ผิด!) และห้ามใช้ 真 ขยายคำนาม","Exclamatory sentences (感叹句) express strong emotion and end with !. · Two core HSK 1 patterns: (1) 太 + Adj + 了! works for both high praise (太好了!, 太好吃了!) and complaints ('too…': 太贵了!, 太冷了!). (2) 真 + Adj! ('really…!') expresses heartfelt reaction (今天天气真好!). · Cautions: (1) Affirmative 太 almost always closes with 了 (太好了!, not bare 太好!). (2) Never use 真 in questions or as a noun modifier.","感叹句用来抒发强烈情感，句末用感叹号“！”。 · HSK 1 两大核心句式：（1）“太＋形容词＋了！”既可赞叹（太好了！太好吃了！）也可抱怨过度（太贵了！）；（2）“真＋形容词！”抒发由衷感叹（今天天气真好！）。 · 注意：（1）肯定感叹“太……”句末通常必须带“了”；（2）“真”不能用于疑问句，也不能作定语修饰名词。","Câu cảm thán (感叹句) bộc lộ cảm xúc mạnh, kết thúc bằng !. · 2 mẫu chính HSK 1: (1) 太 + tính từ + 了! (vừa khen 太好了! vừa chê quá mức 太贵了!); (2) 真 + tính từ! ('thật sự…!': 今天天气真好!). · Lưu ý: (1) Khẳng định với 太 thường bắt buộc có 了; (2) Không dùng 真 trong câu hỏi hoặc làm định ngữ.","感嘆文（感叹句）は強い感情を表し文末は「！」。 · HSK1の2大構文：（1）「太＋形容詞＋了！」（称賛「太好了！」にも過度「太贵了！」にも）、（2）「真＋形容詞！」（心からの感嘆「今天天气真好！」）。 · 注意：（1）肯定の「太…」は通常「了」が必要。（2）「真」は疑問文や名詞修飾に使えない。"],"use":[{"ok":true,"zh":"这个菜太好吃了！","fix":"","py":"Zhège cài tài hǎochī le!","tr":["อาหารจานนี้อร่อยเหลือเกิน!","This dish is so delicious!","Món này ngon quá trời!","この料理は最高においしい！"],"h":["ชมหรือบ่นด้วย 太 + คุณศัพท์ + 了！ (ต้องมี 了 ปิดท้าย)","Praise or complain with 太 + Adj + 了! (keep the closing 了)","肯定式“太＋形容词＋了！”须带“了”","Khen/chê bằng 太 + tính từ + 了! (giữ 了 ở cuối)","「太＋形容詞＋了！」（肯定では「了」を添える）"],"w":["ทำได้เพราะเป็นอุทานชื่นชมที่สมบูรณ์ด้วยโครงสร้างคู่ 太…了 (เช่นเดียวกับ 太好了！, 太漂亮了！, 太贵了！)","Works cleanly with the complete paired frame 太…了 (just like 太好了!, 太漂亮了!, 太贵了!).","“太……了”前后呼应，赞叹和抱怨都同样地道。","Đúng vì cặp 太…了 đi trọn bộ, dùng khen hay chê đều chuẩn.","「太…了」の呼応で感嘆が完成している。"],"ref":"กลุ่มเทียบคำ g14 · HSK 3.0 g3-1-051"},{"ok":true,"zh":"今天天气真好！","fix":"","py":"Jīntiān tiānqì zhēn hǎo!","tr":["วันนี้อากาศดีจริง ๆ!","The weather is really nice today!","Hôm nay thời tiết đẹp thật đấy!","今日は本当にいい天気ですね！"],"h":["อุทานความรู้สึกจากใจใช้ 真 + คุณศัพท์！ (ไม่ต้องมี 了)","Express heartfelt reaction with 真 + Adj! (no 了 needed)","“真＋形容词！”表由衷感叹（一般不加“了”）","Cảm thán chân thành dùng 真 + tính từ! (không cần 了)","心からの感嘆は「真＋形容詞！」（「了」不要）"],"w":["ทำได้เพราะผู้พูดสัมผัสสภาพอากาศจริง ๆ แล้วอุทานชมจากใจ (เช่นเดียวกับ 这件衣服真漂亮！, 你真好！)","Works because the speaker directly experiences the nice weather and reacts spontaneously (just like 你真好!).","“真”直接表达说话人的主观赞叹，不需要搭配“了”。","Đúng vì người nói cảm nhận trực tiếp và thốt lên khen ngợi.","話し手の実感からの感嘆を表し、「了」は要らない。"],"ref":"กลุ่มเทียบคำ g14 · HSK 3.0 g3-1-051"},{"ok":false,"zh":"今天太冷！","fix":"今天太冷了！","py":"Jīntiān tài lěng le!","tr":["วันนี้หนาวเกินไปแล้ว!","It's way too cold today!","Hôm nay lạnh quá rồi!","今日は寒すぎます！"],"h":["อย่าลืม 了 ท้ายประโยคอุทานบอกเล่า 太…了！","Don't drop 了 in affirmative 太…了! exclamations","肯定感叹“太……”不能漏掉句尾“了”","Không bỏ quên 了 trong câu cảm thán khẳng định 太…了!","肯定の「太…了！」では文末の「了」を落とさない"],"w":["ไม่สมบูรณ์เพราะในประโยคบอกเล่า 太 ต้องการ 了 ปิดท้ายคู่กันเป็น 太冷了！(ยกเว้นรูปปฏิเสธที่ตัด 了 ได้ เช่น 今天不太冷 = วันนี้ไม่ค่อยหนาว)","Incomplete because affirmative 太 pairs with 了 (太冷了!), whereas negative 不太 drops 了 (今天不太冷 'not very cold').","不完整，肯定式“太＋形容词”须带“了”；只有否定式“不太＋形容词”（不太冷）才不加“了”。","Chưa hoàn chỉnh vì dạng khẳng định 太 cần có 了 ở cuối; chỉ phủ định 不太冷 mới không có 了.","肯定の「太＋形容詞」は「了」が必要（否定「不太冷」のみ「了」なし）。"],"ref":"กลุ่มเทียบคำ g14 · HSK 3.0 g3-1-051"},{"ok":false,"zh":"今天天气真好吗？","fix":"今天天气好吗？","py":"Jīntiān tiānqì hǎo ma?","tr":["วันนี้อากาศดีไหม","Is the weather nice today?","Hôm nay thời tiết có đẹp không?","今日の天気はいいですか。"],"h":["ห้ามใช้ 真 ในประโยคคำถามธรรมดา (ตัด 真 ออก)","Never use exclamatory 真 in ordinary questions","“真”带主观感叹语气，不用于普通疑问句","Không dùng 真 trong câu hỏi thông thường","感嘆の「真」は普通の疑問文に使えない"],"w":["ไม่ได้ เพราะ 真 เป็นการอุทานว่าผู้พูดเห็นและรู้สึกเองแล้วว่าดีจริง ๆ จึงขัดกับการถามอีกฝ่ายว่า 'ดีไหม?' ถ้าจะถามให้ตัด 真 ออกเป็น 今天天气好吗？","Wrong because 真 already asserts the speaker's own exclamation, which clashes with asking a neutral question.","不行，“真”表说话人已认定的感叹，不能放进普通是非问句里。","Không được vì 真 thể hiện người nói đã cảm nhận sẵn rồi, mâu thuẫn với câu hỏi.","「真」は話し手がすでに感じている感嘆なので、普通の疑問文とは矛盾する。"],"ref":"HSK 3.0 g3-1-051"}],"ex":[["太好了！","Tài hǎo le!","ดีเหลือเกิน / เยี่ยมเลย!","That's great!","Tuyệt quá!","よかった！／最高！","太"],["这个手机太贵了！","Zhège shǒujī tài guì le!","โทรศัพท์เครื่องนี้แพงเกินไปแล้ว!","This phone is too expensive!","Chiếc điện thoại này đắt quá!","このスマホは高すぎます！","太"],["今天天气真好！","Jīntiān tiānqì zhēn hǎo!","วันนี้อากาศดีจริง ๆ!","The weather is really nice today!","Hôm nay thời tiết đẹp thật!","今日は本当にいい天気だ！","真"],["这件衣服真漂亮！","Zhè jiàn yīfu zhēn piàoliang!","เสื้อตัวนี้สวยจริง ๆ!","This piece of clothing is really pretty!","Chiếc áo này đẹp thật đấy!","この服は本当にきれいですね！","真"],["今天不太热。","Jīntiān bù tài rè.","วันนี้ไม่ค่อยร้อน","It's not too hot today.","Hôm nay không nóng lắm.","今日はあまり暑くないです。","不太"]],"err":[["今天太冷！","今天太冷了！","ประโยคบอกเล่าของ 太 ต้องมี 了 ปิดท้าย (太冷了！)","Affirmative 太… exclamations need closing 了 (太冷了!).","肯定感叹“太……”句末须加“了”。","Câu cảm thán khẳng định 太… cần có 了 ở cuối.","肯定の「太…」は文末に「了」が必要。"],["今天天气真好吗？","今天天气好吗？","真 ใช้อุทานเท่านั้น ไม่ใช้ในประโยคคำถามธรรมดา","真 is for exclamations only, not neutral questions.","“真”用于感叹，不用于普通疑问句。","真 chỉ dùng cảm thán, không dùng trong câu hỏi.","「真」は感嘆専用で普通の疑問文には使わない。"]],"rel":["g3-1-043","g3-1-015","g3-1-026"]},"g3-1-052":{"t":["ประโยค “是” (是字句1): เป็น / คือ (บอกตัวตนหรือกลุ่มประเภท)","是 sentences (是字句1): identity & classification","特殊句型·“是”字句1：表示等同或类属","Câu chữ 是 (是字句1): đồng nhất và phân loại","「是」構文（是字句1）：同一・所属"],"f":["主语 + 是 + 名词（我是学生 / 他是王老师）","否定：主语 + 不是 + 名词（他不是医生）"],"why":["“是”字句 ใช้เชื่อมประธานกับคำนามเพื่อบอก 2 ความหมายหลัก: (1) เท่ากับ/คือคนหรือสิ่งเดียวกัน (他是王老师, 这是我的书) (2) อยู่ในกลุ่มประเภทนั้น ๆ (我是学生, 苹果是水果) · ปฏิเสธใช้ 不是 และถามใช้ …吗？ หรือ 是不是 · ข้อควรระวังสำคัญ 3 ข้อ: (1) ห้ามเอา 是 ไปวางหน้าคุณศัพท์เด็ดขาด (她很漂亮 ไม่ใช่ 她是漂亮) (2) ห้ามซ้อน 叫 กับ 是 (我叫大卫 ไม่ใช่ 我叫是大卫!) (3) บอกตำแหน่งใช้ 在 ไม่ใช่ 是 (我在学校 ไม่ใช่ 我是学校)","是 sentences link a subject to a noun for two core meanings: (1) identity/equivalence (他是王老师, 这是我的书) and (2) membership/category (我是学生, 苹果是水果). · Negate with 不是; question with …吗？ or 是不是. · Three major cautions: (1) NEVER place 是 before an adjective (她很漂亮, NOT 她是漂亮). (2) NEVER combine 叫 + 是 (我叫大卫, NOT 我叫是大卫!). (3) Use 在 — not 是 — for physical location.","“是”字句连接主语与名词宾语，表示：（1）等同（他是王老师、这是我的书）；（2）类属（我是学生、苹果是水果）。 · 否定用“不是”，疑问用“……吗？”或“是不是”。 · 三大注意：（1）不能接形容词（不说“她是漂亮”）；（2）不能与“叫”连用（说“我叫大卫”，不说“我叫是大卫”）；（3）表位置用“在”不用“是”。","Câu chữ 是 nối chủ ngữ với danh từ để chỉ: (1) đồng nhất (他是王老师, 这是我的书), (2) phân loại (我是学生, 苹果是水果). · Phủ định dùng 不是. · 3 lưu ý lớn: (1) KHÔNG đặt 是 trước tính từ; (2) KHÔNG ghép 叫 + 是 (我叫大卫, không nói 我叫是大卫); (3) Chỉ vị trí dùng 在 chứ không dùng 是.","「是」構文は主語と名詞を結び、（1）同一（他是王老师・这是我的书）、（2）所属（我是学生・苹果是水果）を表す。 · 否定は「不是」。 · 3大注意：（1）形容詞の前に置かない、（2）「叫」と重ねない（我叫大卫、「我叫是大卫」は不可）、（3）所在は「是」でなく「在」。"],"use":[{"ok":true,"zh":"我是中国人，她是我的老师。","fix":"","py":"Wǒ shì Zhōngguórén, tā shì wǒ de lǎoshī.","tr":["ฉันเป็นคนจีน เธอคือคุณครูของฉัน","I am Chinese; she is my teacher.","Tôi là người Trung Quốc, cô ấy là giáo viên của tôi.","私は中国人で、彼女は私の先生です。"],"h":["ใช้ 是 เชื่อมประธานกับกลุ่มประเภท (中国人) หรือระบุตัวตน (我的老师)","Use 是 to link a subject to a category (中国人) or specific identity (我的老师)","“是”连接主语与表类属或等同的名词","Dùng 是 nối chủ ngữ với phân loại (中国人) hoặc định danh (我的老师)","「是」で所属（中国人）や同一（我的老师）を表す"],"w":["ทำได้เพราะทั้ง 中国人 และ 我的老师 เป็นคำนาม/วลีนามที่ระบุตัวตนและประเภทของประธานโดยตรง","Works cleanly because both 中国人 (category) and 我的老师 (identity) are noun predicates matching 是.","“中国人”表类属，“我的老师”表等同，都是“是”字句的标准宾语。","Đúng vì 中国人 (loại) và 我的老师 (định danh) đều là danh từ đi chuẩn với 是.","「中国人」（所属）も「我的老师」（同一）も名詞で「是」の標準的な用法。"],"ref":"HSK 3.0 g3-1-052"},{"ok":true,"zh":"我叫大卫。","fix":"","py":"Wǒ jiào Dàwèi.","tr":["ฉันชื่อเดวิด","My name is David.","Tôi tên là David.","私の名前はデビッドです。"],"h":["แนะนำชื่อใช้ 我叫 + ชื่อ (หรือ 我是 + ชื่อ) อย่างใดอย่างหนึ่งเท่านั้น","Introduce your name with EITHER 我叫 + Name OR 我是 + Name — never both","介绍名字用“我叫……”或“我是……”，二选一","Giới thiệu tên dùng 我叫… HOẶC 我是…, chỉ chọn một","名乗るときは「我叫…」か「我是…」のどちらか一方"],"w":["ทำได้เพราะ 叫 แปลว่า 'ชื่อว่า/เรียกว่า' เป็นกริยาสมบูรณ์ในตัวอยู่แล้ว จึงตามด้วยชื่อคนได้ทันทีไม่ต้องมี 是","Works because 叫 ('be called') is already a full verb taking the name directly — no 是 needed.","“叫”本身就是完整动词，直接接姓名，不需要再加“是”。","Đúng vì 叫 đã là động từ hoàn chỉnh, nối thẳng tên không cần 是.","「叫」自体が本動詞なのでそのまま名前を続けられる。"],"ref":"เสริม w3-00091"},{"ok":false,"zh":"我叫是大卫。","fix":"我叫大卫。","py":"Wǒ jiào Dàwèi.","tr":["ฉันชื่อเดวิด","My name is David.","Tôi tên là David.","私はデビッドといいます。"],"h":["ห้ามเอา 叫 กับ 是 มาซ้อนติดกัน (叫是 ผิดเสมอ!)","NEVER combine 叫 + 是 together (叫是 is always wrong!)","绝不能把“叫”和“是”连用（不说“我叫是大卫”）","Không ghép 叫 + 是 liền nhau (không nói 我叫是大卫)","「叫」と「是」を並べてはいけない（我叫是大卫は不可）"],"w":["ไม่ได้ เพราะผู้เรียนไทยและเวียดนามมักแปลคำว่า 'ชื่อ + คือ' ตรงตัวเป็น 叫是 แต่ภาษาจีนบังคับเลือกอย่างเดียว: 我叫大卫 หรือ 我是大卫","Wrong because learners often translate 'is called' literally as 叫是; pick ONLY ONE: 我叫大卫 or 我是大卫.","不行，“叫”和“是”不能叠用，只能说“我叫大卫”或“我是大卫”。","Không được vì người Việt/Thái hay dịch thẳng 'tên là' thành 叫是; chỉ chọn 我叫大卫 hoặc 我是大卫.","「叫」と「是」は重ねられない。「我叫大卫」または「我是大卫」にする。"],"ref":"เสริม w3-00091"},{"ok":false,"zh":"我是学校。","fix":"我在学校。","py":"Wǒ zài xuéxiào.","tr":["ฉันอยู่ที่โรงเรียน","I am at school.","Tôi đang ở trường.","私は学校にいます。"],"h":["บอกตำแหน่งว่า 'อยู่ที่ไหน' ใช้ 在 ห้ามใช้ 是","Use 在 — NOT 是 — to say where someone is located","表示身在某处用“在”，不能用“是”","Nói đang ở đâu dùng 在, không dùng 是","場所「〜にいる」には「是」でなく「在」"],"w":["ไม่ได้ เพราะ 我是学校 แปลว่า 'ตัวฉันคือโรงเรียน' (เป็นอาคารโรงเรียน!) ถ้าจะบอกว่าอยู่ที่โรงเรียนต้องใช้กริยา 在: 我在学校","Wrong because 我是学校 literally claims 'I AM a school'! Use 在 for location: 我在学校.","不行，“我是学校”变成了“我等于学校”；表示处于某地必须用“在”：我在学校。","Không được vì 我是学校 nghĩa là 'tôi là ngôi trường'! Chỉ vị trí phải dùng 在: 我在学校.","「我是学校」は「私は学校という建物だ」の意味になる。所在は「我在学校」。"],"ref":"HSK 3.0 g3-1-052 · g3-1-021"}],"ex":[["我是学生。","Wǒ shì xuésheng.","ฉันเป็นนักเรียน","I am a student.","Tôi là học sinh.","私は学生です。","是"],["他是王老师。","Tā shì Wáng lǎoshī.","เขาคืออาจารย์หวัง","He is Teacher Wang.","Ông ấy là thầy Vương.","彼は王先生です。","是"],["苹果是水果。","Píngguǒ shì shuǐguǒ.","แอปเปิลเป็นผลไม้","Apples are fruit.","Táo là hoa quả.","りんごは果物です。","是"],["他不是医生。","Tā bù shì yīshēng.","เขาไม่ใช่หมอ","He is not a doctor.","Anh ấy không phải bác sĩ.","彼は医者ではありません。","不是"],["这是我的手机。","Zhè shì wǒ de shǒujī.","นี่คือโทรศัพท์มือถือของฉัน","This is my mobile phone.","Đây là điện thoại của tôi.","これは私のスマホです。","是"]],"err":[["我叫是大卫。","我叫大卫。","ห้ามใช้ 叫 กับ 是 ซ้อนกัน (เลือก 我叫… หรือ 我是…)","Never combine 叫 and 是; use either 我叫… or 我是….","“叫”和“是”不能连用，说“我叫大卫”。","Không ghép 叫 và 是; chỉ dùng 我叫大卫.","「叫」と「是」は重ねない（「我叫大卫」）。"],["我是学校。","我在学校。","บอกตำแหน่ง 'อยู่ที่…' ใช้ 在 ไม่ใช่ 是","Use 在 (not 是) to express location.","表处所位置用“在”，不用“是”。","Chỉ vị trí dùng 在, không dùng 是.","所在を表すときは「是」でなく「在」。"]],"rel":["g3-1-044","g3-1-054","g3-1-021"]},"g3-1-053":{"t":["ประโยค “有” (有字句1): มี / เป็นเจ้าของ","有 sentences (有字句1): possession & belonging","特殊句型·“有”字句1：表示领有","Câu chữ 有 (有字句1): sở hữu","「有」構文（有字句1）：所有"],"f":["肯定：主语 + 有 + 宾语（我有两本书 / 我家有四口人）","否定：主语 + 没（有）+ 宾语（我没有猫，绝不用“不有”）","疑问：主语 + 有没有 + 宾语？（你有没有手机？）"],"why":["“有”字句 (表示领有) ใช้บอกว่าบุคคลหรือองค์กร 'มี / เป็นเจ้าของ' สิ่งใดสิ่งหนึ่ง เช่น 我有一只猫 (ฉันมีแมวหนึ่งตัว), 他有很多朋友 (เขามีเพื่อนเยอะ), 我们学校有饭店 (โรงเรียนพวกเรามีร้านอาหาร) · ข้อควรระวังเด็ดขาด 3 ข้อ: (1) ปฏิเสธ 有 ใช้ 没(有) เท่านั้น ห้ามใช้ 不有 เด็ดขาด! (2) ในประโยคปฏิเสธ 没有 ตามด้วยคำนามทั่วไป ไม่นิยมใส่จำนวน 一 (เช่น 我没有书 = ฉันไม่มีหนังสือ ไม่ค่อยพูด 我没有一本书 เว้นแต่เน้นว่า 'แม้แต่เล่มเดียวก็ไม่มี') (3) ห้ามใส่ 很 หรือ 了1 คู่กับ 有 แบบสุ่มสี่สุ่มห้า (ห้ามพูด 我很有书)","Possessive 有 sentences state what a person or group has or owns (我有一只猫, 他有很多朋友). · Three strict cautions: (1) ALWAYS negate 有 with 没(有) — NEVER 不有! (2) After 没有, normally omit 一 + measure word (我没有书 'I don't have a book', not 我没有一本书). (3) Never put 很 directly before 有 for concrete ownership (say 我有很多书, NEVER 我很有书).","“有”字句表示某人或某单位领有某物（我有一只猫、他有很多朋友）。 · 三条铁律：（1）“有”的唯一否定式是“没（有）”，绝不能说“不有”；（2）“没有”后一般不带“一＋量词”（说“我没有书”，一般不说“我没有一本书”）；（3）不能说“很有书”，要说“有很多书”。","Câu chữ 有 chỉ sở hữu (我有一只猫, 他有很多朋友). · 3 quy tắc cứng: (1) Phủ định luôn là 没(有), KHÔNG nói 不有; (2) Sau 没有 thường không kèm 一 + lượng từ (我没有书, không nói 我没有一本书); (3) Không nói 很有书 mà phải nói 有很多书.","所有の「有」構文は人や組織が何かを持っていることを表す（我有一只猫・他有很多朋友）。 · 鉄則3つ：（1）否定は必ず「没（有）」（「不有」は不可）。（2）「没有」の後ろに「一＋量詞」は普通付けない（我没有书）。（3）「很有书」とは言えず「有很多书」にする。"],"use":[{"ok":true,"zh":"我有很多朋友。","fix":"","py":"Wǒ yǒu hěn duō péngyou.","tr":["ฉันมีเพื่อนเยอะมาก","I have many friends.","Tôi có rất nhiều bạn bè.","私には友達がたくさんいます。"],"h":["จะบอกว่า 'มีเยอะ' วาง 很多 ไว้หลัง 有 หน้าคำนาม","For 'have a lot of…', put 很多 AFTER 有 before the noun","表示“有很多”时，“很多”放“有”后面修饰名词","Nói 'có nhiều…' đặt 很多 SAU 有 trước danh từ","「たくさん持っている」は「有＋很多＋名詞」"],"w":["ทำได้เพราะ 很多 ขยายคำนาม 朋友 จึงวางระหว่าง 有 กับ 朋友 เป็น 有很多朋友 (และไม่ใช้ 很有朋友)","Works because 很多 modifies the noun 朋友, sitting between 有 and 朋友: 我有很多朋友.","“很多”作定语修饰“朋友”，放在“有”后面：有很多朋友、有很多书。","Đúng vì 很多 bổ nghĩa cho danh từ 朋友 nên đứng sau 有.","「很多」は名詞「朋友」を修飾するため「有」の後ろに置く。"],"ref":"HSK 3.0 g3-1-053"},{"ok":true,"zh":"我没有电脑。","fix":"","py":"Wǒ méiyǒu diànnǎo.","tr":["ฉันไม่มีคอมพิวเตอร์","I don't have a computer.","Tôi không có máy tính.","パソコンを持っていません。"],"h":["ปฏิเสธการมีใช้ 没有 + คำนาม (ตัด 一 + ลักษณนามออก)","Negate possession with 没有 + bare noun (drop 一 + CL)","否定领有用“没有＋名词”（不加“一＋量词”）","Phủ định dùng 没有 + danh từ trần (bỏ 一 + lượng từ)","否定は「没有＋名詞」（「一＋量詞」を省く）"],"w":["ทำได้และเป็นธรรมชาติที่สุดในภาษาจีน ต่างจากภาษาอังกฤษที่พูด 'I don't have a computer' (มี 'a') แต่ภาษาจีนตัด 一个 ออกเลย","Works most naturally: unlike English 'don't have A computer', Chinese drops 一个 → 我没有电脑.","否定拥有时通常直接接光杆名词“没有电脑／没有书”，不必加“一个”。","Đúng và tự nhiên nhất: tiếng Trung bỏ 一个 khi phủ định với 没有.","英語の a と違い、否定の「没有」の後は「一个」を付けず「没有电脑」と言う。"],"ref":"กลุ่มเทียบคำ g6 · HSK 3.0 g3-1-053"},{"ok":false,"zh":"我很有书。","fix":"我有很多书。","py":"Wǒ yǒu hěn duō shū.","tr":["ฉันมีหนังสือเยอะมาก","I have many books.","Tôi có rất nhiều sách.","本をたくさん持っています。"],"h":["ห้ามวาง 很 ไว้หน้า 有 เวลาบอกจำนวนสิ่งของ","Never put 很 before 有 for concrete nouns — use 有很多","不能说“很有书”，应说“有很多书”","Không nói 很有书 mà phải nói 有很多书","「很有书」は不可、「有很多书」にする"],"w":["ไม่ได้ เพราะ 有 ไม่ใช่คุณศัพท์ 很 ขยายจำนวนหนังสือหน้า 有 ไม่ได้ ต้องย้ายไปเป็น 很多 หน้า 书: 我有很多书","Wrong because 很 cannot modify 有 for concrete objects; place 很多 before 书 → 我有很多书.","不行，表数量多必须把“很多”放在名词前：我有很多书。","Không được vì phải đặt 很多 trước danh từ 书: 我有很多书.","具象名詞の多さを言うときは「有」の前でなく「很多」を名詞の前に置く。"],"ref":"HSK 3.0 g3-1-053"},{"ok":false,"zh":"我不有手机。","fix":"我没有手机。","py":"Wǒ méiyǒu shǒujī.","tr":["ฉันไม่มีโทรศัพท์มือถือ","I don't have a mobile phone.","Tôi không có điện thoại.","スマホを持っていません。"],"h":["ห้ามปฏิเสธ 有 ด้วย 不","NEVER negate 有 with 不","“有”绝不能用“不”否定","Tuyệt đối không dùng 不有","「不有」は絶対不可（必ず「没有」）"],"w":["ไม่ได้ เพราะรูปปฏิเสธเพียงหนึ่งเดียวของ 有 คือ 没有 (หรือ 没)","Wrong because the sole negation of 有 in Chinese is 没(有).","不行，“有”只能用“没（有）”否定。","Không được vì phủ định duy nhất của 有 là 没(有).","「有」の否定は「没（有）」だけ。"],"ref":"กลุ่มเทียบคำ g6"}],"ex":[["我有一只小猫。","Wǒ yǒu yī zhī xiǎo māo.","ฉันมีลูกแมวหนึ่งตัว","I have a kitten.","Tôi có một chú mèo con.","子猫を一匹飼っています。","有"],["我家有四口人。","Wǒ jiā yǒu sì kǒu rén.","ครอบครัวฉันมีสี่คน","There are four people in my family.","Nhà tôi có bốn người.","私の家族は4人です。","有"],["他有很多中国朋友。","Tā yǒu hěn duō Zhōngguó péngyou.","เขามีเพื่อนคนจีนเยอะมาก","He has many Chinese friends.","Anh ấy có rất nhiều bạn Trung Quốc.","彼には中国人の友達がたくさんいます。","有"],["我没有电脑。","Wǒ méiyǒu diànnǎo.","ฉันไม่มีคอมพิวเตอร์","I don't have a computer.","Tôi không có máy tính.","パソコンを持っていません。","没有"],["你有没有时间？","Nǐ yǒu méiyǒu shíjiān?","คุณมีเวลาไหม","Do you have time?","Bạn có thời gian không?","時間はありますか。","有没有"]],"err":[["我不有手机。","我没有手机。","ปฏิเสธ 有 ต้องใช้ 没有 เท่านั้น","Always negate 有 with 没有, never 不有.","“有”的否定必须用“没有”。","Phủ định 有 bắt buộc dùng 没有.","「有」の否定は必ず「没有」。"],["我很有书。","我有很多书。","จะบอกว่ามีเยอะใช้ 有很多 + คำนาม ไม่ใช้ 很有","Say 有很多 + noun, never 很有 + concrete noun.","表示数量多说“有很多书”，不说“很有书”。","Nói 有很多书, không nói 很有书.","量が多いときは「很有书」でなく「有很多书」。"]],"rel":["g3-1-020","g3-1-055","g3-1-049"]},"g3-1-054":{"t":["ประโยคแสดงการมีอยู่ (存现句1-1): สถานที่ + 是 + คำนาม","Existence sentences (存现句1-1): Place + 是 + Noun","特殊句型·存现句1（1）：处所+是+名词","Câu tồn hiện (存现句1-1): Nơi chốn + 是 + Danh từ","存在文（存现句1-1）：場所＋是＋名詞"],"f":["处所词 / 方位短语 + 是 + 名词（桌子上是一本书 / 房间里是我的朋友）"],"why":["โครงสร้าง 'สถานที่ + 是 + คำนาม' เป็นประโยคบอกการมีอยู่ (存现句) แบบระบุเจาะจงว่า 'สิ่ง/คนที่อยู่ตรงจุดนั้นคืออะไร/ใคร' เช่น 桌子上是一本书 (บนโต๊ะคือหนังสือเล่มหนึ่ง), 房间里是我的朋友 (ในห้องคือเพื่อนของฉัน), 学校外边是一家商店 (ข้างนอกโรงเรียนคือร้านค้าแห่งหนึ่ง) · ต่างจาก 'สถานที่ + 有' อย่างไร? (1) ใช้ 是 เมื่อต้องการ 'ชี้ชัด/ระบุตัวตน' ว่าสิ่งเดียวหรือคนที่เป็นเจ้าของที่อยู่ตรงนั้นคืออะไร (เช่น 房间里是我的朋友 = ในห้องนั้นคือเพื่อนฉันเอง ไม่ใช่คนอื่น) (2) ใช้ 有 เมื่อบอกแค่ว่ามีอยู่โดยไม่เจาะจง · ข้อควรระวัง: ห้ามใส่ 在 หน้าสถานที่ที่เป็นประธาน (桌子上是一本书 ไม่ใช่ 在桌子上是一本书)","The pattern 'Place + 是 + Noun' is an existence sentence identifying WHO or WHAT occupies a specific spot: 桌子上是一本书 ('What's on the table is a book'), 房间里是我的朋友 ('The one inside the room is my friend'). · How does it differ from 'Place + 有'? Use 是 when identifying a known/sole occupant or pointing out what a place is; use 有 to simply state existence. · Caution: NEVER put 在 in front of the place subject (never 在桌子上是一本书).","“处所＋是＋名词”用来指明某处所存在的人或事物具体是什么（桌子上是一本书、房间里是我的朋友、学校外边是一家商店）。 · 与“处所＋有”的区别：“是”侧重确指、辨认该处的人或物（常为唯一或已知对象），“有”侧重客观存在。 · 注意：处所主语前绝不能加“在”（不说“在桌子上是一本书”）。","Mẫu 'Nơi chốn + 是 + Danh từ' xác định rõ ai/cái gì đang ở vị trí đó (桌子上是一本书, 房间里是我的朋友). · Khác 'Nơi chốn + 有': 是 nhấn mạnh định danh/duy nhất, còn 有 chỉ nêu sự tồn tại khách quan. · Lưu ý: KHÔNG thêm 在 trước chủ ngữ nơi chốn.","「場所＋是＋名詞」はある場所にあるもの・いる人を特定して示す存在文（桌子上是一本书・房间里是我的朋友）。 · 「場所＋有」との違い：「是」はそこに何（誰）があるか特定・同定するニュアンス、「有」は単なる存在。 · 注意：場所主語の前に「在」を付けない。"],"use":[{"ok":true,"zh":"房间里是我的朋友。","fix":"","py":"Fángjiān lǐ shì wǒ de péngyou.","tr":["ในห้องคือเพื่อนของฉัน","The one in the room is my friend.","Trong phòng là bạn của tôi.","部屋の中にいるのは私の友達です。"],"h":["ระบุตัวบุคคล/สิ่งของที่เจาะจง ณ ตำแหน่งนั้น ใช้ สถานที่ + 是 + คำนาม","Use Place + 是 + Noun to identify a specific person or thing at a location","指认某处的特定人或物用“处所＋是＋名词”","Xác định đích danh người/vật tại vị trí đó dùng Nơi chốn + 是 + Danh từ","その場所にいる特定の人・物を指し示す「場所＋是＋名詞」"],"w":["ทำได้เพราะ 我的朋友 เป็นบุคคลที่เจาะจงอยู่แล้ว ประโยคนี้ตอบคำถามว่า 'ใครอยู่ในห้อง?' → ในห้องคือเพื่อนของฉัน","Works naturally because 我的朋友 is definite — it answers 'Who is in the room?' rather than just saying 'there exists a friend'.","“我的朋友”是确指对象，用“是”回答“房间里是谁？”，比“有”更准确。","Đúng vì 我的朋友 là đối tượng xác định, dùng 是 trả lời câu 'Trong phòng là ai?' rất chuẩn.","「我的朋友」は特定の人なので、「部屋にいるのは誰？」への答えとして「是」が最適。"],"ref":"HSK 3.0 g3-1-054"},{"ok":true,"zh":"学校外边是一家商店。","fix":"","py":"Xuéxiào wàibian shì yī jiā shāngdiàn.","tr":["ข้างนอกโรงเรียนคือร้านค้าแห่งหนึ่ง","Outside the school is a shop.","Bên ngoài trường là một cửa hàng.","学校の外は一軒のお店です。"],"h":["ชี้บอกสภาพแวดล้อมรอบสถานที่ ใช้ ตำแหน่ง + 是 + สถานที่/สิ่งของ","Point out landmarks around a place with Place + 是 + Noun","介绍周边布局可用“方位短语＋是＋名词”","Chỉ rõ công trình/vật quanh đó dùng Phương vị + 是 + Danh từ","周囲の位置関係の説明にも「場所＋是＋名詞」"],"w":["ทำได้เพราะเป็นการชี้บอกว่าพื้นที่ด้านนอกโรงเรียนเป็นที่ตั้งของร้านค้าแห่งหนึ่ง (ไม่มี 在 นำหน้า 学校外边)","Works cleanly to identify what occupies the space right outside the school (with NO 在 before 学校外边).","“学校外边”作处所主语，用“是”指明那里的建筑是一家商店。","Đúng vì 学校外边 làm chủ ngữ trực tiếp (không thêm 在) rồi nối 是 + 一家商店.","「学校外边」をそのまま主語にして「是」でそこにある建物を指し示している。"],"ref":"HSK 3.0 g3-1-054"},{"ok":false,"zh":"在桌子上是一本书。","fix":"桌子上是一本书。","py":"Zhuōzi shàng shì yī běn shū.","tr":["บนโต๊ะคือหนังสือหนึ่งเล่ม","On the table is a book.","Trên bàn là một cuốn sách.","机の上にあるのは1冊の本です。"],"h":["ห้ามใส่ 在 หน้าคำสถานที่ที่เป็นประธานในประโยค 存现句","NEVER put 在 before the location subject in existence sentences","存现句处所主语前绝不能加“在”","Tuyệt đối không thêm 在 trước nơi chốn đầu câu tồn hiện","存在文の場所主語の前に「在」を付けない"],"w":["ไม่ได้ เพราะถ้าใส่ 在 ข้างหน้า 桌子上 จะกลายเป็นวลีบุพบท ทำให้ประโยคขาดประธานทันที ต้องตัด 在 ออกเหลือ 桌子上是一本书","Wrong because adding 在 turns 桌子上 into a prepositional phrase, leaving the sentence without a subject. Drop 在.","不行，加“在”会使全句失去主语，必须去掉“在”：桌子上是一本书。","Không được vì thêm 在 làm câu mất chủ ngữ; phải bỏ 在 thành 桌子上是一本书.","「在」を付けると主語が失われる。必ず「在」を取って「桌子上是一本书」にする。"],"ref":"HSK 3.0 g3-1-054 · g3-1-034"}],"ex":[["桌子上是一本书。","Zhuōzi shàng shì yī běn shū.","บนโต๊ะคือหนังสือหนึ่งเล่ม","On the table is a book.","Trên bàn là một cuốn sách.","机の上にあるのは本1冊です。","是"],["房间里是我的朋友。","Fángjiān lǐ shì wǒ de péngyou.","ในห้องคือเพื่อนของฉัน","In the room is my friend.","Trong phòng là bạn của tôi.","部屋の中にいるのは私の友達です。","是"],["学校外边是一家商店。","Xuéxiào wàibian shì yī jiā shāngdiàn.","ข้างนอกโรงเรียนคือร้านค้าแห่งหนึ่ง","Outside the school is a shop.","Bên ngoài trường là một cửa hàng.","学校の外は一軒のお店です。","是"],["椅子下是一只小猫。","Yǐzi xià shì yī zhī xiǎo māo.","ใต้เก้าอี้คือลูกแมวหนึ่งตัว","Under the chair is a kitten.","Dưới ghế là một chú mèo con.","椅子の下にいるのは子猫1匹です。","是"],["这儿不是医院，是学校。","Zhèr bù shì yīyuàn, shì xuéxiào.","ที่นี่ไม่ใช่โรงพยาบาล เป็นโรงเรียน","This is not a hospital; it's a school.","Ở đây không phải bệnh viện, là trường học.","ここは病院ではなく、学校です。","不是"]],"err":[["在桌子上是一本书。","桌子上是一本书。","ประธานสถานที่ในประโยค 存现句 ห้ามใส่ 在 นำหน้า","Never put 在 in front of the place subject.","处所主语前不能加“在”。","Không thêm 在 trước chủ ngữ nơi chốn.","場所主語の前に「在」は入れない。"]],"rel":["g3-1-055","g3-1-052","g3-1-034"]},"g3-1-055":{"t":["ประโยคแสดงการมีอยู่ (存现句1-2): สถานที่ + 有 + จำนวน + คำนาม","Existence sentences (存现句1-2): Place + 有 + Qty + Noun","特殊句型·存现句1（2）：处所+有+数量短语+名词","Câu tồn hiện (存现句1-2): Nơi chốn + 有 + Số lượng + Danh từ","存在文（存现句1-2）：場所＋有＋数量詞＋名詞"],"f":["肯定：处所 + 有 + 数量短语 + 名词（桌子上有一本书 / 房间里有两个人）","否定：处所 + 没有 + 名词（房间里没有人）","对比“在”：已知物 + 在 + 处所（我的书在桌子上）"],"why":["โครงสร้าง 'สถานที่ + 有 + จำนวน + คำนาม' แปลว่า 'ที่…มี…อยู่' (ตรงกับ There is / There are ในภาษาอังกฤษ) ใช้แนะนำสิ่งของหรือคนที่ผู้ฟังยังไม่รู้ว่ามีอยู่ตรงนั้น เช่น 桌子上有一本书 (บนโต๊ะมีหนังสือหนึ่งเล่ม), 房间里有两个人 (ในห้องมีคนสองคน) · ข้อแตกต่างสำคัญมากระหว่าง 有 กับ 在: (1) สิ่งที่ไม่เจาะจง/เพิ่งพูดถึง → สถานที่ + 有 + จำนวน + คำนาม (桌子上有一本书) (2) สิ่งที่เจาะจง/รู้จักแล้ว → คำนามเจาะจง + 在 + สถานที่ (我的书在桌子上 = หนังสือของฉันอยู่บนโต๊ะ) · ข้อควรระวัง: ห้ามใส่ 在 นำหน้าสถานที่หน้า 有 และห้ามเอาคำนามเจาะจงอย่าง 我的书 มาต่อหลัง 处所 + 有 แบบแปลก ๆ","'Place + 有 + Qty + Noun' means 'There is / There are… at [place]' and introduces indefinite/new items: 桌子上有一本书, 房间里有两个人. · Crucial contrast with 在: (1) Indefinite item → Place + 有 + Qty + Noun (桌子上有一本书 'There is a book on the table'); (2) Definite/known item → Known Noun + 在 + Place (我的书在桌子上 'My book is on the table'). · Caution: NEVER put 在 before the place subject (never 在桌子上有一本书).","“处所＋有＋数量短语＋名词”表示某处存在某人或某物（桌子上有一本书、房间里有两个人），宾语通常是无定的新信息。 · 与“在”的核心对比：无定新信息用“处所＋有＋数量＋名词”（桌子上有一本书）；有定已知对象用“名词＋在＋处所”（我的书在桌子上）。 · 注意：处所前不加“在”，否定用“没有”。","'Nơi chốn + 有 + Số lượng + Danh từ' nghĩa là 'Ở [nơi] có [vật/người]' (桌子上有一本书, 房间里有两个人). · Phân biệt 有 vs 在: đối tượng chưa xác định dùng 'Nơi chốn + 有' (桌子上有一本书); đối tượng đã xác định dùng 'Danh từ + 在 + Nơi chốn' (我的书在桌子上). · Lưu ý: không thêm 在 đầu câu.","「場所＋有＋数量詞＋名詞」は「〜に…がある／いる」（桌子上有一本书・房间里有两个人）。 · 「在」との重要な違い：不特定の新情報は「場所＋有」（桌子上有一本书）、特定の既知のものは「名詞＋在＋場所」（我的书在桌子上）。 · 注意：場所主語の前に「在」を付けない。"],"use":[{"ok":true,"zh":"房间里有两个学生。","fix":"","py":"Fángjiān lǐ yǒu liǎng ge xuésheng.","tr":["ในห้องมีนักเรียนสองคน","There are two students in the room.","Trong phòng có hai học sinh.","部屋の中に学生が2人います。"],"h":["แนะนำสิ่ง/คนที่ยังไม่เจาะจง: สถานที่ + 有 + จำนวน + คำนาม","Introduce indefinite items/people: Place + 有 + Qty + Noun","无定存在用“处所＋有＋数量短语＋名词”","Giới thiệu đối tượng chưa xác định: Nơi chốn + 有 + Số lượng + Danh từ","不特定の存在は「場所＋有＋数量詞＋名詞」"],"w":["ทำได้เพราะ 两个学生 เป็นข้อมูลใหม่ที่ไม่ระบุชื่อเจาะจง จึงวางหลัง 房间里有 ได้สมบูรณ์ตามแบบแผน 存现句","Works cleanly because 两个学生 is indefinite new information placed after 房间里有.","“两个学生”是无定数量短语，放在“房间里有”后最自然。","Đúng vì 两个学生 là thông tin mới chưa xác định, đặt sau 房间里有 rất chuẩn.","「两个学生」が不特定の新情報なので「房间里有」の後ろに置くのが自然。"],"ref":"HSK 3.0 g3-1-055"},{"ok":true,"zh":"我的书在桌子上。","fix":"","py":"Wǒ de shū zài zhuōzi shàng.","tr":["หนังสือของฉันอยู่บนโต๊ะ","My book is on the table.","Sách của tôi ở trên bàn.","私の本は机の上にあります。"],"h":["ถ้าเป็นของที่เจาะจงแล้ว (我的书 / 小王) ให้ขึ้นต้นด้วยของแล้วใช้ 在","When the item is definite (我的书 / 小王), put it first with 在","有定已知对象（我的书、小王）用“主语＋在＋处所”","Đối tượng xác định (我的书 / 小王) đặt đầu câu với 在","特定のもの（我的书・小王）は「主語＋在＋場所」"],"w":["ทำได้เพราะผู้พูด-ผู้ฟังรู้ชัดเจนว่าหมายถึง 'หนังสือของฉัน' จึงเอาขึ้นเป็นประธานแล้วบอกตำแหน่งด้วย 在桌子上","Works because 我的书 is definite/known — Chinese puts known things first and locates them with 在.","“我的书”是已知有定对象，须放句首用“在”说明位置。","Đúng vì 我的书 đã xác định nên đưa lên đầu câu rồi dùng 在 chỉ vị trí.","「我的书」は特定なので主語にして「在」で場所を示す。"],"ref":"HSK 3.0 g3-1-055 · g3-1-021"},{"ok":false,"zh":"在房间里有两个学生。","fix":"房间里有两个学生。","py":"Fángjiān lǐ yǒu liǎng ge xuésheng.","tr":["ในห้องมีนักเรียนสองคน","There are two students in the room.","Trong phòng có hai học sinh.","部屋の中に学生が2人います。"],"h":["ห้ามใส่ 在 หน้าสถานที่เมื่อใช้โครงสร้าง 'ที่…มี…'","NEVER put 在 before the place in 'Place + 有' sentences","“处所＋有”前面不能加“在”","Không thêm 在 trước nơi chốn trong mẫu 'Nơi chốn + 有'","「場所＋有」の前に「在」を付けない"],"w":["ไม่ได้ เพราะผู้เรียนไทยมักแปลคำว่า 'ในห้อง' ตรงตัวว่า 在房间里 แต่เมื่อกริยาหลักคือ 有 ต้องตัด 在 ออกให้ 房间里 เป็นประธานโดยตรง","Wrong because learners often translate 'in the room' as 在房间里, but before 有 you must drop 在 so 房间里 is the subject.","不行，前加“在”会让句子缺主语，须去掉“在”：房间里有两个学生。","Không được vì thêm 在 làm câu thiếu chủ ngữ; phải bỏ 在 → 房间里有两个学生.","「在」を付けると主語が欠けるため、必ず「在」を省く。"],"ref":"HSK 3.0 g3-1-055 · g3-1-034"},{"ok":false,"zh":"一本书在桌子上。","fix":"桌子上有一本书。","py":"Zhuōzi shàng yǒu yī běn shū.","tr":["บนโต๊ะมีหนังสือหนึ่งเล่ม","There is a book on the table.","Trên bàn có một cuốn sách.","机の上に本が1冊あります。"],"h":["ไม่เอาคำนามไม่เจาะจง (一本书) มาขึ้นต้นประโยคกับ 在","Don't start a 在-sentence with an indefinite noun (一本书)","无定名词（一本书）一般不作“在”字句主语","Không đặt danh từ bất định (一本书) làm chủ ngữ với 在","不特定の名詞（一本书）を「在」文の主語にしない"],"w":["ไม่เป็นธรรมชาติในภาษาจีน เพราะประธานหน้า 在 ควรเป็นสิ่งที่เจาะจง (เช่น 这本书 / 我的书) ถ้าเป็น 'หนังสือเล่มหนึ่ง' ให้ใช้ 桌子上有一本书 แทน","Unnatural in Chinese: subjects of 在 should be definite (这本书/我的书). For indefinite 'a book', use 桌子上有一本书.","不自然，“在”字句主语须是有定的（这本书在桌子上）；无定的“一本书”要用存现句“桌子上有一本书”。","Không tự nhiên: chủ ngữ của 在 cần xác định (这本书); bất định 一本书 phải dùng 桌子上有一本书.","「在」文の主語は特定物（这本书など）にする。不特定の「一本书」は「桌子上有一本书」にする。"],"ref":"HSK 3.0 g3-1-055"}],"ex":[["桌子上有一本书。","Zhuōzi shàng yǒu yī běn shū.","บนโต๊ะมีหนังสือหนึ่งเล่ม","There is a book on the table.","Trên bàn có một cuốn sách.","机の上に本が1冊あります。","有"],["房间里有两个学生。","Fángjiān lǐ yǒu liǎng ge xuésheng.","ในห้องมีนักเรียนสองคน","There are two students in the room.","Trong phòng có hai học sinh.","部屋の中に学生が2人います。","有"],["商店里有很多水果。","Shāngdiàn lǐ yǒu hěn duō shuǐguǒ.","ในร้านค้ามีผลไม้เยอะมาก","There is a lot of fruit in the shop.","Trong cửa hàng có rất nhiều hoa quả.","店の中に果物がたくさんあります。","有"],["这里有一家医院。","Zhèlǐ yǒu yī jiā yīyuàn.","ที่นี่มีโรงพยาบาลหนึ่งแห่ง","There is a hospital here.","Ở đây có một bệnh viện.","ここに病院が一軒あります。","有"],["房间里没有人。","Fángjiān lǐ méiyǒu rén.","ในห้องไม่มีคนเลย","There is nobody in the room.","Trong phòng không có ai.","部屋の中に誰もいません。","没有"]],"err":[["在房间里有两个学生。","房间里有两个学生。","ประโยค 'สถานที่ + 有' ห้ามใส่ 在 นำหน้า","Never place 在 before the location in 'Place + 有'.","“处所＋有”前不能加“在”。","Không thêm 在 trước nơi chốn trong câu tồn hiện.","「場所＋有」の前に「在」を付けない。"],["一本书在桌子上。","桌子上有一本书。","สิ่งที่ไม่เจาะจง (一本书) ใช้ 'สถานที่ + 有' แทน '在'","Indefinite 'a book' takes 'Place + 有' instead of 在.","无定对象用存现句“桌子上有一本书”。","Vật bất định (一本书) dùng 'Nơi chốn + 有'.","不特定のものは「在」ではなく「場所＋有」にする。"]],"rel":["g3-1-054","g3-1-053","g3-1-034"]},"g3-1-056":{"t":["ประโยคกริยาต่อเนื่อง 1 (连动句1-1): ไป/มา…เพื่อทำ… (บอกจุดประสงค์)","Serial-verb sentences 1 (连动句1-1): go/come to do (purpose)","特殊句型·连动句1（1）：后一动作是前一动作的目的","Câu liên động 1 (连动句1-1): đi/đến để làm gì (mục đích)","連動文1（连动句1-1）：移動＋目的の動作"],"f":["主语 + 去 / 来 / 回 +（处所）+ 动词2（目的）","例如：我去商店买苹果 / 他来中国学习汉语"],"why":["连动句 แบบบอกจุดประสงค์ คือประโยคที่มีกริยา 2 ตัวขึ้นไปของประธานคนเดียวกันเรียงต่อกันตามลำดับเวลาที่เกิดจริง: ทำกริยาที่ 1 (เดินทางไป/มา/กลับสถานที่) ก่อน แล้วตามด้วยกริยาที่ 2 (จุดประสงค์ที่ไปทำ) โดยไม่ต้องมีคำเชื่อม 'เพื่อ / to' คั่นเลย! · เช่น 我去商店买苹果 (ฉันไปร้านค้าซื้อแอปเปิล), 他来中国学习汉语 (เขามาจีนเรียนภาษาจีน) · ข้อควรระวังเด็ดขาด 2 ข้อ: (1) ห้ามสลับลำดับเอากริยาจุดประสงค์ขึ้นก่อนการเดินทาง (ห้ามพูด 我买苹果去商店!) (2) ห้ามเอา 了1 ไปใส่หลัง 去 ในประโยคที่ยังไม่เสร็จทั้งคู่ หรือถ้าเกิดจบแล้วให้วาง 了 ไว้หลังกริยาที่ 2 หรือท้ายประโยค (我去商店买了苹果)","Purpose serial-verb sentences (连动句) line up two actions by the same subject in strict chronological order — motion FIRST (去/来/回 + place), purpose SECOND (Verb 2), with NO connecting word like 'to': 我去商店买苹果, 他来中国学习汉语. · Two strict cautions: (1) NEVER reverse the order (never 我买苹果去商店). (2) When the trip + purpose are completed, attach 了 to Verb 2 or sentence end (我去商店买了苹果), not after 去.","连动句（表目的）由同一主语连续发出两个动作，严格按发生先后排列：先“去／来／回（＋处所）”，再接目的动作，中间不加任何连词（我去商店买苹果、他来中国学习汉语）。 · 两条注意：（1）绝不能把目的动作放在前面；（2）动作完成时“了”常放在第二个动词后或句末（我去商店买了苹果）。","Câu liên động chỉ mục đích xếp 2 hành động của cùng chủ ngữ theo đúng thứ tự thời gian: di chuyển (去/来/回 + nơi chốn) TRƯỚC, mục đích (động từ 2) SAU, KHÔNG cần từ nối: 我去商店买苹果. · Lưu ý: không đảo ngược thứ tự; khi đã làm xong đặt 了 sau động từ 2 (我去商店买了苹果).","目的を表す連動文は同一主語の2動作を時間順にそのまま並べる：移動（去・来・回＋場所）が先、目的の動作（動詞2）が後で接続詞は不要（我去商店买苹果）。 · 注意：（1）順序を逆にしない。（2）完了の「了」は動詞2の後ろに置く（我去商店买了苹果）。"],"use":[{"ok":true,"zh":"我去超市买水果。","fix":"","py":"Wǒ qù chāoshì mǎi shuǐguǒ.","tr":["ฉันไปซูเปอร์มาร์เก็ตเพื่อซื้อผลไม้","I'm going to the supermarket to buy fruit.","Tôi đi siêu thị mua hoa quả.","スーパーへ果物を買いに行きます。"],"h":["เรียงตามลำดับเวลาจริง: ไปถึงที่ (去超市) → ทำจุดประสงค์ (买水果)","Follow real chronological order: go to place (去超市) → do purpose (买水果)","按先后顺序：先“去超市”，再“买水果”，不加连词","Xếp đúng thứ tự thời gian: 去超市 trước → 买水果 sau","時間順に「去超市」→「买水果」と接続詞なしで並べる"],"w":["ทำได้และตรงกับวิธีคิดของภาษาไทย ('ไปซูเปอร์ซื้อผลไม้') เป๊ะ ไม่ต้องเติมคำเชื่อมใด ๆ คั่นกลางระหว่างสองกริยา","Works seamlessly in chronological order with no connector between the two verb phrases.","完全按事情发生的自然顺序连接两个动词短语，简明地道。","Đúng và rất tự nhiên giống hệt tiếng Việt ('đi siêu thị mua hoa quả').","出来事の順序どおりに2つの動詞句をそのまま並べる自然な連動文。"],"ref":"HSK 3.0 g3-1-056 · ประโยคตัวอย่าง_300"},{"ok":true,"zh":"我昨天去书店买了一本书。","fix":"","py":"Wǒ zuótiān qù shūdiàn mǎile yī běn shū.","tr":["เมื่อวานฉันไปร้านหนังสือซื้อหนังสือมาหนึ่งเล่ม","Yesterday I went to the bookstore and bought a book.","Hôm qua tôi đi hiệu sách mua một cuốn sách.","昨日、本屋へ行って本を1冊買いました。"],"h":["เมื่อทำสำเร็จแล้ว วาง 了 ไว้หลังกริยาตัวที่สอง (买 + 了)","When completed, place 了 after the second (main purpose) verb","动作已完成时，“了1”放在第二个动词后面（买了）","Khi đã xong, đặt 了 sau động từ thứ hai (买了)","完了したときは「了」を2番目の動詞の後ろに置く（买了）"],"w":["ทำได้เพราะจุดสำคัญของประโยคคือซื้อหนังสือได้สำเร็จแล้ว จึงวาง 了1 ติดกับกริยา 买 (ไม่ใส่หลัง 去 เป็น 去了书店买…)","Works because the goal was buying the book, so 了1 attaches to 买 rather than 去.","焦点在目的动作“买”，所以完成助词“了”加在“买”后，不加在“去”后。","Đúng vì trọng tâm là hành động mục đích 买 nên 了 gắn sau 买.","主眼は目的の「买」にあるため、完了の「了」は「去」ではなく「买」に付ける。"],"ref":"HSK 3.0 g3-1-056"},{"ok":false,"zh":"我买苹果去商店。","fix":"我去商店买苹果。","py":"Wǒ qù shāngdiàn mǎi píngguǒ.","tr":["ฉันไปร้านค้าซื้อแอปเปิล","I go to the shop to buy apples.","Tôi đi cửa hàng mua táo.","お店へりんごを買いに行きます。"],"h":["ห้ามเอากริยาจุดประสงค์ขึ้นหน้ากริยาเดินทาง (去/来)","NEVER put the purpose verb before the motion verb (去/来)","不能把目的动作放到“去／来”前面","Không đảo động từ mục đích lên trước 去/来","目的の動詞を移動動詞（去・来）の前に置けない"],"w":["ไม่ได้ เพราะในชีวิตจริงเราต้องไปถึงร้านค้าก่อนแล้วค่อยซื้อแอปเปิล ภาษาจีนเรียงตามเข็มนาฬิกาเสมอ: 去商店 → 买苹果","Wrong because you must go to the shop BEFORE buying apples — Chinese serial verbs strictly follow chronological order.","不行，汉语连动句严格遵守时间先后顺序，必须先“去商店”再“买苹果”。","Không được vì phải đi tới cửa hàng rồi mới mua táo; thứ tự bắt buộc là 去商店买苹果.","店に行ってから買うという時間順を守るため「我去商店买苹果」にする。"],"ref":"HSK 3.0 g3-1-056"}],"ex":[["我去商店买苹果。","Wǒ qù shāngdiàn mǎi píngguǒ.","ฉันไปร้านค้าซื้อแอปเปิล","I go to the shop to buy apples.","Tôi đi cửa hàng mua táo.","店へりんごを買いに行きます。","去商店"],["他来中国学习汉语。","Tā lái Zhōngguó xuéxí Hànyǔ.","เขามาเมืองจีนเพื่อเรียนภาษาจีน","He came to China to study Chinese.","Anh ấy đến Trung Quốc học tiếng Trung.","彼は中国語を学びに来中しました。","来中国"],["我们去饭店吃饭吧。","Wǒmen qù fàndiàn chīfàn ba.","พวกเราไปกินข้าวที่ร้านอาหารกันเถอะ","Let's go to the restaurant to eat.","Chúng ta đi nhà hàng ăn cơm đi.","レストランへご飯を食べに行きましょう。","去饭店"],["妈妈去医院看医生。","Māma qù yīyuàn kàn yīshēng.","แม่ไปโรงพยาบาลหาหมอ","Mom goes to the hospital to see a doctor.","Mẹ đi bệnh viện khám bác sĩ.","母は病院へ診察に行きます。","去医院"],["我去电影院看电影。","Wǒ qù diànyǐngyuàn kàn diànyǐng.","ฉันไปโรงหนังดูภาพยนตร์","I'm going to the cinema to watch a movie.","Tôi đi rạp xem phim.","映画館へ映画を見に行きます。","去电影院"]],"err":[["我买苹果去商店。","我去商店买苹果。","เรียงตามเวลาที่เกิดจริง: ไปสถานที่ก่อน แล้วค่อยทำจุดประสงค์","Follow real time order: go to the place first, then do the purpose.","按先后顺序：先“去商店”，后“买苹果”。","Xếp đúng thứ tự thời gian: 去商店 trước rồi 买苹果.","時間順に「去商店」→「买苹果」とする。"]],"rel":["g3-1-057","g3-1-030","g3-1-042"]},"g3-1-057":{"t":["ประโยคกริยาต่อเนื่อง 2 (连动句1-2): นั่งรถ/เครื่องบินไป… (บอกวิธีการ)","Serial-verb sentences 2 (连动句1-2): take transport to go (means)","特殊句型·连动句1（2）：前一动作是后一动作的方式","Câu liên động 2 (连动句1-2): phương tiện + đi đâu","連動文2（连动句1-2）：手段・交通機関＋移動"],"f":["主语 + 坐 + 交通工具（飞机 / 火车 / 出租车）+ 去 / 来 / 回 + 处所","主语 + 开车 + 去 + 处所"],"why":["连动句 แบบบอกวิธีการ/พาหนะ คือการวาง 'กริยาวิธีเดินทาง' ไว้ข้างหน้า แล้วตามด้วย 'กริยาจุดหมาย' ไว้ข้างหลัง — ซึ่งตรงข้ามกับภาษาไทยและอังกฤษ! · ไทย: 'ไปปักกิ่ง + โดยเครื่องบิน' / อังกฤษ: 'go to Beijing + by plane' · จีน: 'นั่งเครื่องบิน + ไปปักกิ่ง' (坐飞机去北京), 'นั่งแท็กซี่ + ไปโรงพยาบาล' (坐出租车去医院), 'ขับรถ + ไปทำงาน' (开车去上班) · ข้อควรระวัง: (1) ห้ามเอา 去北京 ขึ้นหน้า 坐飞机 (ห้ามพูด 我去北京坐飞机!) (2) คำถามว่า 'ไปอย่างไร?' ให้ถามว่า 你怎么去北京？ (วาง 怎么 หน้า 去)","Means/manner serial-verb sentences put the METHOD/TRANSPORT first and the DESTINATION second — the reverse of Thai and English! · English/Thai: 'go to Beijing by plane' → Chinese: 坐飞机去北京 ('sit-plane go Beijing'), 坐出租车去医院 ('take a taxi to the hospital'), 开车去上班 ('drive to work'). · Cautions: (1) NEVER put 去北京 before 坐飞机 (never 我去北京坐飞机). (2) Ask 'how?' with 怎么 before 去: 你怎么去北京？","连动句（表方式）把表示方式或交通工具的动词短语放在前面，把去向动作放在后面——语序与泰语、英语相反！ · 例：坐飞机去北京、坐出租车去医院、开车去上班。 · 注意：（1）绝不能说“我去北京坐飞机”；（2）询问交通方式用“怎么＋去……”（你怎么去北京？）。","Câu liên động chỉ phương tiện/cách thức đặt PHƯƠNG TIỆN trước, ĐÍCH ĐẾN sau — ngược tiếng Việt/Thái/Anh! · Ví dụ: 坐飞机去北京 (đi Bắc Kinh bằng máy bay), 坐出租车去医院, 开车去上班. · Lưu ý: KHÔNG nói 我去北京坐飞机; hỏi phương tiện dùng 你怎么去…？","手段・交通機関を表す連動文は「乗り物・手段」が先、「移動先」が後になる。 · 例：坐飞机去北京、坐出租车去医院、开车去上班。 · 注意：（1）「我去北京坐飞机」と逆にしてはいけない。（2）手段を尋ねるときは「你怎么去北京？」。"],"use":[{"ok":true,"zh":"我坐飞机去北京。","fix":"","py":"Wǒ zuò fēijī qù Běijīng.","tr":["ฉันนั่งเครื่องบินไปปักกิ่ง","I take a plane to Beijing.","Tôi đi Bắc Kinh bằng máy bay.","飛行機で北京へ行きます。"],"h":["พาหนะ (坐飞机 / 坐火车 / 坐出租车) วางหน้า 去/来/回 เสมอ","Put transport (坐飞机 / 坐火车 / 坐出租车) BEFORE 去/来/回","交通方式“坐飞机／坐火车／开车”放在“去／来／回”前","Đặt phương tiện (坐飞机/坐火车/开车) TRƯỚC 去/来/回","交通手段（坐飞机・坐火车・开车）を「去・来・回」の前に置く"],"w":["ทำได้เพราะตามลำดับเวลาจริง เราขึ้นเครื่องบิน (坐飞机) ก่อน จึงพาไปถึงปักกิ่ง (去北京) — จำง่ายว่า ขึ้นรถก่อนแล้วค่อยไป!","Works naturally because you board the plane first (坐飞机) in order to go to Beijing (去北京).","按逻辑与习惯，先交代交通方式“坐飞机”，再说目的地“去北京”。","Đúng vì theo thứ tự thực tế: lên máy bay (坐飞机) rồi mới đi tới Bắc Kinh (去北京).","飛行機に乗る（手段）→北京へ行く（目的の移動）という自然な語順。"],"ref":"HSK 3.0 g3-1-057 · ประโยคตัวอย่าง_300"},{"ok":true,"zh":"我开车去上班。","fix":"","py":"Wǒ kāichē qù shàngbān.","tr":["ฉันขับรถไปทำงาน","I drive to work.","Tôi lái xe đi làm.","車で出勤します。"],"h":["ขับรถเองใช้ 开车 + 去 (นั่งรถโดยสารใช้ 坐车)","Use 开车 for driving yourself vs 坐 for riding as a passenger","自己驾驶用“开车去……”，乘坐交通工具用“坐……去……”","Tự lái xe dùng 开车, ngồi phương tiện dùng 坐","自分で運転は「开车」、乗客として乗るのは「坐」"],"w":["ทำได้เพราะ 开车 (ขับรถ) เป็นวิธีการที่วางหน้ากริยา 去上班 ได้ทันที ต่างจาก 坐出租车 ที่แปลว่านั่งในฐานะผู้โดยสาร","Works cleanly: 开车 ('drive') expresses the means before 去上班, distinct from riding as a passenger with 坐.","“开车”表方式放“去上班”前，区分于乘客身份的“坐出租车／坐火车”。","Đúng vì 开车 là tự lái xe, đặt trước 去上班 (khác với 坐 là ngồi xe).","自分で運転する手段「开车」を「去上班」の前に置く（乗客なら「坐」）。"],"ref":"HSK 3.0 g3-1-057"},{"ok":false,"zh":"我去北京坐飞机。","fix":"我坐飞机去北京。","py":"Wǒ zuò fēijī qù Běijīng.","tr":["ฉันไปปักกิ่งโดยเครื่องบิน","I go to Beijing by plane.","Tôi đi Bắc Kinh bằng máy bay.","飛行機で北京へ行きます。"],"h":["ห้ามเอา 'ไปที่ไหน' ขึ้นหน้า 'นั่งรถอะไร' แบบภาษาไทย/อังกฤษ","NEVER put 'go to [place]' before 'by [transport]' like English/Thai","不能把“坐飞机”放在“去北京”后面","Không đặt phương tiện 坐飞机 sau 去北京","「去北京」の後ろに「坐飞机」を置けない"],"w":["ไม่ได้ เพราะ 我去北京坐飞机 จะแปลเพี้ยนเป็น 'ฉันไปปักกิ่งเพื่อจะไปลองนั่งเครื่องบิน (ที่ปักกิ่ง)'! ต้องวางวิธีเดินทางขึ้นก่อนเสมอ: 我坐飞机去北京","Wrong because 我去北京坐飞机 means 'I go to Beijing IN ORDER TO ride a plane there'! Always put the transport first.","不行，“我去北京坐飞机”会变成“去北京的目的是坐飞机”；表方式必须把“坐飞机”放前面。","Không được vì 我去北京坐飞机 sẽ bị hiểu thành 'đến Bắc Kinh để ngồi máy bay'! Phải đưa 坐飞机 lên trước.","「我去北京坐飞机」は「飛行機に乗るために北京へ行く」の意味になってしまう。必ず「我坐飞机去北京」。"],"ref":"HSK 3.0 g3-1-057"}],"ex":[["我坐飞机去北京。","Wǒ zuò fēijī qù Běijīng.","ฉันนั่งเครื่องบินไปปักกิ่ง","I go to Beijing by plane.","Tôi đi Bắc Kinh bằng máy bay.","飛行機で北京へ行きます。","坐飞机"],["他坐火车回家。","Tā zuò huǒchē huí jiā.","เขานั่งรถไฟกลับบ้าน","He takes the train home.","Anh ấy đi tàu hỏa về nhà.","彼は電車で帰省します。","坐火车"],["我们坐出租车去医院。","Wǒmen zuò chūzūchē qù yīyuàn.","พวกเรานั่งแท็กซี่ไปโรงพยาบาล","We take a taxi to the hospital.","Chúng tôi đi taxi tới bệnh viện.","タクシーで病院へ行きます。","坐出租车"],["爸爸开车去上班。","Bàba kāichē qù shàngbān.","พ่อขับรถไปทำงาน","Dad drives to work.","Bố lái xe đi làm.","父は車で出勤します。","开车"],["你怎么去学校？","Nǐ zěnme qù xuéxiào?","คุณไปโรงเรียนยังไง","How do you go to school?","Bạn đi học bằng cách nào?","どうやって学校へ行きますか。","怎么"]],"err":[["我去北京坐飞机。","我坐飞机去北京。","วิธีเดินทาง (坐飞机) ต้องวางหน้าจุดหมาย (去北京) เสมอ","Put the transport (坐飞机) BEFORE the destination (去北京).","方式动作“坐飞机”必须放在“去北京”前。","Đặt phương tiện (坐飞机) TRƯỚC đích đến (去北京).","手段（坐飞机）を移動先（去北京）の前に置く。"],["爸爸去上班开车。","爸爸开车去上班。","วาง 开车 ไว้หน้า 去上班 เสมอ","Put 开车 before 去上班.","方式“开车”放在“去上班”前。","Đặt 开车 trước 去上班.","「开车」を「去上班」の前に置く。"]],"rel":["g3-1-056","g3-1-008","g3-1-042"]},"g3-1-058":{"t":["ประโยคกรรมสองตัว (双宾语句1): กริยา + คน (กรรม 1) + สิ่งของ (กรรม 2)","Double-object sentences (双宾语句1): Verb + Person + Thing","特殊句型·双宾语句1：主语+动词+宾语1+宾语2","Câu hai tân ngữ (双宾语句1): Động từ + Người + Vật","二重目的語文（双宾语句1）：動詞＋人＋物"],"f":["主语 + 给 / 问 + 宾语1（人）+ 宾语2（事物）","例如：他给我一本书 / 我问老师一个问题"],"why":["双宾语句 คือประโยคที่กริยาตัวเดียวรับกรรมพร้อมกัน 2 ตัว: กรรมตัวที่ 1 คือ 'ผู้รับ/คน' (间接宾语) และกรรมตัวที่ 2 คือ 'สิ่งของ/เรื่องราว' (直接宾语) · กริยาหลักใน HSK 1 คือ 给 (ให้) และ 问 (ถาม) เช่น 他给我一本书 (เขาให้หนังสือฉันเล่มหนึ่ง), 我问老师一个问题 (ฉันถามคำถามคุณครูหนึ่งข้อ) · กฎเหล็ก 2 ข้อที่คนไทยพลาดบ่อย: (1) ต้องวาง 'คน (กรรม 1)' ไว้ก่อน 'สิ่งของ (กรรม 2)' เสมอ ห้ามสลับแบบภาษาไทยว่า 'ให้หนังสือ + ฉัน' (2) ไม่ใช่ทุกกริยาจะรับกรรมสองตัวได้ — กริยาอย่าง 买 (ซื้อ) ไม่รับกรรมสองตัวตรง ๆ (ห้ามพูด 我买他一本书!)","Double-object sentences (双宾语句) take two objects after one verb: Object 1 = Person (recipient) FIRST, Object 2 = Thing SECOND. · Core HSK 1 verbs: 给 ('give') and 问 ('ask') — e.g., 他给我一本书, 我问老师一个问题. · Two strict rules: (1) ALWAYS put the PERSON before the THING (never swap to 他给一本书我!). (2) Only specific verbs allow double objects (给, 问) — ordinary verbs like 买 do NOT (never 我买他一本书).","双宾语句中一个动词先后带两个宾语：宾语1（指人，间接宾语）在前，宾语2（指事物，直接宾语）在后。 · HSK 1 核心动词为“给、问”：他给我一本书、我问老师一个问题。 · 两条铁律：（1）绝不能把物放在人前（不说“他给一本书我”）；（2）只有特定动词能带双宾语，“买”等动词不能直接说“我买他一本书”。","Câu hai tân ngữ (双宾语句) có 1 động từ nhận liền 2 tân ngữ: Tân ngữ 1 (Người) đứng TRƯỚC, Tân ngữ 2 (Vật/Việc) đứng SAU. · Động từ trọng tâm HSK 1: 给 (cho), 问 (hỏi): 他给我一本书, 我问老师一个问题. · Lưu ý: (1) KHÔNG đảo Vật lên trước Người; (2) Chỉ một số động từ như 给, 问 nhận 2 tân ngữ (không nói 我买他一本书).","二重目的語文（双宾语句）は動詞の後ろに「目的語1（人）＋目的語2（物・事）」の順で2つ並べる。 · HSK1の中心動詞は「给（あげる）」「问（尋ねる）」：他给我一本书、我问老师一个问题。 · 鉄則：（1）「物→人」と逆順にしてはいけない。（2）使える動詞は限られ、「买」などは不可。"],"use":[{"ok":true,"zh":"我问老师一个问题。","fix":"","py":"Wǒ wèn lǎoshī yī ge wèntí.","tr":["ฉันถามคำถามคุณครูหนึ่งข้อ","I ask the teacher a question.","Tôi hỏi thầy giáo một câu hỏi.","先生に質問を一つします。"],"h":["วาง 'คน (老师)' ก่อน แล้วตามด้วย 'สิ่งของ/คำถาม (一个问题)'","Put the PERSON (老师) first, then the THING (一个问题)","先人后物：问＋老师（宾1）＋一个问题（宾2）","Đặt NGƯỜI (老师) trước rồi mới tới VẬT/VIỆC (一个问题)","「人（老师）」を先、「事（一个问题）」を後に並べる"],"w":["ทำได้เพราะ 问 เป็นกริยากรรมสองตัวมาตรฐาน รับผู้ถูกถาม (老师) ก่อน แล้วตามด้วยคำถาม (一个问题) ทันทีโดยไม่ต้องมีบุพบท","Works cleanly because 问 takes person (老师) directly before thing (一个问题) with no preposition.","“问”是典型双宾动词，紧接对象“老师”和内容“一个问题”。","Đúng vì 问 nhận trực tiếp 老师 rồi tới 一个问题 không cần giới từ.","「问」は典型的な二重目的語動詞で「人＋事」の順に直接並べる。"],"ref":"HSK 3.0 g3-1-058 · ประโยคตัวอย่าง_300"},{"ok":true,"zh":"妈妈给我五个苹果。","fix":"","py":"Māma gěi wǒ wǔ ge píngguǒ.","tr":["แม่ให้แอปเปิลฉันห้าลูก","Mom gives me five apples.","Mẹ cho tôi năm quả táo.","母が私にりんごを5個くれます。"],"h":["给 + ผู้รับ (我) + สิ่งของ (五个苹果)","给 + recipient (我) + item (五个苹果)","“给＋人（宾1）＋物（宾2）”","给 + người nhận (我) + đồ vật (五个苹果)","「给＋人（我）＋物（五个苹果）」"],"w":["ทำได้เพราะ 给 สื่อการส่งมอบโดยตรงจากผู้ให้ (妈妈) → ผู้รับ (我) → สิ่งของ (五个苹果) ครบโครงสร้าง双宾语句","Works directly with 给: giver (妈妈) → recipient (我) → item (五个苹果).","“给”直接表达给予，宾语顺序固定为“人＋物”。","Đúng vì 给 diễn tả sự trao tặng trực tiếp theo đúng trật tự Người → Vật.","授与の「给」は必ず「人（我）＋物（五个苹果）」の順になる。"],"ref":"HSK 3.0 g3-1-058"},{"ok":false,"zh":"他给一本书我。","fix":"他给我一本书。","py":"Tā gěi wǒ yī běn shū.","tr":["เขาให้หนังสือฉันหนึ่งเล่ม","He gives me a book.","Anh ấy cho tôi một cuốn sách.","彼は私に本を1冊くれます。"],"h":["ห้ามสลับเอา 'สิ่งของ' ขึ้นหน้า 'คน' (给一本书我 ผิด!)","NEVER put the THING before the PERSON (给一本书我 is wrong!)","双宾语句绝不能先物后人（不说“给一本书我”）","Không bao giờ đặt VẬT trước NGƯỜI (không nói 给一本书我)","「物→人」の順にしてはいけない（给一本书我は不可）"],"w":["ไม่ได้ เพราะในภาษาไทยพูดว่า 'ให้หนังสือ + ฉัน' ได้ แต่ภาษาจีนบังคับให้ผู้รับ (我) อยู่ติดหลังกริยา 给 เสมอ: 他给我一本书","Wrong because Chinese double-object order is strictly Verb + Person + Thing (他给我一本书), never Verb + Thing + Person.","不行，双宾语语序铁律是“先人后物”，必须说“他给我一本书”。","Không được vì tiếng Trung bắt buộc 'Người trước, Vật sau': 他给我一本书.","二重目的語は常に「人→物」の順で固定。「他给我一本书」にする。"],"ref":"HSK 3.0 g3-1-058"},{"ok":false,"zh":"我问一个问题老师。","fix":"我问老师一个问题。","py":"Wǒ wèn lǎoshī yī ge wèntí.","tr":["ฉันถามคำถามครูหนึ่งข้อ","I ask the teacher a question.","Tôi hỏi thầy một câu hỏi.","先生に質問を一つします。"],"h":["หลัง 问 ก็ต้องวาง 'คน' ก่อน 'คำถาม' เสมอ","After 问 too, ALWAYS put the person before the question","“问”同样必须先人后事（问老师一个问题）","Sau 问 cũng luôn đặt Người trước Câu hỏi","「问」の後ろも必ず「人→事」の順"],"w":["ไม่ได้ เพราะ 问 เป็นกริยากรรมสองตัวเช่นเดียวกับ 给 ต้องวางผู้ถูกถาม (老师) ไว้ติดกริยา 问 ก่อน然后ค่อยตามด้วย 一个问题","Wrong because 问 follows the exact same Person → Thing rule as 给: 我问老师一个问题.","不行，“问”也严格遵守“动词＋人＋事”顺序：我问老师一个问题。","Không được vì 问 cũng theo đúng trật tự 'Động từ + Người + Việc': 我问老师一个问题.","「问」も「给」と同じく必ず「動詞＋人＋事」（我问老师一个问题）にする。"],"ref":"HSK 3.0 g3-1-058"}],"ex":[["他给我一本书。","Tā gěi wǒ yī běn shū.","เขาให้หนังสือฉันหนึ่งเล่ม","He gives me a book.","Anh ấy cho tôi một cuốn sách.","彼は私に本を1冊くれます。","给我"],["我问老师一个问题。","Wǒ wèn lǎoshī yī ge wèntí.","ฉันถามคำถามคุณครูหนึ่งข้อ","I ask the teacher a question.","Tôi hỏi thầy giáo một câu hỏi.","先生に質問を一つします。","问老师"],["请给我一杯水。","Qǐng gěi wǒ yī bēi shuǐ.","กรุณาขอน้ำให้ฉันหนึ่งแก้ว","Please give me a glass of water.","Xin cho tôi một cốc nước.","お水を一杯ください。","给我"],["妈妈给我十块钱。","Māma gěi wǒ shí kuài qián.","แม่ให้เงินฉันสิบหยวน","Mom gives me ten yuan.","Mẹ cho tôi mười tệ.","母が私に10元くれました。","给我"],["他给了我两个苹果。","Tā gěile wǒ liǎng ge píngguǒ.","เขาให้แอปเปิลฉันมาสองลูก","He gave me two apples.","Anh ấy đã cho tôi hai quả táo.","彼は私にりんごを2個くれました。","给了我"]],"err":[["他给一本书我。","他给我一本书。","ประโยคกรรมสองตัวต้องวาง 'คน' ก่อน 'สิ่งของ' เสมอ","Double-object sentences ALWAYS put Person before Thing.","双宾语句必须先人后物（给我一本书）。","Câu 2 tân ngữ luôn đặt Người trước Vật (给我一本书).","二重目的語は常に「人→物」の順（给我一本书）。"],["我问一个问题老师。","我问老师一个问题。","วางผู้ถูกถาม (老师) ไว้หน้าคำถาม (一个问题)","Put the person (老师) before the question (一个问题).","先“老师”后“一个问题”。","Đặt 老师 trước 一个问题.","「老师」を「一个问题」の前に置く。"]],"rel":["g3-1-038","g3-1-030","g3-1-042"]},"g3-1-059":{"t":["ประโยคความซ้อนแบบไม่ใช้คำเชื่อม (不用关联词语的复句)","Compound sentences without conjunctions (不用关联词语的复句)","句子的类型·复句：不用关联词语的复句","Câu ghép không dùng từ nối (不用关联词语的复句)","接続詞を使わない複文（不用关联词语的复句）"],"f":["分句1，分句2。（靠语序和语义直接连接，不用“和”）","例如：天气很冷，我在家看书。/ 我喝茶，他喝牛奶。"],"why":["ลักษณะเด่นที่สวยงามมากของภาษาจีน (意合 = เชื่อมด้วยความหมาย) คือประโยคความซ้อนหลายแบบไม่จำเป็นต้องใส่คำเชื่อมอย่าง 'และ / แต่ / เพราะ / ดังนั้น' เลย แค่เรียงประโยคย่อย 2 ประโยคคั่นด้วยจุลภาคจีน ， ก็เข้าใจความสัมพันธ์ได้ทันที · เช่น (1) เทียบเคียงกัน: 我喝茶，他喝牛奶。(ฉันดื่มชา เขาดื่มนม) (2) เหตุ→ผลตามธรรมชาติ: 今天很冷，我在家看书。(วันนี้หนาวมาก ฉันเลยอ่านหนังสืออยู่บ้าน) (3) ลำดับก่อน→หลัง: 我先吃饭，明天再去看电影 → 我吃完饭… (ใน HSK 1 เช่น 我下班了，我去买菜。) · ข้อควรระวังเด็ดขาด: ห้ามเอา 和 มาเชื่อมระหว่างประโยคย่อยสองประโยคแทนจุลภาค!","A hallmark of Chinese grammar is parataxis (意合): two clauses often join cleanly with just a comma — NO conjunction ('and / so / but') required! · Examples: (1) Parallel contrast: 我喝茶，他喝牛奶。; (2) Natural cause→effect: 今天很冷，我在家看书。; (3) Sequence: 苹果很贵，我买面包。 · Strict caution: NEVER insert 和 between two full clauses to translate 'and'!","汉语复句重“意合”，许多时候不用任何关联词，只用逗号把两个分句连接起来就能自然表达并列、顺承或因果关系。 · 例：我喝茶，他喝牛奶（并列）；今天很冷，我在家看书（因果）。 · 注意：绝不能用“和”代替逗号连接两个完整分句。","Đặc trưng đẹp của tiếng Trung là liên kết bằng ngữ nghĩa (意合): nhiều câu ghép chỉ cần dấu phẩy ， nối 2 vế mà không cần từ nối! · Ví dụ: 我喝茶，他喝牛奶。(đối chiếu); 今天很冷，我在家看书。(nguyên nhân–kết quả). · Lưu ý: KHÔNG dùng 和 để nối hai mệnh đề.","中国語の複文は接続詞を使わず読点「，」だけで2つの節を結び、意味や語順で関係（並列・因果・継起）を表すのが非常に自然。 · 例：我喝茶，他喝牛奶。／今天很冷，我在家看书。 · 注意：2つの節を「和」でつないではいけない。"],"use":[{"ok":true,"zh":"今天很冷，我在家看书。","fix":"","py":"Jīntiān hěn lěng, wǒ zài jiā kàn shū.","tr":["วันนี้หนาวมาก ฉันอ่านหนังสืออยู่บ้าน","It's very cold today, so I'm reading at home.","Hôm nay rất lạnh, tôi ở nhà đọc sách.","今日はとても寒いので家で本を読みます。"],"h":["วางเหตุไว้หน้า ผลไว้หลัง แล้วคั่นด้วยจุลภาคจีน ， ได้เลย","Put cause first and result second, separated simply by a comma","前因后果直接用逗号连接，不必硬加关联词","Đặt nguyên nhân trước, kết quả sau, chỉ cần dấu phẩy","原因を前・結果を後に置き読点「，」だけでつなぐ"],"w":["ทำได้และเป็นธรรมชาติมากในภาษาจีน เพราะเหตุ (วันนี้หนาวมาก) เกิดก่อนผล (เลยอยู่บ้านอ่านหนังสือ) คนฟังเข้าใจความสัมพันธ์ทันที","Works very naturally: placing cause before result lets listeners grasp the 'so' link with just a comma.","“今天很冷”是原因，“我在家看书”是结果，汉语直接用逗号衔接最为地道。","Đúng và rất tự nhiên vì nguyên nhân đi trước kết quả, không cần từ nối vẫn hiểu ngay.","原因→結果の順に並べれば接続詞なしでも因果関係が自然に伝わる。"],"ref":"HSK 3.0 g3-1-059"},{"ok":true,"zh":"我喝茶，他喝牛奶。","fix":"","py":"Wǒ hē chá, tā hē niúnǎi.","tr":["ฉันดื่มชา เขาดื่มนม","I drink tea; he drinks milk.","Tôi uống trà, anh ấy uống sữa.","私はお茶を飲み、彼は牛乳を飲みます。"],"h":["สองประโยคคู่ขนานหรือเปรียบเทียบกัน คั่นด้วยจุลภาคเฉย ๆ","Join two parallel or contrasting clauses with a plain comma","并列对比的两个分句用逗号直接分开","Nối hai vế song song/đối chiếu chỉ bằng dấu phẩy","並列・対比の2節は読点だけでつなぐ"],"w":["ทำได้เพราะโครงสร้างคู่ขนาน (我喝茶 / 他喝牛奶) ชัดเจนอยู่แล้ว ไม่ต้องใส่ 和 หรือคำเชื่อมใด ๆ","Works cleanly because the parallel clause structure makes the contrast obvious without any conjunction.","前后句式对称，“，”就能清楚表达对比并列关系。","Đúng vì hai vế đối xứng rõ ràng, chỉ cần dấu phẩy là đủ.","対称的な2節が読点だけで綺麗に並列・対比される。"],"ref":"HSK 3.0 g3-1-059"},{"ok":false,"zh":"我喝茶和他喝牛奶。","fix":"我喝茶，他喝牛奶。","py":"Wǒ hē chá, tā hē niúnǎi.","tr":["ฉันดื่มชา เขาดื่มนม","I drink tea, and he drinks milk.","Tôi uống trà, anh ấy uống sữa.","私はお茶を飲み、彼は牛乳を飲みます。"],"h":["ห้ามใช้ 和 เชื่อมประโยคย่อย 2 ประโยคแทนจุลภาค","NEVER use 和 to link two full clauses instead of a comma","绝不能用“和”连接两个完整分句","Không dùng 和 nối hai mệnh đề đầy đủ","2つの節を「和」でつないではいけない"],"w":["ไม่ได้ เพราะ 和 เชื่อมได้เฉพาะคำนามหรือกลุ่มคำ (เช่น 茶和牛奶) เท่านั้น ถ้าเชื่อมประโยค 2 ประโยคให้ใช้จุลภาค ， เฉย ๆ","Wrong because 和 only joins nouns/phrases (茶和牛奶), never full clauses — use a comma instead.","不行，“和”只能连接名词短语，连接分句直接用逗号即可。","Không được vì 和 chỉ nối danh từ/cụm từ; nối 2 câu phải dùng dấu phẩy.","「和」は名詞の並列専用。節と節は読点「，」で結ぶ。"],"ref":"HSK 3.0 g3-1-059 · g3-1-023"}],"ex":[["我喝茶，他喝牛奶。","Wǒ hē chá, tā hē niúnǎi.","ฉันดื่มชา เขาดื่มนม","I drink tea, and he drinks milk.","Tôi uống trà, anh ấy uống sữa.","私はお茶を飲み、彼は牛乳を飲みます。","他喝"],["今天很冷，我在家看书。","Jīntiān hěn lěng, wǒ zài jiā kàn shū.","วันนี้หนาวมาก ฉันอ่านหนังสืออยู่บ้าน","It's very cold today, so I'm reading at home.","Hôm nay rất lạnh, tôi ở nhà đọc sách.","今日はとても寒いので家で本を読みます。","在家"],["爸爸是医生，妈妈是老师。","Bàba shì yīshēng, māma shì lǎoshī.","พ่อเป็นหมอ แม่เป็นครู","Dad is a doctor, and Mom is a teacher.","Bố là bác sĩ, mẹ là giáo viên.","父は医者で、母は先生です。","妈妈"],["这个手机太贵了，我不买。","Zhège shǒujī tài guì le, wǒ bù mǎi.","โทรศัพท์เครื่องนี้แพงเกินไป ฉันไม่ซื้อ","This phone is too expensive; I'm not buying it.","Chiếc điện thoại này đắt quá, tôi không mua.","このスマホは高すぎるので買いません。","不买"],["下雨了，我们坐出租车吧。","Xià yǔ le, wǒmen zuò chūzūchē ba.","ฝนตกแล้ว พวกเรานั่งแท็กซี่กันเถอะ","It's raining; let's take a taxi.","Trời mưa rồi, chúng ta đi taxi đi.","雨が降ってきたのでタクシーに乗りましょう。","坐出租车"]],"err":[["爸爸是医生和妈妈是老师。","爸爸是医生，妈妈是老师。","ห้ามใช้ 和 เชื่อมประโยคเต็มสองประโยค ให้ใช้จุลภาคจีน ，","Never link two full clauses with 和; use a comma.","不能用“和”连接两个分句，应改用逗号。","Không dùng 和 nối 2 mệnh đề, dùng dấu phẩy.","2つの節を「和」でつながず読点にする。"]],"rel":["g3-1-060","g3-1-061","g3-1-023"]},"g3-1-060":{"t":["ประโยคความซ้อนคู่ขนาน: ……，也…… (…ก็…ด้วย)","Parallel compound sentences: ……，也…… ('…and also…')","句子的类型·并列复句：……，也……","Câu ghép đẳng lập: ……，也…… (…cũng…)","並列複文：……，也……（〜し、〜も…）"],"f":["主语1 + 谓语1，主语2 + 也 + 谓语1（我是学生，他也是学生）","主语 + 谓语1，也 + 谓语2（我喜欢猫，也喜欢狗）"],"why":["并列复句 “……，也……” ใช้เชื่อมสองประโยคย่อยที่มีลักษณะคล้ายกันหรือคู่ขนานกัน มี 2 รูปแบบหลัก: (1) คนละประธานแต่ทำ/เป็นเหมือนกัน: 我是学生，他也是学生。(ฉันเป็นนักเรียน เขาก็เป็นนักเรียนเหมือนกัน) (2) ประธานคนเดียวกันแต่มี 2 สิ่ง/อาการคู่กัน: 我喜欢猫，也喜欢狗。(ฉันชอบแมว และก็ชอบหมาด้วย) · ข้อควรระวังเด็ดขาด 2 ข้อ: (1) 也 ต้องอยู่ 'หลังประธาน หน้ากริยา' ของประโยคที่สองเสมอ ห้ามวางหน้าประธาน (ห้ามพูด 我是学生，也他是学生!) (2) ในรูปปฏิเสธวาง 也 หน้า 不/没 (我不喝茶，也不喝牛奶)","The parallel compound pattern '……，也……' connects two similar or equal clauses in two ways: (1) Two subjects sharing the same trait/action: 我是学生，他也是学生。; (2) One subject with two equal traits/actions: 我喜欢猫，也喜欢狗。 · Two strict cautions: (1) NEVER place 也 before the second clause's subject (never 也他是学生!). (2) In negatives, put 也 BEFORE 不/没 (也不喝牛奶).","并列复句“……，也……”连接两件相同或平行的情况：（1）不同主语做相同的事（我是学生，他也是学生）；（2）同一主语并列两项情况（我喜欢猫，也喜欢狗）。 · 两条注意：（1）“也”只能放在第二分句主语之后、谓语之前，绝不能放主语前；（2）否定时用“也不／也没”。","Câu ghép đẳng lập '……，也……' nối 2 vế song song: (1) khác chủ ngữ cùng hành động/tính chất (我是学生，他也是学生), (2) cùng chủ ngữ có 2 đặc điểm/hành động (我喜欢猫，也喜欢狗). · Lưu ý: 也 luôn đứng SAU chủ ngữ vế 2, TRƯỚC động/tính từ (không nói 也他是学生); phủ định là 也不.","並列複文「……，也……」は同様の2事態を結ぶ：（1）別の主語が同じ行動・状態（我是学生，他也是学生）、（2）同一主語の2つの動作・好み（我喜欢猫，也喜欢狗）。 · 注意：（1）「也」は必ず第2節の主語の後・動詞の前に置く（也他是学生は不可）。（2）否定は「也不／也没」。"],"use":[{"ok":true,"zh":"我是学生，他也是学生。","fix":"","py":"Wǒ shì xuésheng, tā yě shì xuésheng.","tr":["ฉันเป็นนักเรียน เขาก็เป็นนักเรียนเหมือนกัน","I am a student, and he is a student too.","Tôi là học sinh, anh ấy cũng là học sinh.","私は学生で、彼も学生です。"],"h":["สองประธานเหมือนกัน: ประธาน 2 + 也 + ภาคแสดง","Two subjects with the same trait: Subject 2 + 也 + Predicate","两个主语情况相同：主语2＋也＋谓语","Hai chủ ngữ giống nhau: Chủ ngữ 2 + 也 + Vị ngữ","2つの主語が同じ場合：「主語2＋也＋述語」"],"w":["ทำได้เพราะวาง 也 ไว้หลังประธานที่สอง (他) และหน้ากริยา (是) อย่างถูกต้องแม่นยำ","Works cleanly with 也 placed right after the second subject (他) and before the verb (是).","“也”位于第二分句主语“他”后、动词“是”前，呼应前半句。","Đúng vì 也 đứng sau chủ ngữ 2 (他) và trước động từ (是).","第2節の主語「他」の後ろ・動詞「是」の前に「也」を置いている。"],"ref":"HSK 3.0 g3-1-060 · g3-1-019"},{"ok":true,"zh":"我喜欢猫，也喜欢狗。","fix":"","py":"Wǒ xǐhuan māo, yě xǐhuan gǒu.","tr":["ฉันชอบแมว และก็ชอบหมาด้วย","I like cats, and I also like dogs.","Tôi thích mèo và cũng thích chó.","私は猫が好きで、犬も好きです。"],"h":["ประธานคนเดียวกันสามารถละประธานในประโยคหลังแล้วขึ้น 也 ได้เลย","With the same subject, omit it in clause 2 and start with 也","同一主语时第二分句可省主语，直接用“也＋谓语”","Cùng chủ ngữ thì vế 2 lược chủ ngữ rồi nối 也","同一主語なら第2節の主語を省いて「也＋述語」にできる"],"w":["ทำได้และกระชับมาก เพราะทั้งสองประโยคย่อยมีประธานคือ 我 เหมือนกัน จึงละ 我 ในช่วงหลังได้ทันที","Works concisely because both clauses share subject 我, so clause 2 cleanly omits 我 before 也.","前后主语相同，后句省略“我”，直接用“也喜欢狗”更流畅。","Đúng và gọn vì hai vế cùng chủ ngữ 我 nên vế sau lược 我.","前後で主語「我」が同じなので第2節の主語を省くとすっきりする。"],"ref":"HSK 3.0 g3-1-060"},{"ok":false,"zh":"我是学生，也他是学生。","fix":"我是学生，他也是学生。","py":"Wǒ shì xuésheng, tā yě shì xuésheng.","tr":["ฉันเป็นนักเรียน เขาก็เป็นนักเรียนเหมือนกัน","I am a student, and he is also a student.","Tôi là học sinh, anh ấy cũng là học sinh.","私は学生で、彼も学生です。"],"h":["ห้ามวาง 也 ไว้หน้าประธานของประโยคที่สอง","NEVER place 也 before the subject of the second clause","“也”不能放在主语前面（绝不说“也他是……”）","Không bao giờ đặt 也 trước chủ ngữ vế hai","「也」を第2節の主語の前に置けない"],"w":["ไม่ได้ เพราะ 也 เป็นคำวิเศษณ์ที่ต้องวางหน้ากริยา/คุณศัพท์เท่านั้น ไม่ใช่คำสันธานที่จะยืนหน้าประธานแบบ 'Also, he is…' ต้องย้ายมาหลัง 他: 他也是学生","Wrong because 也 is an adverb, not a sentence-initial conjunction like English 'Also, he…'; always put it after 他: 他也是学生.","不行，“也”是副词不是连词，必须位于主语“他”后、动词前：他也是学生。","Không được vì 也 là phó từ, không đứng trước chủ ngữ như 'Also, he…'; phải đặt sau 他.","「也」は副詞なので主語の前には置けず、必ず「他也是学生」とする。"],"ref":"HSK 3.0 g3-1-060"}],"ex":[["我是学生，他也是学生。","Wǒ shì xuésheng, tā yě shì xuésheng.","ฉันเป็นนักเรียน เขาก็เป็นนักเรียนเหมือนกัน","I am a student, and he is a student too.","Tôi là học sinh, anh ấy cũng là học sinh.","私は学生で、彼も学生です。","也"],["我喜欢猫，也喜欢狗。","Wǒ xǐhuan māo, yě xǐhuan gǒu.","ฉันชอบแมว และก็ชอบหมาด้วย","I like cats, and I also like dogs.","Tôi thích mèo, cũng thích chó.","猫が好きで、犬も好きです。","也"],["爸爸在家，妈妈也在家。","Bàba zài jiā, māma yě zài jiā.","พ่ออยู่บ้าน แม่ก็อยู่บ้านด้วย","Dad is at home, and Mom is at home too.","Bố ở nhà, mẹ cũng ở nhà.","父は家にいて、母も家にいます。","也"],["我不喝茶，也不喝牛奶。","Wǒ bù hē chá, yě bù hē niúnǎi.","ฉันไม่ดื่มชา และก็ไม่ดื่มนมด้วย","I don't drink tea, and I don't drink milk either.","Tôi không uống trà, cũng không uống sữa.","お茶も飲まないし、牛乳も飲みません。","也"],["苹果很便宜，面包也很便宜。","Píngguǒ hěn piányi, miànbāo yě hěn piányi.","แอปเปิลถูกมาก ขนมปังก็ถูกมากเหมือนกัน","Apples are cheap, and bread is cheap too.","Táo rất rẻ, bánh mì cũng rất rẻ.","りんごはとても安く、パンもとても安いです。","也"]],"err":[["我是学生，也他是学生。","我是学生，他也是学生。","也 ต้องวางหลังประธาน (他也是) ห้ามวางหน้าประธาน","Put 也 after the subject (他也是), never before it.","“也”放在主语后面（他也是），不能放主语前。","Đặt 也 sau chủ ngữ (他也是), không đặt trước chủ ngữ.","「也」は主語の後ろ（他也是）に置く。"],["我不喝茶，不也喝牛奶。","我不喝茶，也不喝牛奶。","ปฏิเสธคู่ขนานวาง 也 หน้า 不 เสมอ (也不)","Always put 也 before 不 (也不, never 不也).","固定语序是“也不”，不是“不也”。","Luôn là 也不, không phải 不也.","語順は必ず「也不」で「不也」は不可。"]],"rel":["g3-1-019","g3-1-061","g3-1-059"]},"g3-1-061":{"t":["ประโยคความซ้อนเพิ่มเติม: ……，还…… (…แล้วยัง…อีก)","Additive compound sentences: ……，还…… ('…and also / in addition…')","句子的类型·并列复句：……，还……","Câu ghép bổ sung: ……，还…… (…còn…nữa)","並列・追加複文：……，还……（〜し、さらに…も）"],"f":["同一主语 + 动词1 + 宾语1，还 + 动词2 + 宾语2","例如：我买了苹果，还买了牛奶 / 他会说汉语，还会写汉字"],"why":["并列复句 “……，还……” ใช้เมื่อ 'ประธานคนเดียวกัน' ทำเรื่องที่ 1 แล้วยังมีเรื่องที่ 2 เพิ่มเติมเข้ามาอีก (แปลว่า '…แล้วยัง…อีกด้วย') เช่น 我买了苹果，还买了牛奶 (ฉันซื้อแอปเปิล แล้วยังซื้อนมอีก), 他会说汉语，还会写汉字 (เขาพูดภาษาจีนเป็น แล้วยังเขียนอักษรจีนเป็นอีก) · จุดต่างสำคัญมากระหว่าง 还 กับ 也 ในประโยคความซ้อน: (1) ประธานคนเดียวกันเพิ่มเติมรายการ → ใช้ได้ทั้ง 还 และ 也 (แต่ 还 ให้ความรู้สึก 'แถม/เพิ่มอีก' ชัดกว่า) (2) เปลี่ยนเป็นประธานคนใหม่ (ฉัน… เขาก็…) → ต้องใช้ 也 เท่านั้น ห้ามใช้ 还! (ห้ามพูด 我是学生，他还是学生 เพื่อแปลว่า 'เขาก็เป็นนักเรียนด้วย')","The additive compound pattern '……，还……' adds a second action or ability for the SAME subject ('…and also / in addition…'): 我买了苹果，还买了牛奶。; 他会说汉语，还会写汉字。 · Key contrast between 还 and 也: (1) Same subject adding another item → 还 feels especially natural ('plus…'). (2) Switching to a DIFFERENT subject ('I…, and HE also…') → MUST use 也, NEVER 还 (他还是学生 means 'he is STILL a student', NOT 'he is a student too')!","并列复句“……，还……”表示同一主语在前面情况之外又补充增加另一项（我买了苹果，还买了牛奶；他会说汉语，还会写汉字）。 · 与“也”的关键区别：两分句主语相同时可用“还”表补充；若换了新主语表“同样”（我是学生，他也是学生），必须用“也”，绝不能用“还”！","Câu ghép bổ sung '……，还……' dùng cho CÙNG một chủ ngữ bổ sung thêm hành động/khả năng thứ hai (我买了苹果，还买了牛奶). · Phân biệt 还 vs 也: cùng chủ ngữ bổ sung thêm dùng 还 rất tự nhiên; đổi sang chủ ngữ khác (tôi…, anh ấy cũng…) BẮT BUỘC dùng 也, không dùng 还 (他还是学生 = anh ấy VẪN là học sinh!).","並列・追加複文「……，还……」は同一主語にもう1つ動作や能力を追加する（我买了苹果，还买了牛奶／他会说汉语，还会写汉字）。 · 「也」との重要な違い：別の主語に移って「〜も」と言うときは必ず「也」を使い「还」は使えない（「他还是学生」は「彼はまだ学生だ」になる）。"],"use":[{"ok":true,"zh":"他会说汉语，还会写汉字。","fix":"","py":"Tā huì shuō Hànyǔ, hái huì xiě Hànzì.","tr":["เขาพูดภาษาจีนเป็น แล้วยังเขียนอักษรจีนเป็นด้วย","He can speak Chinese, and can also write Chinese characters.","Anh ấy biết nói tiếng Trung, còn biết viết chữ Hán nữa.","彼は中国語が話せるうえ、漢字も書けます。"],"h":["ประธานคนเดียวกันเสริมความสามารถ/การกระทำที่สอง ใช้ ……，还……","Same subject adding a second ability/action: ……，还……","同一主语补充第二项能力或动作：……，还……","Cùng chủ ngữ bổ sung thêm khả năng/hành động thứ 2: ……，还……","同一主語に能力・行動を追加する「……，还……」"],"w":["ทำได้และสละสลวยมาก เพราะทั้งสองประโยคพูดถึงความสามารถของ 他 คนเดียวกัน จึงละประธานประโยคหลังแล้วใช้ 还 เสริมข้อมูลเพิ่ม","Works smoothly because both clauses add skills of the same subject 他, with 还 highlighting the extra skill.","前后主语均为“他”，“还”自然引出补充能力，语气比“也”更有递进感。","Đúng và tự nhiên vì cả hai vế cùng chủ ngữ 他, 还 nhấn mạnh thêm kỹ năng nữa.","同一主語「他」の能力を「还」で自然に追加している。"],"ref":"HSK 3.0 g3-1-061 · กลุ่มเทียบคำ g16"},{"ok":true,"zh":"我买了苹果，还买了牛奶。","fix":"","py":"Wǒ mǎile píngguǒ, hái mǎile niúnǎi.","tr":["ฉันซื้อแอปเปิล แล้วยังซื้อนมอีก","I bought apples, and also bought milk.","Tôi mua táo, còn mua cả sữa nữa.","りんごを買い、さらに牛乳も買いました。"],"h":["เพิ่มเติมรายการที่ทำ/ซื้อเพิ่ม ใช้ 还 + กริยา","Add extra items bought/done with 还 + verb","补充列举所买或所做之事用“还＋动词”","Bổ sung thêm món đồ đã mua dùng 还 + động từ","買ったもの・したことの追加には「还＋動詞」"],"w":["ทำได้เพราะเป็นประธาน 我 คนเดิมที่ซื้อของ 2 อย่างต่อเนื่องกัน โดยวาง 还 หน้ากริยา 买了 ของประโยคย่อยหลัง","Works cleanly with same subject 我 adding a second purchase, placing 还 before the second verb 买了.","同一主语补充购买清单，“还”放在第二个动词“买”前。","Đúng vì cùng chủ ngữ 我 bổ sung thêm đồ đã mua, đặt 还 trước 买了.","同じ主語「我」がさらに買ったものを「还＋买了」で追加している。"],"ref":"HSK 3.0 g3-1-061"},{"ok":false,"zh":"我去学校，他还去学校。","fix":"我去学校，他也去学校。","py":"Wǒ qù xuéxiào, tā yě qù xuéxiào.","tr":["ฉันไปโรงเรียน เขาก็ไปโรงเรียนเหมือนกัน","I go to school, and he goes to school too.","Tôi đi học, anh ấy cũng đi học.","私は学校へ行き、彼も学校へ行きます。"],"h":["เปลี่ยนประธานเป็นอีกคน ('ฉัน… เขาก็…') ต้องใช้ 也 ไม่ใช่ 还","When switching to a DIFFERENT subject ('I…, and he too'), use 也 — NOT 还","前后主语不同表“同样”必须用“也”，不能用“还”","Đổi sang chủ ngữ khác để nói 'cũng' bắt buộc dùng 也, không dùng 还","別の主語に変わって「〜も」と言うときは「还」ではなく「也」"],"w":["ไม่ได้ตามความหมายที่ต้องการ เพราะ 他还去学校 แปลว่า 'เขายังคงไปโรงเรียนอยู่' ไม่ใช่ 'เขาก็ไปโรงเรียนเหมือนฉัน' พอเปลี่ยนประธาน (我 → 他) ต้องใช้ 也 เท่านั้น","Wrong meaning: 他还去学校 means 'he STILL goes to school', NOT 'he goes too'! Changing subjects (我 → 他) requires 也.","不行，换了主语（我→他）表示“也一样”时只能用“也”；用“还”意思会变成“他仍然去学校”。","Không được vì đổi chủ ngữ (我 → 他) nói 'cũng đi' phải dùng 也; dùng 还 sẽ thành 'anh ấy VẪN đi học'.","主語が「我→他」に変わるときに「还」を使うと「彼はまだ行く」の意味になってしまう。「也」を使う。"],"ref":"กลุ่มเทียบคำ g16 · HSK 3.0 g3-1-061"}],"ex":[["我买了苹果，还买了牛奶。","Wǒ mǎile píngguǒ, hái mǎile niúnǎi.","ฉันซื้อแอปเปิล แล้วยังซื้อนมอีก","I bought apples, and also bought milk.","Tôi mua táo, còn mua cả sữa nữa.","りんごを買い、さらに牛乳も買いました。","还"],["他会说汉语，还会写汉字。","Tā huì shuō Hànyǔ, hái huì xiě Hànzì.","เขาพูดภาษาจีนเป็น แล้วยังเขียนอักษรจีนเป็นด้วย","He can speak Chinese, and can also write characters.","Anh ấy biết nói tiếng Trung, còn biết viết chữ Hán.","彼は中国語が話せ、漢字も書けます。","还"],["我喜欢看书，还喜欢看电影。","Wǒ xǐhuan kàn shū, hái xǐhuan kàn diànyǐng.","ฉันชอบอ่านหนังสือ แล้วยังชอบดูหนังด้วย","I like reading, and I also like watching movies.","Tôi thích đọc sách, còn thích xem phim nữa.","本を読むのが好きで、映画を見るのも好きです。","还"],["我喝了一杯茶，还吃了一个苹果。","Wǒ hēle yī bēi chá, hái chīle yī ge píngguǒ.","ฉันดื่มชาไปหนึ่งแก้ว แล้วยังกินแอปเปิลอีกหนึ่งลูก","I drank a cup of tea, and also ate an apple.","Tôi uống một cốc trà, còn ăn thêm một quả táo.","お茶を1杯飲み、さらにりんごも1個食べました。","还"],["商店有水果，还有面包。","Shāngdiàn yǒu shuǐguǒ, hái yǒu miànbāo.","ร้านค้ามีผลไม้ แล้วยังมีขนมปังด้วย","The shop has fruit, and also has bread.","Cửa hàng có hoa quả, còn có bánh mì nữa.","店には果物があり、さらにパンもあります。","还"]],"err":[["我去学校，他还去学校。","我去学校，他也去学校。","เปลี่ยนประธานคนละคน ('ฉัน… เขาก็…') ใช้ 也 ไม่ใช่ 还","When switching to another subject ('I…, and he too'), use 也 not 还.","前后主语不同表“同样”用“也”，不用“还”。","Đổi sang chủ ngữ khác để nói 'cũng' dùng 也, không dùng 还.","別の主語で「〜も」と言うときは「还」ではなく「也」。"]],"rel":["g3-1-060","g3-1-019","g3-1-059"]},"g3-1-062":{"t":["การณ์ลักษณะสมบูรณ์ (完成态): กริยา + 了1","Completed aspect (完成态): Verb + 了1","动作的态·完成态：用动态助词“了1”表示","Thể hoàn thành (完成态): Động từ + 了1","完了アスペクト（完成态）：動詞＋了1"],"f":["肯定：主语 + 动词 + 了1 + 数量/定语 + 宾语（我买了一本书）","否定：主语 + 没（有）+ 动词 + 宾语（我没买书，去掉“了1”）"],"why":["完成态 (了1) วาง 'ติดหลังกริยา' ทันทีเพื่อบอกว่าการกระทำนั้นเกิดขึ้นและสำเร็จเรียบร้อยแล้ว (ไม่ได้แปลว่าอดีตเสมอไป เพราะบอกเงื่อนไขในอนาคตก็ได้ แต่ใน HSK 1 ใช้กับเหตุการณ์ที่ทำสำเร็จไปแล้วเป็นหลัก) · กฎทอง 3 ข้อที่คนเรียนพลาดบ่อยที่สุด: (1) เมื่อมี 了1 หลังกริยา กรรมที่ตามมามักต้องมีส่วนขยายหรือจำนวนกำกับ (我买了一本书, 他喝了两杯茶 — ไม่ค่อยพูดห้วน ๆ ว่า 我买了书 เฉย ๆ เว้นแต่มีประโยคต่อ) (2) ปฏิเสธว่า 'ไม่ได้ทำ' ต้องใช้ 没(有) และ 'ตัด 了1 ทิ้งเสมอ'! (3) กริยาสภาวะ (是, 在, 认识, 知道) หรือกิจวัตรที่ทำประจำ ไม่ใส่ 了1","Completed aspect 了1 attaches DIRECTLY after a verb to mark that an action has been completed. · Three crucial rules: (1) With Verb + 了1 + Object, the object normally carries a quantity or modifier (我买了一本书, 他喝了两杯茶 — bare 我买了书 sounds unfinished unless followed by another clause). (2) To negate, use 没(有) and ALWAYS DROP 了1 (我没买书). (3) Never put 了1 after static verbs (是, 在, 认识, 知道) or habitual routines.","完成态“了1”紧跟在动词后，表示动作已经完成实现。 · 三条核心规律：（1）“动词＋了1＋宾语”作单句时，宾语通常需带数量词或定语（我买了一本书、他喝了两杯茶），光杆宾语（我买了书）往往显得句子没说完；（2）否定用“没（有）＋动词”，必须去掉“了1”；（3）静态动词（是、认识）及经常性习惯动作不加“了1”。","Thể hoàn thành 了1 đứng NGAY SAU động từ để chỉ hành động đã hoàn tất. · 3 quy tắc quan trọng: (1) Khi đứng một câu độc lập, tân ngữ sau 'động từ + 了1' thường cần số lượng hoặc định ngữ (我买了一本书, 他喝了两杯茶); (2) Phủ định dùng 没(有) và LUÔN BỎ 了1; (3) Không dùng 了1 với động từ trạng thái (是, 认识) hay thói quen lặp lại.","完了アスペクトの「了1」は動詞の直後に付き、動作の実現・完了を表す。 · 3つの鉄則：（1）単独の文では目的語に数量詞や修飾語を伴うのが普通（我买了一本书・他喝了两杯茶）。（2）否定は「没（有）」を使い必ず「了1」を落とす。（3）状態動詞（是・认识）や習慣には付けない。"],"use":[{"ok":true,"zh":"我买了一本汉语书。","fix":"","py":"Wǒ mǎile yī běn Hànyǔ shū.","tr":["ฉันซื้อหนังสือภาษาจีนมาหนึ่งเล่ม","I bought a Chinese textbook.","Tôi đã mua một cuốn sách tiếng Trung.","中国語の本を1冊買いました。"],"h":["กริยา + 了1 + จำนวน/คำขยาย + กรรม (สมบูรณ์จบประโยคได้)","Verb + 了1 + quantity/modifier + object (complete standalone sentence)","“动词＋了1＋数量／定语＋宾语”独立成句","Động từ + 了1 + số lượng/định ngữ + tân ngữ","「動詞＋了1＋数量・修飾語＋目的語」で完結する"],"w":["ทำได้และสมบูรณ์ 100% เพราะกรรม 汉语书 มีจำนวน 一本 กำกับชัดเจน ทำให้ประโยคลงจังหวะจบได้อย่างธรรมชาติ","Works 100% cleanly because object 汉语书 is quantified by 一本, letting the sentence end naturally.","宾语带数量定语“一本汉语书”，单句收束自然完整。","Đúng 100% vì tân ngữ có số lượng 一本 giúp câu kết thúc trọn vẹn.","目的語に数量詞「一本」があるため、単独の文として自然に完結する。"],"ref":"HSK 3.0 g3-1-062 · g3-1-025"},{"ok":true,"zh":"我昨天没买书。","fix":"","py":"Wǒ zuótiān méi mǎi shū.","tr":["เมื่อวานฉันไม่ได้ซื้อหนังสือ","I didn't buy any books yesterday.","Hôm qua tôi không mua sách.","昨日、本を買いませんでした。"],"h":["ปฏิเสธเหตุการณ์ที่ไม่ได้เกิดขึ้น ใช้ 没 + กริยา (และตัด 了1 ออก)","Negate completion with 没 + verb (and DROP 了1)","否定完成态用“没＋动词”，绝不留“了1”","Phủ định thể hoàn thành dùng 没 + động từ (bỏ 了1)","完了の否定は「没＋動詞」（「了1」は必ず落とす）"],"w":["ทำได้เพราะเมื่อการซื้อไม่เกิดขึ้น จึงไม่มีความ 'สำเร็จแล้ว' ของ 了1 ต้องใช้ 没 แทนและตัด 了1 ทิ้งเสมอ","Works because an action that never happened cannot be 'completed' — use 没 and drop 了1.","动作并未发生，所以必须用“没”并去掉“了1”。","Đúng vì hành động chưa xảy ra nên dùng 没 và bỏ 了1.","実現しなかった動作に完了の「了1」は使えず、「没」にして「了1」を落とす。"],"ref":"กลุ่มเทียบคำ g6 · HSK 3.0 g3-1-062"},{"ok":false,"zh":"我昨天没买了书。","fix":"我昨天没买书。","py":"Wǒ zuótiān méi mǎi shū.","tr":["เมื่อวานฉันไม่ได้ซื้อหนังสือ","I didn't buy any books yesterday.","Hôm qua tôi không mua sách.","昨日、本を買いませんでした。"],"h":["ห้ามใส่ 没 กับ 了1 ในประโยคเดียวกัน","NEVER combine 没 and 了1 in the same clause","“没”和“了1”绝不能同现","Không bao giờ dùng 没 và 了1 cùng lúc","「没」と「了1」は絶対に併用できない"],"w":["ไม่ได้ เพราะ 没 (ไม่ได้ทำ) กับ 了1 (ทำสำเร็จแล้ว) ขัดแย้งกันโดยตรง ต้องตัด 了1 ทิ้งเป็น 我昨天没买书","Wrong because 没 ('did not happen') and 了1 ('completed') directly contradict each other.","不行，“没”表未实现，“了1”表已完成，二者不能并存。","Không được vì 没 (chưa xảy ra) mâu thuẫn trực tiếp với 了1 (đã xong).","「没」（未実現）と「了1」（完了）は矛盾するため同時に使えない。"],"ref":"HSK 3.0 g3-1-062 · g3-1-020"},{"ok":false,"zh":"我昨天是了学生。","fix":"他昨天来了学校。","py":"Tā zuótiān láile xuéxiào.","tr":["เมื่อวานเขามาที่โรงเรียน","He came to school yesterday.","Hôm qua anh ấy đã đến trường.","彼は昨日学校に来ました。"],"h":["ห้ามใส่ 了1 หลังกริยาสภาวะอย่าง 是 / 认识 / 知道 (ใช้ได้เฉพาะกริยาการกระทำ)","Never attach 了1 to stative verbs like 是 / 认识 / 知道","“是、认识、知道”等静态动词后不加“了1”","Không gắn 了1 sau động từ trạng thái (是 / 认识 / 知道)","状態動詞（是・认识・知道）に「了1」は付けられない"],"w":["ไม่ได้ เพราะ 了1 แสดงความเสร็จสิ้นของ 'การกระทำ' (เช่น 买了, 喝了, 来了) ไม่ใช่ตัวบอกอดีตแบบ -ed ในภาษาอังกฤษ จึงใส่หลัง 是/在/知道 ไม่ได้","Wrong because 了1 marks completed ACTION (买了, 喝了, 来了), NOT English past tense -ed — it never attaches to 是/在/知道.","不行，“了1”不是英语过去时标记，不能加在“是、在、认识、知道”后，只用于动作动词。","Không được vì 了1 là thể hoàn thành hành động chứ không phải thì quá khứ -ed; không gắn sau 是/认识.","「了1」は過去時制ではなく動作の完了なので「是・在・认识」には付けず、動作動詞に使う。"],"ref":"HSK 3.0 g3-1-062"}],"ex":[["我买了一本书。","Wǒ mǎile yī běn shū.","ฉันซื้อหนังสือหนึ่งเล่ม","I bought a book.","Tôi đã mua một cuốn sách.","本を1冊買いました。","买了"],["他喝了两杯茶。","Tā hēle liǎng bēi chá.","เขาดื่มชาไปสองแก้ว","He drank two cups of tea.","Anh ấy đã uống hai cốc trà.","彼はお茶を2杯飲みました。","喝了"],["妈妈做了很多菜。","Māma zuòle hěn duō cài.","แม่ทำกับข้าวเยอะมาก","Mom cooked a lot of dishes.","Mẹ đã nấu rất nhiều món.","母は料理をたくさん作りました。","做了"],["我吃了一个苹果。","Wǒ chīle yī ge píngguǒ.","ฉันกินแอปเปิลไปหนึ่งลูก","I ate an apple.","Tôi đã ăn một quả táo.","りんごを1個食べました。","吃了"],["我在北京住了三年。","Wǒ zài Běijīng zhùle sān nián.","ฉันอยู่ปักกิ่งมาสามปี","I lived in Beijing for three years.","Tôi đã sống ở Bắc Kinh ba năm.","北京に3年住みました。","住了"]],"err":[["我昨天没买了书。","我昨天没买书。","หลัง 没 ห้ามใส่ 了1 เด็ดขาด","Always drop 了1 after 没.","“没”后必须去掉“了1”。","Sau 没 bắt buộc bỏ 了1.","「没」の後ろでは「了1」を必ず落とす。"],["我昨天买书了一本。","我昨天买了一本书。","了1 ต้องเกาะติดหลังกริยา (买 + 了 + 一本书)","了1 attaches directly to the verb (买 + 了 + 一本书).","“了1”紧跟在动词后：买了一本书。","了1 bám sát ngay sau động từ: 买了一本书.","「了1」は動詞の直後に付ける（买了一本书）。"]],"rel":["g3-1-025","g3-1-063","g3-1-020"]},"g3-1-063":{"t":["การณ์ลักษณะเปลี่ยนแปลง (变化态): …了2 (ท้ายประโยค)","Change-of-state aspect (变化态): sentence-final 了2","动作的态·变化态：用动态助词“了2”表示","Thể biến hóa (变化态): 了2 cuối câu","変化アスペクト（变化态）：文末の「了2」"],"f":["主语 + 动词 / 形容词 / 数量 + 了2（下雨了 / 天气冷了 / 他病了 / 我二十岁了）"],"why":["变化态 (了2) วางไว้ 'ท้ายประโยค' เพื่อบอกว่า 'เกิดสถานการณ์ใหม่ / เปลี่ยนจากสภาพเดิมไปแล้ว' เช่น จากไม่ตก → 下雨了 (ฝนตกแล้ว), จากไม่ป่วย → 他病了 (เขาป่วยแล้ว), จากไม่หนาว → 天气冷了 (อากาศหนาวขึ้นแล้ว), จาก 19 ขวบ → 我二十岁了 (ฉันอายุยี่สิบแล้ว) · จุดสำคัญที่คนเรียนมักพลาด: คำว่า 病 (ป่วย) ในภาษาจีนเป็นกริยาบอกการเปลี่ยนแปลงสภาพ จึงต้องใส่ 了2 ต่อท้ายเป็น 他病了 (ห้ามพูดห้วน ๆ ว่า 他病!) · ข้อควรระวัง: พอใช้ 了2 บอกความเปลี่ยนแปลง (天气冷了) ไม่ต้องใส่ 很 นำหน้าคุณศัพท์ (ไม่พูด 天气很冷了 เว้นแต่จะแปลว่าหนาวมากแล้วในบริบทเฉพาะ)","Change-of-state 了2 sits at the END of a sentence to signal a NEW situation or change from before: 下雨了 ('it started raining'), 他病了 ('he got sick'), 天气冷了 ('it turned cold'), 我二十岁了 ('I've turned 20'). · Classic learner mistake from our reference docs: 病 ('get sick') needs 了2 → 他病了 (NEVER bare 他病!). · Note: Adjective + 了2 does not need 很 (天气冷了 = 'it's gotten cold').","变化态“了2”位于句末，表示出现了新情况或状态发生了变化：下雨了、他病了、天气冷了、我二十岁了。 · 经典易错点：“病”表进入生病状态，必须说“他病了”（绝不说“他病”）。 · 注意：形容词加“了2”表变化时通常不加“很”（天气冷了）。","Thể biến hóa 了2 đứng CUỐI câu báo hiệu tình huống mới / sự thay đổi trạng thái: 下雨了 (trời mưa rồi), 他病了 (anh ấy ốm rồi), 天气冷了 (trời lạnh rồi), 我二十岁了 (tôi 20 tuổi rồi). · Lỗi kinh điển: phải nói 他病了 (KHÔNG nói trống 他病!).","変化アスペクトの「了2」は文末に置き、新しい状況・状態の変化を表す：下雨了、他病了、天气冷了、我二十岁了。 · 定番ミス：「病」は単独で言わず必ず「他病了」にする（「他病」は不可）。 · 形容詞＋「了2」は普通「很」を付けない（天气冷了）。"],"use":[{"ok":true,"zh":"他病了，今天不去上班。","fix":"","py":"Tā bìng le, jīntiān bù qù shàngbān.","tr":["เขาป่วยแล้ว วันนี้ไม่ไปทำงาน","He got sick, so he isn't going to work today.","Anh ấy ốm rồi, hôm nay không đi làm.","彼は病気になったので今日仕事に行きません。"],"h":["เกิดสภาพใหม่ (ป่วย / ฝนตก / หนาวขึ้น) ใส่ 了2 ปิดท้ายประโยค","Mark a newly occurred state (sick / raining / colder) with sentence-final 了2","出现新状态（病了、下雨了、冷了）句末加“了2”","Trạng thái mới xuất hiện (病了, 下雨了, 冷了) thêm 了2 cuối câu","新しい状態の発生（病了・下雨了・冷了）は文末に「了2」"],"w":["ทำได้และจำเป็นมาก เพราะ 病 บอกการเปลี่ยนจากปกติเป็นป่วย การใส่ 了2 ปิดท้ายทำให้ประโยคสมบูรณ์และเป็นธรรมชาติ 100%","Works and is essential: 病 describes entering a state of illness, so final 了2 makes 他病了 complete and natural.","“病”进入新状态须带句尾“了2”（他病了），完整自然。","Đúng và bắt buộc: 病 chỉ sự chuyển sang trạng thái ốm nên cần 了2 (他病了).","「病」は病気という状態への変化を表すため文末の「了2」が不可欠。"],"ref":"เสริม w3-00012 · HSK 3.0 g3-1-063"},{"ok":true,"zh":"现在八点了，我们上课吧。","fix":"","py":"Xiànzài bā diǎn le, wǒmen shàngkè ba.","tr":["ตอนนี้แปดโมงแล้ว พวกเราเข้าเรียนกันเถอะ","It's 8 o'clock now; let's start class.","Bây giờ 8 giờ rồi, chúng ta vào học thôi.","もう8時になりました、授業を始めましょう。"],"h":["บอกเวลาหรืออายุที่มาถึงจุดใหม่แล้ว ใช้ เวลา/อายุ + 了2","Use Time/Age + 了2 to signal a new time or age reached","时间、年龄进入新阶段用“……了2”（八点了、二十岁了）","Thời gian/tuổi đạt mốc mới dùng Thời gian/Tuổi + 了2","時刻や年齢が新しい段階に達したとき「…了2」"],"w":["ทำได้เพราะ 了2 เตือนให้ผู้ฟังรู้ว่าเวลาเดินมาถึง 8 โมงแล้ว (เปลี่ยนจากก่อนหน้านี้) จึงชวนให้เริ่มเรียนต่อทันที","Works because 了2 highlights that 8:00 has now arrived, prompting the next action.","“八点了”提示时间已到新节点，引出后面的行动建议。","Đúng vì 了2 báo hiệu đã đến mốc 8 giờ rồi để dẫn sang hành động tiếp theo.","「八点了」で8時になったという変化を示し、次の行動へつなげている。"],"ref":"HSK 3.0 g3-1-063"},{"ok":false,"zh":"他病，今天不去学校。","fix":"他病了，今天不去学校。","py":"Tā bìng le, jīntiān bù qù xuéxiào.","tr":["เขาป่วยแล้ว วันนี้ไม่ไปโรงเรียน","He is sick, so he isn't going to school today.","Anh ấy ốm rồi, hôm nay không đi học.","彼は病気なので今日学校に行きません。"],"h":["ห้ามพูด 他病 เฉย ๆ โดยไม่มี 了2","NEVER say bare 他病 without 了2","不能光说“他病”，必须说“他病了”","Không nói trống 他病 mà phải nói 他病了","裸の「他病」は不可、必ず「他病了」"],"w":["ไม่ได้ตามเอกสารอ้างอิง เสริม w3-00012 เพราะ 病 ตัวเดียวโดด ๆ ไม่สามารถยืนเป็นภาคแสดงสมบูรณ์ได้ ต้องเติม 了2 เป็น 他病了 เสมอ","Wrong per reference doc w3-00012: bare 病 cannot stand alone as a predicate — always add 了2 (他病了).","不行，单音节动词“病”不能光杆作谓语，必须加“了2”说“他病了”。","Không được vì 病 đứng lẻ không làm vị ngữ trọn vẹn; bắt buộc thêm 了2 thành 他病了.","1音節の「病」は単独で述語になれず、必ず「他病了」と「了2」を付ける。"],"ref":"เสริม w3-00012"}],"ex":[["他病了。","Tā bìng le.","เขาป่วยแล้ว","He got sick.","Anh ấy ốm rồi.","彼は病気になりました。","了"],["下雨了！","Xià yǔ le!","ฝนตกแล้ว!","It's started raining!","Trời mưa rồi!","雨が降ってきました！","了"],["天气冷了。","Tiānqì lěng le.","อากาศหนาวขึ้นแล้ว","The weather has turned cold.","Thời tiết lạnh rồi.","寒くなってきました。","了"],["我二十岁了。","Wǒ èrshí suì le.","ฉันอายุยี่สิบปีแล้ว","I am twenty years old now.","Tôi 20 tuổi rồi.","私は20歳になりました。","了"],["现在九点了。","Xiànzài jiǔ diǎn le.","ตอนนี้เก้าโมงแล้ว","It's nine o'clock now.","Bây giờ là 9 giờ rồi.","もう9時になりました。","了"]],"err":[["他病。","他病了。","คำว่า 病 (ป่วย) ต้องมี 了2 ปิดท้ายเสมอ (他病了)","病 ('sick') requires sentence-final 了2 (他病了).","“病”作谓语必须加“了2”（他病了）。","病 làm vị ngữ bắt buộc có 了2 (他病了).","「病」を述語にするときは必ず「他病了」。"],["现在下雨。","现在下雨了。","บอกสภาพอากาศที่เพิ่งเริ่มเกิด ใช้ 下雨了","Use 下雨了 when rain has started.","天气变化开始下雨用“下雨了”。","Báo trời bắt đầu mưa dùng 下雨了.","雨が降り出した変化には「下雨了」。"]],"rel":["g3-1-062","g3-1-026","g3-1-045"]},"g3-1-064":{"t":["การณ์ลักษณะกำลังกระทำ 1 (进行态1): ……在 / 正在 + กริยา","Progressive aspect 1 (进行态1): Subject + 在 / 正在 + Verb","动作的态·进行态（1）：……在/正在+动词","Thể tiếp diễn 1 (进行态1): ……在 / 正在 + Động từ","進行アスペクト1（进行态1）：……在／正在＋動詞"],"f":["肯定：主语 + 在 / 正在 + 动词 +（宾语）","否定：主语 + 没（有）在 + 动词（不用“不在”或“没正在”）"],"why":["进行态 แบบที่ 1 ใช้ 在 หรือ 正在 วางหน้ากริยาการกระทำเพื่อบอกว่า 'กำลังทำสิ่งนั้นอยู่ในขณะนี้' เช่น 我在看书 (ฉันกำลังอ่านหนังสือ), 妈妈正在做饭 (แม่กำลังทำกับข้าว) · ต่างกันนิดเดียว: 正在 เน้นจังหวะ 'กำลังทำอยู่เดี๋ยวนี้พอดี' ชัดกว่า 在 · ข้อควรระวัง 3 ข้อ: (1) ปฏิเสธว่า 'ไม่ได้กำลังทำ' ใช้ 没(有)在 + กริยา (他没在看电视) ห้ามใช้ 没正在 หรือ 不在 (2) ใช้ได้กับกริยาที่ดำเนินต่อเนื่องได้ (看书, 吃饭, 做饭, 睡觉, 说话) ห้ามใช้กับกริยาสภาวะ (是, 有, 认识, 知道) หรือกริยาจบในเสี้ยววินาที (到, 看见) (3) ห้ามใส่ 了1 ปน","Progressive pattern 1 places 在 or 正在 before an action verb ('be doing'): 我在看书, 妈妈正在做饭 (正在 emphasizes 'right at this very moment'). · Three cautions: (1) Negate with 没(有)在 + Verb (never 没正在 or 不在 + action). (2) Only use durative actions — NEVER static verbs (是, 有, 认识, 知道) or instant events (到). (3) Never add completed 了1.","进行态（1）用“在／正在＋动词”表示动作正在持续进行（我在看书、妈妈正在做饭），“正在”更强调此时此刻。 · 三条注意：（1）否定用“没（有）在＋动词”，不说“没正在”；（2）不能用于静态动词（是、有、认识）或瞬间动词（到）；（3）不能和“了1”连用。","Thể tiếp diễn (1) dùng 在 / 正在 + động từ để chỉ hành động đang diễn ra (我在看书, 妈妈正在做饭). · 3 lưu ý: (1) Phủ định dùng 没(有)在 + động từ (không nói 没正在); (2) Không dùng với động từ trạng thái (是, 有, 认识) hay tức thời (到); (3) Không đi chung với 了1.","進行アスペクト（1）は「在／正在＋動詞」で動作の進行中を表す（我在看书・妈妈正在做饭）。 · 3大注意：（1）否定は「没（有）在＋動詞」（没正在は不可）。（2）状態動詞（是・有・认识）や瞬間動詞（到）には使えない。（3）完了の「了1」と併用不可。"],"use":[{"ok":true,"zh":"妈妈正在做饭。","fix":"","py":"Māma zhèngzài zuòfàn.","tr":["แม่กำลังทำกับข้าวอยู่","Mom is cooking right now.","Mẹ đang nấu cơm.","母は今ご飯を作っています。"],"h":["เน้นว่ากำลังทำอยู่เดี๋ยวนี้พอดี ใช้ 正在 + กริยาต่อเนื่อง","Emphasize 'right now in progress' with 正在 + action verb","强调此刻正在进行用“正在＋动作动词”","Nhấn mạnh ngay lúc này đang làm dùng 正在 + động từ","「今ちょうど〜している」は「正在＋動作動詞」"],"w":["ทำได้เพราะ 做饭 (ทำกับข้าว) เป็นกริยาการกระทำที่มีช่วงเวลาต่อเนื่องชัดเจน จึงใช้กับ 正在 ได้อย่างลงตัว","Works cleanly because 做饭 ('cook') is an ongoing dynamic activity ideal for 正在.","“做饭”是持续性动作，配“正在”准确表达此刻正在进行。","Đúng vì 做饭 là hành động có quá trình kéo dài, hợp hoàn toàn với 正在.","「做饭」は継続する動作なので「正在」と完璧に合う。"],"ref":"HSK 3.0 g3-1-064 · g3-1-017"},{"ok":true,"zh":"我没在睡觉，我在学习。","fix":"","py":"Wǒ méi zài shuìjiào, wǒ zài xuéxí.","tr":["ฉันไม่ได้กำลังนอน ฉันกำลังเรียนอยู่","I'm not sleeping; I'm studying.","Tôi không đang ngủ, tôi đang học.","寝ていません、勉強しています。"],"h":["ปฏิเสธความกำลังทำ ใช้ 没在 + กริยา (ตัด 正 ออก)","Negate progressive with 没在 + verb (drop 正)","否定进行态用“没在＋动词”（不说“没正在”）","Phủ định đang làm dùng 没在 + động từ (bỏ 正)","進行の否定は「没在＋動詞」（「正」は入れない）"],"w":["ทำได้เพราะภาษาจีนใช้ 没 นำหน้า 在 เพื่อปฏิเสธว่าไม่ได้กำลังทำกริยานั้นอยู่ แล้วแก้ข้อมูลต่อด้วย 我在学习","Works because Chinese negates progressive actions with 没在 (never 没正在), then states what you ARE doing.","否定进行态固定用“没（有）在＋动词”，然后用“在＋动词”说明实际正在做的事。","Đúng vì phủ định tiếp diễn dùng 没在 (bỏ 正) rồi nêu việc đang làm với 在.","進行形の否定は「没在＋動詞」で固定されており、「没正在」とは言わない。"],"ref":"HSK 3.0 g3-1-064"},{"ok":false,"zh":"他没正在看电视。","fix":"他没在看电视。","py":"Tā méi zài kàn diànshì.","tr":["เขาไม่ได้กำลังดูทีวี","He isn't watching TV.","Anh ấy không đang xem TV.","彼はテレビを見ていません。"],"h":["ห้ามพูด 没正在 (ต้องตัด 正 เหลือ 没在)","Never say 没正在 — drop 正 to form 没在","否定进行态绝不说“没正在”，只说“没在”","Không nói 没正在 — phải bỏ 正 thành 没在","「没正在」は不可、必ず「没在」にする"],"w":["ไม่ได้ เพราะในรูปปฏิเสธของ 正在 ภาษาจีนตัดคำว่า 正 ทิ้งเสมอ เหลือแค่ 没(有)在 + กริยา เท่านั้น","Wrong because the negative of 正在 always drops 正, leaving 没(有)在 + verb.","不行，“正在”的否定必须去掉“正”，说“没（有）在看电视”。","Không được vì phủ định của 正在 luôn bỏ 正, chỉ giữ 没(有)在.","「正在」の否定では必ず「正」を省き「没（有）在」にする。"],"ref":"HSK 3.0 g3-1-064"}],"ex":[["我在看书。","Wǒ zài kàn shū.","ฉันกำลังอ่านหนังสือ","I am reading a book.","Tôi đang đọc sách.","本を読んでいます。","在"],["妈妈正在做饭。","Māma zhèngzài zuòfàn.","แม่กำลังทำกับข้าว","Mom is cooking.","Mẹ đang nấu cơm.","母は料理を作っています。","正在"],["孩子在睡觉。","Háizi zài shuìjiào.","ลูกกำลังนอนหลับ","The child is sleeping.","Đứa bé đang ngủ.","子どもは寝ています。","在"],["爸爸正在打电话。","Bàba zhèngzài dǎ diànhuà.","พ่อกำลังโทรศัพท์อยู่","Dad is on the phone.","Bố đang gọi điện thoại.","父は電話をかけています。","正在"],["他没在看电视。","Tā méi zài kàn diànshì.","เขาไม่ได้กำลังดูทีวี","He isn't watching TV.","Anh ấy không đang xem TV.","彼はテレビを見ていません。","没在"]],"err":[["他没正在看电视。","他没在看电视。","ปฏิเสธ 正在 ต้องตัด 正 เหลือ 没在 เสมอ","Negating 正在 always drops 正 → 没在.","“正在”的否定用“没在”，不说“没正在”。","Phủ định của 正在 luôn là 没在, không nói 没正在.","「正在」の否定は「没正在」ではなく「没在」。"],["我正在知道他的名字。","我知道他的名字。","知道 เป็นกริยาสภาวะ ใช้กับ 正在 ไม่ได้","Stative verb 知道 cannot take 正在.","静态动词“知道”不能用“正在”。","Động từ trạng thái 知道 không dùng 正在.","状態動詞「知道」に「正在」は付けられない。"]],"rel":["g3-1-065","g3-1-066","g3-1-017"]},"g3-1-065":{"t":["การณ์ลักษณะกำลังกระทำ 2 (进行态2): ……在 / 正在 + กริยา… + 呢","Progressive aspect 2 (进行态2): Subject + 在/正在 + Verb… + 呢","动作的态·进行态（2）：……在/正在+动词……+呢","Thể tiếp diễn 2 (进行态2): ……在 / 正在 + Động từ… + 呢","進行アスペクト2（进行态2）：……在／正在＋動詞…＋呢"],"f":["主语 + 在 / 正在 + 动词 +（宾语）+ 呢"],"why":["进行态 แบบที่ 2 คือการนำ 在/正在 หน้ากริยามาจับคู่กับคำช่วยท้ายประโยค 呢 (เช่น 我正在吃饭呢, 他在看书呢) · 呢 ท้ายประโยคช่วยทำ 2 อย่าง: (1) ย้ำให้เห็นภาพชัดเจนว่าเหตุการณ์กำลังดำเนินอยู่จริงในตอนนั้น ('กำลัง…อยู่เลยนะ') (2) ทำให้น้ำเสียงการสนทนาอ่อนโยนและเป็นกันเองมากขึ้น · ข้อควรระวังสำคัญ 2 ข้อ: (1) ห้ามเอา 呢 ไปวางคู่กับ 吗 ท้ายประโยคคำถามเดียวกัน (你在看书呢吗？ ผิด! — ถามว่ากำลังทำอยู่ไหมใช้ 你在看书吗？) (2) รูปปฏิเสธ 没在… ไม่ใส่ 呢 ปิดท้าย","Progressive pattern 2 pairs pre-verbal 在/正在 with sentence-final 呢 (我正在吃饭呢, 他在看书呢). · Final 呢 adds vividness ('right in the middle of it!') and a warm conversational tone. · Two strict cautions: (1) NEVER combine 呢 with 吗 at the end of a question (never 你在看书呢吗？ — just say 你在看书吗？). (2) Don't put progressive 呢 on negative 没在 sentences.","进行态（2）将动词前的“在／正在”与句末的“呢”前后呼应（我正在吃饭呢、他在看书呢），不仅强调动作正在进行，还带有生动亲切的口语语气。 · 两条注意：（1）疑问句中绝不能将“呢”和“吗”连用（说“你在看书吗？”，不说“你在看书呢吗？”）；（2）否定句“没在……”句末一般不加表进行的“呢”。","Thể tiếp diễn (2) kết hợp 在/正在 trước động từ và 呢 cuối câu (我正在吃饭呢, 他在看书呢) giúp giọng nói sinh động, thân mật và nhấn mạnh hành động đang xảy ra. · Lưu ý: KHÔNG ghép 呢 + 吗 trong câu hỏi (chỉ nói 你在看书吗？).","進行アスペクト（2）は「在／正在」と文末の「呢」を呼応させる形（我正在吃饭呢・他在看书呢）。生き生きとした親しみのある口語表現になる。 · 注意：疑問文で「呢」と「吗」は重ねられない（你在看书吗？にする）。"],"use":[{"ok":true,"zh":"爸爸正在喝茶呢。","fix":"","py":"Bàba zhèngzài hē chá ne.","tr":["พ่อกำลังดื่มชาอยู่เลย","Dad is drinking tea right now.","Bố đang uống trà đấy.","父は今お茶を飲んでいるところです。"],"h":["ใช้คู่ 正在…呢 ในบทสนทนาเพื่อเน้นความกำลังทำอยู่","Pair 正在…呢 in speech to vividly mark an ongoing action","“正在＋动词……＋呢”生动表现正在进行","Kết hợp 正在…呢 trong hội thoại để nhấn mạnh đang làm","「正在…呢」の呼応で進行中を生き生きと表す"],"w":["ทำได้และเป็นธรรมชาติมากเวลาตอบคำถามว่า 'พ่อทำอะไรอยู่?' (爸爸在做什么呢？ → 爸爸正在喝茶呢)","Works naturally especially when answering 'What is Dad doing?' with a warm conversational feel.","回答“爸爸在做什么？”时，用“正在……呢”前后呼应最地道生动。","Đúng và rất tự nhiên khi đáp câu hỏi 'Bố đang làm gì vậy?'.","「お父さんは何をしているの？」への返答として非常に自然。"],"ref":"HSK 3.0 g3-1-065 · g3-1-026"},{"ok":true,"zh":"你在看书吗？","fix":"","py":"Nǐ zài kàn shū ma?","tr":["คุณกำลังอ่านหนังสืออยู่ไหม","Are you reading a book?","Bạn đang đọc sách à?","今、本を読んでいますか。"],"h":["ถามใช่/ไม่ใช่ว่ากำลังทำอยู่ไหม ใช้ 在…吗？ (ตัด 呢 ออก)","Ask yes/no progressive questions with 在…吗？ (drop 呢)","是非问句问是否正在进行用“在……吗？”，不加“呢”","Hỏi có đang làm không dùng 在…吗？ (bỏ 呢)","進行中の諾否疑問文は「呢」を省いて「在…吗？」"],"w":["ทำได้เพราะเมื่อมีคำถาม 吗 อยู่ท้ายประโยคแล้ว ต้องตัด 呢 ออกไม่ให้ซ้อนคำช่วยท้ายประโยคสองตัว","Works cleanly because dropping 呢 avoids clashing with question particle 吗 at sentence end.","句末有“吗”表是非疑问时，须省去“呢”避免语气词连用。","Đúng vì đã có 吗 cuối câu thì phải bỏ 呢 để tránh chồng trợ từ.","文末に疑問の「吗」を置くときは「呢」を省くのが正しい。"],"ref":"HSK 3.0 g3-1-065"},{"ok":false,"zh":"你在看书呢吗？","fix":"你在看书吗？","py":"Nǐ zài kàn shū ma?","tr":["คุณกำลังอ่านหนังสืออยู่ไหม","Are you reading a book?","Bạn đang đọc sách à?","本を読んでいますか。"],"h":["ห้ามเอา 呢 กับ 吗 มาวางติดกันท้ายประโยค","NEVER stack 呢 and 吗 together at sentence end","“呢”和“吗”不能在句末连用","Tuyệt đối không ghép 呢 + 吗 cuối câu","文末に「呢」と「吗」を重ねてはいけない"],"w":["ไม่ได้ เพราะ 呢 กับ 吗 ต่างเป็นคำช่วยน้ำเสียงท้ายประโยคที่วางซ้อนกันไม่ได้ ถ้าจะถามใช่/ไม่ใช่ให้ตัด 呢 เหลือ 你在看书吗？ (แต่ถ้าเป็นคำถาม Wh อย่าง 你在看什么呢？ ใช้ 呢 ได้!)","Wrong because 呢 and 吗 cannot stack at sentence end — drop 呢 for yes/no questions (though wh-questions like 你在看什么呢？ CAN keep 呢!).","不行，“呢”和“吗”不能叠用；是非问用“你在看书吗？”，特指问则可用“你在看什么呢？”。","Không được vì 呢 và 吗 không đứng cạnh nhau; câu hỏi 吗 phải bỏ 呢 (còn 你在看什么呢？ thì dùng 呢 được).","「呢」と「吗」は併用不可（諾否疑問文は「你在看书吗？」、疑問詞疑問文なら「你在看什么呢？」が可能）。"],"ref":"HSK 3.0 g3-1-065 · g3-1-047"}],"ex":[["我在看书呢。","Wǒ zài kàn shū ne.","ฉันกำลังอ่านหนังสืออยู่เลย","I'm reading a book right now.","Tôi đang đọc sách đây.","今、本を読んでいるところです。","呢"],["爸爸正在喝茶呢。","Bàba zhèngzài hē chá ne.","พ่อกำลังดื่มชาอยู่เลย","Dad is drinking tea right now.","Bố đang uống trà đấy.","父は今お茶を飲んでいますよ。","呢"],["他们在说话呢。","Tāmen zài shuōhuà ne.","พวกเขากำลังคุยกันอยู่","They are talking right now.","Họ đang nói chuyện đấy.","彼らは今話していますよ。","呢"],["妈妈正在做饭呢。","Māma zhèngzài zuòfàn ne.","แม่กำลังทำกับข้าวอยู่เลย","Mom is cooking right now.","Mẹ đang nấu cơm đấy.","母は今ご飯を作っていますよ。","呢"],["你在看什么呢？","Nǐ zài kàn shénme ne?","คุณกำลังดูอะไรอยู่เหรอ","What are you watching / reading?","Bạn đang xem gì thế?","何を見ているんですか。","呢"]],"err":[["你在看书呢吗？","你在看书吗？","ห้ามวาง 呢 กับ 吗 ซ้อนกันท้ายประโยค","Never combine 呢 and 吗 at the end of a sentence.","“呢”和“吗”不能在句末连用。","Không ghép 呢 và 吗 ở cuối câu.","文末に「呢」と「吗」を重ねない。"]],"rel":["g3-1-064","g3-1-066","g3-1-026"]},"g3-1-066":{"t":["การณ์ลักษณะกำลังกระทำ 3 (进行态3): ……呢 (ละ 在/正在)","Progressive aspect 3 (进行态3): Verb + Object + 呢","动作的态·进行态（3）：……呢","Thể tiếp diễn 3 (进行态3): ……呢 (lược 在/正在)","進行アスペクト3（进行态3）：……呢（在／正在を省略）"],"f":["主语 + 动词 +（宾语）+ 呢（我看书呢 / 外边下雨呢 / 他睡觉呢）"],"why":["进行态 แบบที่ 3 เป็นสำนวนภาษาพูดที่สั้น กระชับ และเป็นธรรมชาติมากในชีวิตประจำวัน: ละ 在 / 正在 ข้างหน้าทิ้ง เหลือเพียงคำช่วย 呢 ท้ายประโยคตัวเดียวก็สื่อได้ว่า 'กำลังทำอยู่เลย!' · เช่น แม่ถามว่าทำอะไรอยู่ → 我看书呢 (อ่านหนังสืออยู่นะ), 他睡觉呢 (เขานอนหลับอยู่), 外边下雨呢 (ข้างนอกฝนกำลังตกอยู่เลย) · ข้อควรระวัง: (1) ระวังแยกความหมาย 呢 2 แบบใน HSK 1: ท้ายกริยาบอกเล่า = กำลังทำอยู่ (我看书呢) vs ท้ายคำนาม/สรรพนามที่มีเครื่องหมายคำถาม = 'แล้ว…ล่ะ / …อยู่ที่ไหน?' (你呢？ / 我的书呢？) (2) ห้ามใช้กับกริยาสภาวะอย่าง 我是学生呢 หรือปฏิเสธด้วย 没","Progressive pattern 3 is lively everyday speech: omit 在/正在 and let sentence-final 呢 ALONE mark an action in progress! · Examples: 我看书呢 ('I'm reading'), 他睡觉呢 ('He's sleeping'), 外边下雨呢 ('It's raining outside'). · Cautions: (1) Distinguish progressive 呢 after a verb phrase (我看书呢) from question 呢 after a noun/pronoun (你呢？ 'And you?'; 我的书呢？ 'Where's my book?'). (2) Don't pair progressive 呢 with completed 了1 or negative 没.","进行态（3）省略动词前的“在／正在”，只用句末的“呢”同样可以表示动作正在进行，语气轻松自然，非常口语化：我看书呢、他睡觉呢、外边下雨呢。 · 注意区分“呢”的两种用法：接在动作句末表进行（我看书呢）；接在名词／代词后表简略疑问（你呢？我的书呢？）。","Thể tiếp diễn (3) lược bỏ 在/正在, chỉ giữ 呢 ở cuối câu vẫn diễn tả 'đang làm gì' rất tự nhiên trong khẩu ngữ: 我看书呢, 他睡觉呢, 外边下雨呢. · Lưu ý phân biệt với 呢 hỏi ngược sau danh/đại từ (你呢？/ 我的书呢？).","進行アスペクト（3）は「在／正在」を省き、文末の「呢」だけで進行中を表すくだけた口語表現：我看书呢、他睡觉呢、外边下雨呢。 · 名詞・代名詞の後ろで「〜は？」と尋ねる「呢」（你呢？・我的书呢？）と区別しよう。"],"use":[{"ok":true,"zh":"外边下雨呢。","fix":"","py":"Wàibian xià yǔ ne.","tr":["ข้างนอกฝนกำลังตกอยู่เลย","It's raining outside right now.","Bên ngoài trời đang mưa đấy.","外は雨が降っていますよ。"],"h":["ละ 在/正在 แล้วใช้ 呢 ท้ายประโยคเพื่อบอกว่ากำลังเกิดขึ้นอยู่","Drop 在/正在 and use 呢 alone to show an event currently happening","省去“在／正在”，单用句末“呢”表正在进行","Lược 在/正在, chỉ giữ 呢 cuối câu để chỉ việc đang diễn ra","「在／正在」を省き文末の「呢」だけで進行中を表す"],"w":["ทำได้และเป็นธรรมชาติมากในการบอกสถานการณ์ตอนนี้ (เทียบกับ 外边下雨了 ที่เน้นว่า 'เพิ่งเริ่มตกแล้ว' ส่วน 外边下雨呢 เน้นว่า 'กำลังตกอยู่เลย')","Works very naturally for ongoing conditions (contrast 外边下雨了 'it started raining' vs 外边下雨呢 'it's raining right now').","“外边下雨呢”强调此刻正持续在下雨（区别于表变化的“下雨了”）。","Đúng và rất tự nhiên (khác 下雨了 nhấn mạnh vừa bắt đầu mưa, 下雨呢 nhấn mạnh đang rơi).","「下雨了」（降り出した）と違い、「下雨呢」は今まさに降っている最中であることを表す。"],"ref":"HSK 3.0 g3-1-066"},{"ok":true,"zh":"我很好，你呢？","fix":"","py":"Wǒ hěn hǎo, nǐ ne?","tr":["ฉันสบายดี แล้วคุณล่ะ","I'm very well, and you?","Tôi rất khỏe, còn bạn thì sao?","私は元気です、あなたは？"],"h":["ระวังแยกหน้าที่: นาม/สรรพนาม + 呢？ = ถามย้อน (ไม่ใช่กำลังทำอยู่)","Distinguish Noun/Pronoun + 呢？ ('what about…?'), not progressive","注意区分：名词／代词＋“呢？”表简略疑问，而非进行态","Phân biệt: Danh/đại từ + 呢？ là câu hỏi ngược (không phải tiếp diễn)","区別：名詞・代名詞＋「呢？」は省略疑問文であり進行ではない"],"w":["ทำได้เพราะ 呢 มีหลายหน้าที่ใน HSK 1: อยู่หลังประโยคกริยา = กำลังทำอยู่ (我看书呢) ส่วนอยู่หลังสรรพนาม/คำนามพร้อม ？ = ถามย้อนหรือถามหา (你呢？ / 我的手机呢？)","Works because 呢 has two distinct HSK 1 roles: after a verb clause = progressive (我看书呢); after a noun/pronoun + ? = 'what about / where is…?' (你呢？).","“呢”一词多用：动作句尾表进行，名词代词后表“……怎么样／在哪儿？”。","Đúng vì 呢 có 2 vai trò khác nhau: sau cụm động từ là tiếp diễn, sau đại từ là hỏi ngược.","「呢」は動詞文の末尾なら進行、名詞・代名詞の後ろなら「〜は（どう／どこ）？」の疑問。"],"ref":"กลุ่มเทียบคำ g13 · HSK 3.0 g3-1-066"},{"ok":false,"zh":"我看了书呢。","fix":"我看书呢。","py":"Wǒ kàn shū ne.","tr":["ฉันกำลังอ่านหนังสืออยู่นะ","I'm reading right now.","Tôi đang đọc sách đây.","今、本を読んでいるところです。"],"h":["ห้ามเอา 了1 (เสร็จแล้ว) มาใช้คู่กับ 呢 (กำลังทำอยู่)","Never mix completed 了1 with progressive 呢","表完成的“了1”不能和表进行的“呢”混用","Không trộn 了1 (đã xong) với 呢 (đang làm)","完了の「了1」と進行の「呢」を混ぜない"],"w":["ไม่ได้ เพราะ 了1 แปลว่าทำเสร็จไปแล้ว ส่วน 呢 ในรูปนี้แปลว่ากำลังทำอยู่ยังไม่เสร็จ ความหมายขัดแย้งกัน ให้ตัด 了 ออกเหลือ 我看书呢","Wrong because 了1 marks completion while progressive 呢 marks an ongoing action — drop 了 → 我看书呢.","不行，“了1”表完成，“呢”表正在进行，语义冲突，应说“我看书呢”。","Không được vì 了1 là đã xong còn 呢 là đang làm, mâu thuẫn nhau.","完了の「了1」と進行の「呢」は矛盾するため「我看书呢」にする。"],"ref":"HSK 3.0 g3-1-066 · g3-1-062"}],"ex":[["我看书呢。","Wǒ kàn shū ne.","ฉันกำลังอ่านหนังสืออยู่นะ","I'm reading right now.","Tôi đang đọc sách đây.","本を読んでいるところです。","呢"],["妈妈做饭呢。","Māma zuòfàn ne.","แม่กำลังทำกับข้าวอยู่นะ","Mom is cooking right now.","Mẹ đang nấu cơm đấy.","母は料理を作っていますよ。","呢"],["他睡觉呢。","Tā shuìjiào ne.","เขากำลังนอนหลับอยู่","He's sleeping right now.","Anh ấy đang ngủ đấy.","彼は寝ていますよ。","呢"],["外边下雨呢。","Wàibian xià yǔ ne.","ข้างนอกฝนกำลังตกอยู่เลย","It's raining outside.","Bên ngoài trời đang mưa đấy.","外は雨が降っていますよ。","呢"],["爸爸打电话呢。","Bàba dǎ diànhuà ne.","พ่อกำลังคุยโทรศัพท์อยู่","Dad is on the phone right now.","Bố đang gọi điện thoại đấy.","父は電話中ですよ。","呢"]],"err":[["我看了书呢。","我看书呢。","กำลังทำอยู่ (呢) ห้ามใส่ 了1 ที่แปลว่าเสร็จแล้ว","Do not combine completed 了1 with progressive 呢.","表进行用“我看书呢”，不能加“了1”。","Thể tiếp diễn dùng 我看书呢, không thêm 了1.","進行の「呢」に完了の「了1」は混ぜない。"]],"rel":["g3-1-064","g3-1-065","g3-1-026"]},"g3-1-067":{"t":["วิธีบอกจำนวนเงิน (钱数表示法): 块 / 元 / 钱","Expressing Money (钱数表示法): 块 / 元 / 钱","特殊表达法·数的表达法：钱数表示法","Cách nói số tiền (钱数表示法): 块 / 元 / 钱","金額の表し方（钱数表示法）：块・元・钱"],"f":["口语：数词 + 块（+ 钱）：五块钱 / 两块钱 / 十五块","书面/标价：数词 + 元（不加“钱”）：五元 / 十五元","带零头口语：两块五（2.5元）"],"why":["ในระดับ HSK 1 หน่วยเงินจีน (หยวน) ที่ใช้หลักคือ 块 (ภาษาพูด ชีวิตประจำวัน) และ 元 (ภาษาเขียน ป้ายราคา ใบเสร็จ) · กฎสำคัญ 4 ข้อเวลาพูดเรื่องเงิน: (1) ภาษาพูดมักเติม 钱 ต่อท้าย 块 ได้ (五块钱 หรือพูดสั้น ๆ 五块) แต่ 元 เป็นภาษาเขียนจึง 'ไม่เติม 钱' ต่อท้าย (เขียน 五元 ไม่เขียน 五元钱!) (2) จำนวน 2 หยวนใช้ 两 เสมอ (两块钱 / 两元 — ห้ามพูด 二块钱!) (3) ถ้ามีเศษทศนิยม (เช่น 2.5 หยวน) ในภาษาพูดมักย่อหน่วยสุดท้ายเป็น 两块五 (สองหยวนห้าเหมา) (4) ห้ามผสม 块 กับ 元 ในราคาเดียวกัน","In HSK 1, Chinese yuan uses 块 (everyday speech) and 元 (writing, price tags, receipts). · Four key money rules: (1) Spoken 块 optionally takes 钱 (五块钱 or 五块), whereas formal 元 does NOT take 钱 (write 五元, NOT 五元钱!). (2) '2 yuan' is ALWAYS 两 (两块钱 / 两元 — NEVER 二块钱!). (3) Decimals in speech shorten to 两块五 ('2.50 yuan'). (4) Never mix 块 and 元 in the same price.","HSK 1 人民币“元”的表达分口语“块”和书面／标价“元”。 · 四条规则：（1）“块”后常带“钱”（五块钱），书面“元”后一般不加“钱”（写“五元”，不写“五元钱”）；（2）2 元必须用“两”（两块钱、两元，不说“二块”）；（3）带角数口语常省去末尾单位（两块五＝2.5元）；（4）“块”和“元”不混用。","Đơn vị tiền Nhân dân tệ ở HSK 1 gồm 块 (khẩu ngữ) và 元 (văn viết, bảng giá). · 4 quy tắc: (1) 块 hay đi kèm 钱 (五块钱), còn 元 trang trọng KHÔNG thêm 钱 (五元); (2) 2 tệ luôn dùng 两 (两块钱, không nói 二块); (3) Số lẻ như 2.5 tệ khẩu ngữ rút gọn thành 两块五; (4) Không trộn 块 và 元.","HSK1の金額（元）は口語の「块」と書き言葉・値札の「元」を使う。 · 4つのルール：（1）「块」の後には「钱」を付けられる（五块钱）が、「元」の後に「钱」は付けない（五元）。（2）2元は必ず「两」（两块钱・两元、「二块」は不可）。（3）2.5元は口語で「两块五」と略せる。（4）「块」と「元」を混ぜない。"],"use":[{"ok":true,"zh":"这个苹果五块钱。","fix":"","py":"Zhège píngguǒ wǔ kuài qián.","tr":["แอปเปิลลูกนี้ราคาห้าหยวน","This apple costs five yuan.","Quả táo này giá năm tệ.","このりんごは5元です。"],"h":["พูดซื้อของในชีวิตประจำวันใช้ ตัวเลข + 块 + 钱","In everyday shopping speech, use Number + 块 + (钱)","日常口语报价用“数词＋块（＋钱）”","Nói giá hằng ngày dùng Số + 块 (+ 钱)","日常会話の値段は「数詞＋块（＋钱）」"],"w":["ทำได้และเป็นธรรมชาติที่สุดตามกลุ่มเทียบคำ g11: 块 เป็นหน่วยเงินภาษาพูดที่นิยมเติม 钱 ปิดท้าย (หรือพูดสั้น ๆ ว่า 五块 ก็ได้)","Works naturally per comparison group g11: 块 is the everyday spoken unit, optionally followed by 钱 (五块钱 or 五块).","口语买卖说“五块钱”（或简称“五块”）最自然地道。","Đúng và tự nhiên nhất theo nhóm g11: 块 dùng trong khẩu ngữ, thường kèm 钱.","日常会話では「五块钱」（または「五块」）が最も自然。"],"ref":"กลุ่มเทียบคำ g11 · HSK 3.0 g3-1-067"},{"ok":true,"zh":"这本书十五元。","fix":"","py":"Zhè běn shū shíwǔ yuán.","tr":["หนังสือเล่มนี้ราคาสิบห้าหยวน","This book is fifteen yuan.","Cuốn sách này giá 15 tệ.","この本は15元です。"],"h":["ป้ายราคา / ภาษาเขียนใช้ ตัวเลข + 元 (ไม่ต้องมี 钱)","On price tags or formal writing, use Number + 元 (without 钱)","书面语、标价牌用“数词＋元”，不加“钱”","Văn viết / bảng giá dùng Số + 元 (không thêm 钱)","書き言葉・値札は「数詞＋元」（「钱」は不要）"],"w":["ทำได้เพราะ 元 เป็นหน่วยเงินทางการที่ใช้บนป้ายราคา ใบเสร็จ และภาษาเขียน โดยไม่ต้องใส่ 钱 ต่อท้าย","Works cleanly as formal written style for price tags and receipts — no trailing 钱 needed.","“元”属书面正式单位，直接说“十五元”简洁规范。","Đúng chuẩn văn viết/bảng giá vì 元 không cần thêm 钱 phía sau.","「元」は正式な書き言葉単位なので「十五元」で簡潔に完結する。"],"ref":"กลุ่มเทียบคำ g11 · HSK 3.0 g3-1-067"},{"ok":false,"zh":"一杯水二块钱。","fix":"一杯水两块钱。","py":"Yī bēi shuǐ liǎng kuài qián.","tr":["น้ำหนึ่งแก้วสองหยวน","A glass of water is two yuan.","Một cốc nước giá hai tệ.","水1杯は2元です。"],"h":["ราคา 2 หยวนต้องใช้ 两块 / 两元 ห้ามใช้ 二块","Always use 两块 / 两元 for 2 yuan — NEVER 二块","2元必须说“两块钱／两元”，不能说“二块”","2 tệ luôn nói 两块钱 / 两元, không nói 二块","2元は必ず「两块钱／两元」（「二块」は不可）"],"w":["ไม่ได้ เพราะ 块 และ 元 ทำหน้าที่เหมือนลักษณนาม เมื่อจำนวนเป็น 2 โดด ๆ จึงบังคับใช้ 两 เสมอ (两块钱, 两块五 — ส่วน 12 หยวนใช้ 十二块钱)","Wrong because 块 and 元 act like measure words, so standalone 2 takes 两 (两块钱, 两块五; while 12 takes 二: 十二块钱).","不行，“块、元”前表示2元必须用“两”（两块钱）；十二、二十二才用“二”。","Không được vì 块/元 giống lượng từ nên số 2 đứng riêng phải dùng 两 (两块钱).","「块・元」の前の単独の2は必ず「两」（两块钱）。12は「十二块钱」。"],"ref":"กลุ่มเทียบคำ g9 · g11"},{"ok":false,"zh":"这本书十五元钱。","fix":"这本书十五元。","py":"Zhè běn shū shíwǔ yuán.","tr":["หนังสือเล่มนี้สิบห้าหยวน","This book is fifteen yuan.","Cuốn sách này 15 tệ.","この本は15元です。"],"h":["หลัง 元 ไม่นิยมเติม 钱 (เลือก 十五元 หรือ 十五块钱)","Don't add 钱 after formal 元 — choose 十五元 or 十五块钱","书面“元”后不加“钱”（选“十五元”或“十五块钱”）","Không thêm 钱 sau 元 (chọn 十五元 hoặc 十五块钱)","「元」の後ろに「钱」は付けない（「十五元」か「十五块钱」）"],"w":["ไม่เป็นมาตรฐาน เพราะ 元 เป็นภาษาเขียน ส่วน 钱 ท้ายราคาเป็นสไตล์ภาษาพูดที่คู่กับ 块 เท่านั้น ให้เลือกให้ตรงระดับภาษา: 十五元 (เขียน) หรือ 十五块钱 (พูด)","Mismatched register: 元 is formal written while trailing 钱 pairs with spoken 块 — pick either 十五元 or 十五块钱.","语体混搭，书面直接用“十五元”，口语说“十五块钱”。","Lệch văn phong: văn viết dùng 十五元, khẩu ngữ dùng 十五块钱.","文体が混ざってしまうため、書き言葉なら「十五元」、口語なら「十五块钱」に統一する。"],"ref":"กลุ่มเทียบคำ g11"}],"ex":[["这个苹果五块钱。","Zhège píngguǒ wǔ kuài qián.","แอปเปิลลูกนี้ห้าหยวน","This apple is five yuan.","Quả táo này năm tệ.","このりんごは5元です。","块钱"],["一杯水两块钱。","Yī bēi shuǐ liǎng kuài qián.","น้ำหนึ่งแก้วสองหยวน","A cup of water is two yuan.","Một cốc nước hai tệ.","水1杯は2元です。","两块"],["这本书十五元。","Zhè běn shū shíwǔ yuán.","หนังสือเล่มนี้สิบห้าหยวน","This book is fifteen yuan.","Cuốn sách này 15 tệ.","この本は15元です。","元"],["一个面包两块五。","Yī ge miànbāo liǎng kuài wǔ.","ขนมปังหนึ่งก้อนสองหยวนห้า","A loaf of bread is 2.50 yuan.","Một chiếc bánh mì 2 tệ rưỡi.","パン1個は2.5元です。","两块五"],["这件衣服一百块钱。","Zhè jiàn yīfu yībǎi kuài qián.","เสื้อตัวนี้หนึ่งร้อยหยวน","This piece of clothing is 100 yuan.","Chiếc áo này 100 tệ.","この服は100元です。","一百块"]],"err":[["一杯水二块钱。","一杯水两块钱。","2 หยวนใช้ 两块钱 เสมอ ไม่ใช้ 二块钱","Always use 两块钱 for 2 yuan, never 二块钱.","2元说“两块钱”，不说“二块钱”。","2 tệ luôn dùng 两块钱, không dùng 二块钱.","2元は「二块钱」ではなく必ず「两块钱」。"],["这本书十五元钱。","这本书十五元。","ภาษาเขียนใช้ 十五元 (ไม่ใส่ 钱) หรือภาษาพูดใช้ 十五块钱","Use 十五元 (no 钱) in writing, or 十五块钱 in speech.","书面用“十五元”不加“钱”，口语用“十五块钱”。","Văn viết dùng 十五元 (không 钱), khẩu ngữ dùng 十五块钱.","書き言葉は「十五元」（钱不要）、口語は「十五块钱」。"]],"rel":["g3-1-011","g3-1-012","g3-1-036"]},"g3-1-068":{"t":["วิธีบอกเลขลำดับที่ (序数表达法1): 第 + ตัวเลข","Ordinal Numbers (序数表达法1): 第 + Number","特殊表达法·数的表达法：序数表达法1：第+数词","Cách nói số thứ tự (序数表达法1): 第 + Số từ","序数の表し方（序数表达法1）：第＋数詞"],"f":["第 + 数词 + 量词 + 名词（第一个人 / 第二本书 / 第三天）","无需“第”的惯用序数：一年级 / 二月 / 三楼 / 星期一"],"why":["การเปลี่ยนตัวเลขธรรมดาให้เป็น 'ลำดับที่' ทำได้ง่ายมาก แค่เติม 第 ไว้หน้าตัวเลข: 第一 (ที่หนึ่ง), 第二 (ที่สอง), 第三 (ที่สาม), 第十 (ที่สิบ) · เมื่อนำไปขยายคำนาม ต้องมีลักษณนามคั่นเสมอ (เช่น 第一个学生, 第二本书, 第三天 — โดย 天 เป็นลักษณนามเวลาในตัวจึงไม่ใส่ 个) · ข้อควรระวังสำคัญ 3 ข้อ: (1) ลำดับที่สองต้องใช้ 第二 เสมอ ห้ามใช้ 第两 เด็ดขาด! แม้มีลักษณนามตามหลัง (2) ห้ามลืมลักษณนามระหว่าง 第+ตัวเลข กับคำนาม (第一本书 ไม่ใช่ 第一书) (3) คำบางหมวดที่เป็นลำดับอยู่แล้วตามธรรมชาติ เช่น เดือน (一月, 二月) และวันในสัปดาห์ (星期一) ไม่ต้องเติม 第 (ไม่พูด 第五月 หรือ 第星期一!)","Form ordinal numbers simply by placing 第 before a number: 第一 (1st), 第二 (2nd), 第三 (3rd), 第十 (10th). · Before a noun, always include the measure word: 第一个学生, 第二本书, 第三天. · Three key cautions: (1) '2nd' is ALWAYS 第二 — NEVER 第两 even before a measure word! (2) Never drop the measure word before nouns (第一本书, not 第一书). (3) Naturally ordered names like months (五月) and weekdays (星期一) do NOT take 第.","在数词前加“第”构成序数：第一、第二、第三、第十。 · 修饰名词时中间必须加量词：第一个学生、第二本书、第三天。 · 三大注意：（1）“第二”绝不能说“第两”，即使后面有量词（第二本书）；（2）不能省量词（不说“第一书”）；（3）月份（二月）、星期（星期一）等本身已含序数义，不加“第”。","Tạo số thứ tự bằng cách thêm 第 trước số từ: 第一, 第二, 第三, 第十. · Trước danh từ luôn có lượng từ: 第一个学生, 第二本书, 第三天. · 3 lưu ý: (1) 'Thứ hai' luôn là 第二 (không nói 第两); (2) Không bỏ lượng từ trước danh từ; (3) Tháng (二月), thứ (星期一) vốn đã chỉ thứ tự nên KHÔNG thêm 第.","数詞の前に「第」を付けるだけで序数になる（第一・第二・第三・第十）。 · 名詞の前には必ず量詞を挟む（第一个学生・第二本书・第三天）。 · 3大注意：（1）2番目は量詞があっても必ず「第二」（第两は不可）。（2）量詞を省かない。（3）月（二月）や曜日（星期一）には「第」を付けない。"],"use":[{"ok":true,"zh":"这是我买的第三本书。","fix":"","py":"Zhè shì wǒ mǎi de dì-sān běn shū.","tr":["นี่คือหนังสือเล่มที่สามที่ฉันซื้อ","This is the third book I bought.","Đây là cuốn sách thứ ba tôi mua.","これは私が買った3冊目の本です。"],"h":["第 + ตัวเลข + ลักษณนาม + คำนาม ครบโครงสร้าง","Complete ordinal noun phrase: 第 + number + measure word + noun","“第＋数词＋量词＋名词”结构完整","Đủ cấu trúc: 第 + số + lượng từ + danh từ","「第＋数詞＋量詞＋名詞」の完全形"],"w":["ทำได้เพราะวาง 第 หน้าตัวเลข 三 แล้วเชื่อมกับคำนาม 书 ด้วยลักษณนามเฉพาะ 本 (第三本书) ถูกต้อง 100%","Works 100% cleanly with 第 + 三 + measure word 本 + noun 书.","“第三”加专用量词“本”修饰“书”，规范自然。","Đúng 100% vì có đủ 第 + 三 + lượng từ 本 + danh từ 书.","「第三」＋専用量詞「本」＋名詞「书」の正確な形。"],"ref":"HSK 3.0 g3-1-068 · g3-1-001"},{"ok":true,"zh":"第二天我去了北京。","fix":"","py":"Dì-èr tiān wǒ qùle Běijīng.","tr":["วันที่สองฉันไปปักกิ่ง","On the second day, I went to Beijing.","Ngày thứ hai tôi đã đi Bắc Kinh.","2日目に北京へ行きました。"],"h":["ลำดับที่สองใช้ 第二 เสมอ และ 天 ไม่ต้องเติม 个","Always use 第二 for '2nd', and 天 takes no 个","“第二”不用“两”，且“天”前不加“个”（第二天）","Thứ hai luôn dùng 第二, và 天 không thêm 个","2番目は必ず「第二」、「天」に「个」は不要"],"w":["ทำได้เพราะ 第二 ใช้ 二 เสมอ (ไม่ใช้ 两) และ 天 เป็นลักษณนามเวลาในตัวจึงเป็น 第二天 (เช่นเดียวกับ 第二年 = ปีที่สอง)","Works because ordinals always take 二 (第二) and 天 is a self-measuring time unit (第二天, 第二年).","序数永远用“第二”，“天、年”本身是时量词，直接说“第二天、第二年”。","Đúng vì số thứ tự luôn dùng 二 và 天 tự là lượng từ thời gian (第二天).","序数は常に「第二」、「天・年」は時間量詞なので直接「第二天」となる。"],"ref":"กลุ่มเทียบคำ g9 · HSK 3.0 g3-1-068"},{"ok":false,"zh":"第两本书很好看。","fix":"第二本书很好看。","py":"Dì-èr běn shū hěn hǎokàn.","tr":["หนังสือเล่มที่สองน่าอ่านมาก","The second book is very interesting.","Cuốn sách thứ hai rất hay.","2冊目の本はとても面白いです。"],"h":["ห้ามใช้ 第两 แม้จะมีลักษณนามตามหลัง","NEVER write 第两 even before a measure word","序数绝不能说“第两”","Không bao giờ nói 第两 dù có lượng từ","量詞があっても「第两」は絶対不可"],"w":["ไม่ได้ เพราะเมื่อเติม 第 เป็นเลขลำดับ กฎบังคับใช้ 二 เท่านั้น (第二本书 = เล่มที่สอง) ต่างจากบอกจำนวนว่า 2 เล่ม (两本书)","Wrong because 第 forces 二 (第二本书 'the 2nd book'), unlike cardinal quantity 两本书 ('two books').","不行，表序数永远用“第二”，表数量才用“两本”。","Không được vì có 第 bắt buộc dùng 二 (第二本书), khác số lượng 两本书.","序数の「第」が付くときは必ず「第二」（第二本书）。数量の「两本书」と区別する。"],"ref":"กลุ่มเทียบคำ g9"},{"ok":false,"zh":"今天是第五月。","fix":"今天是五月。","py":"Jīntiān shì wǔ yuè.","tr":["ตอนนี้เดือนพฤษภาคม (เดือนห้า)","It is May now.","Bây giờ là tháng Năm.","今は5月です。"],"h":["ชื่อเดือน (五月) และวันในสัปดาห์ (星期一) ไม่ต้องเติม 第","Months (五月) and weekdays (星期一) do NOT take 第","月份、星期本身已表序数，不能加“第”","Tháng (五月) và thứ (星期一) không thêm 第","月（五月）や曜日（星期一）に「第」は付けない"],"w":["ไม่ได้ เพราะในภาษาจีน 一月…十二月 และ 星期一…星期六 มีความหมายเรียงลำดับในตัวอยู่แล้ว การเติม 第 เป็น 第五月 จะกลายเป็น 'เดือนที่ 5 ของระยะเวลา' ไม่ใช่ชื่อเดือนพฤษภาคม","Wrong because calendar months (五月) and weekdays (星期一) are inherent ordinals — never add 第 for month names.","不行，日历月份（五月）和星期（星期一）前面绝不加“第”（“第五个月”才指持续的第五个月份）。","Không được vì tên tháng (五月) và thứ (星期一) vốn là số thứ tự rồi, không thêm 第.","暦の月名（五月）や曜日（星期一）には「第」を付けない。"],"ref":"HSK 3.0 g3-1-068 · g3-1-069"}],"ex":[["他是第一个学生。","Tā shì dì-yī ge xuésheng.","เขาเป็นนักเรียนคนแรก","He is the first student.","Anh ấy là học sinh đầu tiên.","彼は最初の学生です。","第一"],["第二本书很好看。","Dì-èr běn shū hěn hǎokàn.","หนังสือเล่มที่สองน่าอ่านมาก","The second book is very interesting.","Cuốn sách thứ hai rất hay.","2冊目の本はとても面白いです。","第二"],["第二天我去了医院。","Dì-èr tiān wǒ qùle yīyuàn.","วันที่สองฉันไปโรงพยาบาล","On the second day I went to the hospital.","Ngày thứ hai tôi đã đi bệnh viện.","2日目に病院へ行きました。","第二天"],["这是我的第三个手机。","Zhè shì wǒ de dì-sān ge shǒujī.","นี่คือโทรศัพท์เครื่องที่สามของฉัน","This is my third mobile phone.","Đây là chiếc điện thoại thứ ba của tôi.","これは私の3台目のスマホです。","第三"],["我买了第五本书。","Wǒ mǎile dì-wǔ běn shū.","ฉันซื้อหนังสือเล่มที่ห้าแล้ว","I bought the fifth book.","Tôi đã mua cuốn sách thứ năm.","5冊目の本を買いました。","第五"]],"err":[["第两本书很好看。","第二本书很好看。","ลำดับที่สองต้องใช้ 第二 เสมอ ห้ามใช้ 第两","Always use 第二 (never 第两) for 'second'.","序数必须用“第二”，不能说“第两”。","Số thứ tự thứ hai luôn là 第二, không nói 第两.","序数の2番目は必ず「第二」（第两は不可）。"],["这是第一书。","这是第一本书。","หลัง 第 + ตัวเลข ก่อนคำนามต้องมีลักษณนามเสมอ","Include the measure word between 第+number and the noun.","“第＋数词”与名词间须加量词（第一本书）。","Giữa 第 + số và danh từ cần có lượng từ (第一本书).","「第＋数詞」と名詞の間に量詞を入れる（第一本书）。"]],"rel":["g3-1-001","g3-1-011","g3-1-069"]},"g3-1-069":{"t":["วิธีบอกวัน เดือน ปี และวันในสัปดาห์ (年、月、日、星期表示法)","Dates: Year, Month, Day & Weekday (年、月、日、星期)","特殊表达法·时间表示法（1）：年、月、日、星期表示法","Cách nói Năm, Tháng, Ngày, Thứ (年、月、日、星期)","年月日の表し方（年・月・日・星期）"],"f":["从大到小：XXXX年 + X月 + X号（口语）/ 日（书面）+ 星期X","星期一～星期六 · 周日：星期天（口语）/ 星期日（书面）"],"why":["กฎเหล็กอันดับ 1 ของการบอกวันที่ในภาษาจีน: เรียงจาก 'หน่วยใหญ่ → หน่วยเล็ก' เสมอ! ปี (年) → เดือน (月) → วันที่ (号/日) → วันในสัปดาห์ (星期…) ซึ่ง 'กลับด้าน' กับภาษาไทย ('วันจันทร์ที่ 8 พฤษภาคม 2026') อย่างสิ้นเชิง · กฎสำคัญ 4 ข้อที่ออกสอบตลอด: (1) ปีปฏิทินอ่านทีละหลัก ไม่ใช่หลักพัน เช่น 2026年 อ่าน 二零二六年 (2) วันที่ในภาษาพูดใช้ 号 ส่วนภาษาเขียนใช้ 日 (3) เดือนสองใช้ 二月 ห้ามใช้ 两月 (4) วันอาทิตย์ใช้ 星期天 (พูด) หรือ 星期日 (เขียน) — ห้ามพูด 星期七 เด็ดขาด!","Rule #1 for Chinese dates: ALWAYS go BIGGEST → SMALLEST! Year (年) → Month (月) → Day (号/日) → Weekday (星期…) — the exact reverse of Thai/British '8 May 2026'. · Four exam-critical rules: (1) Read calendar years digit by digit: 2026年 = 二零二六年. (2) Spoken dates use 号; written dates use 日. (3) February is 二月 (NEVER 两月!). (4) Sunday is 星期天 (spoken) or 星期日 (written) — NEVER 星期七!","汉语日期严格遵守“从大到小”顺序：年→月→日／号→星期（与泰语顺序完全相反）。 · 四大要点：（1）年份按数字逐位读（二零二六年）；（2）日期口语用“号”，书面用“日”；（3）二月绝不说“两月”；（4）星期日／星期天绝不说“星期七”。","Quy tắc số 1 của ngày tháng tiếng Trung: LUÔN đi từ LỚN → NHỎ (Năm 年 → Tháng 月 → Ngày 号/日 → Thứ 星期…) — ngược hoàn toàn tiếng Việt/Thái! · 4 lưu ý thi cử: (1) Năm đọc từng chữ số (二零二六年); (2) Ngày: nói dùng 号, viết dùng 日; (3) Tháng 2 là 二月 (không nói 两月); (4) Chủ nhật là 星期天 / 星期日 (TUYỆT ĐỐI không nói 星期七!).","中国語の日付は必ず「大きい単位→小さい単位」（年→月→日・号→曜日）の順。 · 4つの鉄則：（1）西暦は1桁ずつ読む（二零二六年）。（2）日付は口語「号」・書き言葉「日」。（3）2月は必ず「二月」（两月は不可）。（4）日曜日は「星期天／星期日」（「星期七」は絶対不可）。"],"use":[{"ok":true,"zh":"今天是五月八号。","fix":"","py":"Jīntiān shì wǔ yuè bā hào.","tr":["วันนี้คือวันที่ 8 พฤษภาคม","Today is May 8th.","Hôm nay là ngày 8 tháng 5.","今日は5月8日です。"],"h":["เรียง เดือน (五月) ก่อน วันที่ (八号) จากใหญ่ไปเล็ก","Put Month (五月) BEFORE Day (八号): big-to-small","先“月”后“号／日”（从大到小）：五月八号","Đặt Tháng (五月) TRƯỚC Ngày (八号): lớn đến nhỏ","「月→日」と大きい単位から小さい単位の順（五月八号）"],"w":["ทำได้และถูกต้องตามเอกสาร เสริม w3-00076 โดยในภาษาพูดใช้ 号 (ส่วนภาษาเขียนทางการใช้ 日 เช่น 今天是十月一日)","Works per reference doc w3-00076 (month first, day second), using spoken 号 (or formal written 日: 十月一日).","符合汉语“大单位在前、小单位在后”原则，口语用“号”，书面用“日”。","Đúng theo tài liệu w3-00076: tháng trước ngày sau, khẩu ngữ dùng 号 (viết dùng 日).","大きい単位から並べる原則通り。口語は「号」、書き言葉は「日」。"],"ref":"เสริม w3-00076 · กลุ่มเทียบคำ g20"},{"ok":true,"zh":"明天是星期天。","fix":"","py":"Míngtiān shì xīngqītiān.","tr":["พรุ่งนี้เป็นวันอาทิตย์","Tomorrow is Sunday.","Ngày mai là Chủ nhật.","明日は日曜日です。"],"h":["วันอาทิตย์ใช้ 星期天 (พูด) หรือ 星期日 (เขียน)","Sunday is 星期天 (spoken) or 星期日 (written)","周日说“星期天”（口语）或“星期日”（书面）","Chủ nhật là 星期天 (nói) hoặc 星期日 (viết)","日曜日は「星期天」（口語）または「星期日」（書き言葉）"],"w":["ทำได้เพราะจันทร์–เสาร์ไล่เลข 1–6 (星期一 ถึง 星期六) ส่วนวันอาทิตย์ไม่ใช้เลขเจ็ดแต่ใช้ 天 / 日 แทน","Works because Monday–Saturday take numbers 1–6 (星期一–星期六), while Sunday takes 天 or 日 (never 七).","周一至周六用数字一到六，周日固定用“星期天／星期日”。","Đúng vì thứ 2–thứ 7 dùng số 1–6, còn Chủ nhật dùng 天 hoặc 日.","月〜土は一〜六だが、日曜日だけは「星期天／星期日」を使う。"],"ref":"HSK 3.0 g3-1-069"},{"ok":false,"zh":"今天是八号五月。","fix":"今天是五月八号。","py":"Jīntiān shì wǔ yuè bā hào.","tr":["วันนี้คือวันที่ 8 พฤษภาคม","Today is May 8th.","Hôm nay là ngày 8 tháng 5.","今日は5月8日です。"],"h":["ห้ามเอาวันที่ขึ้นก่อนเดือนแบบภาษาไทย ('8 พฤษภาคม')","NEVER put Day before Month like Thai/Vietnamese","绝不能把“号／日”放在“月”前面","Không bao giờ đặt Ngày trước Tháng như tiếng Việt/Thái","「日→月」の順にしてはいけない"],"w":["ไม่ได้ตามเอกสาร เสริม w3-00076 เพราะในภาษาไทยเรียง 'วันที่ → เดือน → ปี' แต่ภาษาจีนบังคับเรียง 'ปี → เดือน → วันที่' เสมอ: 五月八号","Wrong per reference doc w3-00076: Chinese strictly requires Year → Month → Day (五月八号), never Day → Month.","不行，汉语日期严格“先月后日”，必须说“五月八号”，不能说“八号五月”。","Không được vì tiếng Trung bắt buộc 'Tháng trước, Ngày sau': 五月八号.","中国語は必ず「年→月→日」の順なので「五月八号」とする。"],"ref":"เสริม w3-00076"},{"ok":false,"zh":"明天星期七。","fix":"明天星期天。","py":"Míngtiān xīngqītiān.","tr":["พรุ่งนี้วันอาทิตย์","Tomorrow is Sunday.","Ngày mai là Chủ nhật.","明日は日曜日です。"],"h":["ห้ามพูด 星期七 สำหรับวันอาทิตย์เด็ดขาด!","NEVER say 星期七 for Sunday!","绝不能把星期天说成“星期七”","Tuyệt đối không nói 星期七 cho Chủ nhật!","日曜日を「星期七」とは絶対に言わない"],"w":["ไม่ได้ เพราะในภาษาจีนไม่มีคำว่า 星期七 วันอาทิตย์ต้องใช้ 星期天 หรือ 星期日 เท่านั้น (และเดือนกุมภาพันธ์ใช้ 二月 ไม่ใช่ 两月)","Wrong because 星期七 does not exist in Chinese — Sunday is ALWAYS 星期天 or 星期日 (and February is 二月, never 两月).","不行，汉语里没有“星期七”，星期日只能说“星期天”或“星期日”。","Không được vì tiếng Trung không có 星期七; Chủ nhật luôn là 星期天 hoặc 星期日.","「星期七」は存在しない。日曜日は必ず「星期天」か「星期日」。"],"ref":"HSK 3.0 g3-1-069"}],"ex":[["今天是五月八号。","Jīntiān shì wǔ yuè bā hào.","วันนี้วันที่ 8 พฤษภาคม","Today is May 8th.","Hôm nay là ngày 8 tháng 5.","今日は5月8日です。","五月八号"],["今天是十月一日。","Jīntiān shì shí yuè yī rì.","วันนี้วันที่ 1 ตุลาคม (ทางการ)","Today is October 1st.","Hôm nay là ngày 1 tháng 10.","今日は10月1日です。","十月一日"],["今年是二零二六年。","Jīnnián shì èr líng èr liù nián.","ปีนี้คือปี 2026","This year is 2026.","Năm nay là năm 2026.","今年は2026年です。","二零二六年"],["今天星期几？","Jīntiān xīngqī jǐ?","วันนี้วันอะไร (ในสัปดาห์)","What day of the week is today?","Hôm nay là thứ mấy?","今日は何曜日ですか。","星期几"],["明天星期天，我不上班。","Míngtiān xīngqītiān, wǒ bù shàngbān.","พรุ่งนี้วันอาทิตย์ ฉันไม่ไปทำงาน","Tomorrow is Sunday; I don't work.","Ngày mai Chủ nhật, tôi không đi làm.","明日は日曜日で、仕事は休みです。","星期天"]],"err":[["今天是八号五月。","今天是五月八号。","วันที่ภาษาจีนเรียงจากใหญ่ไปเล็ก: ปี → เดือน → วันที่ (五月八号)","Dates go biggest-to-smallest: Year → Month → Day (五月八号).","日期从大到小：先月后日（五月八号）。","Ngày tháng xếp từ lớn đến nhỏ: Tháng trước Ngày sau (五月八号).","日付は大きい単位から（五月八号）。"],["明天星期七。","明天星期天。","วันอาทิตย์ใช้ 星期天 หรือ 星期日 เท่านั้น (ไม่มี 星期七)","Sunday is ALWAYS 星期天 or 星期日 (never 星期七).","周日只能说“星期天／星期日”，没有“星期七”。","Chủ nhật là 星期天 / 星期日, không có 星期七.","日曜日は「星期七」ではなく「星期天／星期日」。"]],"rel":["g3-1-070","g3-1-014","g3-1-036"]},"g3-1-070":{"t":["วิธีบอกเวลาตามนาฬิกา (钟点表示法): 点 / 分 / 半 / 零","Telling Clock Time (钟点表示法): 点 / 分 / 半 / 零","特殊表达法·时间表示法（2）：钟点表示法","Cách nói giờ giấc (钟点表示法): 点 / 分 / 半 / 零","時刻の表し方（钟点表示法）：点・分・半・零"],"f":["整点：X点（八点 / 两点） · 半点：X点半（两点半）","点+分：X点X分（八点十分 / 九点零五分）","时段 + 钟点：上午八点 / 下午三点半 / 晚上九点（从大到小）"],"why":["การบอกเวลานาฬิกาในภาษาจีนใช้หน่วย 点 (โมง/นาฬิกา) และ 分 (นาที) โดยมีกฎสำคัญ 5 ข้อที่ต้องจำให้แม่น: (1) 'บ่ายสอง / ตีสอง' (เลข 2 หน้า 点) ต้องใช้ 两点 เสมอ — ห้ามพูด 二点 เด็ดขาด! (แต่ 12 โมงใช้ 十二点) (2) ครึ่งชั่วโมงวาง 半 หลัง 点 (两点半 = สองโมงครึ่ง) ห้ามวางหน้า 点 (3) นาทีเลขหลักเดียว (01–09 นาที) ต้องอ่าน 零 นำหน้า เช่น 9:05 = 九点零五分 (4) ช่วงเวลาของวัน (早上, 上午, 中午, 下午, 晚上) วาง 'หน้า' ชั่วโมงเสมอตามกฎใหญ่→เล็ก (下午三点 ไม่ใช่ 三点下午!) (5) แยกให้ชัด: 两点 = เวลา 2 โมง (จุดเวลา) ต่างจาก 两个小时 = ระยะเวลา 2 ชั่วโมง!","Chinese clock time uses 点 (o'clock) and 分 (minute), with 5 essential rules: (1) '2 o'clock' is ALWAYS 两点 — NEVER 二点 (while 12 is 十二点). (2) Half past places 半 right after 点 (两点半 = 2:30). (3) Single-digit minutes (01–09) require 零: 9:05 = 九点零五分. (4) Time-of-day (上午, 下午, 晚上) ALWAYS comes BEFORE the hour (下午三点, NEVER 三点下午!). (5) Distinguish 两点 ('2:00', clock point) from 两个小时 ('2 hours', duration).","钟点用“点、分、半”表示，需掌握五条规则：（1）2点必须说“两点”（绝不说“二点”）；（2）半小时说“X点半”（两点半）；（3）1～9分前须加“零”（九点零五分）；（4）时段词（上午、下午、晚上）永远放在钟点前（下午三点）；（5）严格区分时点“两点”与时长“两个小时”。","Cách nói giờ dùng 点 (giờ), 分 (phút), 半 (rưỡi) với 5 quy tắc: (1) 2 giờ luôn là 两点 (KHÔNG nói 二点); (2) Rưỡi đặt 半 sau 点 (两点半); (3) Phút lẻ 1–9 thêm 零 (九点零五分); (4) Buổi (上午, 下午, 晚上) luôn đứng TRƯỚC giờ (下午三点); (5) Phân biệt 两点 (2 giờ) với 两个小时 (2 tiếng đồng hồ).","時刻は「点（時）・分・半」で表す。5大ルール：（1）2時は必ず「两点」（「二点」は不可）。（2）30分は「〜点半」（两点半）。（3）1〜9分は「零」を入れる（九点零五分）。（4）時間帯（上午・下午・晚上）は常に時刻の前（下午三点）。（5）「两点」（2時）と「两个小时」（2時間）を区別する。"],"use":[{"ok":true,"zh":"现在两点半。","fix":"","py":"Xiànzài liǎng diǎn bàn.","tr":["ตอนนี้สองโมงครึ่ง (บ่ายสองครึ่ง)","It is 2:30 now.","Bây giờ là 2 giờ rưỡi.","今2時半です。"],"h":["สองโมงใช้ 两点 (ไม่ใช้ 二点) และ 'ครึ่ง' วางหลัง 点 เป็น 两点半","Use 两点 (not 二点) for 2 o'clock, and put 半 after 点 (两点半)","2点用“两点”，半小时把“半”放“点”后（两点半）","2 giờ dùng 两点 (không 二点), rưỡi đặt 半 sau 点 (两点半)","2時は「两点」、30分は「点」の後ろに「半」（两点半）"],"w":["ทำได้เพราะรวมกฎ 2 ข้อในประโยคเดียว: เลข 2 หน้า 点 ใช้ 两 และ ครึ่งชั่วโมงใส่ 半 ต่อท้าย 点 ได้เลยโดยไม่ต้องใส่ 分","Works cleanly combining two rules: 两 before 点, and 半 directly after 点 with no 分 needed.","“两点半”简洁规范，同时遵循2点用“两”和“半”放“点”后的规则。","Đúng chuẩn cả 2 quy tắc: 两 trước 点 và 半 ngay sau 点.","「两点」と「点半」の2ルールをきれいに満たしている。"],"ref":"กลุ่มเทียบคำ g9 · HSK 3.0 g3-1-070"},{"ok":true,"zh":"我下午三点去医院。","fix":"","py":"Wǒ xiàwǔ sān diǎn qù yīyuàn.","tr":["บ่ายสามโมงฉันไปโรงพยาบาล","I'm going to the hospital at 3:00 PM.","3 giờ chiều tôi đi bệnh viện.","午後3時に病院へ行きます。"],"h":["ช่วงเวลา (上午 / 下午 / 晚上) วางหน้าชั่วโมงเสมอ (ใหญ่ → เล็ก)","Put time-of-day (上午 / 下午 / 晚上) BEFORE the hour (big-to-small)","时段词放钟点前（下午三点、晚上八点）","Đặt buổi (上午/下午/晚上) TRƯỚC giờ (下午三点)","時間帯（上午・下午・晚上）を時刻の前に置く（下午三点）"],"w":["ทำได้เพราะ 下午 (ตอนบ่าย) ใหญ่กว่า 三点 (สามโมง) จึงวาง 下午 ขึ้นก่อน แล้ววางทั้งก้อนเวลาหน้ากริยา 去医院","Works because 下午 ('afternoon') is larger than 三点 ('3:00'), and the whole time phrase sits before 去医院.","按从大到小顺序先“下午”后“三点”，整体作时间状语放在动词前。","Đúng vì 下午 lớn hơn 三点, và cả cụm thời gian đứng trước động từ 去医院.","大→小の順に「下午三点」と並べ、そのまま動詞「去医院」の前に置いている。"],"ref":"HSK 3.0 g3-1-070 · g3-1-040"},{"ok":false,"zh":"现在二点十分。","fix":"现在两点十分。","py":"Xiànzài liǎng diǎn shí fēn.","tr":["ตอนนี้สองโมงสิบนาที","It is 2:10 now.","Bây giờ là 2 giờ 10 phút.","今2時10分です。"],"h":["ห้ามพูด 二点 (ต้องใช้ 两点 เสมอ!)","NEVER say 二点 — ALWAYS say 两点!","2点绝不能说“二点”，必须说“两点”","Tuyệt đối không nói 二点 — luôn nói 两点!","「二点」は絶対不可、必ず「两点」"],"w":["ไม่ได้ เพราะ 点 เป็นลักษณนามเวลา (时量词) เมื่อเป็นเลข 2 เดี่ยว ๆ จึงบังคับใช้ 两点 เสมอ (ส่วน 2 นาทีพูด 两分 หรือ 二分 ได้ แต่ในเวลาเช่น 8:02 นิยม 八点零二分)","Wrong because 点 is a time measure word taking 两 for 2:00 (两点); only 12:00 uses 二 (十二点).","不行，“点”前表示2点必须用“两点”（12点才说“十二点”）。","Không được vì 点 là lượng từ thời gian nên 2 giờ bắt buộc dùng 两点 (12 giờ mới dùng 十二点).","「点」は時間量詞なので2時は必ず「两点」（12時は「十二点」）。"],"ref":"กลุ่มเทียบคำ g9 · HSK 3.0 g3-1-070"},{"ok":false,"zh":"我学习了两点。","fix":"我学习了两个小时。","py":"Wǒ xuéxíle liǎng ge xiǎoshí.","tr":["ฉันเรียนไปสองชั่วโมง","I studied for two hours.","Tôi đã học hai tiếng đồng hồ.","2時間勉強しました。"],"h":["ห้ามเอา 点 (โมง = จุดเวลา) ไปใช้แทน 小时 (ชั่วโมง = ระยะเวลา)","NEVER confuse 点 (o'clock, point in time) with 小时 (hours, duration)","“两点”是钟点，“两个小时”才是时长","Không nhầm 点 (mấy giờ) với 小时 (mấy tiếng đồng hồ)","「两点」（2時）と「两个小时」（2時間）を混同しない"],"w":["ไม่ได้ เพราะ 两点 แปลว่า 'เวลาตีสอง/บ่ายสองโมง' ไม่ใช่ระยะเวลา 2 ชั่วโมง! ถ้าบอกความยาวนานต้องใช้ 两个小时 เสมอ","Wrong because 两点 means '2:00 o'clock' (a point in time), NOT a 2-hour duration — use 两个小时 for duration.","不行，“两点”指具体时刻，表示持续两小时必须说“两个小时”。","Không được vì 两点 là mốc 2 giờ, còn khoảng thời gian 2 tiếng phải nói 两个小时.","「两点」は時刻の2時。2時間という長さは必ず「两个小时」を使う。"],"ref":"HSK 3.0 g3-1-070 · g3-1-014"}],"ex":[["现在几点？","Xiànzài jǐ diǎn?","ตอนนี้กี่โมงแล้ว","What time is it now?","Bây giờ là mấy giờ?","今何時ですか。","几点"],["现在两点半。","Xiànzài liǎng diǎn bàn.","ตอนนี้สองโมงครึ่ง","It is 2:30 now.","Bây giờ là 2 giờ rưỡi.","今2時半です。","两点半"],["上午八点十分我上课。","Shàngwǔ bā diǎn shí fēn wǒ shàngkè.","แปดโมงสิบนาทีตอนเช้าฉันเข้าเรียน","I have class at 8:10 AM.","8 giờ 10 sáng tôi vào học.","午前8時10分に授業があります。","八点十分"],["现在九点零五分。","Xiànzài jiǔ diǎn líng wǔ fēn.","ตอนนี้เก้าโมงห้านาที","It is 9:05 now.","Bây giờ là 9 giờ 05 phút.","今9時5分です。","零五分"],["我晚上十点睡觉。","Wǒ wǎnshang shí diǎn shuìjiào.","ตอนกลางคืนฉันเข้านอนสี่ทุ่ม","I go to sleep at 10:00 PM.","10 giờ tối tôi đi ngủ.","夜10時に寝ます。","晚上十点"]],"err":[["现在二点半。","现在两点半。","เวลา 2 โมงต้องใช้ 两点 เสมอ ห้ามใช้ 二点","Always use 两点 (never 二点) for 2 o'clock.","2点必须说“两点”，不能说“二点”。","2 giờ luôn dùng 两点, không dùng 二点.","2時は必ず「两点」（「二点」は不可）。"],["我学习了两点。","我学习了两个小时。","ระยะเวลา 2 ชั่วโมงใช้ 两个小时 (ไม่ใช่ 两点 ที่แปลว่า 2 โมง)","Use 两个小时 for duration ('2 hours'), not 两点 ('2 o'clock').","表示时长用“两个小时”，不用“两点”。","Thời lượng 2 tiếng dùng 两个小时, không dùng 两点.","「2時間」の長さは「两点」ではなく「两个小时」。"]],"rel":["g3-1-069","g3-1-014","g3-1-040"]}};
